window.HS_LOAD(8,{"intro":[[["جب نبی کریمؐ اور آپ کے صحابہ کرامؓ نے مادی اسباب کو چھوڑ دیا اور روحانی اسباب کو مضبوطی سے پکڑ لیا اور حضورؐ کی طرح صحابہ کرامؓ کو اقوام عالم کی ہدایت کا اور انہیں دعوت دینے کا فکر تھا اور وہ حضرات دعوت و جہاد کے سلسلہ میں حضورؐ کے اخلاق اور عادات کے ساتھ متصف ہو گئے تھے تو کس طرح سے انہیں ہر وقت غیبی تائید حاصل رہتی تھی۔",""]]],"topics":{"220":{"lead":[],"stories":[{"b":[["n",[["حضرت سہل بن سعدؓ","b"],[" کہتے ہیں حضرت ابواسیدؓ نے بینائی جانے کے بعد فرمایا اے میرے بھتیجے! میں اور تم اگر میدان بدر میں ہوتے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ میری بینائی واپس کر دیتے تو میں تمہیں وہ گھاٹی دکھاتا جہاں سے فرشتے نکل کر ہمارے لشکر میں آئے تھے اور اس بات میں کسی قسم کا شک و شبہ نہیں ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.3 Pg.280). Tabraani has reported a similar narration, but Haythami (Vol.6 Pg.84) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عروہؒ","b"],[" نے فرمایا حضرت جبرائیل علیہ السلام جنگ بدر کے دن حضرت زبیرؓ کی شکل و صورت پر اترے تھے، انہوں نے سر پر زرد رنگ کی پگڑی باندھی ہوئی تھی جس کا کچھ کپڑا ان کے چہرے پر بھی تھا۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.84)."]]},{"b":[["n",[["حضرت عباد بن عبد","b"],["ٱللَّٰه","a"],[" بن زبیرؒ","b"],[" نے فرمایا حضرت زبیر بن عوامؓ کے سر پر غزوہ بدر کے دن زرد پگڑی تھی جس کا کچھ کپڑا ان کے چہرے پر تھا، چنانچہ فرشتے آسمان سے اترے تو ان کے سروں پر زرد پگڑیاں تھیں۔",""],[" (3)","s"]]]],"f":[["(3)","Haakim (Vol.3 Pg.361). Tabraani and Ibn Asaakir have reported a similar narration, as quoted in Kanzul Ummaal (Vol.5 Pg.267)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" نے فرمایا غزوہ بدر کے دن فرشتوں کی نشانی سفید پگڑیاں تھیں جن کے شملے پشت پر لٹکے ہوئے تھے (بعض فرشتوں کی پگڑیاں سفید تھیں اور بعض کی زرد) اور غزوہ حنین کے دن ان کی نشانی سبز پگڑیاں تھیں اور غزوہ بدر کے دن تو فرشتوں نے جنگ کی تھی، باقی کسی غزوے کے دن جنگ نہیں کی تھی، البتہ شریک ہو کر مسلمانوں کی تعداد بڑھاتے تھے اور ان کی مدد کرتے تھے، کسی کافر پر حملہ نہیں کرتے تھے۔",""]]]],"f":[]},{"b":[["n",[["حضرت عکرمہؒ","b"],[" کہتے ہیں حضورؐ کے آزاد کردہ غلام حضرت ابو رافعؓ نے فرمایا میں حضرت عباس بن عبدالمطلبؓ کا غلام تھا اور اسلام ہمارے گھر میں داخل ہو چکا تھا، چنانچہ حضرت عباسؓ، ان کی اہلیہ حضرت ام فضلؓ اور میں، ہم سب مسلمان ہو چکے تھے لیکن حضرت عباسؓ اپنی قوم سے ڈرتے تھے اور ان کے خلاف کرنے کو پسند نہیں کرتے تھے اور اپنے اسلام کو چھپاتے تھے اور بہت زیادہ مالدار تھے، ان کا بہت سا مال ان کی قوم میں بکھرا ہوا تھا۔ ابولہب بھی جنگ بدر میں نہیں گیا تھا اور اس نے اپنی جگہ عاص بن ہشام بن مغیرہ کو بھیجا تھا۔ باقی تمام کافروں نے بھی یہی کیا تھا، جو خود اس جنگ میں نہیں گیا تھا اس نے اپنی جگہ کسی نہ کسی کو بھیجا تھا۔ جب اسے جنگ بدر میں کفار قریش کے شکست کھانے کی خبر ملی تو ",""],["ٱللَّٰه","a"],[" نے اسے خوب رسوا و ذلیل کیا اور ہمیں اس خبر سے اپنے اندر بہت قوت اور غلبہ محسوس ہوا۔ حضرت ابو رافعؓ کہتے ہیں میں ایک کمزور آدمی تھا اور زمزم کے خیمے میں تیر بنایا کرتا تھا، انہیں چھیلا کرتا تھا۔ ",""],["ٱللَّٰه","a"],[" کی قسم! میں خیمے میں بیٹھا ہوا تیر چھیل رہا تھا اور حضرت ام فضلؓ میرے پاس بیٹھی ہوئی تھیں اور یہ جو خبر آئی تھی اس سے ہم بہت خوش تھے کہ اتنے میں ابولہب بری طرح پاؤں گھسیٹتا ہوا آیا اور خیمے کی رسی پر آ کر بیٹھ گیا اور اس کی پشت میری پشت کی طرف تھی، وہ یوں بیٹھا ہوا تھا کہ اتنے میں لوگوں نے کہا یہ ابوسفیان ہے جو جنگ بدر سے واپس آیا ہے۔ اس ابوسفیان کا نام مغیرہ بن حارث بن عبدالمطلب ہے (یہ ابوسفیان اور ہیں، اور جو ابوسفیان قریش کے سردار اور ہر جنگ کے سپہ سالار تھے وہ اور ہیں، ان کا نام صخر بن حرب بن امیہ ہے)۔ ابولہب نے ابوسفیان سے کہا میرے پاس آ، کیونکہ میری زندگی کی قسم! صحیح خبر تو تمہارے پاس ہے۔ وہ ابولہب کے پاس آ کر بیٹھ گیا اور لوگ بھی پاس آ کر کھڑے ہو گئے۔ ابولہب نے کہا اے میرے بھتیجے! ذرا یہ تو بتاؤ کہ لوگوں کو کیا ہوا؟ کیسے شکست ہوئی؟ اس نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! ہم لڑنے کے لیے مسلمانوں کے سامنے کھڑے ہی ہوئے تھے کہ مسلمان ہم پر چھا گئے اور جسے چاہتے تھے قتل کر دیتے تھے اور جسے چاہتے تھے قید کر لیتے تھے۔ اور ",""],["ٱللَّٰه","a"],[" کی قسم! میں اس میں اپنے لشکر کا کوئی قصور نہیں سمجھتا کیونکہ ہمارا مقابلہ تو مسلمانوں سے ہوا ہی نہیں بلکہ ہمارے مقابلہ میں تو ایسے لوگ آ گئے تھے جن کا رنگ سفید تھا اور وہ زمین و آسمان کے درمیان چتکبرے گھوڑوں پر سوار تھے اور وہ لوگ تو کسی چیز کو چھوڑتے نہیں تھے۔ ان کے سامنے کوئی چیز ٹھہر نہیں سکتی تھی۔ حضرت ابو رافعؓ کہتے ہیں میں نے خیمہ کی رسی ہاتھ میں اٹھائی اور کہا ",""],["ٱللَّٰه","a"],[" کی قسم! یہ تو فرشتے تھے (چونکہ کفار قریش فرشتوں کو مانتے نہیں تھے اس وجہ سے)۔ ابولہب نے ہاتھ اٹھا کر مجھے زور سے مارا، میں اس سے گتھ گیا، اس نے مجھے اٹھا کر زمین پر پٹخا اور پھر میرے سینے پر بیٹھ کر مجھے مارنے لگا۔ میں کمزور آدمی تھا۔ اس پر حضرت ام فضلؓ نے کھڑے ہو کر خیمہ کا ایک کھونٹا لیا اور زور سے ابولہب کے سر پر مارا جس سے اس کے سر میں بڑا زخم ہو گیا اور یوں کہا چونکہ اس غلام کا آقا موجود نہیں ہے، اس لیے تو نے اسے کمزور سمجھ رکھا ہے۔ ابولہب اٹھا اور رسوا ہو کر پشت پھیر کر چلا گیا (کہ مکہ کے اس سردار نے آج ایک غلام اور ایک عورت سے مار کھائی)۔ ",""],["ٱللَّٰه","a"],[" کی قسم! وہ اس کے بعد صرف سات دن ہی زندہ رہا پھر ",""],["ٱللَّٰه","a"],[" نے اسے چیچک میں مبتلا کر دیا جس سے وہ مر گیا۔ یونس کی روایت میں مزید یہ بھی ہے کہ ابولہب کے دو بیٹے تھے، انہوں نے اس کی لاش کو مرنے کے بعد تین دن ویسے ہی پڑا رہنے دیا، اسے دفن نہیں کیا یہاں تک کہ وہ سڑ گیا اور اس میں بدبو پیدا ہو گئی اور قریش کے لوگ طاعون کی طرح چیچک سے بھی ڈرتے تھے اور اس سے بچتے تھے۔ آخر قریش کے ایک آدمی نے ان دونوں سے کہا تم دونوں کا ناس ہو! کیا تمہیں شرم نہیں آتی؟ تمہارا باپ گھر میں پڑا سڑ رہا ہے تم اسے دفن نہیں کرتے۔ دونوں نے کہا ہمیں چیچک اور اس کے زخم سے ڈر ہے، یہ ایک متعدی بیماری ہے، اس لیے ہمیں ڈر ہے کہ ہمیں نہ ہو جائے۔ اس نے کہا چلو میں تمہاری مدد کرتا ہوں۔ چنانچہ تینوں نے دور سے اس پر پانی پھینک کر غسل دیا، اس کے قریب نہ گئے، پھر اسے اٹھا کر مکہ کے بالائی حصہ میں لے گئے اور ایک دیوار کے سہارے اسے لٹا کر اس پر پتھر ڈال دیے۔",""],[" (4)","s"],[" (5)","s"]]]],"f":[["(4)","Abu Nu'aym in his Dalaa'il (Pg.170)."],["(5)","Ibn Is'haaq, as quoted in Al Bidaayah wan Nihaayah (Vol.3 Pg.308). Ibn Sa'd (Vol.4 Pg.73) and Haakim (Vol.3 Pg.321) have reported a similar narration, as have Tabraani and Bazzaar, but Haythami (Vol.6 Pg.89) has commented on the chain of narrators. Haakim (Vol.3 Pg.322) has also reported the narration from another source, as has Abu Nu'aym in his Dalaa'il (Pg.170)."]]},{"b":[["n",[["حضرت ام برثنؒ کے غلام حضرت عبدالرحمٰنؒ","b"],[" ان صحابی سے نقل کرتے ہیں جو غزوہ حنین میں حالت کفر میں شریک ہوئے تھے اور بعد میں مسلمان ہوئے تھے، وہ فرماتے ہیں جب میدان جنگ میں ہمارا اور حضورؐ کا آمنا سامنا ہوا تو مسلمان ہمارے سامنے اتنی دیر بھی نہیں ٹھہر سکے جتنی دیر میں ایک بکری کا دودھ نکالا جاتا ہے، ان کے پاؤں اکھڑ گئے اور انہیں شکست ہو گئی اور ہم تلواریں ہلاتے ہوئے حضورؐ کے سامنے پہنچ گئے۔ جب ہم حضورؐ پر چھانے لگے تو ایک دم ہمارے اور حضورؐ کے درمیان ایسے لوگ آ گئے جن کے چہرے بڑے خوبصورت تھے، انہوں نے کہا (تمہارے) چہرے بگڑ جائیں، لہٰذا تم واپس چلے جاؤ۔ بس ان لوگوں کی اتنی سی بات سے ہمیں شکست ہو گئی۔",""],[" (6)","s"]]]],"f":[["(6)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.332)."]]},{"b":[["n",[["حضرت ابو برثنؒ کے آزاد کردہ غلام حضرت عبدالرحمٰنؒ","b"],[" کہتے ہیں ایک صاحب جو غزوہ حنین کے دن مشرکوں کے ساتھ تھے انہوں نے مجھے یہ واقعہ یوں بتایا کہ جب ہم نے انہیں شکست دے دی تو ہم ان کا پیچھا کر رہے تھے یہاں تک کہ ہم لوگ سفید خچر والے سوار تک پہنچ گئے۔ ہم نے دیکھا تو وہ حضورؐ تھے۔ حضورؐ کے پاس ہمیں گورے چٹے خوبصورت چہرے والے لوگ ملے۔ انہوں نے ہم سے کہا (تمہارے) چہرے بگڑ جائیں، جاؤ۔ بس اس پر ہمیں شکست ہو گئی اور صحابہؓ ہمارے اوپر سوار ہو گئے اور وہ جیت گئے۔ یہ تھا ہماری شکست کا قصہ۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Jareer, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.345)."]]},{"b":[["n",[["حضرت جبیر بن مطعمؓ","b"],[" فرماتے ہیں غزوہ حنین کے دن ہم لوگ حضورؐ کے ساتھ تھے اور لوگ لڑ رہے تھے کہ مجھے اچانک نظر پڑی تو مجھے ایک کالی چادر آسمان سے اترتی ہوئی نظر آئی جو ہمارے اور کافروں کے درمیان آ کر گر پڑی۔ وہ چیونٹیاں تھیں جو بکھر گئیں اور ساری وادی میں پھیل گئیں، اس کے بعد کافروں کو یکدم شکست ہو گئی۔ ہمیں ان چیونٹیوں کے فرشتے ہونے میں کوئی شک نہیں تھا۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Is'haaq, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.334)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن فضلؒ","b"],[" کہتے ہیں حضورؐ نے جنگ احد کے دن حضرت مصعب بن عمیرؓ کو جھنڈا دیا۔ جب حضرت مصعبؓ شہید ہو گئے تو ایک فرشتے نے اس جھنڈے کو پکڑ لیا جو کہ حضرت مصعبؓ کی شکل میں تھا۔ دن کے آخری حصہ میں حضورؐ اس سے فرمانے لگے اے مصعب! آگے بڑھو۔ اس فرشتے نے حضورؐ کی طرف متوجہ ہو کر کہا میں مصعب نہیں ہوں، تب حضورؐ کو پتہ چلا کہ یہ فرشتہ ہے جو حضورؐ کی مدد و نصرت کے لیے آیا ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Sa'd (Vol.3 Pg.121)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" نے فرمایا جب حضورؐ قبیلہ بنو قریظہ کی طرف تشریف لے گئے اس وقت حضرت جبرائیل علیہ السلام اپنی سواری پر سوار ہو کر قبیلہ بنی غنم کی گلی میں سے گزرے تھے جس سے اس گلی میں غبار اٹھا تھا، وہ غبار اب بھی گویا کہ مجھے نظر آ رہا ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Nu'aym in his Dalaa'il (Pg.182). Ibn Sa'd (Vol.2 Pg.76) has reported a similar narration."]]},{"b":[["n",[["حضرت حمید بن ہلالؒ","b"],[" نے بنو قریظہ کے غزوے کے بارے میں پوری حدیث بیان کی اور اس میں یہ بھی ہے کہ حضورؐ اور آپ کے صحابہؓ نے (غزوہ خندق سے فارغ ہو کر) ہتھیار رکھ دیے تو حضرت جبرائیل علیہ السلام حضورؐ کی خدمت میں حاضر ہوئے۔ حضورؐ حضرت جبرائیلؑ کے پاس باہر تشریف لائے۔ حضرت جبرائیلؑ اپنے گھوڑے کے سینے پر سہارا لے کر کھڑے ہوئے تھے اور ان کی پلکوں پر خوب غبار پڑا ہوا تھا۔ حضورؐ نیچے تشریف لائے تو حضرت جبرائیلؑ نے عرض کیا ہم نے تو ابھی تک ہتھیار نہیں رکھے، بنو قریظہ کی طرف تشریف لے چلیں (ان سے جنگ کرنی ہے)۔ حضورؐ نے فرمایا میرے ساتھی تھکے ہوئے ہیں، آپ انہیں چند دن کی مہلت دے دیں تو اچھا ہے۔ حضرت جبرائیلؑ نے عرض کیا نہیں، آپ ابھی وہاں تشریف لے چلیں، میں اپنے اس گھوڑے کو ان کے قلعوں میں گھسا دوں گا اور ان کے سارے قلعے گرا کر زمین کے برابر کر دوں گا۔ چنانچہ حضرت جبرائیلؑ اور ان کے ساتھ جتنے فرشتے تھے یہ سب وہاں سے پشت پھیر کر چلے تو انصار کے قبیلہ بنی غنم کی گلیوں میں غبار اڑنے لگا۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Sa'd (Vol.2 Pg.77)."]]}]},"221":{"lead":[],"stories":[{"b":[["n",[["حضرت سہیل بن عمروؓ","b"],[" نے فرمایا میں نے جنگ بدر کے دن بہت سے گورے چٹے آدمی دیکھے جو چتکبرے گھوڑوں پر آسمان اور زمین کے درمیان سوار تھے، ان پر نشانیاں لگی ہوئی تھیں، وہ جنگ بھی کر رہے تھے اور کافروں کو قید بھی کر رہے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir and Waaqidi, as quoted in Kanzul Ummaal (Vol.5 Pg.268)."]]},{"b":[["n",[["حضرت براءؓ","b"],[" وغیرہ حضرات فرماتے ہیں ایک انصاری صحابی حضرت عباسؓ کو قید کر کے لائے (حضرت عباسؓ نے اس وقت تک اپنا مسلمان ہونا ظاہر نہیں کیا تھا اس لیے وہ جنگ بدر میں کافروں کے ساتھ تھے)۔ حضرت عباسؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! انہوں نے مجھے قید نہیں کیا بلکہ مجھے تو ایسے آدمی نے قید کیا ہے جس کے سر کا شروع کا حصہ گنجا تھا اور اس کی شکل و صورت ایسی اور ایسی تھی۔ حضورؐ نے ان انصاری سے فرمایا ",""],["ٱللَّٰه","a"],[" نے ایک کریم فرشتے کے ذریعہ تمہاری مدد فرمائی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.85)."]]},{"b":[["n",[["حضرت علیؓ نے غزوہ بدر کے بارے میں ایک لمبی حدیث بیان فرمائی ہے۔ اس میں یہ بھی ہے کہ ایک انصاری صحابی حضرت عباس بن عبدالمطلبؓ کو قید کر کے لائے۔ حضرت عباسؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" کی قسم! انہوں نے مجھے قید نہیں کیا، مجھے تو اس آدمی نے قید کیا ہے جو کنپٹی سے گنجا تھا، اس کا چہرہ سب سے زیادہ خوبصورت تھا اور چتکبرے گھوڑے پر سوار تھا، اب وہ مجھے مسلمانوں میں نظر نہیں آ رہا۔ ان انصاری نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے انہیں قید کیا ہے۔ حضورؐ نے فرمایا اے میاں! خاموش رہو، ",""],["ٱللَّٰه","a"],[" نے ایک کریم فرشتے کے ذریعہ تمہاری مدد فرمائی ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Shaybah, Ahmad, Ibn Jareer and Bayhaqi, as quoted in Kanzul Ummaal (Vol.5 Pg.266). Haythami (Vol.6 Pg.75) has attributed the narration to Ahmad and Bazzaar."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضرت عباسؓ کو بنو سلمہ کے حضرت ابوالیسر کعب بن عمروؓ نے قید کیا تھا۔ حضرت ابوالیسرؓ ایک پست قد آدمی تھے اور حضرت عباسؓ قد آور اور بڑے ڈیل ڈول والے تھے۔ حضورؐ نے حضرت ابوالیسرؓ سے فرمایا اے ابوالیسر! تم نے عباس کو کیسے قید کر لیا؟ انہوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! انہیں قید کرنے میں ایک آدمی نے میری مدد کی ہے جسے نہ میں نے جنگ سے پہلے دیکھا ہے اور نہ اب جنگ کے بعد وہ نظر آ رہا ہے۔ اس کی شکل و صورت ایسی اور ایسی تھی۔ حضورؐ نے فرمایا ایک کریم فرشتے نے اس میں تمہاری مدد کی ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Sa'd (Vol.4 Pg.12). Ahmad has reported a similar narration, but Haythami (Vol.6 Pg.86) has commented on the chain of narrators. Abu Nu'aym has also reported the narration in his Dalaa'il (Pg.169)."]]},{"b":[["n",[["حضرت ابن عباسؓ فرماتے ہیں ایک مشرک آگے تھا اور ایک انصاری مسلمان اس کے پیچھے دوڑ رہا تھا کہ اتنے میں اس مسلمان نے اپنے اوپر کی جانب کوڑا مارنے کی آواز سنی اور ایک گھوڑے سوار کو یہ کہتے ہوئے سنا اے حیزوم! (یہ حضرت جبرائیل علیہ السلام کے گھوڑے کا نام ہے) آگے بڑھ۔ اس مسلمان نے دیکھا تو وہ مشرک پشت کے بل نیچے گرا ہوا تھا اور کوڑے کی مار سے اس کی ناک زخمی تھی اور چہرہ پھٹا ہوا تھا اور یہ سارا حصہ نیلا ہو چکا تھا۔ اس انصاری نے حضورؐ کی خدمت میں حاضر ہو کر یہ واقعہ بیان کیا۔ حضورؐ نے فرمایا تم سچ کہتے ہو، یہ تیسرے آسمان سے مدد آئی تھی۔ چنانچہ مسلمانوں نے اس دن ستر کافروں کو قتل کیا اور ستر کو قید کیا۔",""],[" (5)","s"]]]],"f":[["(5)","Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.3 Pg.279)."]]},{"b":[["n",[["حضرت ابن عباسؓ فرماتے ہیں کہ قبیلہ بنی غفار کے ایک آدمی نے بیان کیا کہ میں اور میرے ایک چچازاد بھائی ہم دونوں ایک پہاڑ پر چڑھے جہاں سے ہمیں میدان بدر اچھی طرح نظر آ رہا تھا۔ ہم دونوں ان دنوں مشرک تھے اور یہ انتظار کر رہے تھے کہ کسے شکست ہوتی ہے تاکہ ہم جیتنے والوں کے ساتھ مل کر لوٹ مار کریں۔ ہم ابھی پہاڑ پر تھے کہ اتنے میں ہمارے قریب سے ایک بادل گزرا جس میں سے ہمیں گھوڑے کے ہنہنانے کی آواز سنائی دی اور کسی کو یہ کہتے ہوئے سنا اے حیزوم! آگے بڑھ۔ یہ سن کر میرے چچازاد بھائی کے دل کا پردہ پھٹ گیا اور وہ وہیں مر گیا، میں بھی مرنے کے قریب ہو گیا تھا لیکن مشکل سے اپنے آپ کو سنبھالا۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Dalaa'il (Pg.170)."]]},{"b":[["n",[["حضرت ابوطلحہؓ","b"],[" فرماتے ہیں ہم لوگ ایک غزوہ میں حضورؐ کے ساتھ تھے، دشمن سے مقابلہ ہوا۔ میں نے حضورؐ کو یہ دعا کرتے ہوئے سنا",""]]],["q",[["مَالِكِ يَوْمِ ٱلدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","a"]]],["p",[["ترجمہ: \"اے روز جزا کے مالک! ہم تیری ہی عبادت کرتے ہیں اور تجھ ہی سے مدد مانگتے ہیں۔\" میں نے دیکھا کہ دشمن کے آدمی گرتے چلے جا رہے ہیں اور فرشتے انہیں آگے سے پیچھے سے مار رہے ہیں۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Dalaa'il (Pg.164)."]]},{"b":[["n",[["حضرت ابوامامہ بن سہلؒ","b"],[" کہتے ہیں میرے والد (حضرت سہلؓ) نے فرمایا اے میرے بیٹے! ہم نے غزوہ بدر میں ",""],["ٱللَّٰه","a"],[" کی غیبی نصرت کی وجہ سے اپنا یہ حال دیکھا تھا کہ ہم میں سے کوئی آدمی مشرک کے سر کی طرف اشارہ کر دیتا تو اس کا سر تلوار لگنے سے پہلے ہی جسم سے کٹ کر نیچے گر جاتا۔",""],[" (8)","s"]]]],"f":[["(8)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.3 Pg.281). Haakim (Vol.3 Pg.409), reporting from reliable sources as confirmed by Dhahabi. Tabraani has reported a similar narration but Haythami (Vol.6 Pg.84) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابو واقد لیثیؓ","b"],[" فرماتے ہیں میں ایک مشرک کا پیچھا کر رہا تھا تاکہ میں اس پر تلوار کا وار کروں لیکن میری تلوار اس تک پہنچنے سے پہلے ہی اس کا سر کٹ کر زمین پر گر گیا جس سے میں سمجھ گیا کہ میرے علاوہ کسی اور (نظر نہ آنے والی مخلوق یعنی فرشتے) نے اسے قتل کیا ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Is'haaq, as quoted in Al Bidaayah wan Nihaayah (Vol.3 Pg.281). Ahmad has reported the same words from Abu Dawood Maazini who participated in Badr; Haythami (Vol.6 Pg.83) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.170)."]]},{"b":[["n",[["حضرت سہل بن ابی حثمہؓ","b"],[" فرماتے ہیں حضرت ابو بردہ حارثؓ جنگ بدر کے دن (مشرکوں کے) تین سر اٹھائے ہوئے حضورؐ کی خدمت میں حاضر ہوئے۔ حضورؐ نے جب انہیں دیکھا تو فرمایا تمہارا دایاں ہاتھ کامیاب رہا۔ انہوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ان میں سے دو کو تو میں نے قتل کیا اور تیسرے کی صورت یہ ہوئی کہ میں نے ایک خوبصورت، خوب رو اور گورا چٹا آدمی دیکھا جس نے اس کا سر تن سے جدا کر دیا۔ حضورؐ نے فرمایا وہ فلاں فرشتہ تھا۔",""],[" (10)","s"]]]],"f":[["(10)","Tabraani. Haythami (Vol.6 Pg.83) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت محمود بن لبیدؒ","b"],[" کہتے ہیں حضرت حارث بن صمہؓ نے فرمایا حضورؐ ایک گھاٹی میں تھے، آپ نے مجھ سے پوچھا کیا تم نے عبدالرحمٰن بن عوف کو دیکھا؟ میں نے عرض کیا جی ہاں، یا رسول ",""],["ٱللَّٰه","a"],["! میں نے انہیں پہاڑ کے دامن میں دیکھا تھا اور کافروں کی ایک فوج نے ان پر حملہ کیا ہوا تھا، اس لیے میں نیچے اترنے لگا (تاکہ ان کی مدد کروں) لیکن راستہ میں آپؐ مجھے نظر آ گئے تو میں انہیں چھوڑ کر آپؐ کے پاس آ گیا۔ حضورؐ نے فرمایا غور سے سنو! فرشتے ان کے ساتھ مل کر کافروں سے جنگ کر رہے ہیں۔ حضرت حارثؓ کہتے ہیں میں وہاں سے حضرت عبدالرحمٰنؓ کی طرف چل پڑا۔ میں نے وہاں جا کر دیکھا کہ مشرکوں کا لشکر جا چکا ہے اور حضرت عبدالرحمٰنؓ کے چاروں طرف سات مشرک قتل ہوئے پڑے ہیں۔ میں نے کہا آپ کا دایاں ہاتھ کامیاب ہو گیا، کیا آپ نے اکیلے ان سب کو قتل کیا ہے؟ انہوں نے کہا یہ ارطات بن عبد شرجیل ہے اور یہ دوسرا کافر ہے، ان دو کو تو میں نے قتل کیا ہے اور باقی ان پانچ کو اس شخص نے قتل کیا ہے جو مجھے نظر نہیں آ رہا تھا۔ میں نے کہا ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ نے سچ کہا۔",""],[" (11)","s"]]]],"f":[["(11)","Tabraani and Bazzaar. Haythami (Vol.6 Pg.114) has commented on the chain of narrators. Ibn Mandah and Abu Nu'aym have reported a similar narration, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.76)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" نے فرمایا حضورؐ مکہ میں کچھ لوگوں کے پاس سے گزرے، وہ پیچھے سے اشارہ کر کے حضورؐ کے بارے میں کہنے لگے یہ وہ آدمی ہے جو یہ دعویٰ کرتا ہے کہ وہ نبی ہے، اور اس وقت حضورؐ کے ساتھ حضرت جبرائیل علیہ السلام بھی تھے۔ حضرت جبرائیلؑ نے ان کافروں کی طرف انگلی سے اشارہ کیا تو ایک دم ان کے جسم پر ناخن جیسے نشان پڑ گئے جو بعد میں زخم بن گئے اور سڑ گئے جس سے ان میں بدبو پیدا ہو گئی اور اس وجہ سے کوئی بھی ان کے قریب نہ جا سکا۔ اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیت نازل فرمائی",""]]],["q",[["إِنَّا كَفَيْنَـٰكَ ٱلْمُسْتَهْزِءِينَ","a"]]],["p",[["ترجمہ: \"یہ لوگ جو ہنستے ہیں (اور) ",""],["ٱللَّٰه","a"],[" تعالیٰ کے ساتھ دوسرا معبود قرار دیتے ہیں ان سے آپ کے لیے ہم کافی ہیں۔\" (سورۂ حجر، آیت 95)۔",""],[" (12)","s"]]]],"f":[["(12)","Tabraani and Bazzaar. Haythami (Vol.7 Pg.46) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جو فرمایا ہے",""]]],["q",[["إِنَّا كَفَيْنَـٰكَ ٱلْمُسْتَهْزِءِينَ اس سے مراد ہنسنے والے اور مذاق اڑانے والے کافر ولید بن مغیرہ، اسود بن عبد یغوث، اسود بن مطلب ابو زمعہ جو کہ قبیلہ بنو اسد بن عبدالعزیٰ میں سے تھا، حارث بن عیطل سہمی اور عاصی بن وائل تھے۔ حضرت جبرائیلؑ حضورؐ کے پاس آئے تو حضورؐ نے ان سے کافروں کی شکایت کی۔ حضرت جبرائیلؑ نے کہا آپ مجھے یہ لوگ دکھا دیں۔ چنانچہ حضورؐ نے انہیں ولید بن مغیرہ دکھایا، حضرت جبرائیلؑ نے ولید کے بازو کی بڑی رگ کی طرف بس ایک اشارہ ہی کیا۔ حضورؐ نے فرمایا آپ نے تو کچھ بھی نہیں کیا؟ حضرت جبرائیلؑ نے کہا اب آپ کو کچھ کرنے کی ضرورت نہیں، میں نے اس کا انتظام کر دیا ہے۔ پھر حضورؐ نے انہیں حارث بن عیطل سہمی دکھایا۔ حضرت جبرائیلؑ نے اس کے پیٹ کی طرف اشارہ کیا۔ حضورؐ نے فرمایا آپ نے کچھ تو کیا نہیں؟ حضرت جبرائیلؑ نے کہا اب آپ کو کچھ کرنے کی ضرورت نہیں، میں نے اس کا انتظام کر دیا ہے۔ پھر حضورؐ نے عاصی بن وائل دکھایا، حضرت جبرائیلؑ نے اس کے تلوے کی طرف اشارہ کیا۔ حضورؐ نے فرمایا آپ نے کچھ تو کیا نہیں؟ حضرت جبرائیلؑ نے کہا اب آپ کو کچھ کرنے کی ضرورت نہیں، میں نے اس کا انتظام کر دیا ہے۔ چنانچہ ولید بن مغیرہ کا یہ ہوا کہ وہ قبیلہ خزاعہ کے ایک آدمی کے پاس سے گزرا جو اپنا تیر چھیل رہا تھا، وہ تیر ولید کے بازو کی بڑی رگ کو لگ گیا جس سے وہ رگ کٹ گئی۔ اور اسود بن مطلب اندھا ہو گیا۔ بعض کہتے ہیں ویسے ہی اندھا ہو گیا، بعض کہتے ہیں وہ ایک درخت کے نیچے لیٹا ہوا تھا کہ کہنے لگا اے میرے بیٹو! کیا تم مجھے نہیں بچاتے؟ میں تو ہلاک ہو گیا، میری آنکھوں میں کانٹے چبھ رہے ہیں۔ اس کے بیٹوں نے کہا ہمیں تو کچھ نظر نہیں آ رہا۔ کچھ دیر اسے یوں ہی کانٹے چبھتے رہے پھر اس کی دونوں آنکھیں اندھی ہو گئیں۔ اور اسود بن عبد یغوث کے سر میں پھوڑے نکل آئے جن سے وہ مر گیا۔ اور حارث بن عیطل کے پیٹ میں صفرا یعنی زرد پانی کا زور ہو گیا، آخر پاخانہ منہ کے راستے سے آنے لگا جس سے وہ مر گیا۔ اور عاصی بن وائل چلا جا رہا تھا، اس کے پاؤں میں شبرقہ نامی کانٹے دار جھاڑی کا کانٹا لگ گیا جس سے اس کا پاؤں سوج گیا اور وہ مر گیا۔","a"],[" (13)","s"]]]],"f":[["(13)","Tabraani. Haythami (Vol.7 Pg.47) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ حضورؐ کے صحابہؓ میں سے ایک صحابی کی کنیت ابو معلق تھی اور وہ تاجر تھے، اپنے اور دوسروں کے مال سے تجارت کیا کرتے تھے اور وہ بہت عبادت گزار اور پرہیزگار تھے۔ ایک مرتبہ وہ سفر میں گئے، انہیں راستہ میں ایک ہتھیاروں سے مسلح ڈاکو ملا، اس نے کہا اپنا سارا سامان یہاں رکھ دو، میں تمہیں قتل کروں گا۔ اس صحابی نے کہا تم نے مال لینا ہے وہ لے لو۔ ڈاکو نے کہا نہیں، میں تو تمہارا خون بہانا چاہتا ہوں۔ اس صحابی نے کہا مجھے ذرا مہلت دو، میں نماز پڑھ لوں۔ اس نے کہا جتنی پڑھنی ہے پڑھ لو۔ چنانچہ انہوں نے وضو کر کے نماز پڑھی اور یہ دعا تین مرتبہ مانگی",""]]],["q",[["يَا وَدُودُ يَا ذَا ٱلْعَرْشِ ٱلْمَجِيدِ يَا فَعَّالًا لِّمَا يُرِيدُ أَسْأَلُكَ بِعِزَّتِكَ ٱلَّتِي لَا تُرَامُ وَمُلْكِكَ ٱلَّذِي لَا يُضَامُ وَبِنُورِكَ ٱلَّذِي مَلَأَ أَرْكَانَ عَرْشِكَ أَنْ تَكْفِيَنِي شَرَّ هَذَا ٱللِّصِّ يَا مُغِيثُ أَغِثْنِي","a"]]],["p",[["ترجمہ: \"اے بہت محبت کرنے والے! اے بڑے عرش والے! اے ہر اس کام کو کر لینے والے جس کا تو ارادہ کرے! میں تیری اس عزت کے واسطے سے جس کو کوئی مانگنے کا سوچ بھی نہیں سکتا اور تیری اس بادشاہت کے واسطے سے جس پر کوئی غالب نہیں آ سکتا اور تیرے اس نور کے واسطے سے جس نے تیرے عرش کے تمام کونوں کو بھرا ہوا ہے، یہ سوال کرتا ہوں کہ مجھے اس ڈاکو کے شر سے بچا لے، اے فریاد رس! میری فریاد کو پہنچ۔\" تو اچانک ایک گھوڑے سوار نمودار ہوا جس کے ہاتھ میں ایک نیزہ تھا جسے اٹھا کر اس نے اپنے گھوڑے کے کانوں کے درمیان بلند کیا ہوا تھا۔ اس نے اس ڈاکو کو نیزہ مار کر قتل کر دیا، پھر وہ اس تاجر کی طرف متوجہ ہوا۔ تاجر نے اس سے پوچھا تم کون ہو؟ ",""],["ٱللَّٰه","a"],[" نے تمہارے ذریعے سے میری مدد فرمائی ہے۔ اس نے کہا میں چوتھے آسمان کا فرشتہ ہوں۔ جب آپ نے (پہلی مرتبہ) دعا کی تو میں نے آسمان کے دروازوں کی کھڑکھڑاہٹ سنی۔ جب آپ نے دوبارہ دعا کی تو میں نے آسمان والوں کی چیخ و پکار سنی، پھر آپ نے تیسری مرتبہ دعا کی تو کسی نے کہا یہ ایک مصیبت زدہ کی دعا ہے، میں نے ",""],["ٱللَّٰه","a"],[" تعالیٰ کی بارگاہ میں عرض کیا کہ اس ڈاکو کو قتل کرنے کا کام میرے ذمہ کر دیں۔ پھر اس فرشتے نے کہا آپ کو خوشخبری ہو کہ جو آدمی بھی وضو کر کے چار رکعت نماز پڑھے اور پھر یہ دعا مانگے اس کی دعا ضرور قبول ہوگی چاہے وہ مصیبت زدہ ہو یا نہ ہو۔",""],[" (14)","s"]]]],"f":[["(14)","Ibn Abi Dunya in Mujaabud Da'wah and Abu Moosa in Kitaabul Wazaa'if, as quoted in Isaabah (Vol.4 Pg.182)."]]},{"b":[["n",[["حضرت لیث بن سعدؒ","b"],[" کہتے ہیں مجھے یہ بات پہنچی ہے کہ حضرت زید بن حارثہؓ نے اپنا قصہ اس طرح سنایا کہ میں نے طائف کے ایک آدمی سے ایک خچر کرایہ پر لیا۔ کرایہ پر دینے والے نے یہ شرط لگائی کہ وہ راستہ میں جس منزل پر چاہے گا مجھے ٹھہرائے گا۔ چنانچہ وہ مجھے ایک ویرانے کی طرف لے کر چل پڑا اور وہاں پہنچ کر اس نے کہا یہاں اتر جاؤ۔ میں وہاں اتر گیا تو دیکھا کہ بہت سے لوگ وہاں قتل ہوئے پڑے تھے۔ جب وہ مجھے قتل کرنے لگا تو میں نے کہا مجھے ذرا دو رکعت نماز پڑھنے دو۔ اس نے کہا پڑھ لو، تم سے پہلے ان لوگوں نے بھی نماز پڑھی تھی لیکن نماز سے انہیں کوئی فائدہ نہیں ہوا تھا۔ جب میں نماز پڑھ چکا تو وہ مجھے قتل کرنے کے لیے آگے بڑھا تو میں نے کہا یا ارحم الراحمین! تو اس نے ایک آواز سنی کہ اسے قتل نہ کرو۔ وہ ایک دم ڈر گیا اور اس آواز والے کو تلاش کرنے گیا تو اسے کوئی نظر نہ آیا۔ وہ پھر لوٹ کر واپس آیا تو میں نے اونچی آواز سے کہا یا ارحم الراحمین! اس طرح تین مرتبہ ہوا، پھر اچانک گھوڑے پر ایک سوار نمودار ہوا، اس کے ہاتھ میں لوہے کا ایک نیزہ تھا اور اس نیزے کے سرے سے آگ کا شعلہ نکل رہا تھا۔ اس سوار نے اس کو اس زور سے نیزہ مارا کہ پار ہو کر کمر کی طرف نکل آیا اور وہ مر کر زمین پر گر گیا۔ پھر مجھ سے کہا جب تم نے پہلی مرتبہ یا ارحم الراحمین! کہہ کر پکارا تھا اس وقت میں ساتویں آسمان پر تھا، جب تم نے دوبارہ پکارا تھا تو میں آسمان دنیا پر تھا، جب تم نے تیسری بار پکارا تھا تو میں آپ کے پاس پہنچ گیا۔",""],[" (15)","s"]]]],"f":[["(15)","Ibn Abdul Barr in his Isti'aab (Vol.1 Pg.548)."]]}]},"222":{"lead":[],"stories":[{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں ایک مرتبہ حضورؐ نے کسی شخص کی آواز سنی تو آپؐ جلدی سے اٹھے اور گھر کے باہر اس کے پاس گئے۔ میں بھی دیکھنے کے لیے آپؐ کے پیچھے گئی تو میں نے دیکھا کہ ایک آدمی اپنے ترکی گھوڑے کی گردن کے بالوں پر سہارا لگائے کھڑا ہے۔ جب میں نے ذرا غور سے دیکھا تو ایسے لگا کہ یہ حضرت دحیہ کلبیؓ ہیں اور وہ پگڑی باندھے ہوئے ہیں جس کا شملہ ان کے کندھوں کے درمیان لٹکا ہوا ہے۔ جب حضورؐ میرے پاس اندر تشریف لائے تو میں نے عرض کیا کہ آپؐ بہت تیزی سے اٹھ کر باہر گئے تھے، میں نے بھی باہر جا کر دیکھا تو وہ حضرت دحیہ کلبیؓ تھے (ان کی وجہ سے آپؐ کو اتنی جلدی کرنے کی ضرورت نہیں تھی)۔ حضورؐ نے فرمایا کیا تم نے انہیں دیکھا ہے؟ میں نے عرض کیا جی ہاں! فرمایا یہ حضرت جبرائیلؑ تھے، انہوں نے مجھے کہا ہے کہ میں بنو قریظہ پر حملہ کرنے کے لیے چلوں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Dalaa'il (Pg.182). Ibn Sa'd (Vol.4 Pg.250) has reported a similar narration."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" بنو قریظہ کے بارے میں لمبی حدیث بیان کرتے ہیں جس میں یہ مضمون بھی ہے کہ نبی کریمؐ بنو قریظہ تشریف لے چلے تو راستہ میں نبی کریمؐ کا صحابہ کرامؓ کی کئی مجلسوں پر گزر ہوا۔ حضورؐ نے ان سے پوچھا کیا ابھی تمہارے پاس سے کوئی گزرا ہے؟ ان سب نے کہا جی ہاں! ابھی حضرت دحیہ کلبیؓ گزرے تھے جو سفید خچر پر سوار تھے، ان کے نیچے ایک ریشمی چادر بھی تھی۔ حضورؐ نے فرمایا وہ حضرت دحیہؓ نہیں تھے بلکہ حضرت جبرائیلؑ تھے جنہیں بنو قریظہ کی طرف اس لیے بھیجا گیا ہے تاکہ وہ ان کے قلعوں کو ہلا کر ان کے دلوں میں رعب ڈال دیں۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Dalaa'il (Pg.182)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ ایک انصاری کی عیادت کے لیے تشریف لے گئے۔ جب حضورؐ ان کے گھر کے قریب پہنچے تو حضورؐ نے سنا کہ وہ انصاری گھر کے اندر کسی سے بات کر رہے ہیں۔ جب حضورؐ اجازت لے کر اندر تشریف لے گئے تو آپؐ کو وہاں کوئی نظر نہ آیا۔ آپؐ نے ان سے پوچھا ابھی میں سن رہا تھا کہ تم کسی سے باتیں کر رہے تھے۔ انہوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! لوگوں نے میرے بخار کی وجہ سے دو باتیں کیں، ان سے مجھے بہت غم و صدمہ ہوا، اس وجہ سے میں اندر آ گیا، پھر میرے پاس اندر ایک آدمی آیا، آپؐ کے بعد میں نے ایسا کوئی آدمی نہیں دیکھا جو اس سے زیادہ عمدہ مجلس والا اور زیادہ اچھی بات والا ہو۔ حضورؐ نے فرمایا یہ حضرت جبرائیلؑ تھے اور تم میں کچھ لوگ ایسے بھی ہیں کہ اگر وہ ",""],["ٱللَّٰه","a"],[" پر قسم کھا لیں تو ",""],["ٱللَّٰه","a"],[" ان کی قسم ضرور پوری کر دے۔",""],[" (3)","s"]]]],"f":[["(3)","Bazzaar and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.41)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں میں اپنے والد کے ساتھ حضورؐ کی خدمت میں حاضر تھا۔ آپؐ کے پاس ایک آدمی تھا جو آپؐ کے کان میں چپکے چپکے باتیں کر رہا تھا جس کی وجہ سے آپؐ نے میرے والد سے اعراض کیے رکھا۔ جب ہم حضورؐ کے پاس سے باہر آئے تو میرے والد نے کہا اے میرے بیٹے! کیا تم نے اپنے چچازاد بھائی کو نہیں دیکھا کہ انہوں نے مجھ سے اعراض کیے رکھا؟ میں نے کہا ابا جان آپؐ کے پاس تو ایک آدمی تھا جو ان کے کان میں چپکے چپکے باتیں کر رہا تھا۔ ہم پھر دوبارہ حضورؐ کی خدمت میں گئے، میرے والد نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے اپنے بیٹے عبد",""],["ٱللَّٰه","a"],[" سے یہ اور یہ بات کہی، اس نے مجھے بتایا کہ آپؐ کے پاس ایک آدمی تھا جو آپؐ کے کان میں چپکے چپکے باتیں کر رہا تھا، تو کیا آپؐ کے پاس کوئی تھا؟ حضورؐ نے فرمایا اے عبد",""],["ٱللَّٰه","a"],["! کیا تم نے اسے دیکھا ہے؟ میں نے کہا جی ہاں! حضورؐ نے فرمایا یہ حضرت جبرائیلؑ تھے، ان ہی کی وجہ سے میں آپ کی طرف متوجہ نہ ہو سکا۔",""],[" (4)","s"]]]],"f":[["(4)","Ahmad and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.276)."]]},{"b":[["n",[["حضرت ابن عباسؓ نے فرمایا حضرت عباسؓ نے مجھے کسی کام سے حضورؐ کی خدمت میں بھیجا۔ حضورؐ کے پاس کوئی آدمی بیٹھا ہوا تھا، اس لیے میں نے حضورؐ سے کوئی بات نہ کی بلکہ ویسے ہی واپس آ گیا۔ بعد میں حضورؐ نے پوچھا کیا تم نے اس آدمی کو دیکھا تھا؟ میں نے عرض کیا جی ہاں! فرمایا یہ حضرت جبرائیلؑ تھے۔ اس کے بعد حضورؐ نے میرے بارے میں فرمایا انہیں علم خوب دیا جائے گا لیکن مرنے سے پہلے ان کی بینائی جاتی رہے گی (چنانچہ بعد میں ",""],["ٱللَّٰه","a"],[" نے ایسے ہی کیا)۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.277)."]]},{"b":[["n",[["حضرت عروہ بن رویمؒ","b"],[" کہتے ہیں حضرت عرباض بن ساریہؓ حضورؐ کے صحابہؓ میں سے تھے، بہت بوڑھے ہو گئے تھے اور چاہتے تھے کہ انہیں موت آ جائے، اس لیے یہ دعا کرتے تھے اے ",""],["ٱللَّٰه","a"],["! میری عمر بڑی ہو گئی اور میری ہڈیاں پتلی اور کمزور ہو گئیں، لہٰذا مجھے اپنے پاس اٹھا لے۔ حضرت عرباضؓ فرماتے ہیں ایک دن میں دمشق کی مسجد میں تھا، وہاں مجھے ایک نوجوان نظر آیا جو بہت حسین و جمیل تھا۔ اس نے سبز جوڑا پہنا ہوا تھا۔ اس نے کہا آپ یہ کیا دعا کرتے ہیں؟ میں نے اس سے کہا اے میرے بھتیجے! پھر میں کیا دعا کروں؟ اس نے کہا آپ یہ دعا کریں اے ",""],["ٱللَّٰه","a"],["! میرے عمل اچھے کر دے اور مجھے موت تک پہنچا دے۔ میں نے کہا ",""],["ٱللَّٰه","a"],[" تم پر رحم کرے، تم کون ہو؟ اس نے کہا میں ریبائیل (وہ فرشتہ) ہوں جو مومنوں کے دلوں سے تمام غم نکالتا ہوں۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani. Haythami (Vol.10 Pg.184) has commented on the chain of narrators."]]}]},"223":{"lead":[],"stories":[{"b":[["n",[["حضرت مطرف بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں مجھ سے حضرت عمران بن حصینؓ نے فرمایا اے مطرف! یہ بات جان لو کہ فرشتے میرے سر کے پاس اور میرے کمرے کے پاس اور حطیم کعبہ کے پاس آ کر مجھے سلام کیا کرتے تھے اور اب میں نے اپنے آپ کو (علاج کے لیے) لوہے سے داغ دیا تو یہ بات جاتی رہی۔ چنانچہ جب ان کے زخم ٹھیک ہو گئے تو مجھ سے فرمایا اے مطرف! جان لو کہ جو بات جاتی رہی تھی وہ اب پھر دوبارہ شروع ہو گئی ہے، لیکن اے مطرف! میرے مرنے تک میرا یہ راز چھپائے رکھنا۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim (Vol.3 Pg.472)."]]},{"b":[["n",[["حضرت مطرفؒ","b"],[" کہتے ہیں حضرت عمران بن حصینؓ نے مجھ سے فرمایا کیا تمہیں پتہ چلا کہ فرشتے مجھے سلام کیا کرتے تھے؟ لیکن جب میں نے اپنے آپ کو داغ دیا تو پھر سلام کا یہ سلسلہ ختم ہو گیا۔ میں نے کہا وہ فرشتے آپ کے سر کی طرف سے آتے تھے یا پیروں کی طرف سے؟ انہوں نے فرمایا پیروں کی طرف سے نہیں، وہ سر کی طرف سے آتے تھے۔ میں نے کہا میرا خیال یہ ہے کہ آپ کے مرنے سے پہلے یہ سلسلہ پھر شروع ہو جائے گا۔ کچھ عرصہ کے بعد مجھ سے انہوں نے فرمایا کیا تمہیں پتہ چلا کہ سلام کا سلسلہ پھر شروع ہو گیا ہے؟ اس کے چند دن بعد ہی ان کا انتقال ہو گیا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.4 Pg.289)."]]},{"b":[["n",[["حضرت قتادہؒ","b"],[" فرماتے ہیں فرشتے حضرت عمران بن حصینؓ سے مصافحہ کیا کرتے تھے لیکن جب انہوں نے اپنے آپ کو داغ دیا تو فرشتے ہٹ گئے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Sa'd (Vol.4 Pg.288)."]]}]},"224":{"lead":[],"stories":[{"b":[["n",[["حضرت سلمہ بن عطیہ اسدیؒ","b"],[" کہتے ہیں حضرت سلمانؓ ایک آدمی کی عیادت کے لیے گئے، وہ نزع کی حالت میں تھا، تو حضرت سلمانؓ نے فرمایا اے فرشتے! ان کے ساتھ نرمی کرو۔ اس بیمار آدمی نے کہا وہ فرشتہ کہہ رہا ہے میں ہر مومن کے ساتھ نرمی کرتا ہوں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.204)."]]}]},"225":{"lead":[],"stories":[{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں ایک مرتبہ حضرت ابی بن کعبؓ نے فرمایا میں مسجد میں جاؤں گا اور ",""],["ٱللَّٰه","a"],[" کی ایسی تعریف کروں گا کہ ویسی کسی نے نہیں کی ہوگی۔ چنانچہ وہ نماز پڑھ کر ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کرنے کے لیے بیٹھے تو انہوں نے اچانک اپنے پیچھے سے ایک بلند آواز سنی کہ کوئی کہنے والا کہہ رہا ہے اے ",""],["ٱللَّٰه","a"],["! تمام تعریفیں تیرے لیے ہیں اور ساری بادشاہت تیری ہے اور ساری خیریں تیرے ہاتھ میں ہیں اور سارے چھپے اور پوشیدہ امور تیری ہی طرف لوٹتے ہیں، ساری تعریفیں تیرے لیے ہیں، تو ہر چیز پر قادر ہے، میرے پچھلے سارے گناہ معاف فرما اور آئندہ زندگی میں ہر گناہ اور ہر ناگواری سے میری حفاظت فرما اور ان پاکیزہ اعمال کی مجھے توفیق عطا فرما جن سے تو مجھ سے راضی ہو جائے اور میری توبہ قبول فرما۔ حضرت ابیؓ نے حضورؐ کی خدمت میں حاضر ہو کر سارا قصہ سنایا، آپؐ نے فرمایا یہ حضرت جبرائیلؑ تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Dunya in his Kitaabudh Dhikr, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.101)."]]}]},"226":{"lead":[],"stories":[{"b":[["n",[["حضرت ابو سعید خدریؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا جس نے عمرؓ سے بغض کیا اس نے مجھ سے بغض کیا اور جس نے عمرؓ سے محبت کی اس نے مجھ سے محبت کی اور عرفات کی شام کو ",""],["ٱللَّٰه","a"],[" نے مسلمانوں پر عام طور سے فخر کیا لیکن عمرؓ پر خاص طور پر فخر کیا اور ",""],["ٱللَّٰه","a"],[" نے جو نبی بھی بھیجا اس کی امت میں ایک محدث ضرور پیدا کیا اور اگر میری امت میں کوئی محدث ہوگا تو وہ عمرؓ ہوں گے۔ صحابہؓ نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! محدث کون ہوتا ہے؟ حضورؐ نے فرمایا جس کی زبان پر فرشتے بات کرتے ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani. Haythami (Vol.9 Pg.69) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت انس بن حلیسؒ","b"],[" کہتے ہیں ہم فارس والوں سے شکست کھا کر بہرسیر قلعہ کے اندر چلے گئے تھے اور ہم نے بہرسیر کا محاصرہ کیا ہوا تھا تو بادشاہ کے قاصد نے قلعہ کے اوپر سے جھانک کر ہمیں کہا بادشاہ آپ لوگوں سے کہہ رہا ہے کیا آپ لوگ اس شرط پر صلح کرنے کے لیے تیار ہیں کہ دریائے دجلہ کا جو کنارہ ہماری طرف ہے وہاں سے لے کر ہمارے پہاڑ تک کی جگہ ہماری ہو اور دوسرے کنارے سے لے کر تمہارے پہاڑ تک کی جگہ تمہاری ہو؟ کیا ابھی تک تمہارا پیٹ نہیں بھرا؟ ",""],["ٱللَّٰه","a"],[" کبھی تمہارا پیٹ نہ بھرے۔ تو حضرت ابومفزر اسود بن قطبہؓ لوگوں سے آگے بڑھے اور ",""],["ٱللَّٰه","a"],[" نے ان سے ایسی بات کہلوا دی جس کا نہ انہیں پتہ چلا کہ انہوں نے کیا کہا ہے اور نہ ہمیں۔ وہ قاصد واپس چلا گیا اور ہم نے دیکھا کہ وہ ٹکڑیاں بن کر بہرسیر سے مدائن شہر جا رہے ہیں۔ ہم نے کہا اے ابومفزر! آپ نے اسے کیا کہا؟ انہوں نے کہا اس ذات کی قسم جس نے حضرت محمدؐ کو حق دے کر بھیجا ہے، مجھے کچھ پتہ نہیں میں نے کیا کہا تھا، مجھے تو بس اتنا پتہ ہے کہ اس وقت مجھ پر خاص قسم کا سکینہ نازل ہوا تھا اور مجھے امید ہے کہ مجھ سے خیر کی بات کہلوائی گئی ہے۔ لوگ باری باری آ کر ان سے یہ بات پوچھتے رہے یہاں تک کہ حضرت سعدؓ نے اس بارے میں سنا، وہ ہمارے پاس تشریف لائے اور فرمایا اے ابومفزر! تم نے کیا کہا تھا؟ ",""],["ٱللَّٰه","a"],[" کی قسم! وہ تو سارے بھاگ رہے ہیں۔ حضرت ابومفزرؓ نے انہیں بھی وہی جواب دیا جو ہمیں دیا تھا۔ پھر حضرت سعدؓ نے لوگوں میں (قلعہ پر حملہ کرنے کا) اعلان کرایا اور ان کو لے کر صف آراء ہو گئے اور منجنیقوں سے قلعہ پر مسلسل پتھر پھینکنے لگیں لیکن اس قلعہ کی دیوار پر کوئی آدمی ظاہر نہ ہوا اور نہ ہی شہر سے نکل کر کوئی باہر آیا، بس ایک آدمی امان پکارتا ہوا باہر آیا، ہم نے اسے امان دے دی، اس نے کہا اب اس شہر میں کوئی نہیں رہا، تو تم کیوں رکے ہوئے ہو؟ اس پر لشکر والے دیوار پھاند کر اندر چلے گئے اور ہم نے اسے فتح کر لیا۔ اس میں نہ کوئی چیز ملی اور نہ کوئی انسان۔ بس شہر سے باہر چند آدمی ملے جنہیں ہم نے قید کر لیا۔ ہم نے ان لوگوں سے اور امان لینے والے آدمی سے پوچھا کہ یہ سب لوگ کیوں بھاگ گئے؟ انہوں نے کہا بادشاہ نے قاصد بھیجا تھا جس نے آپ لوگوں سے صلح کی پیشکش کی، آپ لوگوں نے اسے یہ جواب دیا کہ ہماری اور تمہاری صلح تب ہوگی جب ہم افریذین شہر کے شہد کو کوثی شہر کے ترنج کے ساتھ ملا کر کھا لیں گے۔ اس پر بادشاہ نے کہا ہائے ہماری بربادی! غور سے سنو! فرشتے ان کی زبانوں پر بولتے ہیں اور عربوں کی طرف سے ہمیں جواب دیتے ہیں۔ ",""],["ٱللَّٰه","a"],[" کی قسم! اگر فرشتہ اس آدمی کی زبان پر نہیں بھی بولا تو بھی یہ جواب ایسا ہے جو ",""],["ٱللَّٰه","a"],[" کی طرف سے اس کی زبان پر جاری کیا گیا ہے تاکہ ہم ان کے مقابلہ سے باز آ جائیں۔ اس پر سارے شہر والے دور والے شہر مدائن چلے گئے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Jareer in his Taareekh (Vol.3 Pg.118)."]]}]},"227":{"lead":[],"stories":[{"b":[["n",[["حضرت ابو سعید خدریؓ","b"],[" فرماتے ہیں ایک رات حضرت اسید بن حضیرؓ اپنے کھلیان میں قرآن پڑھ رہے تھے کہ اتنے میں ان کا گھوڑا بدکنے لگا۔ وہ رک گئے تو گھوڑا بھی رک گیا۔ انہوں نے دوبارہ پڑھنا شروع کیا تو وہ پھر بدکنے لگا، وہ رک گئے تو گھوڑا بھی رک گیا۔ انہوں نے پھر تیسری مرتبہ پڑھنا شروع کیا تو وہ پھر بدکنے لگا۔ حضرت اسیدؓ فرماتے ہیں مجھے ڈر ہوا کہ کہیں یہ گھوڑا (میرے بیٹے) یحییٰ کو نہ روند ڈالے، میں کھڑا ہو کر گھوڑے کے پاس گیا تو مجھے اپنے سر کے اوپر ایک سائبان نظر آیا جس میں بہت سے چراغ تھے، پھر اس سائبان نے آسمان پر چڑھنا شروع کیا یہاں تک کہ میری نگاہوں سے اوجھل ہو گیا۔ میں نے صبح حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آج رات میں اپنے کھلیان میں قرآن پڑھ رہا تھا کہ اتنے میں میرا گھوڑا بدکنے لگا۔ حضورؐ نے فرمایا اے ابن حضیر! پڑھتے رہو۔ میں نے پھر پڑھا تو وہ گھوڑا پھر بدکا۔ حضورؐ نے فرمایا اے ابن حضیر! پڑھتے رہو۔ یحییٰ گھوڑے کے قریب تھا تو مجھے ڈر ہوا کہ کہیں گھوڑا اسے روند نہ ڈالے، اس لیے میں نے قرآن پڑھنا چھوڑ دیا تو مجھے سائبان سا نظر آیا جس میں بہت سے چراغ تھے، وہ آسمان میں چڑھنے لگا یہاں تک کہ نگاہوں سے اوجھل ہو گیا۔ حضورؐ نے فرمایا یہ فرشتے تھے جو تمہارا قرآن سننے آئے تھے۔ اگر تم قرآن پڑھتے رہتے تو صبح کو سارے لوگ ان فرشتوں کو دیکھتے اور یہ فرشتے ان لوگوں سے چھپ نہ سکتے۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari and Muslim, the wording being theirs."]]},{"b":[["n",[["حاکم کی روایت میں ہے کہ حضرت اسیدؓ فرماتے ہیں میں نے ادھر دیکھا تو مجھے چراغ کی مانند بہت سی چیزیں نظر آئیں جو زمین و آسمان کے درمیان لٹکی ہوئی تھیں۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! اسے دیکھ کر میرے بس میں نہ رہا کہ میں آگے پڑھوں۔ حضورؐ نے فرمایا یہ فرشتے تھے جو تمہارے قرآن پڑھنے کی وجہ سے اترے تھے۔ اگر تم آگے پڑھتے رہتے تو بہت سے عجائبات دیکھتے۔ ایک روایت میں ہے کہ حضورؐ نے فرمایا یہ فرشتے تمہاری آواز کی وجہ سے اتنے قریب آئے تھے اور اگر تم پڑھتے رہتے تو صبح کو لوگ ان کو دیکھتے اور یہ ان سے چھپ نہ سکتے۔",""],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.13). Ibn Hibbaan, Tabraani and Bayhaqi have reported a similar narration from Usayd, as quoted in Kanzul Ummaal (Vol.7 Pg.7)."],["(3)","Abu Ubayd, Bukhaari, Nasa'ee, Ahmad and others."]]}]},"228":{"lead":[],"stories":[{"b":[["n",[["حضرت محمود بن لبیدؒ","b"],[" کہتے ہیں جنگ احد کے دن قبیلہ بنو عمرو بن عوف کے حضرت حنظلہ بن ابی عامرؓ کا اور حضرت ابوسفیان بن حربؓ کا (جو کہ اس وقت تک مسلمان نہیں ہوئے تھے) مقابلہ ہوا۔ جب حضرت حنظلہؓ حضرت ابوسفیانؓ پر غالب آ گئے تو شداد بن اسود جسے ابن شعوب کہا جاتا تھا، نے دیکھا کہ حضرت حنظلہؓ حضرت ابوسفیانؓ پر چڑھ بیٹھے ہیں تو اس نے تلوار کے وار سے حضرت حنظلہؓ کو شہید کر دیا۔ جنگ کے بعد حضورؐ نے فرمایا تمہارے اس ساتھی کو یعنی حضرت حنظلہؓ کو فرشتے غسل دے رہے ہیں۔ ان کے گھر والوں سے پوچھو کہ کیا بات ہے۔ ان کی بیوی سے پوچھا گیا تو انہوں نے بتایا جوں ہی انہوں نے مسلمانوں کی شکست کی آواز سنی تھی اسی وقت گھر سے چل پڑے تھے اور اس وقت انہیں نہانے کی حاجت تھی۔ حضورؐ نے فرمایا اسی وجہ سے فرشتوں نے انہیں غسل دیا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.357). Ibn Is'haaq has reported a similar narration in his Maghaazi, as has Sarraaj, as quoted in Isaabah (Vol.1 Pg.361). Haakim (Vol.3 Pg.204) has reported a similar narration from reliable sources."]]},{"b":[["n",[["حضرت محمود بن لبیدؒ","b"],[" کہتے ہیں جب غزوہ خندق کے دن حضرت سعدؓ کے بازو کی رگ میں تیر لگنے سے زخم ہو گیا تو وہ بہت زیادہ بیمار ہو گئے۔ اس لیے انہیں رفیدہ نامی عورت کے پاس منتقل کر دیا گیا۔ آگے اور بھی حدیث ذکر کی ہے، اس میں یہ بھی ہے کہ ان کے انتقال کی خبر پر حضورؐ تشریف لے گئے اور ہم بھی آپؐ کے ساتھ چل پڑے۔ آپؐ اتنی تیزی سے چلے کہ ہماری جوتیوں کے تسمے ٹوٹنے لگے اور ہمارے کندھوں سے چادریں گرنے لگیں۔ صحابہؓ نے بطور شکایت عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نے تیز چل کر ہمیں تھکا دیا۔ حضورؐ نے فرمایا مجھے اس بات کا ڈر تھا کہ جیسے فرشتوں نے حضرت حنظلہؓ کو غسل دے دیا تھا کہیں ان کو بھی فرشتے ہم سے پہلے غسل نہ دے دیں۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.427)."]]},{"b":[["n",[["حضرت عاصم بن عمر بن قتادہؒ","b"],[" کہتے ہیں حضورؐ سو گئے، جب آپؐ بیدار ہوئے تو آپؐ کے پاس حضرت جبرائیلؑ یا کوئی اور فرشتہ آیا اور اس نے کہا آپؐ کی امت میں سے آج رات کون فوت ہوا ہے جن کے مرنے پر آسمان والے خوش ہو رہے ہیں؟ آپؐ نے فرمایا اور تو مجھے کوئی معلوم نہیں، البتہ سعدؓ رات کو بہت بیمار تھے۔ سعدؓ کا کیا ہوا؟ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ان کا انتقال ہو گیا تھا، ان کی قوم انہیں اٹھا کر اپنے محلہ میں لے گئی ہے۔ حضورؐ نے فجر کی نماز پڑھائی پھر حضرت سعدؓ کی طرف تشریف لے چلے۔ آپؐ کے ساتھ صحابہؓ بھی تھے، آپؐ اتنے تیز چلے کہ صحابہؓ کو دقت پیش آنے لگی اور تیزی کی وجہ سے ان کے جوتوں کے تسمے ٹوٹنے لگے اور ان کی چادریں کندھوں سے گرنے لگیں۔ ایک آدمی نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نے تو لوگوں کو مشقت میں ڈال دیا۔ آپؐ نے فرمایا مجھے یہ ڈر ہے کہ جیسے فرشتوں نے ہم سے پہلے حنظلہ کو غسل دے دیا تھا کہیں ان کو بھی نہ دے دیں۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Sa'd (Vol.3 Pg.423)."]]}]},"229":{"lead":[],"stories":[{"b":[["n",[["جب حضرت جابرؓ کے والد شہید ہوئے تو وہ ان کے چہرے سے کپڑا ہٹا کر رونے لگے۔ لوگوں نے انہیں منع کیا تو حضورؐ نے فرمایا تم اپنے والد کو رؤو یا نہ رؤو تمہاری مرضی ہے، لیکن (",""],["ٱللَّٰه","a"],[" کے ہاں ان کا اتنا بڑا درجہ ہے کہ) آپ لوگوں کے اٹھانے تک فرشتے ان پر اپنے پروں سے سایہ کرتے رہے۔ حضرت جابرؓ کی دوسری روایت میں بھی یہی ہے کہ حضورؐ نے فرمایا جنازے کے اٹھانے تک فرشتے اپنے پروں سے ان پر سایہ کرتے رہے۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari and Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.44). Ibn Sa'd (Vol.3 Pg.561) has reported a similar narration."]]},{"b":[["n",[["حضرت سلمہ بن اسلمؓ","b"],[" فرماتے ہیں کہ ہم لوگ دروازے پر تھے اور حضورؐ بھی تھے، ہمارا ارادہ تھا کہ جب حضورؐ اندر تشریف لے جائیں گے تو ہم بھی آپؐ کے پیچھے اندر چلے جائیں گے۔ اندر کمرے میں صرف حضرت سعدؓ تھے جنہیں کپڑے سے ڈھکا ہوا تھا اور کوئی بھی نہیں تھا۔ آپؐ اندر تشریف لے گئے تو میں نے دیکھا کہ آپؐ بہت آہستہ آہستہ قدم رکھ رہے ہیں اور ایسے چل رہے ہیں کہ گویا کسی کی گردن پھلانگ رہے ہیں۔ یہ دیکھ کر میں رک گیا اور حضورؐ نے مجھے اشارے سے فرمایا ٹھہر جاؤ۔ میں خود بھی رک گیا اور جو میرے پیچھے تھے ان کو بھی روک دیا۔ حضورؐ کچھ دیر وہاں بیٹھے پھر باہر تشریف لے آئے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے تو اندر کوئی نظر نہیں آ رہا تھا لیکن آپؐ آہستہ آہستہ اس طرح چل رہے تھے کہ جیسے آپؐ کسی کی گردن پھلانگ رہے ہوں۔ حضورؐ نے فرمایا اندر فرشتے بہت زیادہ تھے، مجھے بھی بیٹھنے کی جگہ تب ملی جب ایک فرشتے نے اپنے دو پروں میں سے ایک کو سمیٹ لیا، پھر میں بیٹھ سکا اور حضورؐ حضرت سعدؓ کو فرما رہے تھے اے ابو عمرو! (یہ حضرت سعدؓ کی کنیت ہے) تمہیں مبارک ہو۔ اے ابو عمرو! تمہیں مبارک ہو۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.328)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا سعد بن معاذؓ کی وجہ سے ایسے ستر ہزار فرشتے اترے ہیں جنہوں نے اس سے پہلے کبھی زمین پر قدم نہیں رکھا۔ اور جب حضرت سعدؓ دفن ہو گئے تو آپؐ نے فرمایا سبحان ",""],["ٱللَّٰه","a"],["! اگر قبر کے بھینچنے سے کسی کو چھٹکارا ملتا تو سعدؓ کو ضرور مل جاتا۔",""],[" (3)","s"]]]],"f":[["(3)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.308). Ibn Sa'd (Vol.3 Pg.430) has reported a similar narration."]]},{"b":[["n",[["حضرت سعد بن ابراہیمؒ","b"],[" کہتے ہیں جب حضرت سعدؓ کا جنازہ باہر نکالا گیا تو کچھ منافقوں نے کہا سعدؓ کا جنازہ کتنا ہلکا ہے۔ حضورؐ نے فرمایا ستر ہزار فرشتے اترے ہیں جو سعدؓ کے جنازے میں شریک ہوئے ہیں اور ان فرشتوں نے آج سے پہلے کبھی زمین پر قدم نہیں رکھا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Sa'd (Vol.3 Pg.429)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں حضرت سعد بن معاذؓ بڑے بھاری بھرکم جسیم آدمی تھے۔ جب ان کا انتقال ہوا اور لوگ ان کا جنازہ لے کر جا رہے تھے تو منافق بھی ان کے جنازے کے پیچھے چل رہے تھے، منافق کہنے لگے ہم نے آج جیسا ہلکا آدمی تو کبھی دیکھا نہیں (یہ ان کے گناہ گار ہونے کی نشانی ہے) اور کہنے لگے کیا آپ جانتے ہیں ایسا کیوں ہے؟ اس وجہ سے ہے کہ انہوں نے بنو قریظہ کے یہودیوں کے بارے میں غلط فیصلہ کیا تھا۔ جب حضورؐ سے اس بات کا تذکرہ کیا گیا تو آپؐ نے فرمایا اس ذات کی قسم جس کے قبضے میں میری جان ہے! فرشتے ان کا جنازہ اٹھائے ہوئے تھے (اس لیے ان کا جنازہ ہلکا رہا تھا)۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Sa'd (Vol.3 Pg.430)."]]}]},"230":{"lead":[],"stories":[{"b":[["n",[["حضرت معاویہ بن حیدہ قشیریؓ","b"],[" فرماتے ہیں میں نبی کریمؐ کی خدمت میں حاضری کے ارادہ سے آیا۔ جب مجھے آپؐ کی خدمت میں لایا گیا تو آپؐ نے فرمایا غور سے سنو! میں نے ",""],["ٱللَّٰه","a"],[" تعالیٰ سے سوال کیا ہے کہ دو چیزوں سے میری مدد کرے، ایک تو تم لوگوں پر ایسی قحط سالی ڈالے جو تمہیں جڑ سے اکھیڑ دے اور دوسرے تمہارے دلوں میں ہمارا رعب ڈال دے۔ میں نے دونوں ہاتھوں سے اشارہ کرتے ہوئے عرض کیا اتنی اور اتنی مرتبہ (یعنی انگلیوں کی تعداد کے مطابق دس مرتبہ) قسم کھائی تھی کہ نہ آپ پر ایمان لاؤں گا اور نہ آپ کا اتباع کروں گا لیکن آپ کی اس بددعا کی وجہ سے قحط سالی میری جڑیں اکھیڑتی رہی اور میرے دل میں آپ کا رعب بڑھتا رہا یہاں تک کہ میں آج آپ کے سامنے کھڑا ہوں۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani in his Awsat. Haythami (Vol.6 Pg.66) has commented on the chain of narrators. Nasa'ee has reported a similar narration without mention of the drought and fear."]]},{"b":[["n",[["حضرت سائب بن یسارؒ","b"],[" کہتے ہیں حضرت یزید بن عامر سوائیؓ سے ہم لوگ پوچھتے تھے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے غزوہ حنین کے دن جو رعب مشرکوں کے دل میں ڈالا تھا اس کی کیا صورت ہوئی تھی؟ تو حضرت یزیدؓ ہمیں سمجھانے کے لیے کنکری لے کر طشت میں پھینکتے تھے جس سے طشت میں آواز ہوتی تھی۔ پھر حضرت یزیدؓ فرماتے ہیں بس اس جیسی آواز ہم اپنے پیٹ میں محسوس کرتے تھے (حضرت یزیدؓ غزوہ حنین میں مشرکوں کے ساتھ تھے اس لیے اپنا حال بتا رہے ہیں)۔",""],[" (2)","s"]]]],"f":[["(2)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.333)."]]}]},"231":{"lead":[],"stories":[{"b":[["n",[["حضرت زید بن اسلمؒ","b"],[" وغیرہ حضرات کہتے ہیں حضرت سراقہ بن مالکؓ (جو ابھی مسلمان نہیں ہوئے تھے) نے حضورؐ کی تلاش میں جانے نہ جانے کے بارے میں تین دفعہ تیروں سے فال نکالی تھی، ہر دفعہ فال میں نہ جانا نکلتا تھا لیکن وہ پھر بھی حضورؐ کی تلاش میں گھوڑے پر سوار ہو کر چل پڑے اور حضورؐ اور آپؐ کے ساتھیوں تک پہنچ گئے۔ حضورؐ نے ان کے لیے بددعا کی کہ ان کے گھوڑے کے پاؤں زمین میں گڑ جائیں، چنانچہ ایسے ہی ہوا اور ان کے گھوڑے کے پاؤں زمین میں دھنس گئے۔ اس پر انہوں نے کہا اے محمد! (",""],["ﷺ","a"],[") آپ ",""],["ٱللَّٰه","a"],[" سے دعا کریں کہ وہ میرے گھوڑے کو چھوڑ دے، میں آپ کی تلاش میں آنے والوں کو واپس کروں گا۔ چنانچہ حضورؐ نے ان کے لیے دعا کی اے ",""],["ٱللَّٰه","a"],["! اگر یہ سچا ہے تو اس کے گھوڑے کو چھوڑ دے۔ اس پر ان کے گھوڑے کے پاؤں زمین سے باہر نکل آئے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.1 Pg.188)."]]},{"b":[["n",[["حضرت عمیر بن اسحاقؒ","b"],[" کی روایت میں یہ ہے کہ حضرت سراقہؓ نے کہا اے دونوں حضرات! میرے لیے ",""],["ٱللَّٰه","a"],[" سے دعا کر دیں، میں آپ دونوں سے وعدہ کرتا ہوں کہ دوبارہ آپ حضرات کا پیچھا نہیں کروں گا۔ چنانچہ ان دونوں حضرات نے دعا کی تو اس کا گھوڑا باہر نکل آیا، اس نے پھر پیچھا کرنا شروع کر دیا جس پر پھر گھوڑے کے پاؤں زمین میں دھنس گئے تو انہوں نے کہا میرے لیے ",""],["ٱللَّٰه","a"],[" سے دعا کر دیں اور اب پکا وعدہ کرتا ہوں کہ اب پیچھا نہیں کروں گا۔ اور حضرت سراقہؓ نے ان حضرات کی خدمت میں زاد سفر اور سواری بھی پیش کی تو ان حضرات نے فرمایا اس کی تو ضرورت نہیں ہے، بس تم ہمارا پیچھا چھوڑ دو، اپنی ذات سے ہمیں نقصان نہ پہنچاؤ۔ انہوں نے کہا بہت اچھا، ایسے ہی کروں گا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.1 Pg.232)."]]},{"b":[["n",[["حضرت ابومعبد خزاعیؓ","b"],[" حضورؐ کے سفر ہجرت کی لمبی حدیث بیان کرتے ہیں، اس میں یہ بھی ہے کہ حضرت سراقہؓ نے کہا اے محمد! (",""],["ﷺ","a"],[") آپ ",""],["ٱللَّٰه","a"],[" سے دعا کریں کہ وہ میرے گھوڑے کو چھوڑ دے، میں واپس چلا جاؤں گا اور جتنے لوگ مجھے آپ کی تلاش میں ملیں گے میں ان سب کو واپس لے جاؤں گا۔ چنانچہ حضورؐ نے دعا فرمائی جس سے ان کا گھوڑا باہر نکل آیا۔ انہیں واپسی میں بہت سے لوگ ملے جو حضورؐ کو تلاش کر رہے تھے۔ انہوں نے ان سب سے کہا واپس چلے جاؤ، اس طرف کا سارا علاقہ میں اچھی طرح دیکھ آیا ہوں اور تمہیں معلوم ہی ہے کہ نشانات قدم پہچاننے کے بارے میں میری نگاہ کتنی تیز ہے۔ چنانچہ وہ سب واپس چلے گئے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Sa'd (Vol.1 Pg.232)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" ہجرت کی حدیث بیان کرتے ہیں، اس میں یہ بھی ہے کہ حضرت ابوبکرؓ نے مڑ کر دیکھا تو انہیں ایک گھوڑے سوار نظر آیا جو بالکل قریب آ چکا تھا۔ انہوں نے کہا اے ",""],["ٱللَّٰه","a"],[" کے نبی! یہ گھوڑے سوار تو ہمارے بالکل پاس آ گیا ہے۔ حضورؐ نے اس طرف متوجہ ہو کر دعا مانگی اے ",""],["ٱللَّٰه","a"],["! اسے پچھاڑ دے۔ حضرت انسؓ فرماتے ہیں حضورؐ کے دعا فرماتے ہی گھوڑے نے اسے پچھاڑ دیا اور خود ہنہناتے ہوئے کھڑا ہو گیا۔ چنانچہ اس سوار نے کہا اے ",""],["ٱللَّٰه","a"],[" کے نبی! آپ مجھے جو بھی حکم دیں میں اس کے لیے تیار ہوں۔ حضورؐ نے فرمایا آگے مت آؤ، اپنی جگہ ٹھہرے رہو (بلکہ واپس چلے جاؤ) اور کسی کو ہماری طرف نہ آنے دینا۔ حضرت انسؓ فرماتے ہیں کہ وہ سوار یعنی حضرت سراقہؓ دن کے شروع میں تو حضورؐ کے خلاف کوشش کرنے والے تھے اور دن کے آخر میں ہتھیار کی طرح حضورؐ کے لیے حفاظت کا ذریعہ بن گئے۔ اور پہلی جلد میں صفحہ 366 پر ہجرت کے باب میں نبی کریمؐ کی ہجرت کے بارے میں حضرت براءؓ کی روایت میں حضرت سراقہؓ کا قصہ گزر چکا ہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں اربد بن قیس اور عامر بن طفیل حضورؐ سے ملنے مدینہ آئے۔ جب یہ دونوں حضورؐ کے پاس آئے تو حضورؐ بیٹھے ہوئے تھے، یہ دونوں بھی حضورؐ کے سامنے بیٹھ گئے۔ عامر بن طفیل نے کہا اے محمد! (",""],["ﷺ","a"],[") اگر میں اسلام لے آؤں تو آپ مجھے کیا خاص چیزیں دیں گے؟ حضورؐ نے فرمایا تمہیں بھی وہ تمام حقوق حاصل ہوں گے جو سارے مسلمانوں کو حاصل ہیں اور تم پر بھی وہ تمام ذمہ داریاں ہوں گی جو ان پر ہیں۔ عامر بن طفیل نے کہا اگر میں اسلام لے آؤں تو کیا آپ اپنے بعد خلیفہ بننے کا حق مجھے دیں گے؟ حضورؐ نے فرمایا یہ حق نہ تمہیں مل سکتا ہے اور نہ تمہاری قوم کو، البتہ تمہیں گھڑ سوار دستہ کا کمانڈر بنا دیں گے۔ عامر نے کہا میں تو اب بھی نجد کی گھڑ سوار فوج کا کمانڈر ہوں۔ اچھا آپ ایسا کریں دیہات کی حکومت مجھے دے دیں اور شہروں کی حکومت آپ لے لیں۔ آپؐ نے فرمایا نہیں، ایسے نہیں ہو سکتا۔ جب دونوں حضورؐ کے پاس سے واپس جانے لگے تو عامر نے کہا خبردار! ",""],["ٱللَّٰه","a"],[" کی قسم! میں سارے مدینہ کو آپ کے خلاف گھوڑے سوار اور پیادہ فوج سے بھر دوں گا۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" تمہیں ایسا کرنے سے روک دے گا، تم ایسا نہیں کر سکو گے۔ جب اربد اور عامر باہر نکلے تو عامر نے کہا اے اربد! میں محمد (",""],["ﷺ","a"],[") کو باتوں میں مشغول کر لوں گا، تم تلوار کا کام تمام کر دینا کیونکہ جب تم محمد کو قتل کر دو گے تو لوگ زیادہ سے زیادہ خون بہا پر راضی ہو جائیں گے، اس سے زیادہ مطالبہ نہیں کریں گے اور لڑائی کو اچھا نہیں سمجھیں گے، ہم انہیں خون بہا دے دیں گے۔ اربد نے کہا ٹھیک ہے، میں تیار ہوں۔ چنانچہ دونوں واپس آئے اور عامر نے کہا اے محمد! (",""],["ﷺ","a"],[") آپ ذرا میرے ساتھ کھڑے ہوں، میں آپ سے بات کرنا چاہتا ہوں۔ حضورؐ اٹھ کر ان کے ساتھ گئے، وہ دونوں ایک دیوار کے ساتھ بیٹھ گئے۔ حضورؐ بھی ان کے ساتھ بیٹھ گئے اور عامر سے باتیں کرنے لگے۔ اربد نے حضورؐ پر تلوار سونتنے کا ارادہ کیا، جب اس نے تلوار کے قبضے پر ہاتھ رکھا تو اس کا ہاتھ خشک ہو گیا اور وہ تلوار نہ سونت سکا، اس طرح اسے کافی دیر ہو گئی۔ حضورؐ نے مڑ کر اربد کی طرف دیکھا تو اس کی یہ بزدلانہ حرکت نظر آئی۔ حضورؐ دونوں کو چھوڑ کر آ گئے۔ عامر اور اربد حضورؐ کے پاس سے چلے اور جب حرہ رقم یعنی پتھریلے میدان میں پہنچے تو دونوں وہاں ٹھہر گئے۔ حضرت سعد بن معاذؓ اور حضرت اسید بن حضیرؓ دونوں ان کے پاس گئے اور ان سے کہا اے ",""],["ٱللَّٰه","a"],[" کے دشمنو! اٹھو اور یہاں سے چلے جاؤ، ",""],["ٱللَّٰه","a"],[" تم دونوں پر لعنت کرے۔ عامر نے پوچھا اے سعد! یہ آپ کے ساتھ کون ہے؟ حضرت سعدؓ نے کہا یہ اسید بن حضیر کاتب یعنی پڑھے لکھے آدمی ہیں۔ چنانچہ وہ دونوں وہاں سے چل پڑے۔ جب وہ مقام رقم میں پہنچے تو ",""],["ٱللَّٰه","a"],[" نے اربد پر ایسی بجلی گرائی جس سے وہ وہیں مر گیا۔ عامر وہاں سے آگے چلا۔ جب وہ مقام خریم پہنچا تو ",""],["ٱللَّٰه","a"],[" نے اس کے جسم میں ایک پھوڑا پیدا کر دیا اور اسے قبیلہ بنی سلول کی ایک عورت کے گھر میں رات گزارنی پڑی (یہ قبیلہ عربوں میں گھٹیا شمار ہوتا تھا)۔ وہ پھوڑا حلق میں ہوا تھا۔ وہ اپنے پھوڑے کو ہاتھ لگاتا تھا اور کہتا یہ اتنی بڑی گلٹی ہے جتنی بڑی اونٹ کی ہوتی ہے۔ میں سلولیہ عورت کے گھر میں پڑا ہوا ہوں اور میں اس کے گھر میں مرنا نہیں چاہتا (اول تو قبیلہ سب سے گھٹیا ہے، پھر عورت کا گھر، یہ دونوں باتیں ذلت کی ہیں)۔ پھر وہ اپنے گھوڑے پر سوار ہوا اور اسے ایڑ لگائی اور یوں واپسی میں اپنے گھوڑے پر ہی مر گیا۔ اور ان دونوں کے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیات نازل فرمائیں",""]]],["q",[["ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلْأَرْحَامُ وَمَا تَزْدَادُ ۖ وَكُلُّ شَىْءٍ عِندَهُۥ بِمِقْدَارٍ ۝ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْكَبِيرُ ٱلْمُتَعَالِ ۝ سَوَآءٌ مِّنكُم مَّنْ أَسَرَّ ٱلْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفٍۭ بِٱلَّيْلِ وَسَارِبٌۢ بِٱلنَّهَارِ ۝ لَهُۥ مُعَقِّبَـٰتٌ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍ سُوٓءًا فَلَا مَرَدَّ لَهُۥ ۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" تعالیٰ کو سب خبر رہتی ہے جو کچھ کسی عورت کو حمل رہتا ہے اور جو کچھ رحم میں کمی بیشی ہوتی ہے اور ہر شے ",""],["ٱللَّٰه","a"],[" کے نزدیک ایک خاص انداز سے (مقرر) ہے۔ وہ تمام پوشیدہ اور ظاہر چیزوں کو جاننے والا ہے، سب سے بڑا (اور) عالیشان ہے۔ تم میں سے جو شخص کوئی بات چپکے سے کہے اور جو پکار کر کہے اور جو شخص رات میں کہیں چھپ جاوے اور جو دن میں چلے پھرے، یہ سب برابر ہیں۔ ہر شخص (کی حفاظت) کے لیے فرشتے (مقرر) ہیں جن کی بدلی ہوتی رہتی ہے، کچھ اس کے آگے اور کچھ اس کے پیچھے کہ وہ بحکم خدا اس کی حفاظت کرتے ہیں۔ واقعی ",""],["ٱللَّٰه","a"],[" تعالیٰ کسی قوم کو (اچھی) حالت میں تغیر نہیں کرتا جب تک وہ لوگ خود اپنی (صلاحیت کی) حالت کو نہیں بدل دیتے اور جب ",""],["ٱللَّٰه","a"],[" تعالیٰ کسی قوم پر مصیبت ڈالنا تجویز کر لیتا ہے تو پھر اس کے ہٹنے کی کوئی صورت ہی نہیں اور کوئی خدا کے سوا ان کا مددگار نہیں رہتا۔\" (سورۂ رعد، آیات 8 تا 11)۔ حضرت ابن عباسؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کے حکم سے باری باری آنے والے فرشتے حضرت محمدؐ کی حفاظت کرتے ہیں۔ پھر انہوں نے اربد پر بجلی گرنے کا واقعہ بیان کیا اور فرمایا",""]]],["q",[["وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ","a"]]],["p",[["ترجمہ: \"اور وہ بجلیاں بھیجتا ہے (پھر جس پر چاہتا ہے ان کو گرا دیتا ہے)۔\" (سورۂ رعد، آیت 13)۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.506)."]]}]},"232":{"lead":[],"stories":[{"b":[["n",[["حضرت حارث بن بدلؒ","b"],[" ایک صحابی سے نقل کرتے ہیں، وہ صحابی فرماتے ہیں میں غزوہ حنین کے دن حضورؐ کے مقابلہ پر مشرکوں کے ساتھ تھا، پہلے تو حضرت عباس بن عبدالمطلبؓ اور حضرت ابوسفیان بن حارثؓ کے علاوہ حضورؐ کے تمام صحابہؓ شکست کھا گئے۔ حضورؐ نے زمین سے ایک مٹی اٹھا کر ہمارے چہروں پر پھینکی جس سے ہمیں شکست ہوئی اور مجھے ایسے محسوس ہو رہا تھا کہ ہر درخت اور ہر پتھر ہمارے پیچھے دوڑ رہا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani, Abu Nu'aym and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.304). Ibn Mandah and Ibn Asaakir have also reported the narration in brief, as quoted in Kanzul Ummaal as well."]]},{"b":[["n",[["حضرت عمرو بن سفیان ثقفیؓ","b"],[" وغیرہ حضرات فرماتے ہیں جنگ حنین کے دن پہلے مسلمانوں کو شکست ہوئی اور حضورؐ کے ساتھ حضرت عباس بن عبدالمطلبؓ اور حضرت ابوسفیان بن حارثؓ کے علاوہ اور کوئی نہ رہا۔ پھر حضورؐ نے کنکریوں کی ایک مٹھی اٹھا کر کافروں کے چہروں پر پھینکی جس سے ہمیں شکست ہو گئی اور ہمیں یہ محسوس ہو رہا تھا کہ ہر پتھر اور ہر درخت گھوڑے سوار ہے جو ہمیں تلاش کر رہا ہے۔ حضرت عمرو ثقفیؓ کہتے ہیں میں نے اپنے گھوڑے کو تیز دوڑایا یہاں تک کہ طائف میں داخل ہو گیا۔",""],[" (2)","s"]]]],"f":[["(2)","Ya'qoob bin Sufyaan, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.332)."]]},{"b":[["n",[["حضرت حکیم بن حزامؓ","b"],[" فرماتے ہیں ہم نے سنا کہ ایک آواز آسمان سے زمین کی طرف آئی تھی، وہ آواز ایسی تھی جیسی طشت میں کنکری کے گرنے کی ہوتی ہے اور حضورؐ نے وہ کنکری اٹھا کر ہماری طرف پھینک دی جس سے ہمیں شکست ہو گئی۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani in his Kabeer and Awsat, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.84)."]]},{"b":[["n",[["حضرت حکیم بن حزامؓ فرماتے ہیں جنگ بدر کے دن ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضورؐ کو حکم دیا جس پر آپؐ نے کنکریوں کی مٹھی لی اور ہمارے سامنے آ کر اسے ہم پر پھینک دیا اور فرمایا تمہارے چہرے بگڑ جائیں۔ اسی پر ہمیں شکست ہو گئی اور اسی پر ",""],["ٱللَّٰه","a"],[" نے یہ آیت نازل فرمائی",""]]],["q",[["وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَـٰكِنَّ ٱللَّهَ رَمَىٰ","a"]]],["p",[["ترجمہ: \"اور آپ نے خاک کی مٹھی نہیں پھینکی جس وقت آپ نے پھینکی تھی لیکن ",""],["ٱللَّٰه","a"],[" تعالیٰ نے وہ پھینکی۔\" (سورۂ انفال، آیت 17)۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani in his Kabeer and Awsat, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.84)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ نے حضرت علیؓ سے فرمایا مجھے ایک مٹھی کنکریاں دو۔ حضرت علیؓ نے حضورؐ کو ایک مٹھی کنکریاں دیں۔ حضورؐ نے وہ مٹھی میں لے کر کافروں کے چہروں پر پھینک دیں، ",""],["ٱللَّٰه","a"],[" کی قدرت سے ہر کافر کی دونوں آنکھیں کنکریوں سے بھر گئیں۔ پھر یہ آیت نازل ہوئی",""]]],["q",[["وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَـٰكِنَّ ٱللَّهَ رَمَىٰ","a"]]],["p",[["ترجمہ: \"اور آپ نے خاک کی مٹھی نہیں پھینکی جس وقت آپ نے پھینکی تھی لیکن ",""],["ٱللَّٰه","a"],[" تعالیٰ نے وہ پھینکی۔\" (سورۂ انفال، آیت 17)۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani in his Kabeer and Awsat, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.84)."]]},{"b":[["n",[["حضرت یزید بن عامر سوائیؓ","b"],[" فرماتے ہیں حضورؐ نے زمین سے ایک مٹھی لی اور مشرکوں کی طرف متوجہ ہو کر ان کے چہروں پر پھینک دی اور فرمایا واپس چلے جاؤ، تمہارے چہرے بگڑ جائیں۔ چنانچہ جو کافر بھی اپنے بھائی سے ملتا تھا اس سے اپنی دونوں آنکھوں میں خاک پڑ جانے کی شکایت کرتا۔",""],[" (6)","s"]]]],"f":[["(6)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.333)."]]}]},"233":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں غزوہ بدر کے دن کفار ہمیں بہت تھوڑے دکھائی دے رہے تھے یہاں تک کہ میرے قریب جو ساتھی تھا میں نے اس سے کہا تمہارے خیال میں یہ کافر ستر ہوں گے؟ اس نے کہا میرے خیال میں سو ہوں گے۔ پھر ہم نے ان کے ایک آدمی کو پکڑا اور اس سے اس بارے میں پوچھا تو اس نے کہا ہم ہزار تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani, as quoted in Majma'uz Zawaa'id (Vol.6 Pg.84). Ibn Abi Haatim and Ibn Jareer have reported a similar narration from Abdullaah bin Mas'ood, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.315)."]]}]},"234":{"lead":[],"stories":[{"b":[["n",[["حضرت سعید بن جبیرؒ","b"],[" کہتے ہیں غزوہ خندق مدینہ میں ہوا تھا، حضرت ابوسفیان بن حربؓ (جو اس وقت تک مسلمان نہیں ہوئے تھے وہ) قریش کو اور اپنے پیچھے چلنے والے تمام قبائل عرب کو لے کر مدینہ پر حملہ آور ہوئے تھے۔ ان قبائل میں کنانہ، عیینہ بن حصن، غطفان، طلیحہ، بنو اسد، ابو الاعور اور بنو سلیم شامل تھے۔ اور قریظہ کے یہودیوں کا حضورؐ کے درمیان پہلے سے معاہدہ تھا جسے انہوں نے توڑ دیا اور مشرکوں کی مدد کی، ان کے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیت نازل فرمائی",""]]],["q",[["وَأَنزَلَ ٱلَّذِينَ ظَـٰهَرُوهُم مِّنْ أَهْلِ ٱلْكِتَـٰبِ مِن صَيَاصِيهِمْ","a"]]],["p",[["ترجمہ: \"اور جن اہل کتاب نے ان کی مدد کی تھی ان کو ان کے قلعوں سے نیچے اتار دیا۔\" (سورۂ احزاب، آیت 26)۔ حضرت جبرائیلؑ ہوا کو ساتھ لے کر آئے۔ جب حضورؐ نے حضرت جبرائیلؑ کو دیکھا تو تین دفعہ فرمایا غور سے سنو! تمہیں خوشخبری ہو۔ پھر ",""],["ٱللَّٰه","a"],[" نے ان پر ایسی ہوا بھیجی جس نے ان کے خیمے پھاڑ دیے اور ان کی دیگچیں الٹ دیں اور ان کے کجاوے مٹی میں دبا دیے اور خیموں کے باندھنے کے کھونٹے توڑ دیے اور وہ لوگ ایسے گھبرا کر بھاگے کہ کوئی مڑ کر دوسرے کو نہیں دیکھتا تھا۔ اس پر ",""],["ٱللَّٰه","a"],[" نے یہ آیت نازل فرمائی",""]]],["q",[["إِذْ جَآءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا","a"]]],["p",[["ترجمہ: \"جب تم پر بہت سے لشکر چڑھ آئے پھر ہم نے ان پر ایک آندھی بھیجی اور ایسی فوج بھیجی جو تم کو دکھائی نہ دیتی تھی۔\" (سورۂ احزاب، آیت 9)۔ کفار کے بھاگنے کے بعد حضورؐ مدینہ واپس آ گئے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.2 Pg.71)."]]},{"b":[["n",[["حضرت حمید بن ہلالؒ","b"],[" کہتے ہیں نبی کریمؐ اور قریظہ کے درمیان کچا پکا معاہدہ تھا، جب غزوہ خندق میں کفار کے گروہ اپنے لشکر لے کر آئے تو قریظہ نے وہ معاہدہ توڑ دیا اور مشرکوں کی مدد کی۔ پھر ",""],["ٱللَّٰه","a"],[" نے فرشتوں کے لشکر اور ہوا بھیجی جس سے یہ گروہ بھاگ گئے اور قریظہ کے یہود نے اپنے قلعے میں پناہ لی۔ اس کے بعد غزوہ بنو قریظہ کے بارے میں حدیث ذکر کی۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.2 Pg.77)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں غزوہ خندق کی ایک رات کو مشرقی ہوا شمالی ہوا کے پاس آئی اور کہنے لگی چل اور حضورؐ کی مدد کر۔ شمالی ہوا نے کہا آزاد اور شریف عورت رات کو نہیں چلا کرتی (اس لیے میں نہیں چلوں گی)۔ چنانچہ جس ہوا کے ذریعہ حضورؐ کی مدد کی گئی وہ پروا یعنی مشرقی ہوا تھی۔",""],[" (3)","s"]]]],"f":[["(3)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.66). Ibn Abi Haatim and Ibn Jareer have reported a similar narration, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.470)."]]}]},"235":{"lead":[],"stories":[{"b":[["n",[["حضرت بریدہؓ","b"],[" فرماتے ہیں ایک کافر نے جنگ احد کے دن کہا اے ",""],["ٱللَّٰه","a"],["! اگر محمد (علیہ السلام) حق پر ہیں تو مجھے زمین میں دھنسا دے، چنانچہ وہ اسی وقت زمین میں دھنس گیا۔",""],[" (1)","s"]]]],"f":[["(1)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.122)."]]},{"b":[["n",[["حضرت نافع بن عاصمؒ","b"],[" کہتے ہیں بنو ہذیل کے عبد",""],["ٱللَّٰه","a"],[" بن قمیہ نے حضورؐ کے چہرے کو زخمی کیا تھا، ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس پر ایک بکرا مسلط کر دیا جس نے اسے سینگ مار مار کر مار ڈالا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Dalaa'il (Pg.176)."]]}]},"236":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مغفل مزنیؓ","b"],[" فرماتے ہیں ہم حدیبیہ میں حضورؐ کے ساتھ تھے، اس کے بعد صلح حدیبیہ کے بارے میں حدیث ذکر کی ہے، اس میں یہ بھی ہے کہ ہم اسی حال میں تھے کہ تیس نوجوان ہتھیار لگائے ہوئے سامنے آئے اور ہمارے مقابلہ کے لیے تیار ہو گئے۔ حضورؐ نے ان کے لیے بددعا فرمائی تو ",""],["ٱللَّٰه","a"],[" نے اسی وقت ان کی بینائی ختم کر دی اور ہم نے جا کر انہیں پکڑ لیا۔ حضورؐ نے ان سے پوچھا کہ کیا تم لوگ کسی سے معاہدہ کر کے آئے ہو؟ کیا کسی نے تمہیں امن دیا ہے؟ انہوں نے کہا نہیں، تو حضورؐ نے انہیں چھوڑ دیا۔ اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیت نازل فرمائی",""]]],["q",[["وَهُوَ ٱلَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ ۚ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا","a"]]],["p",[["ترجمہ: \"اور وہ ایسا ہے کہ اس نے ان کے ہاتھ تم سے (یعنی تمہارے قتل سے) اور تمہارے ہاتھ ان (کے قتل) سے عین مکہ (کے قرب) میں روک دیے بعد اس کے کہ تم کو ان پر قابو دے دیا تھا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہارے کاموں کو دیکھ رہا تھا۔\" (سورۂ فتح، آیت 24)۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.145). Nasa'ee has reported a similar narration, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.192)."]]},{"b":[["n",[["حضرت زاذانؒ","b"],[" کہتے ہیں حضرت علیؓ نے ایک حدیث بیان کی، ایک آدمی نے اس حدیث کو جھٹلایا۔ حضرت علیؓ نے فرمایا اگر تو جھوٹا ہے تو میں تیرے لیے بددعا کروں گا۔ اس نے کہا کر دیں۔ چنانچہ حضرت علیؓ نے اس کے لیے بددعا کی تو اسی مجلس میں اس کی بینائی جاتی رہی۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani. Haythami (Vol.9 Pg.116) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عمارؓ","b"],[" فرماتے ہیں حضرت علیؓ نے ایک آدمی سے حدیث بیان کی، اس نے اس حدیث کو جھٹلا دیا تو وہ آدمی وہاں سے اٹھنے سے پہلے ہی اندھا ہو گیا۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Dalaa'il (Pg.211)."]]},{"b":[["n",[["حضرت زاذانؒ","b"],[" کہتے ہیں ایک آدمی نے حضرت علیؓ سے ایک حدیث بیان کی حضرت علیؓ نے کہا میرے خیال میں تم مجھ سے جھوٹ بول رہے ہو۔ اس نے کہا نہیں، میں نے جھوٹ نہیں بولا۔ حضرت علیؓ نے کہا اگر تم نے جھوٹ نہیں بولا ہے تو میں تمہارے لیے بددعا کروں گا۔ اس نے کہا کر دیں۔ حضرت علیؓ نے بددعا کی تو اسی مجلس میں اندھا ہو گیا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Dunya, as quoted in Al Bidaayah wan Nihaayah (Vol.8 Pg.5)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں اروی بنت اویس عورت نے کسی چیز کے بارے میں حضرت سعید بن زیدؓ سے جھگڑا کر رکھا تھا۔ مروان نے کچھ لوگوں کو حضرت سعیدؓ کے پاس بھیجا تاکہ وہ اروی کے بارے میں ان سے گفتگو کریں۔ حضرت سعیدؓ نے فرمایا یہ لوگ سمجھتے ہیں کہ میں اس عورت پر ظلم کر رہا ہوں، حالانکہ میں نے حضورؐ کو فرماتے ہوئے سنا کہ جو ظلم کر کے کسی سے ایک بالشت زمین لے گا تو قیامت کے دن ساتوں زمینوں میں سے ایک بالشت زمین طوق بنا کر اس کے گلے میں ڈال دی جائے گی۔ اے ",""],["ٱللَّٰه","a"],["! اگر اروی جھوٹی ہے تو اسے موت نہ دے جب تک کہ وہ اندھی نہ ہو جائے اور اس کی قبر اس کے کنویں میں بنا دے۔ ",""],["ٱللَّٰه","a"],[" کی قسم! اسے موت تب ہی آئی جب اس کی بینائی جاتی رہی۔ ایک دفعہ وہ اپنے گھر میں بڑی احتیاط سے چل رہی تھی کہ وہ اپنے کنویں میں گر گئی اور وہ کنواں ہی اس کی قبر بن گیا۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilyah (Vol.1 Pg.96)."]]},{"b":[["n",[["حضرت ابوبکر محمد بن عمرو بن حزمؒ","b"],[" کہتے ہیں اروی نامی عورت نے حضرت سعید بن زیدؓ کے ظلم کی جھوٹی شکایت کر کے مروان سے مدد چاہی۔ حضرت سعیدؓ نے یہ بددعا کی اے ",""],["ٱللَّٰه","a"],["! یہ اروی دعویٰ کر رہی ہے کہ میں نے اس پر ظلم کیا ہے۔ اگر یہ جھوٹی ہے تو اسے اندھا کر دے اور اسے اس کے کنویں میں گرا دے اور میرے حق میں ایسی روشن دلیل ظاہر کر جس سے سارے مسلمانوں کو صاف نظر آ جائے کہ میں نے اس پر ظلم نہیں کیا۔ اسی دوران وادی عقیق میں ایسا زبردست سیلاب آیا کہ اس سے پہلے کبھی ایسا سیلاب نہیں آیا تھا۔ سیلاب کی وجہ سے وہ حد صاف واضح ہو گئی جس میں حضرت سعیدؓ اور اروی کا اختلاف تھا اور اس میں حضرت سعیدؓ بالکل سچے نکلے۔ پھر ایک مہینہ نہیں گزرا تھا کہ اروی اندھی ہو گئی اور ایک دفعہ وہ اپنی اسی زمین کا چکر لگا رہی تھی کہ اچانک اپنے کنویں میں گر گئی۔ اور جب ہم چھوٹے بچے تھے تو سنا کرتے تھے کہ لوگ ایک دوسرے کو کہا کرتے تھے کہ ",""],["ٱللَّٰه","a"],[" تجھے ایسے اندھا کرے جیسے اروی کو اندھا کیا۔ ہم یہی سمجھتے تھے کہ اروی سے مراد جنگلی پہاڑی بکریاں ہیں (کیونکہ عربی زبان میں اروی کا یہی ترجمہ ہے)، یہ تو بعد میں ہمیں اس قصہ کا پتہ چلا اور اس سے معلوم ہوا کہ اروی سے مراد تو ایک عورت ہے جسے حضرت سعید بن زیدؓ کی بددعا لگی تھی اور چونکہ ",""],["ٱللَّٰه","a"],[" نے ان کی بددعا پوری کر دی تھی اس لیے لوگ یہ بات کہتے تھے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilyah (Vol.1 Pg.97)."]]},{"b":[["n",[["حضرت ابو رجاء عطاردیؒ","b"],[" نے کہا حضرت علیؓ کو اور حضورؐ کے گھرانے میں سے کسی کو برا بھلا نہ کہو کیونکہ ہمارا ایک پڑوسی بنو ہجیم کا تھا، اس نے گستاخی کی اور یوں کہا کیا تم لوگوں نے اس فاسق حسین بن علی کو نہیں دیکھا؟ ",""],["ٱللَّٰه","a"],[" انہیں قتل کرے۔ یہ گستاخی کرتے ہی ",""],["ٱللَّٰه","a"],[" نے اس کی دونوں آنکھوں میں دو سفید نقطے پیدا کر دیے اور اس کی بینائی کو ختم کر دیا۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.196)."]]}]},"237":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ مسجد حرام میں اونچی آواز سے قرآن پڑھ رہے تھے جس سے قریش کے کچھ لوگوں کو تکلیف ہوئی اور وہ حضورؐ کو پکڑنے کے لیے کھڑے ہوئے تو ایک دم ان کے ہاتھ ان کی گردنوں کے ساتھ بندھ گئے اور وہ اندھے ہو گئے، انہیں کچھ نظر نہیں آ رہا تھا۔ انہوں نے حضورؐ کی خدمت میں آ کر کہا اے محمد! ہم تمہیں ",""],["ٱللَّٰه","a"],[" کا اور رشتہ داری کا واسطہ دیتے ہیں (دعا کر کے ہمیں اس مصیبت سے نکال دیں)۔ قریش کے ہر خاندان کی حضورؐ سے رشتہ داری تھی۔ چنانچہ حضورؐ نے دعا کی تو ان کی یہ مصیبت جاتی رہی۔ اس پر یہ آیتیں نازل ہوئیں",""]]],["q",[["يس ۝ وَٱلْقُرْءَانِ ٱلْحَكِيمِ ۝ إِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ ۝ ... سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ","a"]]],["p",[["ترجمہ: \"یٰسین۔ قسم ہے قرآن باحکمت کی کہ بے شک آپ مجملہ پیغمبروں کے ہیں ... اور ان کے حق میں آپ کا ڈرانا یا نہ ڈرانا دونوں برابر ہیں، یہ ایمان نہ لاویں گے۔\" (سورۂ یٰسین، آیات 1 تا 10)۔ چنانچہ ان لوگوں میں سے کوئی آدمی ایمان نہیں لایا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Dalaa'il (Pg.63)."]]},{"b":[["n",[["حضرت قتادہ بن نعمانؓ","b"],[" فرماتے ہیں کسی نے حضورؐ کو مدینہ میں کمان دی جو جنگ احد کے دن حضورؐ نے مجھے عطا فرمائی۔ میں حضورؐ کے سامنے کھڑا ہو کر اس سے تیر چلاتا رہا یہاں تک کہ اس کمان کا ایک کنارہ ٹوٹ گیا۔ پھر میں حضورؐ کے چہرے کے سامنے اسی جگہ کھڑا رہا اور آنے والے تیروں کو اپنے چہرے پر لیتا رہا۔ جب بھی کوئی تیر حضورؐ کے چہرے کی طرف آتا تو میں حضورؐ کے چہرے کو بچانے کے لیے اپنا چہرہ اور سر اس کے آگے کر دیتا اور یہ سب کچھ میں بغیر تیر چلائے کر رہا تھا (کیونکہ کمان تو ٹوٹ چکی تھی)۔ آخری تیر مجھے اس طرح لگا کہ میری آنکھ نکل کر میرے رخسار پر گر گئی۔ پھر مشرکوں کا لشکر بکھر گیا، پھر میں اپنی آنکھ ہتھیلی میں پکڑ کر دوڑ کر حضورؐ کی خدمت میں گیا۔ جب حضورؐ نے میری آنکھ کو دیکھا تو حضورؐ کی دونوں آنکھوں میں آنسو آ گئے، پھر آپؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! قتادہؓ نے اپنے چہرے کو تیرے نبی کے سامنے رکھا تھا (جس کی وجہ سے اس کی آنکھ باہر نکل آئی ہے)، اب اس کی اس آنکھ کو دونوں آنکھوں میں سب سے زیادہ خوبصورت اور زیادہ تیز نظر والی بنا دے (پھر حضورؐ نے وہ آنکھ اپنے ہاتھ سے اندر رکھ دی)۔ چنانچہ وہ آنکھ دونوں آنکھوں میں زیادہ خوبصورت اور زیادہ تیز نظر والی تھی۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani. Haythami (Vol.8 Pg.297) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.174), as has Ibn Sa'd (Vol.3 Pg.453)."]]},{"b":[["n",[["حضرت محمود بن لبیدؒ","b"],[" کہتے ہیں جنگ احد کے دن حضرت قتادہؓ کی آنکھ زخمی ہو گئی تھی اور باہر نکل کر ان کے رخسار پر گر گئی تھی، جسے نبی کریمؐ نے اپنی جگہ واپس رکھ دیا تو وہ آنکھ دوسری آنکھ سے بھی زیادہ اچھی ہو گئی تھی۔ ابونعیم کی روایت میں ہے کہ وہ آنکھ دونوں آنکھوں میں سے زیادہ خوبصورت اور زیادہ تیز ہو گئی تھی۔",""],[" (3)","s"]]]],"f":[["(3)","Daaraqutni and Ibn Shaaheen, as quoted in Isaabah (Vol.3 Pg.225). Abu Nu'aym has also reported it in his Dalaa'il (Pg.174)."]]},{"b":[["n",[["حضرت عاصم بن عمر بن قتادہؒ","b"],[" کہتے ہیں حضرت قتادہ بن نعمانؓ کی آنکھ جنگ بدر کے دن زخمی ہو گئی تھی اور آنکھ کا ڈیلا نکل کر ان کے رخسار پر آ گیا تھا۔ صحابہؓ نے اسے کاٹنا چاہا تو کچھ لوگوں نے کہا نہیں، ٹھہرو، پہلے ہم حضورؐ سے مشورہ کر لیں۔ حضورؐ سے مشورہ کیا تو آپؐ نے فرمایا نہ کاٹو۔ پھر حضرت قتادہؓ کو حضورؐ نے بلایا اور ہتھیلی ڈیلے پر رکھ کر اسے دبایا اور اندر کر دیا۔ چنانچہ وہ آنکھ ایسی ٹھیک ہوئی کہ پتہ نہیں چلتا تھا کہ کون سی ضائع ہوئی تھی۔",""],[" (4)","s"]]]],"f":[["(4)","Baghawi and Abu Ya'la, as quoted in Isaabah (Vol.3 Pg.225). Haythami (Vol.8 Pg.298) has commented on Abu Ya'la's chain of narrators."]]},{"b":[["n",[["حضرت عبیدہؒ","b"],[" کہتے ہیں جنگ احد کے دن حضرت ابوذرؓ کی آنکھ زخمی ہو گئی تھی۔ حضورؐ نے اس پر اپنا لعاب لگایا تو وہ دوسری سے بھی زیادہ اچھی ہو گئی تھی۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Ya'la. Haythami (Vol.8 Pg.298) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت رفاعہ بن رافعؓ","b"],[" فرماتے ہیں جنگ بدر کے دن مجھے ایک تیر لگا جس سے میری آنکھ پھوٹ گئی۔ حضورؐ نے اس پر لعاب لگایا اور میرے لیے دعا فرمائی جس سے مجھے آنکھ میں کوئی تکلیف محسوس نہیں ہوئی۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Dalaa'il (Pg.223)."]]},{"b":[["n",[["قبیلہ بنو سلمان کے ایک آدمی کی والدہ بیان کرتی ہیں کہ میرے ماموں حضرت حبیب بن فویکؒ نے مجھے بتایا کہ ان کے والد کو لوگ حضورؐ کی خدمت میں لے گئے، ان کی آنکھیں بالکل سفید تھیں اور انہیں کچھ نظر نہیں آتا تھا۔ حضورؐ نے ان سے آنکھیں سفید ہونے کی وجہ پوچھی تو میرے والد نے کہا میں اپنے ایک اونٹ کو سدھار رہا تھا کہ اتنے میں میرا پاؤں کسی سانپ کے انڈے پر پڑ گیا جس سے میری بینائی جاتی رہی۔ حضورؐ نے ان کی آنکھوں پر دم فرمایا جس سے وہ ایک دم بینا ہو گئے۔ میرے ماموں کہتے ہیں میں نے دیکھا کہ میرے والد کی عمر اسی سال ہو چکی تھی اور ان کی دونوں آنکھیں سفید تھیں لیکن وہ سوئی میں دھاگہ ڈال لیتے تھے۔ طبرانی کی روایت میں یہ ہے کہ میرے والد نے حضورؐ کو یہ بتایا کہ (جب میرا پاؤں سانپ کے انڈے پر پڑا تو) اس وقت میں اپنی اونٹنیوں کے تھنوں پر دودھ نکالنے کے لیے ہاتھ پھیر رہا تھا۔ ابونعیم کی روایت میں یہ ہے کہ میں اپنے اونٹ کو سدھار رہا تھا۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abi Shaybah, as quoted in Isaabah (Vol.1 Pg.308). A narration of Tabraani states that he stepped on a snake's egg while milking his camel. Haythami (Vol.8 Pg.298) has however commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.223)."]]},{"b":[["n",[["حضرت سعد بن ابراہیمؒ","b"],[" کہتے ہیں حضرت زنیرہؓ رومی باندی تھیں۔ وہ مسلمان ہو گئیں تو ان کی بینائی جاتی رہی، اس پر مشرکوں نے کہا لات و عزیٰ ہمارے بتوں نے ان کو اندھا کر دیا ہے۔ حضرت زنیرہؓ نے کہا (نہیں، انہوں نے نہیں کیا) میں لات اور عزیٰ (کے معبود ہونے) کا انکار کرتی ہوں۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ان کی بینائی واپس کر دی۔",""],[" (8)","s"]]]],"f":[["(8)","Faakihi and Ibn Mandah."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں مجھ سے حضرت ام ہانی بنت ابی طالبؓ نے فرمایا جب حضرت ابوبکرؓ نے حضرت زنیرہؓ کو آزاد کیا تو ان کی بینائی جاتی رہی۔ اس پر کفار قریش نے کہا انہیں لات اور عزیٰ ہی نے اندھا کیا ہے۔ حضرت زنیرہؓ نے کہا یہ لوگ غلط کہتے ہیں، بیت ",""],["ٱللَّٰه","a"],[" کی قسم! لات و عزیٰ کسی کام نہیں آ سکتے اور کچھ نفع نہیں دے سکتے۔ چنانچہ ",""],["ٱللَّٰه","a"],[" نے ان کی بینائی واپس کر دی۔",""],[" (9)","s"]]]],"f":[["(9)","Muhammad bin Uthmaan bin Abi Shaybah, as quoted in Isaabah (Vol.4 Pg.312)."]]}]},"238":{"lead":[],"stories":[{"b":[["n",[["حضرت ہشام بن عاص امویؓ","b"],[" فرماتے ہیں (حضرت ابوبکر صدیقؓ کے دور میں) مجھے اور ایک اور آدمی کو روم کے بادشاہ ہرقل کے پاس اسلام کی دعوت دینے کے لیے بھیجا گیا۔ چنانچہ ہم سفر میں روانہ ہوئے اور دمشق کے غوطہ مقام پر پہنچے اور جبلہ بن ایہم غسانی (شاہ غسان) کے ہاں ٹھہرے۔ ہم نے جبلہ کے پاس جانا چاہا تو اس نے اپنا قاصد ہم سے بات کرنے کے لیے بھیجا۔ ہم نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! ہم کسی قاصد سے بات نہیں کریں گے، ہمیں تو بادشاہ کے پاس بھیجا گیا ہے۔ اگر بادشاہ ہمیں اجازت دے تو ہم اس سے بات کریں گے ورنہ ہم اس قاصد سے بات نہیں کریں گے۔ قاصد نے واپس جا کر بادشاہ کو ساری بات بتائی جس پر بادشاہ نے ہمیں اجازت دے دی (ہم اندر گئے)۔ اس نے کہا بات کرو۔ چنانچہ میں نے اس سے بات کی اور اسے اسلام کی دعوت دی۔ اس نے کالے کپڑے پہنے ہوئے تھے، میں نے کہا آپ نے یہ کالے کپڑے کیا پہن رکھے ہیں؟ اس نے کہا میں نے یہ کپڑے پہن کر قسم کھائی ہے کہ جب تک تمہیں ملک شام سے نکال نہ دوں یہ کپڑے نہیں اتاروں گا۔ ہم نے کہا تمہارے بیٹھنے کی اس جگہ کی قسم! ان شاء ",""],["ٱللَّٰه","a"],["! یہ جگہ بھی ہم آپ سے لے لیں گے بلکہ شہنشاہ اعظم (شاہ روم) کا ملک بھی لے لیں گے۔ ہمیں یہ بات ہمارے نبی حضرت محمدؐ نے بتائی ہے۔ اس نے کہا تم وہ لوگ نہیں ہو (جو ہم سے ہمارا ملک چھین لیں) بلکہ وہ تو وہ لوگ ہوں گے جو دن کو روزے رکھتے ہوں گے اور رات کو عبادت کرتے ہوں گے۔ تو بتاؤ تمہارے روزے کس طرح ہیں؟ ہم نے اس کو روزے کے بارے میں بتایا تو اس کا سارا چہرہ سیاہ ہو گیا اور اس نے کہا چلو۔ پھر اس نے ہمارے ساتھ شاہ روم کے پاس ایک قاصد بھیجا، چنانچہ ہم وہاں سے چلے۔ جب ہم شہر کے قریب پہنچے تو ہمارے ساتھ جو قاصد تھا اس نے ہم سے کہا آپ لوگوں کی یہ سواریاں بادشاہ کے شہر میں داخل نہیں ہو سکتیں۔ اگر آپ لوگ کہیں تو ہم سواری کے لیے ترکی گھوڑے اور خچر دے دیں۔ ہم نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! ہم تو ان ہی سواریوں پر شہر میں داخل ہوں گے۔ ان لوگوں نے بادشاہ کے پاس پیغام بھیجا کہ یہ لوگ تو نہیں مان رہے ہیں۔ بادشاہ ہرقل نے انہیں حکم دیا کہ ہم لوگ اپنی سواریوں پر ہی آ جائیں۔ چنانچہ ہم تلواریں لٹکائے ہوئے شہر میں داخل ہوئے اور بادشاہ کے بالا خانے تک پہنچ گئے۔ ہم نے بالا خانہ کے نیچے اپنی سواریاں بٹھا دیں، وہ ہمیں دیکھ رہا تھا۔ ہم نے ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و",""],["ٱللَّٰه","a"],[" اکبر کہا تو ",""],["ٱللَّٰه","a"],[" جانتا ہے وہ بالا خانہ ہلنے لگا اور ایسے ہل رہا تھا جیسے درخت کی ٹہنی کو ہوا ہلا رہی ہو۔ ہرقل نے ہمارے پاس پیغام بھیجا کہ تم لوگوں کو اس بات کی اجازت نہیں ہے کہ تم اپنے دین کی باتیں ہمارے سامنے زور سے کرو۔ پھر اس نے پیغام بھیجا کہ اندر آ جاؤ۔ ہم اس کے پاس گئے، وہ اپنے قیمتی بچھونے پر بیٹھا ہوا تھا اور اس کے پاس روم کے تمام جرنیل اور سپہ سالار بیٹھے ہوئے تھے۔ اس کی مجلس میں ہر چیز سرخ تھی، اس کے چاروں طرف سرخی تھی اور اس کے کپڑے بھی سرخ تھے۔ ہم اس کے قریب گئے تو وہ ہنسنے لگا اور کہنے لگا اگر آپ لوگ مجھے ویسے ہی سلام کرتے جیسے آپس میں کرتے ہو تو اس میں کیا حرج تھا؟ اس کے پاس ایک آدمی تھا جو فصیح عربی بولتا تھا اور بہت باتیں کرتا تھا (جو ترجمانی کر رہا تھا)۔ ہم نے کہا جس طرح ہم آپس میں سلام کرتے ہیں اس طرح آپ کو سلام کرنا ہمارے لیے جائز نہیں اور جس طرح آپ کو سلام کیا جاتا ہے اس طرح سلام کرنا ہمارے لیے جائز نہیں۔ اس نے پوچھا آپ لوگ آپس میں کس طرح سلام کرتے ہیں؟ ہم نے کہا السلام علیکم۔ اس نے کہا آپ لوگ اپنے بادشاہ کو کس طرح سلام کرتے ہیں؟ ہم نے کہا اسی طرح۔ اس نے کہا وہ آپ لوگوں کو جواب کیسے دیتا ہے؟ ہم نے کہا ان ہی الفاظ سے۔ پھر اس نے پوچھا آپ لوگوں کا سب سے بڑا کلام کیا ہے؟ ہم نے کہا ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و",""],["ٱللَّٰه","a"],[" اکبر۔ ",""],["ٱللَّٰه","a"],[" جانتا ہے ان کلمات کے کہتے ہی وہ بالا خانہ پھر ہلنے لگا اور بادشاہ سر اٹھا کر دیکھنے لگا۔ پھر اس نے کہا یہ ہیں وہ کلمات جن کے کہنے سے یہ بالا خانہ ہلنے لگا تھا، تو جب یہ کلمات آپ لوگ اپنے گھروں میں کہتے ہیں تو کیا وہ بھی ہلنے لگتے ہیں؟ ہم نے کہا نہیں، یہ بات تو ہم نے صرف آپ کے ہاں دیکھی ہے۔ اس نے کہا میری آرزو یہ ہے کہ آپ لوگ جب بھی یہ کلمات کہیں تو آپ کے آس پاس کی ہر چیز آپ لوگوں پر گر پڑے، چاہے مجھے اس کے لیے اپنا آدھا ملک دینا پڑے۔ ہم نے کہا کیوں؟ اس نے کہا اس لیے کہ اگر ایسا ہو جائے تو پھر یہ نبوت کی نشانی نہ ہوگی بلکہ لوگوں کی شعبدہ بازی میں سے ہوگا۔ پھر اس نے بہت سے سوالات کیے جن کے ہم نے جوابات دیے۔ پھر اس نے کہا آپ لوگوں کے نماز روزے کس طرح ہوتے ہیں؟ اس کی ہم نے تفصیل بتائی۔ پھر اس نے کہا اب آپ لوگ اٹھیں اور چلے جائیں، پھر اس کے حکم دینے پر ہمیں بہت عمدہ مکان میں ٹھہرایا گیا اور بہت زیادہ مہمانی کا اہتمام کیا گیا۔ ہم وہاں تین دن ٹھہرے رہے، پھر ایک رات اس نے ہمارے پاس پیغام بھیجا، ہم اس کے پاس گئے، اس نے کہا اپنی بات دوبارہ کہو۔ ہم نے اپنی ساری بات کہہ دی۔ پھر اس نے ایک چیز منگوائی جو بڑی چوکور پٹاری کی طرح تھی اور اس پر سونے کے پانی کا کام کیا ہوا تھا، اس میں چھوٹے چھوٹے خانے بنے ہوئے تھے جن کے دروازے تھے۔ اس نے تالا کھول کر ایک خانہ کھولا اور اس میں کالے رنگ کے ریشم کا ایک کپڑا نکالا۔ اسے ہم نے پھیلایا تو اس پر ایک آدمی کی سرخ رنگ کی تصویر بنی ہوئی تھی جس کی آنکھیں بڑی اور سرین موٹے تھے اور اتنی لمبی گردن میں نے کسی کی نہیں دیکھی۔ اس کی داڑھی نہیں تھی، البتہ سر کے بالوں کی دو مینڈھیاں تھیں، ",""],["ٱللَّٰه","a"],[" نے جتنے انسان بنائے ان میں سب سے زیادہ خوبصورت تھا۔ بادشاہ نے کہا کیا آپ لوگ اسے پہچانتے ہیں؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت آدم علیہ السلام ہیں، ان کے بال عام لوگوں سے زیادہ تھے۔ پھر اس نے دوسرا دروازہ کھول کر کالے ریشم کا ایک کپڑا نکالا جس پر سفید تصویر بنی ہوئی تھی۔ اس آدمی کے بال گھنگھریالے تھے، آنکھیں سرخ، سر بڑا اور داڑھی خوبصورت تھی۔ اس نے کہا کیا آپ لوگ اسے پہچانتے ہیں؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت نوح علیہ السلام ہیں۔ اس نے پھر ایک دروازہ کھول کر ریشم کا ایک کپڑا نکالا، اس پر ایک آدمی کی تصویر تھی جو بہت سفید تھا۔ اس کی آنکھیں خوبصورت، پیشانی نمایاں، رخسار لمبے، داڑھی سفید تھی، ایسے لگ رہا تھا جیسے مسکرا رہا ہو۔ اس نے کہا کیا آپ لوگ اسے پہچانتے ہیں؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت ابراہیم علیہ السلام ہیں۔ پھر اس نے ایک دروازہ کھولا، اس میں سفید تصویر تھی، ",""],["ٱللَّٰه","a"],[" کی قسم! وہ حضورؐ کی تصویر تھی۔ اس نے کہا کیا انہیں پہچانتے ہو؟ ہم نے کہا ہاں! یہ حضرت محمد صلی ",""],["ٱللَّٰه","a"],[" علیہ وسلم ہیں۔ اور ہم خوشی کے مارے رونے لگ گئے اور ",""],["ٱللَّٰه","a"],[" جانتا ہے کہ وہ اپنی جگہ سے ایک دم اٹھا اور کچھ دیر کھڑا رہا پھر بیٹھ گیا، پھر کہا ",""],["ٱللَّٰه","a"],[" کی قسم! یہ وہی ہیں؟ ہم نے کہا ہاں، بے شک یہ وہی ہیں، گویا کہ آپ ان کو دیکھ رہے ہیں۔ پھر کچھ دیر وہ اسی تصویر کو دیکھتا رہا، پھر کہنے لگا یہ تصویر تھی تو آخری خانے میں لیکن میں نے آپ لوگوں کا امتحان لینے کے لیے ذرا جلدی نکال لی تاکہ پتہ چلے کہ آپ لوگ ان کی کتنی معلومات رکھتے ہیں۔ پھر اس نے ایک اور دروازہ کھول کر اس میں سے کالے رنگ کے ریشم کا ایک کپڑا نکالا جس پر گندمی رنگ والے، سیاہی مائل آدمی کی تصویر تھی، جس کے بال بہت زیادہ گھنگھریالے، آنکھیں اندر گھسی ہوئیں، نگاہ تیز، منہ چڑھا ہوا اور دانت ایک دوسرے پر چڑھے ہوئے اور ہونٹ سمٹا ہوا تھا اور ایسے معلوم ہو رہا تھا جیسے کہ غصے میں ہو۔ اس نے کہا کیا انہیں پہچانتے ہو؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت موسیٰ علیہ السلام ہیں۔ اور ان کے پہلو میں ایک اور تصویر تھی جو بالکل ان جیسی تھی البتہ ان کے سر پر تیل لگا ہوا تھا، پیشانی چوڑی تھی اور ان کی آنکھوں میں کچھ بھینگا پن تھا۔ اس نے کہا کیا انہیں پہچانتے ہو؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت ہارون بن عمران علیہ السلام ہیں۔ پھر اس نے ایک اور دروازہ کھول کر سفید ریشم کا ایک کپڑا نکالا جس پر ایک آدمی کی تصویر تھی جس کا رنگ گندمی، بال سیدھے اور قد درمیانہ تھا اور وہ ایسے نظر آ رہے تھے کہ جیسے غصے میں ہوں۔ اس نے کہا کیا ان کو پہچانتے ہو؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت لوط علیہ السلام ہیں۔ پھر اس نے ایک اور دروازہ کھول کر سفید ریشم کا ایک کپڑا نکالا جس پر ایک سفید آدمی کی تصویر تھی، سفیدی میں کچھ سرخی ملی ہوئی تھی، ناک اونچی، رخسار ہلکے اور چہرہ حسین و جمیل تھا۔ اس نے کہا انہیں پہچانتے ہو؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت اسحاق علیہ السلام ہیں۔ پھر ایک اور دروازہ کھول کر اس نے سفید ریشم کا ایک کپڑا نکالا، اس پر ایک تصویر تھی جو حضرت اسحاقؑ کے مشابہ تھی، صرف یہ فرق تھا کہ ان کے ہونٹ پر تل تھا۔ اس نے کہا کیا انہیں پہچانتے ہو؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت یعقوب علیہ السلام ہیں۔ پھر اس نے ایک اور دروازہ کھول کر کالے ریشم کا ایک کپڑا نکالا جس میں ایک سفید آدمی کی تصویر تھی جس کا چہرہ خوبصورت، ناک اونچی اور قد اچھا تھا۔ اس کے چہرے پر نور بلند ہو رہا تھا، اس کے چہرے سے خشوع معلوم ہو رہا تھا اور اس کا رنگ مائل بہ سرخی تھا۔ اس نے کہا کیا آپ لوگ انہیں پہچانتے ہیں؟ ہم نے کہا نہیں۔ اس نے کہا یہ تمہارے نبی کے دادا حضرت اسماعیل علیہ السلام ہیں۔ پھر اس نے ایک اور دروازہ کھول کر سفید ریشم کا ایک کپڑا نکالا جس میں حضرت آدم علیہ السلام جیسی تصویر تھی اور ان کا چہرہ سورج کی طرح چمک رہا تھا۔ اس نے کہا کیا انہیں پہچانتے ہیں؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت یوسف علیہ السلام ہیں۔ پھر اس نے ایک اور دروازہ کھول کر سفید ریشم کا کپڑا نکالا جس میں ایک آدمی کی تصویر تھی جس کی پنڈلیاں پتلی، آنکھیں چھوٹی اور کمزور، پیٹ بڑا اور قد درمیانہ تھا، تلوار بھی گلے میں لٹکائی ہوئی تھی۔ اس نے پوچھا کیا انہیں پہچانتے ہیں؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت داؤد علیہ السلام ہیں۔ پھر اس نے ایک اور دروازہ کھول کر اس میں سے سفید ریشم کا ایک کپڑا نکالا جس میں ایک آدمی کی تصویر تھی جس کے سرین بڑے، پاؤں لمبے تھے اور وہ ایک گھوڑے پر سوار تھے۔ اس نے کہا کیا آپ انہیں پہچانتے ہیں؟ ہم نے کہا نہیں۔ اس نے کہا یہ سلیمان بن داؤد علیہما السلام ہیں۔ پھر اس نے ایک اور دروازہ کھول کر اس میں سے کالے ریشم کا ایک کپڑا نکالا جس میں سفید تصویر تھی، وہ بالکل جوان تھے، داڑھی بے انتہا کالی اور بال بہت زیادہ، آنکھیں اور چہرہ بہت خوبصورت تھا۔ اس نے کہا کیا انہیں پہچانتے ہیں؟ ہم نے کہا نہیں۔ اس نے کہا یہ حضرت عیسیٰ علیہ السلام ہیں۔ ہم نے پوچھا آپ کو یہ تصویریں کہاں سے ملی ہیں؟ کیونکہ ہمیں یقین ہے کہ انبیاء علیہم السلام کو جو شکل و صورت عطا فرمائی گئی تھی یہ اس کے مطابق ہیں، اس لیے کہ ہم نے اپنے نبی پاک علیہ السلام کی تصویر ان کی شکل و صورت کے مطابق بنی ہوئی دیکھی ہے۔ اس نے کہا حضرت آدم علیہ السلام نے اپنے رب سے یہ سوال کیا تھا کہ میری اولاد میں سے جتنے نبی ہوں گے وہ مجھے دکھا دیں، اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے انبیاء علیہم السلام کی یہ تصویریں حضرت آدمؑ پر اتاری تھیں اور سورج ڈوبنے کی جگہ کے پاس جو حضرت آدمؑ کا خزانہ تھا اس میں یہ تصویریں رکھی ہوئی تھیں جن کو وہاں سے نکال کر ذوالقرنین نے حضرت دانیال علیہ السلام کو دی تھیں۔ پھر ہرقل نے کہا غور سے سنیں! ",""],["ٱللَّٰه","a"],[" کی قسم! اس کے لیے میں دل سے تیار ہوں کہ میں اپنے ملک کو چھوڑ دوں اور آپ لوگوں میں جو اپنے غلاموں کے ساتھ سب سے برا سلوک کرتا ہو میں اس کا مرتے دم تک کے لیے غلام بن جاؤں (لیکن اسلام میں داخل ہونے کے لیے تیار نہیں)۔ پھر اس نے بہت عمدہ تحفے دے کر ہمیں رخصت کیا۔ جب ہم حضرت ابوبکر صدیقؓ کے پاس پہنچے تو ہم نے ان کو ساری کارگزاری سنائی، ہرقل نے ہمیں جو کچھ دکھایا، جو کچھ کہا اور جو تحفے دیے وہ سب ہم نے ان کو بتا دیے۔ یہ سن کر حضرت ابوبکرؓ رو پڑے اور فرمایا یہ بے چارہ ہرقل مسکین ہے، اگر ",""],["ٱللَّٰه","a"],[" کا اس کے ساتھ بھلائی کا ارادہ ہوتا تو یہ بھلائی کا کام کر لیتا یعنی اسلام میں داخل ہو جاتا۔ اور حضرت ابوبکرؓ نے یہ بھی فرمایا کہ حضورؐ نے ہمیں بتایا تھا کہ یہود و نصاریٰ کی کتابوں میں حضرت محمدؐ کے حلیہ مبارک اور صفات وغیرہ کا ذکر موجود ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.251). The author of Kanzul Ummaal has reported the narration (Vol.5 Pg.322) from Bayhaqi and quotes from Ibn Katheer that the chain of narrators is sound. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.9)."]]},{"b":[["n",[["حضرت ہشام بن عاصؓ کی اس حدیث میں تو ان تصویروں میں حضرت ابوبکرؓ کی تصویر کا ذکر نہیں ہے لیکن بیہقی نے ",""],["حضرت جبیر بن مطعمؓ","b"],[" سے یہی حدیث روایت کی ہے جس میں حضرت ابوبکرؓ کی تصویر کا ذکر اس طرح ہے (کہ بصریٰ شہر کے نصاریٰ مجھے ایک گرجا گھر میں لے گئے، اس میں بہت سی تصویریں تھیں)، پھر انہوں نے مجھ سے کہا دیکھو کیا اس نبی کی تصویر ان میں نظر آ رہی ہے؟ میں نے دیکھا تو ان میں حضورؐ کی تصویر بھی تھی اور حضرت ابوبکرؓ کی تصویر بھی تھی۔ وہ حضورؐ کی ایڑی پکڑے ہوئے تھے۔ انہوں نے مجھ سے کہا کیا تمہیں ان کی تصویر نظر آئی؟ میں نے کہا جی ہاں! انہوں نے حضورؐ کی تصویر کی طرف اشارہ کر کے کہا کیا وہ یہ ہیں؟ میں نے کہا جی ہاں، میں گواہی دیتا ہوں کہ وہ یہی ہیں۔ پھر انہوں نے کہا تم ان کو پہچانتے ہو جو ان کی ایڑی پکڑے ہوئے ہیں؟ میں نے کہا جی ہاں! انہوں نے کہا ہم گواہی دیتے ہیں کہ یہ تمہارے یعنی تمہارے نبی ہیں اور یہ ان کے بعد ان کے خلیفہ ہیں۔ طبرانی کی روایت میں یہ ہے کہ میں نے کہا یہ ان کی ایڑی کے پاس کھڑا ہوا آدمی کون ہے؟ اس نصرانی نے کہا تمہارے نبی کے علاوہ ہر نبی کے بعد نبی ضرور ہوتا تھا لیکن تمہارے نبی کے بعد کوئی نبی نہیں آئے گا اور یہ ان کے بعد ان کے خلیفہ ہیں۔ تو یہ حضرت ابوبکرؓ کی تصویر تھی۔ (پہلے نبیوں کی شریعت میں جاندار کی تصویر کی اجازت تھی لیکن ہماری شریعت میں اجازت نہیں)۔",""],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.63). Bukhaari has reported a similar narration briefly in his Taareekh and Abu Nu'aym has reported it in his Dalaa'il (Pg.9)."],["(3)","Tabraani in his Kabeer and Awsat. Haythami (Vol.8 Pg.234) has commented on the chain of narrators."]]},{"b":[["n",[["قبیلہ غسان اور قبیلہ بوقین کے چند مشائخ","b"],[" بیان کرتے ہیں کہ حمص کی لڑائی میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مسلمانوں کے صبر کا بدلہ یہ دیا کہ حمص والوں پر زلزلہ آیا اور اس کی صورت یہ ہوئی کہ مسلمان ان کے مقابلہ کے لیے کھڑے ہوئے تو انہوں نے زور سے ",""],["ٱللَّٰه","a"],[" اکبر کہا جس کی وجہ سے شہر حمص میں رومیوں پر زلزلہ آ گیا اور دیواریں پھٹ گئیں تو وہ سب گھبرا کر اپنے ان سرداروں اور اصحاب شوریٰ کے پاس گئے جو ان کو مسلمانوں سے صلح کرنے کی دعوت دینے لگے تھے لیکن ان لوگوں نے ان سرداروں اور اصحاب شوریٰ کی یہ بات نہ مانی بلکہ ان کے ساتھ ذلت آمیز رویہ اختیار کیا۔ مسلمانوں نے دوبارہ پھر زور سے ",""],["ٱللَّٰه","a"],[" اکبر کہا جس سے بہت سے گھر اور دیواریں گر گئیں اور شہر والے پھر گھبرا کر سرداروں اور اصحاب شوریٰ کے پاس گئے تو انہوں نے کہا کیا تم دیکھتے نہیں کہ یہ ",""],["ٱللَّٰه","a"],[" کا عذاب ہے؟ اس پر شہر والوں نے صلح کی بات مان لی۔ آگے اور بھی حدیث ہے۔",""]]]],"f":[]}]},"239":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں حضرت عمرؓ نے ایک لشکر روانہ کیا اور ان کا امیر ایک آدمی کو بنایا جنہیں ساریہ کہا جاتا تھا۔ ایک دفعہ حضرت عمرؓ جمعہ کا خطبہ دے رہے تھے کہ ایک دم انہوں نے تین مرتبہ پکار کر کہا اے ساریہ! لشکر کو لے کر پہاڑ کی طرف ہو جاؤ۔ پھر اس لشکر کا قاصد آیا، حضرت عمرؓ نے اس سے حالات پوچھے۔ اس نے کہا اے امیر المومنین! ہمیں شکست ہو رہی تھی کہ اتنے میں ہم نے ایک بلند آواز تین مرتبہ سنی اے ساریہ! پہاڑ کی طرف ہو جاؤ۔ چنانچہ ہم نے اپنی پشتیں پہاڑ کی طرف کر دیں جس پر ",""],["ٱللَّٰه","a"],[" نے کفار کو شکست دے دی۔ پھر لوگوں نے حضرت عمرؓ سے کہا آپ ہی نے تو بلند آواز سے یہ کہا تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Jareer (Vol.3 Pg.97)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں حضرت عمرؓ جمعہ کے دن خطبہ دے رہے تھے تو خطبہ میں کہنے لگے اے ساریہ! پہاڑ کی طرف ہو جاؤ اور جس نے بھیڑیے کو بکریوں کا چرواہا بنایا اس نے بکریوں پر ظلم کیا۔ لوگ ایک دوسرے کو حیران ہو کر دیکھنے لگے۔ حضرت علیؓ نے ان سے فرمایا پریشان مت ہو، حضرت عمرؓ خود بتائیں گے کہ انہوں نے یہ کیوں کہا ہے۔ جب حضرت عمرؓ نماز سے فارغ ہوئے تو لوگوں نے ان سے پوچھا۔ انہوں نے فرمایا میرے دل میں ایک دم خیال آیا کہ مشرکوں نے ہمارے بھائیوں کو شکست دے دی ہے اور وہ ایک پہاڑ کے پاس سے گزر رہے ہیں، یہ ہمارے بھائی اگر پہاڑ کی طرف مڑ جائیں تو ان کو صرف ایک طرف سے لڑنا پڑے گا (اور اس طرح ان کو فتح ہو جائے گی) اور اگر یہ لوگ پہاڑ سے آگے نکل گئے تو پھر (ان کو ہر طرف سے لڑنا پڑے گا اور) یہ ہلاک ہو جائیں گے۔ بس اس پر میری زبان سے وہ کلمات نکل گئے جو آپ لوگوں نے سنے ہیں۔ پھر ایک مہینے کے بعد (اس لشکر کی طرف سے فتح کی) خوشخبری دینے والا آیا اور اس نے بتایا کہ ہم لوگوں نے اس دن حضرت عمرؓ کی آواز سنی تھی اور آواز سن کر ہم لوگ پہاڑ کی طرف ہو گئے تھے جس سے ",""],["ٱللَّٰه","a"],[" نے ہمیں فتح نصیب فرما دی۔",""],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Bayhaqi, Laalkaa'i in Sharhus Sunnah, Zain Aaqooli in his Fawaa'id and Ibnul A'raabi in Karaamaatul Awliyaa, as quoted by Harmala in his Jam'u."],["(3)","Ibn Mardawayh, as quoted in Isaabah (Vol.2 Pg.3). Abu Nu'aym in his Dalaa'il (Pg.210) and Abu Abdur Rahmaan Sulami in his Arba'een have reported a similar narration."]]},{"b":[["n",[["خطیب اور ابن عساکر کی روایت میں یہ ہے کہ لوگوں نے حضرت علیؓ سے کہا آپ نے حضرت عمرؓ کو منبر پر خطبہ کے دوران یا ساریہ کہتے ہوئے نہیں سنا؟ حضرت علیؓ نے فرمایا تمہارا بھلا ہو، حضرت عمرؓ کو کچھ نہ کہو، وہ جو بھی کام کرتے ہیں اس کی کوئی نہ کوئی وجہ ضرور ہوتی ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Khateeb and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.386). Allaama Ibn Katheer has commented on the authenticity of the narration in his Al Bidaayah wan Nihaayah (Vol.7 Pg.131)."]]},{"b":[["n",[["ابونعیم کی روایت میں یہ ہے کہ حضرت عمرؓ نے فرمایا میرے دل میں یہ خیال آیا کہ دشمن نے حضرت ساریہؓ کو پہاڑ کی پناہ لینے پر مجبور کر دیا ہے، تو اس خیال سے میں نے یہ کہہ دیا کہ شاید ",""],["ٱللَّٰه","a"],[" کا کوئی بندہ میری آواز حضرت ساریہؓ تک پہنچا دے یعنی کوئی فرشتہ یا مسلمان جن پہنچا دے۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Dalaa'il (Pg.210)."]]},{"b":[["n",[["ابونعیم کی دوسری روایت میں یہ ہے کہ پھر حضرت عبدالرحمٰن بن عوفؓ حضرت عمرؓ کے پاس گئے۔ حضرت عمرؓ کو حضرت عبدالرحمٰنؓ پر مکمل اعتماد اور اطمینان تھا۔ حضرت عبدالرحمٰنؓ نے کہا مجھے آپ کی وجہ سے لوگوں کو برا بھلا کہنا پڑتا ہے، اس کی سب سے بڑی وجہ یہ ہے کہ آپ ہمیشہ ایسا کام کر دیتے ہیں جس کی بظاہر کوئی وجہ نظر نہیں آتی اور یوں لوگوں کو باتیں کرنے کا موقع مل جاتا ہے۔ آپ نے یہ کیا کیا؟ کہ خطبہ دیتے دیتے آپ ایک دم اے ساریہ! پہاڑ کی طرف ہو جاؤ زور سے کہنے لگے۔ حضرت عمرؓ نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! میں اپنے آپ کو قابو میں نہ رکھ سکا۔ میں نے دیکھا کہ حضرت ساریہؓ کا لشکر ایک پہاڑ کے پاس لڑ رہا ہے اور ان پر آگے سے پیچھے سے ہر طرف سے حملہ ہو رہا ہے، اس پر میں اپنے آپ کو قابو میں نہ رکھ سکا اور ایک دم میری زبان سے نکل گیا اے ساریہ! پہاڑ کی طرف ہو جاؤ۔ اور میں نے یہ اس لیے کہا تھا کہ یہ لوگ پہاڑ کی طرف ہو جائیں (اور انہیں صرف ایک طرف سے لڑنا پڑے)۔ کچھ ہی عرصہ کے بعد حضرت ساریہؓ کا قاصد ان کا خط لے کر آیا جس میں لکھا تھا کہ جمعہ کے دن ہمارا دشمن سے مقابلہ ہوا، ہم نے صبح نماز پڑھ کر لڑائی شروع کی یہاں تک کہ جمعہ کا وقت ہو گیا اور سورج کا کنارہ ڈھل گیا تو ہم نے سنا کہ کسی آدمی نے دو مرتبہ زور سے یہ اعلان کیا اے ساریہ! پہاڑ کی طرف ہو جاؤ۔ چنانچہ ہم پہاڑ کی طرف ہو گئے، اس طرح ہم دشمن پر غالب آنے لگے یہاں تک کہ ",""],["ٱللَّٰه","a"],[" نے انہیں شکست دے دی اور ان کو قتل کر دیا۔ حضرت عبدالرحمٰنؓ نے کہا لوگوں نے حضرت عمرؓ کے اس عمل پر خواہ مخواہ اعتراض کیا تھا، اس آدمی کو چھوڑ دو، اس سے کچھ نہ کہو کیونکہ اس کی الٹی بھی سیدھی ہوتی ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Dalaa'il (Pg.211). Waaqidi has reported it from Zaid bin Aslam and Ya'qoob bin Zaid, as quoted in Al Bidaayah wan Nihaayah (Vol.7 Pg.131). Ibn Katheer says: These chains strengthen one another."]]},{"b":[["n",[["واقدی میں زید بن اسلم اور یعقوب بن زید کی روایت میں اس طرح ہے کہ لوگوں نے حضرت عمر بن خطابؓ سے پوچھا آپ نے کیا کہہ دیا تھا؟ حضرتؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے حضرت ساریہؓ کو وہی بات کہی جو ",""],["ٱللَّٰه","a"],[" کی طرف سے میری زبان پر جاری ہوئی۔",""],[" (7)","s"]]]],"f":[["(7)","Waaqidi, as quoted in Al Bidaayah wan Nihaayah (Vol.7 Pg.131)."]]},{"b":[["n",[["حضرت عزہ بنت عیاض بن ابی قرصافہؒ","b"],[" کہتی ہیں رومیوں نے حضرت ابو قرصافہؓ کے ایک بیٹے کو گرفتار کر لیا تھا۔ جب نماز کا وقت ہوتا تو حضرت ابو قرصافہؓ عسقلان شہر کی فصیل کی دیوار پر چڑھ کر زور سے کہتے اے فلانے! نماز کا وقت ہو گیا ہے، اور ان کا بیٹا روم کے شہر میں ان کی یہ آواز سن لیا کرتا تھا۔",""],[" (8)","s"]]]],"f":[["(8)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.396)."]]}]},"240":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں جب حضورؐ کا انتقال ہوا تو غسل دینے والوں میں اختلاف ہو گیا کہ غسل کے لیے حضورؐ کا کرتا اتارا جائے یا نہ اتارا جائے، تو ان سب نے ایک غیبی آواز کو سنا کہ کوئی کہہ رہا ہے کہ تم اپنے نبی کو کرتے ہی میں غسل دو۔ آواز تو آ رہی تھی لیکن بولنے والے کا پتہ نہیں چل رہا تھا کہ کون ہے۔ چنانچہ حضورؐ کو کرتے ہی میں غسل دیا گیا۔ حضرت عائشہؓ کی روایت میں یہ ہے کہ کسی کہنے والے نے کہا تم انہیں کپڑوں سمیت ہی غسل دے دو، کہنے والے کا پتہ نہیں چل رہا تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.2 Pg.276). A similar narration has also been reported from Aa'isha."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ نے سمندر کا سفر کرنے والے ایک لشکر کا حضرت ابوموسیٰؓ کو امیر بنایا تو رات کے وقت کشتی ان کو لیے جا رہی تھی کہ اچانک ایک منادی نے اوپر سے انہیں پکار کر کہا کیا میں تمہیں وہ فیصلہ نہ بتاؤں جو ",""],["ٱللَّٰه","a"],[" نے اپنے بارے میں کیا ہے؟ اور وہ یہ ہے کہ جو آدمی (روزہ رکھ کر) گرم دن میں ",""],["ٱللَّٰه","a"],[" کے لیے پیاسا رہے گا تو ",""],["ٱللَّٰه","a"],[" پر اس کا یہ حق ہے کہ اسے بڑی پیاس والے دن یعنی قیامت کے دن اچھی طرح پانی پلائے۔",""],[" (2)","s"]]]],"f":[["(2)","Haakim (Vol.3 Pg.467), who said that the chain is authentic although Bukhaari and Muslim did not report it; Dhahabi said that Ibn Mu'ammal is weak."]]},{"b":[["n",[["حضرت ابوموسیٰؓ","b"],[" فرماتے ہیں ایک دفعہ ہم لوگ سمندری غزوے میں گئے، چنانچہ ہم سمندر میں سفر کر رہے تھے، ہوا بالکل موافق تھی اور بادبان اٹھے ہوئے تھے۔ ہم نے ایک منادی کو یہ اعلان کرتے ہوئے سنا اے کشتی والو! ٹھہر جاؤ، میں تمہیں ایک خبر دینا چاہتا ہوں۔ اس نے یہ اعلان مسلسل سات مرتبہ کیا۔ میں نے کشتی کے اگلے حصہ پر کھڑے ہو کر کہا تو کون ہے؟ اور کہاں سے آیا ہے؟ کیا تجھے نظر نہیں آ رہا ہے کہ ہم کہاں ہیں؟ کیا ہم یہاں رک سکتے ہیں؟ تو اس نے جواب میں کہا کیا میں آپ لوگوں کو وہ فیصلہ نہ بتاؤں جو ",""],["ٱللَّٰه","a"],[" نے اپنے بارے میں کیا ہے؟ میں نے کہا ضرور بتاؤ۔ اس نے کہا ",""],["ٱللَّٰه","a"],[" نے اپنے بارے میں یہ فیصلہ کیا ہے کہ جو گرم دن میں اپنے آپ کو ",""],["ٱللَّٰه","a"],[" کے لیے (روزہ رکھ کر) پیاسا رکھے گا اس کا ",""],["ٱللَّٰه","a"],[" پر یہ حق ہوگا کہ ",""],["ٱللَّٰه","a"],[" اسے قیامت کے دن سیراب کرے۔ چنانچہ حضرت ابوموسیٰؓ اس سخت گرم دن کی تلاش میں رہتے جس میں انسان کی کھال جل جائے اور اس دن روزہ رکھتے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.260)."]]},{"b":[["n",[["حضرت سعد بن جبیرؒ","b"],[" کہتے ہیں حضرت ابن عباسؓ کا طائف میں انتقال ہوا۔ میں ان کے جنازے میں شریک ہوا تو اتنے میں ایک پرندہ آیا، اس جیسی شکل و صورت کا پرندہ کبھی کسی نے نہیں دیکھا تھا۔ وہ پرندہ آ کر ان کے جسم میں داخل ہو گیا، ہم دیکھتے رہے اور سوچتے رہے کہ کیا اب باہر نکلے گا لیکن کسی نے اسے باہر نکلتے نہ دیکھا۔ اور جب انہیں دفن کیا گیا تو کسی نے قبر کے کنارے پر یہ آیت پڑھی اور پڑھنے والے کا کچھ پتہ نہ چلا",""]]],["q",[["يَـٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ ۝ ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً ۝ فَٱدْخُلِى فِى عِبَـٰدِى ۝ وَٱدْخُلِى جَنَّتِى","a"]]],["p",[["ترجمہ: \"(اور جو ",""],["ٱللَّٰه","a"],[" کے فرمانبردار تھے ان کو ارشاد ہوگا) اے اطمینان والی روح! تو اپنے پروردگار (کے جوار رحمت) کی طرف چل اس طرح سے کہ تو اس سے خوش اور وہ تجھ سے خوش، پھر (ادھر چل کر) تو میرے (خاص) بندوں میں شامل ہو جا (کہ یہ بھی نعمت روحانی ہے) اور میری جنت میں داخل ہو جا۔\" (سورۂ فجر، آیات 27 تا 30)۔ حاکم میں اسماعیل بن علی اور عیسیٰ بن علی کی روایت میں یہ ہے کہ وہ سفید پرندہ تھا اور ہیثمی کی روایت میں ہے کہ وہ سفید پرندہ تھا جسے بگلا کہا جاتا ہے۔ میمون بن مہران کی روایت میں ہے کہ جب ان پر مٹی ڈال دی گئی تو ہم نے ایک آواز سنی، ہم سن رہے تھے لیکن بولنے والا نظر نہیں آ رہا تھا۔",""],[" (4)","s"],[" (5)","s"]]]],"f":[["(4)","Haakim (Vol.3 Pg.543). Tabraani has reported a similar narration from reliable sources as confirmed by Haythami (Vol.9 Pg.285). One of his narrations states that the bird was a crane."],["(5)","Abu Nu'aym in his Hilyah (Vol.1 Pg.329)."]]},{"b":[["n",[["حضرت میمون بن مہرانؒ","b"],[" کی دوسری روایت میں ہے کہ جب حضرت ابن عباسؓ کا انتقال ہوا اور انہیں کفن پہنایا جانے لگا تو ایک سفید پرندہ تیزی سے ان پر گرا اور ان کے کفن کے اندر چلا گیا۔ اسے بہت تلاش کیا گیا لیکن نہ ملا۔ حضرت ابن عباسؓ کے آزاد کردہ غلام حضرت عکرمہؒ نے کہا کیا تم لوگ بیوقوف ہو؟ (جو پرندہ تلاش کر رہے ہو) یہ تو ان کی بینائی ہے جس کے بارے میں حضورؐ نے ان سے وعدہ فرمایا تھا کہ وفات کے دن انہیں واپس مل جائے گی۔ پھر جب لوگ جنازہ قبر پر لے گئے اور انہیں لحد میں رکھ دیا گیا تو غیبی آواز نے چند کلمات کہے جنہیں ان سب لوگوں نے سنا جو قبر کے کنارے پر تھے۔ پھر میمونؒ نے پچھلی آیات ذکر کیں۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.230)."]]}]},"241":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضرت خریم بن فاتکؓ نے حضرت عمر بن خطابؓ سے کہا اے امیر المومنین! کیا آپ کو نہ بتاؤں کہ میرے اسلام لانے کی ابتدا کیسے ہوئی؟ حضرت عمرؓ نے فرمایا ضرور بتاؤ۔ انہوں نے کہا میں ایک مرتبہ اپنے جانور تلاش کر رہا تھا اور ان کے نشانات پر چل رہا تھا کہ اسی میں براق العزاف مقام پر مجھے رات آ گئی تو میں نے اونچی آواز سے پکار کر کہا میں اس وادی کے (جن) بادشاہ کی پناہ چاہتا ہوں اس کی قوم کے بیوقوفوں سے۔ تو غیب سے کسی نے بلند آواز سے کہا",""]]],["q",[["وَيْحَكَ عُذْ بِٱللَّهِ ذِي ٱلْجَلَالِ ۝ وَٱلْمَجْدِ وَٱلنَّعْمَاءِ وَٱلْإِفْضَالِ","a"]]],["q",[["وَاقْرَأْ آيَاتٍ مِنَ ٱلْأَنْفَالِ ۝ وَوَحِّدِ ٱللَّهَ وَلَا تُبَالِ","a"]]],["p",[["ترجمہ: \"تیرا بھلا ہو، ",""],["ٱللَّٰه","a"],[" کی پناہ مانگ جو جلال، بزرگی، نعمت اور فضل والا ہے۔ سورت انفال کی آیتیں پڑھ اور ",""],["ٱللَّٰه","a"],[" کو ایک مان اور کسی کی پرواہ نہ کر۔\" یہ سن کر میں بہت زیادہ ڈر گیا۔ جب میری جان میں جان آئی تو میں نے کہا",""]]],["q",[["يَا أَيُّهَا ٱلْهَاتِفُ مَا تَقُولُ ۝ أَرُشْدٌ عِنْدَكَ أَمْ تَضْلِيلُ","a"]]],["q",[["بَيِّنْ لَنَا هُدِيتَ مَا ٱلسَّبِيلُ","a"]]],["p",[["ترجمہ: \"اے غیبی آواز دینے والے! تو کیا کہہ رہا ہے؟ کیا تو صحیح راستہ دکھانا چاہتا ہے یا گمراہ کرنا چاہتا ہے؟ ",""],["ٱللَّٰه","a"],[" تجھے ہدایت دے، ہمیں صاف صاف بتا کہ کیا صورت ہے؟\" اس نے جواب میں کہا",""]]],["q",[["إِنَّ رَسُولَ ٱللَّهِ ذُو ٱلْخَيْرَاتِ ۝ بِيَثْرِبَ يَدْعُو إِلَى ٱلنَّجَاةِ","a"]]],["q",[["يَأْمُرُ بِٱلصَّوْمِ وَٱلصَّلَاةِ ۝ وَيَزْجُرُ ٱلنَّاسَ عَنِ ٱلْهَنَاتِ","a"]]],["p",[["ترجمہ: \"تمام خیروں کو لے کر آنے والے ",""],["ٱللَّٰه","a"],[" کے رسولؐ یثرب میں نجات کی دعوت دے رہے ہیں، وہ نماز اور روزے کا حکم دیتے ہیں اور شر والے کاموں سے لوگوں کو روکتے ہیں۔\" میں نے اپنی سواری آگے بڑھا کر کہا",""]]],["q",[["أَرْشِدْنِي رَشَدْتَ أُهْدِيتَ ۝ لَا جُعْتَ وَلَا عُرِّيتَ","a"]]],["p",[["ترجمہ: \"مجھے سیدھا راستہ بتا، ",""],["ٱللَّٰه","a"],[" تجھے ہدایت دے، تو کبھی بھوکا نہ ہو اور نہ کبھی ننگا ہو، اور تو ہمیشہ طاقتور سردار بنا رہے اور جو خیر تجھے ملی ہے اس کا مجھ پر زیادہ بوجھ نہ ڈال۔\" وہ یہ اشعار پڑھتا ہوا میرے پیچھے آیا",""]]],["q",[["صَاحَبَكَ ٱللَّهُ وَسَلَّمَ نَفْسَكَا ۝ وَبَلَّغَ ٱلْأَهْلَ وَأَدَّى رَحْلَكَا","a"]]],["q",[["آمِنْ بِهِ أَفْلَحَ رَبِّي حَقَّكَا ۝ وَٱنْصُرْهُ أَعَزَّ رَبِّي نَصْرَكَا","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" ہمیشہ تیرا ساتھی ہو اور تیری جان کو صحیح سالم رکھے اور تجھے گھر والوں تک پہنچائے اور تیری سواری کو بھی پہنچائے۔ تو ",""],["ٱللَّٰه","a"],[" کے رسولؐ پر ایمان لا، میرا رب تیرے حق کو بامراد کرے اور اس رسولؐ کی مدد کر، میرا رب تیری اچھی طرح نصرت کرے۔\" میں نے کہا ",""],["ٱللَّٰه","a"],[" تجھ پر رحم کرے، تو کون ہے؟ اس نے کہا میں اثال کا بیٹا عمرو ہوں اور ",""],["ٱللَّٰه","a"],[" کے رسولؐ کی طرف سے نجد کے مسلمان جنات کا امیر ہوں، تمہارے گھر پہنچنے تک تمہارے اونٹوں کی حفاظت ہوگی، تمہیں اب فکر کرنے کی ضرورت نہیں ہے۔ چنانچہ میں جمعہ کے دن مدینہ میں داخل ہوا۔ حضرت ابوبکر صدیقؓ میرے پاس باہر آئے اور کہا ",""],["ٱللَّٰه","a"],[" تجھ پر رحم کرے، اندر آ جاؤ، ہمیں تمہارے مسلمان ہونے کی خبر پہنچ چکی ہے۔ میں نے کہا مجھے اچھی طرح وضو کرنا نہیں آتا۔ چنانچہ انہوں نے مجھے وضو کرنا سکھایا، پھر میں مسجد میں داخل ہوا۔ میں نے حضورؐ کو منبر پر بیان کرتے ہوئے دیکھا، آپؐ بالکل چودھویں رات کے چاند کی طرح لگ رہے تھے۔ آپؐ فرما رہے تھے جو مسلمان اچھی طرح وضو کرتا ہے اور پھر سوچ سمجھ کر دھیان سے ایسی نماز پڑھتا ہے جس کی ہر طرح حفاظت کرتا ہے وہ جنت میں ضرور داخل ہوگا۔ پھر حضرت عمر بن خطابؓ نے مجھ سے کہا تم اپنی اس حدیث پر گواہ لاؤ ورنہ میں تمہیں سزا دوں گا۔ چنانچہ قریش کے بزرگ حضرت عثمان بن عفانؓ نے میرے حق میں گواہی دی جسے حضرت عمرؓ نے قبول کر لیا۔",""],[" (1)","s"]]]],"f":[["(1)","Rooyaani and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.34)."]]},{"b":[["n",[["ابونعیم نے دلائل النبوۃ میں حضرت ابوہریرہؓ سے اسی جیسی حدیث نقل کی ہے جس میں اشعار اس طرح ہیں",""]]],["q",[["أَرْشِدْنِي رُشْدَ أَيُّهَا هُدِيتَا ۝ لَا جُعْتَ هَذَا وَلَا عُرِّيتَا","a"]]],["q",[["وَلَا صَحِبْتَ صَاحِبًا مَقِيتَا ۝ لَا يُؤْيِنَ ٱلْخَيْرَ أَنْ ثَوَيْتَا","a"]]],["p",[["ترجمہ: \"مجھے صحیح راستہ بتا، ",""],["ٱللَّٰه","a"],[" تجھے ہدایت عطا فرمائے اے فلانے! تو نہ کبھی بھوکا ہو اور نہ کبھی ننگا اور نہ کبھی ایسے ساتھی کے ساتھ رہے جس سے لوگ نفرت کرتے ہوں اور اگر تو مر جائے تو تیری خیر ختم نہ ہو بلکہ ہمیشہ باقی رہے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Dalaa'il (Pg.30)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں حضرت عمرؓ نے حضرت ابن عباسؓ سے فرمایا مجھے کوئی ایسی حدیث سناؤ جس سے حیرت بھی ہو اور خوشی بھی ہو تو حضرت ابن عباسؓ نے مجھے حضرت خریم بن فاتکؓ کا یہ واقعہ سنایا۔ پھر پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Shaybah and Abu Qaasim bin Bushraan, as quoted in Isaabah (Vol.3 Pg.353). Haakim (Vol.3 Pg.621) has reported a similar narration, as has Tabraani, but Haythami (Vol.8 Pg.251) has commented on the chain of narrators. Umawi has also reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.2 Pg.353)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں میں نے جب بھی سنا کہ حضرت عمرؓ نے کسی چیز کے بارے میں کہا ہو کہ میرا گمان یہ ہے کہ یہ اس طرح ہے تو وہ اسی طرح ہوتی جس طرح ان کا گمان ہوتا۔ چنانچہ ایک مرتبہ وہ بیٹھے ہوئے تھے کہ ان کے پاس سے ایک خوبصورت آدمی گزرا۔ حضرت عمرؓ نے فرمایا لو میرا اندازہ غلط ہے یا تو یہ آدمی ابھی تک اپنے جاہلیت والے دین پر ہے یا پھر یہ جاہلیت میں کاہن تھا، اسے میرے پاس لاؤ۔ لوگ اس آدمی کو بلا کر لائے تو حضرت عمرؓ نے اس سے اپنی بات کہی۔ اس نے کہا میں نے آج جیسا دن کبھی نہیں دیکھا کہ کسی مسلمان آدمی کے منہ پر ایسی بات صاف کہہ دی گئی ہو۔ حضرت عمرؓ نے کہا میں تمہیں پُر زور تاکید کرتا ہوں کہ تم مجھے ساری بات بتاؤ۔ اس آدمی نے کہا میں جاہلیت میں کاہن تھا۔ حضرت عمرؓ نے کہا جو جن تمہارے پاس آتا تھا اس کا سب سے عجیب و غریب قصہ کیا ہے؟ اس نے کہا ایک دن میں بازار میں تھا، وہ جن میرے پاس گھبرایا ہوا آیا اور اس نے یہ شعر پڑھے",""]]],["q",[["أَلَمْ تَرَ ٱلْجِنَّ وَإِبْلَاسَهَا ۝ وَيَأْسَهَا مِنْ بَعْدِ إِنْكَاسِهَا","a"]]],["q",[["وَلُحُوقَهَا بِٱلْقِلَاصِ وَأَحْلَاسِهَا","a"]]],["p",[["ترجمہ: \"کیا تم نے دیکھا نہیں کہ تمام جنات حیران و پریشان ہیں اور (پہلے تو آسمان پر چڑھ جاتے تھے اور) اب آسمان سے ناامید ہو کر واپس آ رہے ہیں بلکہ اسلام میں داخل ہو کر جوان اونٹنیوں اور ان پر کجاوے کے نیچے بچھائی جانے والی چادروں والے عربوں کے ساتھ مل رہے ہیں۔\" حضرت عمرؓ نے کہا اس نے سچ کہا، میں بھی ایک دن کفار کے معبودوں کے پاس سویا ہوا تھا کہ ایک آدمی ایک بچھڑا لایا اور اس نے اسے ذبح کیا۔ پھر کسی چیخنے والے نے زور سے چیخ کر کہا، میں نے اس سے زیادہ سخت چیخ کبھی نہیں سنی تھی، اس نے کہا اے جلیح! (یہ کسی آدمی کا نام ہے) یہ کامیابی والا کام ہے، ایک فصیح آدمی ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہہ رہا ہے۔ سب لوگ گھبرا کر اٹھ گئے۔ میں نے کہا میں یہیں رہوں گا، جب تک یہ پتہ نہ چل جائے کہ اس آواز کے پس پردہ کیا ہے تب یہاں سے نہیں جاؤں گا۔ اس نے پھر پکار کر کہا اے جلیح! یہ کامیابی والا کام ہے، ایک فصیح آدمی ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہہ رہا ہے۔ پھر میں وہاں سے اٹھا، کچھ عرصہ بعد ہی ہمیں بتایا گیا کہ یہ نبی ہیں۔ یہ روایت صرف بخاری میں ہے اور یہ کاہن آدمی حضرت سواد بن قاربؓ ہیں۔",""]]]],"f":[]},{"b":[["n",[["حضرت محمد بن کعب قرظیؒ","b"],[" کہتے ہیں ایک دن حضرت عمر بن خطابؓ بیٹھے ہوئے تھے کہ اتنے میں ان کے پاس سے ایک آدمی گزرا۔ کسی نے پوچھا اے امیر المومنین! کیا آپ اس گزرنے والے کو جانتے ہیں؟ حضرت عمرؓ نے پوچھا یہ کون ہے؟ لوگوں نے کہا یہ حضرت سواد بن قاربؓ ہیں جنہیں ان کے پاس آنے والے جن نے حضورؐ کے ظاہر ہونے کی خبر دی تھی۔ چنانچہ حضرت عمرؓ نے پیغام دے کر انہیں بلایا اور فرمایا کیا آپ ہی سواد بن قارب ہیں؟ انہوں نے کہا جی ہاں! حضرت عمرؓ نے فرمایا کیا تم زمانہ جاہلیت میں کہانت کا کام کرتے تھے؟ اس پر حضرت سوادؓ کو غصہ آ گیا اور کہا اے امیر المومنین! جب سے میں مسلمان ہوا ہوں کبھی کسی نے میرے منہ پر ایسی بات نہیں کہی۔ حضرت عمرؓ نے کہا سبحان ",""],["ٱللَّٰه","a"],["! ہم تو جاہلیت میں شرک پر تھے اور یہ شرک تمہاری کہانت سے زیادہ برا تھا۔ تمہارے تابع جن نے حضورؐ کے ظاہر ہونے کی جو خبر دی تھی وہ مجھے بتاؤ۔ انہوں نے کہا اے امیر المومنین! جی ہاں! ایک رات میں لیٹا ہوا تھا اور بیداری اور نیند کی درمیانی حالت میں تھا، میرا جن میرے پاس آیا اور مجھے پاؤں مار کر کہا اے سواد بن قارب! اٹھ اور میری بات سن، اگر تیرے اندر عقل ہے تو تو سمجھ لے کہ (قریش کی شاخ) لوی بن غالب میں ایک رسول مبعوث ہوا ہے جو ",""],["ٱللَّٰه","a"],[" کی عبادت اور اس کی عبادت کی دعوت دیتا ہے۔ پھر یہ شعر پڑھنے لگا",""]]],["q",[["عَجِبْتُ لِلْجِنِّ وَتَطْلَابِهَا ۝ وَشَدِّهَا ٱلْعِيسَ بِأَقْتَابِهَا","a"]]],["q",[["تَهْوِي إِلَى مَكَّةَ تَبْغِي ٱلْهُدَى ۝ مَا صَادِقُ ٱلْجِنِّ كَكَذَّابِهَا","a"]]],["q",[["فَٱرْحَلْ إِلَى ٱلصَّفْوَةِ مِنْ هَاشِمٍ ۝ لَيْسَ قُدَّامُهَا كَأَذْنَابِهَا","a"]]],["p",[["ترجمہ: \"مجھے اس بات پر تعجب ہے کہ جنات حق کو تلاش کر رہے ہیں اور سفید اونٹوں پر کجاوے باندھ کر ہر طرف سفر کر رہے ہیں، یہ سب ہدایت حاصل کرنا چاہتے ہیں اس لیے مکہ کے جا رہے ہیں۔ سچا جن اور جھوٹا جن دونوں ایک جیسے نہیں ہو سکتے، لہٰذا تم سفر کر کے اس ہستی کے پاس جاؤ جو بنی ہاشم میں چیدہ اور عمدہ ہے اور ہدایت میں پہل کرنے والا دیر کرنے والے کی طرح نہیں ہوگا، بلکہ اس سے افضل ہوگا۔\" میں نے اس جن سے کہا مجھے سونے دو، مجھے شام سے بہت نیند آ رہی ہے۔ اگلی رات وہ میرے پاس پھر آیا اور اس نے پھر پاؤں مار کر کہا اے سواد بن قارب! اٹھ اور میری بات سن اور اگر تیرے اندر عقل ہے تو سمجھ لے کہ لوی بن غالب میں ایک رسول مبعوث ہوا ہے جو ",""],["ٱللَّٰه","a"],[" اور اس کی عبادت کی دعوت دے رہا ہے۔ پھر وہ یہ شعر پڑھنے لگا",""]]],["q",[["عَجِبْتُ لِلْجِنِّ وَتَحْيَارِهَا ۝ وَشَدِّهَا ٱلْعِيسَ بِأَكْوَارِهَا","a"]]],["q",[["تَهْوِي إِلَى مَكَّةَ تَبْغِي ٱلْهُدَى ۝ مَا مُؤْمِنُو ٱلْجِنِّ كَكُفَّارِهَا","a"]]],["q",[["فَٱرْحَلْ إِلَى ٱلصَّفْوَةِ مِنْ هَاشِمٍ ۝ بَيْنَ رَوَابِيهَا وَأَحْجَارِهَا","a"]]],["p",[["ترجمہ: \"مجھے اس بات پر تعجب ہے کہ جنات حیران و پریشان ہیں اور سفید اونٹوں پر کجاوے باندھ کر ہر طرف کا سفر کر رہے ہیں، یہ سب ہدایت حاصل کرنا چاہتے ہیں اس لیے مکہ کے جا رہے ہیں۔ مومن جن کافر جن جیسے نہیں ہو سکتے، لہٰذا تم سفر کر کے اس ہستی کے پاس جاؤ جو بنی ہاشم میں چیدہ اور برگزیدہ ہیں اور مکہ کے ٹیلوں اور پتھروں کے درمیان رہتے ہیں۔\" میں نے اس سے کہا مجھے سونے دو، مجھے شام سے بہت نیند آ رہی ہے۔ تیسری رات پھر میرے پاس آیا اور پھر پاؤں مار کر کہا اے سواد بن قارب! اٹھ اور میری بات سن اور اگر تیرے اندر عقل ہے تو سمجھ لے کہ لوی بن غالب میں ایک رسول مبعوث ہوا ہے جو ",""],["ٱللَّٰه","a"],[" کی اور اس کی عبادت کی دعوت دے رہا ہے۔ پھر وہ یہ اشعار پڑھنے لگا",""]]],["q",[["عَجِبْتُ لِلْجِنِّ وَتَجْسَاسِهَا ۝ وَشَدِّهَا ٱلْعِيسَ بِأَحْلَاسِهَا","a"]]],["q",[["تَهْوِي إِلَى مَكَّةَ تَبْغِي ٱلْهُدَى ۝ مَا خَيْرُ ٱلْجِنِّ كَأَنْجَاسِهَا","a"]]],["q",[["فَٱرْحَلْ إِلَى ٱلصَّفْوَةِ مِنْ هَاشِمٍ ۝ وَٱسْمُ بِعَيْنَيْكَ إِلَى رَاسِهَا","a"]]],["p",[["ترجمہ: \"مجھے اس بات پر تعجب ہے کہ جنات حق کو تلاش کر رہے ہیں اور سفید اونٹوں پر کجاوے کے نیچے بچھائی جانے والی چادریں ڈال کر سفر کر رہے ہیں، یہ ہدایت حاصل کرنا چاہتے ہیں اس لیے مکہ کی طرف جا رہے ہیں۔ اور خیر والا جن ناپاک جن کی طرح نہیں ہو سکتا، لہٰذا سفر کر کے اس ہستی کے پاس جاؤ جو بنی ہاشم میں برگزیدہ ہیں اور آنکھیں بلند کر کے مکہ کی چوٹی کی طرف دیکھو۔\" چنانچہ میں اٹھا اور میں نے کہا ",""],["ٱللَّٰه","a"],[" نے میرے دل کو اچھی طرح جانچ لیا ہے یعنی جن کی بات صحیح معلوم ہوتی ہے، اور میں اونٹنی پر سوار ہو کر چل دیا۔ پھر میں مدینہ آیا تو وہاں حضورؐ اپنے صحابہؓ میں تشریف فرما تھے، میں نے قریب جا کر عرض کیا میری درخواست بھی سن لیں۔ آپؐ نے فرمایا کہو۔ میں نے یہ اشعار پڑھے",""]]],["q",[["أَتَانِي نَجِيِّي بَعْدَ هَدْءٍ وَرَقْدَةٍ ۝ وَلَمْ يَكُ فِيمَا قَدْ بَلَوْتُ بِكَاذِبِ","a"]]],["q",[["ثَلَاثُ لَيَالٍ قَوْلُهُ كُلَّ لَيْلَةٍ ۝ أَتَاكَ رَسُولٌ مِنْ لُؤَيِّ بْنِ غَالِبِ","a"]]],["q",[["فَشَمَّرْتُ عَنْ ذَيْلِ ٱلْإِزَارِ وَوَسَّطَتْ ۝ بِيَ ٱلذِّعْلِبُ ٱلْوَجْنَاءُ خَيْرَ ٱلسَّبَاسِبِ","a"]]],["q",[["فَأَشْهَدُ أَنَّ ٱللَّهَ لَا شَيْءَ غَيْرُهُ ۝ وَأَنَّكَ مَأْمُونٌ عَلَى كُلِّ غَائِبِ","a"]]],["q",[["وَأَنَّكَ أَدْنَى ٱلْمُرْسَلِينَ وَسِيلَةً ۝ إِلَى ٱللَّهِ يَا ٱبْنَ ٱلْأَكْرَمِينَ ٱلْأَطَايِبِ","a"]]],["q",[["فَمُرْنَا بِمَا يَأْتِيكَ يَا خَيْرَ مَنْ مَشَى ۝ وَإِنْ كَانَ فِيمَا جَاءَ شَيْبُ ٱلذَّوَائِبِ","a"]]],["q",[["وَكُنْ لِي شَفِيعًا يَوْمَ لَا ذُو شَفَاعَةٍ ۝ سِوَاكَ بِمُغْنٍ عَنْ سَوَادِ بْنِ قَارِبِ","a"]]],["p",[["ترجمہ: \"ابتدائی رات کے کچھ حصے کے گزر جانے اور میرے کچھ سو لینے کے بعد مجھ سے سرگوشی کرنے والا جن میرے پاس تین رات آتا رہا اور جہاں تک میں نے اسے آزمایا وہ جھوٹا نہیں تھا اور ہر رات مجھ سے یہی کہتا رہا کہ تمہارے پاس ایک رسول آیا ہے جو قبیلہ لوی بن غالب میں سے ہے۔ اس پر میں نے سفر کے لیے اپنی لنگی چڑھا لی اور (میں نے سفر شروع کر دیا) تیز رفتار بڑے رخساروں والی اونٹنی مجھے لے کر ہموار اور وسیع غبار آلود میدانوں میں چلتی رہی۔ میں گواہی دیتا ہوں کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کے علاوہ کوئی چیز (عبادت کے لائق) نہیں اور آپ غیب کی ہر بات کے بارے میں قابل اعتماد ہیں اور اے قابل احترام اور پاکیزہ لوگوں کے بیٹے! آپ ",""],["ٱللَّٰه","a"],[" تک پہنچنے کے لیے تمام رسولوں میں سب سے زیادہ قریبی وسیلہ ہیں اور اے روئے زمین پر چلنے والوں میں سب سے اچھے! آپ ہمیں ان تمام اعمال کا حکم دیں جو آپ کے پاس ",""],["ٱللَّٰه","a"],[" کی طرف سے آ رہے ہیں، ہم ان اعمال کو ضرور کریں گے چاہے ان اعمال کی محنت میں ہمارے بال سفید ہو جائیں۔ اور آپ اس دن سفارشی بن جائیں جس دن آپ کے علاوہ اور کوئی سفارشی سواد بن قارب کے کسی کام نہیں آ سکتا۔\" میرے اشعار سن کر حضورؐ اور تمام صحابہؓ بہت زیادہ خوش ہوئے حتیٰ کہ ان سب کے چہروں پر خوشی نمایاں نظر آنے لگی۔ حضرت محمد بن کعب قرظیؒ راوی کہتے ہیں یہ قصہ سنتے ہی حضرت عمرؓ اٹھ کر حضرت سوادؓ سے چمٹ گئے اور فرمایا میری دلی خواہش تھی کہ میں تم سے یہ سارا قصہ سنوں۔ کیا اب بھی وہ جن تمہارے پاس آتا ہے؟ حضرت سوادؓ نے کہا جب سے میں نے قرآن پڑھنا شروع کیا ہے وہ نہیں آیا اور اس جن کی جگہ ",""],["ٱللَّٰه","a"],[" کی کتاب نعم البدل ہے۔ پھر حضرت عمرؓ نے فرمایا ہم قریش کے ایک قبیلہ میں تھے جن کو آل ذریح کہا جاتا ہے۔ انہوں نے اپنا ایک بچھڑا ذبح کیا اور قصاب اس کا گوشت بنا رہا تھا کہ اتنے میں ہم سب نے بچھڑے کے پیٹ میں سے ایک آواز سنی اور بولنے والے کی کوئی چیز ہمیں نظر نہیں آ رہی تھی، وہ یہ کہہ رہا تھا اے آل ذریح! یہ کامیابی والا کام ہے۔ ایک پکارنے والا پکار کر فصیح زبان میں کہہ رہا ہے کہ وہ اس بات کی گواہی دیتا ہے کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Ya'la. Kharaa'iti has reported a similar narration in his Hawaatiful Jinn."]]},{"b":[["n",[["حضرت براءؓ کی روایت میں ہے کہ حضرت سواد بن قاربؓ نے فرمایا میں ہندوستان میں ٹھہرا ہوا تھا کہ ایک رات میرا تابع جن میرے پاس آیا۔ پھر سارے قصے کے بعد آخری اشعار سنانے کے بعد یہ ہے کہ اشعار سن کر حضورؐ اتنے ہنسے کہ آپؐ کے دندان مبارک نظر آنے لگے اور آپؐ نے فرمایا اے سواد! تم کامیاب ہو گئے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Asaakir, as quoted in Al Bidaayah wan Nihaayah (Vol.2 Pg.332)."]]},{"b":[["n",[["حضرت محمد بن کعب قرظیؒ","b"],[" کی دوسری روایت میں ہے کہ حضرت سوادؓ فرماتے ہیں کہ جن کی باتوں سے میرے دل میں اسلام کی محبت بیٹھ گئی اور اسلام کا شوق پیدا ہو گیا۔ صبح کو میں نے اونٹنی پر کجاوہ کسا اور مکہ کی طرف چل پڑا۔ راستہ میں لوگوں نے بتایا کہ نبی کریمؐ ہجرت کر کے مدینہ جا چکے ہیں۔ چنانچہ میں مدینہ چلا گیا اور وہاں جا کر حضورؐ کے بارے میں پوچھا، لوگوں نے بتایا کہ حضورؐ مسجد میں ہیں۔ میں مسجد گیا اور اونٹنی کے پاؤں کو رسی سے باندھ کر اندر گیا تو حضورؐ تشریف فرما تھے اور لوگ آپؐ کے ارد گرد تھے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میری درخواست سن لیں۔ حضرت ابوبکرؓ نے کہا حضورؐ کے قریب آ جاؤ۔ میں آگے بڑھتا رہا یہاں تک کہ حضورؐ کے سامنے پہنچ گیا تو حضورؐ نے فرمایا کہو اور تمہارا جن جو تمہارے پاس آتا رہا اس کے بارے میں بتاؤ۔",""],[" (6)","s"]]]],"f":[["(6)","Haakim (Vol.3 Pg.608). Tabraani has reported a similar narration, as quoted in Majma'uz Zawaa'id (Vol.8 Pg.248). The narration is also reported by Hasan bin Sufyaan. Bayhaqi, Bukhaari in his Taareekh, Baghawi, Tabraani, Ibn Abi Khaythama, Rooyaani and Ibn Shaaheen, as stated in Isaabah (Vol.2 Pg.96)."]]},{"b":[["n",[["حضرت عباس بن مرداس سلمیؓ","b"],[" فرماتے ہیں میرے اسلام لانے کی ابتدا اس طرح ہوئی کہ جب میرے والد مرداس کے مرنے کا وقت قریب آیا تو انہوں نے مجھے ضمار نامی بت کے خیال رکھنے کی وصیت کی۔ میں نے اس بت کو ایک کمرے میں رکھ لیا اور روزانہ اس کے پاس جانے لگا۔ جب نبی کریمؐ کا ظہور ہوا تو ایک دفعہ میں نے آدھی رات کو ایک آواز سنی جس سے میں ڈر گیا اور چھلانگ لگا کر اٹھا اور مدد لینے کے لیے ضمار کے پاس گیا تو میں نے دیکھا کہ اسی کے پیٹ سے آواز آ رہی ہے اور وہ یہ اشعار کہہ رہا ہے",""]]],["q",[["قُلْ لِلْقَبِيلَةِ مِنْ سُلَيْمٍ كُلِّهَا ۝ هَلَكَ ٱلْأَنِيسُ وَعَاشَ أَهْلُ ٱلْمَسْجِدِ","a"]]],["q",[["أَوْدَى ضِمَارُ وَكَانَ يُعْبَدُ مُدَّةً ۝ قَبْلَ ٱلْكِتَابِ إِلَى ٱلنَّبِيِّ مُحَمَّدٍ","a"]]],["q",[["إِنَّ ٱلَّذِي وَرِثَ ٱلنُّبُوَّةَ وَٱلْهُدَى ۝ بَعْدَ ٱبْنِ مَرْيَمَ مِنْ قُرَيْشٍ مُهْتَدِ","a"]]],["p",[["ترجمہ: \"سارے قبیلہ سلیم سے کہہ دو کہ بت اور ان کے پوجنے والے مردہ باد اور مسجد والے زندہ باد۔ ضمار بت ہلاک ہو گیا اور نبی کریم حضرت محمد (",""],["ﷺ","a"],[") کے پاس کتاب کے آنے سے پہلے اس کی عبادت کی جاتی تھی، اور قبیلہ قریش کی جو ہستی (حضرت عیسیٰ) ابن مریم (علیہ السلام) کے بعد نبوت اور ہدایت کی وارث ہوئی ہے وہ ہدایت یافتہ ہے۔\" حضرت عباسؓ فرماتے ہیں میں نے یہ ساری بات لوگوں سے چھپا کر رکھی اور کسی کو نہ بتائی۔ جب کفار غزوہ احزاب سے واپس آئے تو ایک مرتبہ میں ذات عرق کے پاس مقام عقیق کے ایک کنارے میں اونٹوں میں سویا ہوا تھا کہ میں نے ایک دم آواز سنی (جس سے میری آنکھ کھل گئی) اور میں نے دیکھا کہ ایک آدمی شتر مرغ کے پر کے اوپر بیٹھا ہوا کہہ رہا ہے کہ وہ نور حاصل کر لو جو منگل کی رات کو غضباء نامی اونٹنی والے پر بنو عقفاء کے بھائیوں کے علاقہ میں یعنی مدینہ میں اترا ہے۔ اس کے جواب میں اس کی بائیں جانب سے ایک غیبی آواز دینے والے نے یہ اشعار کہے",""]]],["q",[["بَشِّرِ ٱلْجِنَّ وَإِبْلَاسَهَا ۝ إِنْ وُضِعَتِ ٱلْمَطِيُّ أَحْلَاسَهَا","a"]]],["q",[["وَكُلِّئَتِ ٱلسَّمَاءُ أَحْرَاسَهَا","a"]]],["p",[["ترجمہ: \"جنات کو خبر دے دو کہ جنات اس وجہ سے حیران و پریشان ہیں کہ اونٹنیوں نے اپنے پالان رکھ دیے ہیں اور آسمان کے چوکیداروں نے آسمان کی حفاظت شروع کر دی ہے۔\" حضرت عباسؓ کہتے ہیں میں خوفزدہ ہو کر ایک دم اٹھا اور سمجھ گیا کہ حضرت محمدؐ (",""],["ٱللَّٰه","a"],[" کے بھیجے ہوئے) رسول ہیں۔ چنانچہ میں گھوڑے پر سوار ہوا اور بہت تیزی سے سفر کیا یہاں تک کہ میں حضورؐ کی خدمت میں پہنچ کر آپؐ سے بیعت ہو گیا۔ پھر واپس آ کر میں نے ضمار کو آگ سے جلا دیا۔ میں دوبارہ حضورؐ کی خدمت میں حاضر ہوا اور یہ اشعار آپؐ کو سنائے",""]]],["q",[["لَعَمْرُكَ إِنِّي يَوْمَ أَجْعَلُ جَاهِلًا ۝ ضِمَارَ لِرَبِّ ٱلْعَالَمِينَ مُشَارِكَا","a"]]],["q",[["وَتَرْكِي رَسُولَ ٱللَّهِ وَٱلْأَوْسُ حَوْلَهُ ۝ أُولَئِكَ أَنْصَارٌ لَهُ مَا أُولَائِكَا","a"]]],["q",[["كَتَارِكِ سَهْلِ ٱلْأَرْضِ وَٱلْحَزْنَ يَبْتَغِي ۝ لِيَسْلُكَ فِي وَعْثِ ٱلْأُمُورِ ٱلْمَسَالِكَا","a"]]],["q",[["فَآمَنْتُ بِٱللَّهِ ٱلَّذِي أَنَا عَبْدُهُ ۝ وَخَالَفْتُ مَنْ أَمْسَى يُرِيدُ ٱلْمَهَالِكَا","a"]]],["q",[["وَوَجَّهْتُ وَجْهِي نَحْوَ مَكَّةَ قَاصِدًا ۝ أُبَايِعُ نَبِيَّ ٱلْأَكْرَمِينَ ٱلْمُبَارَكَا","a"]]],["q",[["نَبِيٌّ أَتَانَا بَعْدَ عِيسَى بِنَاطِقٍ ۝ مِنَ ٱلْحَقِّ فِيهِ ٱلْفَصْلُ فِيهِ كَذَلِكَا","a"]]],["q",[["أَمِينٌ عَلَى ٱلْفُرْقَانِ أَوَّلُ شَافِعٍ ۝ وَأَوَّلُ مَبْعُوثٍ يُجِيبُ ٱلْمَلَائِكَا","a"]]],["q",[["تَلَافَى عُرَى ٱلْإِسْلَامِ بَعْدَ ٱنْتِقَاضِهَا ۝ فَأَحْكَمَهَا حَتَّى أَقَامَ ٱلْمَنَاسِكَا","a"]]],["q",[["عَنَيْتُكَ يَا خَيْرَ ٱلْبَرِيَّةِ كُلِّهَا ۝ تَوَسَّطْتَ فِي ٱلْفَرْعَيْنِ وَٱلْمَجْدَ مَالِكَا","a"]]],["q",[["وَأَنْتَ ٱلْمُصَفَّى مِنْ قُرَيْشٍ إِذَا سَمَتْ ۝ عَلَى ضُمْرِهَا تَبْقَى ٱلْقُرُونَ ٱلْمُبَارَكَا","a"]]],["q",[["إِذَا ٱنْتَسَبَ ٱلْحَيَّانِ كَعْبٌ وَمَالِكٌ ۝ وَجَدْنَاكَ مَحْضًا وَٱلنِّسَاءَ ٱلْعَوَارِكَا","a"]]],["p",[["ترجمہ: \"آپؐ کی زندگی کی قسم! جب میں جاہل تھا تو میں نے ضمار بت کو رب العالمین کا شریک بنا رکھا تھا اور میں نے ",""],["ٱللَّٰه","a"],[" کے رسولؐ کو چھوڑا ہوا تھا اور قبیلہ اوس ہر وقت آپؐ کے چاروں طرف جاں نثار تھا، یہ سب آپؐ کے مددگار بنے ہوئے تھے اور یہ کیا ہی اچھے لوگ ہیں۔ اور میری مثال اس آدمی جیسی تھی جو نرم زمین کو چھوڑ کر سخت زمین کو تلاش کرے تاکہ مشکل کاموں کے راستے پر چلے۔ پھر میں اس ",""],["ٱللَّٰه","a"],[" پر ایمان لے آیا جس کا میں بندہ ہوں اور میں نے اس آدمی کی مخالفت کی جو (ایمان چھوڑ کر) ہلاکت کے راستوں پر چلنا چاہتا ہے اور میں نے کریم لوگوں کے مبارک نبی سے بیعت ہونے کے ارادے سے اپنا رخ مکہ کی طرف کر لیا۔ عیسیٰ علیہ السلام کے بعد ہمارے پاس ایسے نبی آئے ہیں جو بولتا ہے (یعنی قرآن) اور اس میں ایسی باتیں ہیں جن سے حق اور باطل جدا ہو جاتا ہے۔ حضورؐ قرآن کے امین ہیں اور (قیامت کے دن) سب سے پہلے سفارش کریں گے اور سب سے پہلے اٹھائے جائیں گے اور فرشتوں کو جواب دیں گے۔ اسلام کے دستے ٹوٹ چکے تھے، آپؐ نے ان سب کو جوڑ دیا اور انہیں خوب مضبوط کیا اور سارے احکام الٰہی زندہ کر دیے۔ اے ساری مخلوق میں سب سے بہترین شخص! آپ ہی میرے مقصود ہیں، آپ اگلوں پچھلوں میں اعلیٰ نسب والے ہیں اور قبیلہ مالک میں بزرگی میں سب سے آگے ہیں۔ جب قریش بھوک اور کمزوری کے باوجود بلندیاں حاصل کر رہے ہیں تو آپؐ ان میں سب سے زیادہ صاف ستھرے اور پاکیزہ ہیں اور آپؐ تمام زمانوں میں بابرکت رہیں گے۔ جب قبیلہ کعب اور قبیلہ مالک اپنا اپنا نسب بیان کریں گے تو ہم آپ کو خالص نسب والا اور عورتوں کو گندا پائیں گے۔\" اور خرائطی کی روایت میں پہلے تین اشعار کے بعد یہ ہے کہ حضرت عباس بن مرداسؓ فرماتے ہیں کہ میں خوفزدہ ہو کر نکلا اور اپنی قوم کے پاس آیا اور انہیں سارا قصہ سنایا اور اپنی قوم بنو حارثہ کے تین سو آدمی لے کر حضورؐ کی خدمت میں مدینہ گیا اور وہاں جا کر مسجد میں داخل ہوئے۔ جب حضورؐ نے مجھے دیکھا تو فرمایا اے عباسؓ! تمہارے اسلام لانے کی کیا صورت ہوئی؟ میں نے آپؐ کو سارا قصہ سنایا جس سے آپؐ بہت خوش ہوئے اور یوں میں اور میری قوم والے سب مسلمان ہو گئے۔",""],[" (7)","s"]]]],"f":[["(7)","Kharaa'iti, as quoted in Al Bidaayah wan Nihaayah (Vol.2 Pg.341). Abu Nu'aym has reported a similar narration in his Dalaa'il, as quoted in Al Bidaayah wan Nihaayah (Vol.2 Pg.342). Tabraani has also reported a similar narration, but Haythami (Vol.8 Pg.247) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں نبی کریمؐ کے مبعوث ہونے کی خبر مدینہ میں سب سے پہلے اس طرح ملی کہ مدینہ کی ایک عورت کا ایک جن تابع تھا۔ ایک دفعہ وہ سفید پرندے کی شکل میں آیا اور اس کی دیوار پر بیٹھ گیا۔ اس عورت نے اس سے کہا تم نیچے کیوں نہیں آتے تاکہ ہم آپس میں باتیں کریں اور ایک دوسرے کو حالات بتائیں۔ اس نے کہا مکہ میں ایک نبی مبعوث ہوئے ہیں جنہوں نے زنا کو حرام قرار دیا ہے اور ہمارا چین سکون چھین لیا ہے (پہلے ہم آسمان پر جا کر وہاں کی خبریں لے آتے تھے، اب وہاں نہیں جا سکتے، اس لیے پریشان ہیں)۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Dalaa'il (Pg.29). Ahmad and Tabraani have reported a similar narration from reliable sources as confirmed by Haythami (Vol.8 Pg.243). Ibn Sa'd (Vol.1 Pg.190) has also reported a similar narration."]]},{"b":[["n",[["حضرت علی بن حسینؒ","b"],[" فرماتے ہیں حضورؐ کے بارے میں مدینہ میں سب سے پہلی خبر اس طرح آئی کہ ایک عورت تھی اس کا نام فاطمہ تھا، اس کے پاس ایک جن آیا کرتا تھا۔ چنانچہ ایک دن وہ جن آیا اور دیوار پر کھڑا ہو گیا، اس عورت نے کہا تم نیچے کیوں نہیں آتے؟ اس نے کہا نہیں، اب وہ رسول مبعوث ہو گئے ہیں جنہوں نے زنا کو حرام کر دیا ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Waaqidi, as quoted in Al Bidaayah wan Nihaayah (Vol.2 Pg.338)."]]},{"b":[["n",[["حضرت عثمان بن عفانؓ","b"],[" فرماتے ہیں حضورؐ کی بعثت سے پہلے ہم ایک تجارتی قافلہ میں ملک شام گئے۔ جب ہم ملک شام کی حدود میں داخل ہو گئے تو وہاں ایک نجومی عورت ہمارے سامنے آئی اور اس نے کہا کہ میرا (جن) ساتھی میرے دروازے پر آ کر کھڑا ہو گیا، میں نے کہا تو اندر کیوں نہیں آتا؟ اس نے کہا اب اس کی کوئی صورت نہیں ہے کیونکہ احمدؐ کا ظہور ہو گیا ہے اور ایسا حکم آ گیا ہے جو میرے بس میں نہیں ہے۔ میں وہاں سے جب مکہ واپس آیا تو دیکھا کہ مکہ میں حضورؐ کا ظہور ہو چکا ہے اور وہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کی دعوت دے رہے ہیں۔",""],[" (10)","s"]]]],"f":[["(10)","Waaqidi, as quoted in Al Bidaayah wan Nihaayah (Vol.2 Pg.338). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.29)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں ایک بڑے میاں نے جاہلیت کا زمانہ پایا تھا، انہیں ابن عیسیٰ کہا جاتا تھا، غزوہ رودس میں ہم اور وہ اکٹھے تھے (رودس ملک شام کا ایک جزیرہ ہے)۔ انہوں نے مجھے اپنا یہ واقعہ سنایا کہ میں اپنے خاندان کی ایک گائے ہانکے جا رہا تھا کہ اتنے میں میں نے اس کے پیٹ سے یہ آواز سنی اے آل ذریح! ایک صاف اور واضح بات ہے کہ ایک آدمی بلند آواز سے ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہہ رہا ہے۔ وہ بڑے میاں کہتے ہیں پھر ہم مکہ آئے تو ہم نے دیکھا کہ وہاں نبی کریمؐ کا ظہور ہو چکا ہے۔",""],[" (11)","s"]]]],"f":[["(11)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.8 Pg.243)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ ایک کافر جن نے مکہ میں ابو قبیس پہاڑ پر آواز دی، وہ نظر نہیں آ رہا تھا، اس نے یہ اشعار کہے",""]]],["q",[["قبح الله رأي كعب بن فهر ۝ مارق العقول والأحلام","a"]]],["q",[["دينها أنها يعنف فيها ۝ دين آبائها الحماة الكرام","a"]]],["q",[["خالف الجن جن بصرى عليكم ۝ ورجال النخيل والآطام","a"]]],["q",[["هل كريم لكم له نفس حر ۝ ماجد الوالدين والأعمام","a"]]],["q",[["يوشك الخيل إن تروها تهادى ۝ تقتل القوم في بلاد التهام","a"]]],["q",[["ضارب ضربة تكون نكالا ۝ ورواحا من كربة واغتمام","a"]]],["p",[["ترجمہ: \"کعب بن فہر یعنی قریش کی رائے کو ",""],["ٱللَّٰه","a"],[" برا کرے، ان کی عقل اور سمجھ کس قدر کمزور ہے۔ (قریش میں جو مسلمان ہو چکے ہیں) ان کا دین یہ ہے کہ وہ اپنے حفاظت کرنے والے بزرگ آباؤ اجداد کے دین یعنی بت پرستی کو برا بھلا کہتے ہیں۔ بصریٰ کے جنات نے اور کھجور کے درختوں اور قلعوں کے علاقہ یعنی مدینہ کے رہنے والے انصار نے (اسلام لا کر اور اسے پھیلانے کی محنت کر کے) عام جنات کی مخالفت کی ہے اور اس طرح تمہیں نقصان پہنچایا ہے۔ کیا تم میں ایسا با اخلاق آدمی نہیں ہے جو شریف النفس ہو اور جس کے والدین اور سارے چچا بزرگی والے ہوں؟ عنقریب تم گھوڑوں والا لشکر دیکھو گے جو ایک دوسرے سے آگے بڑھ رہے ہوں گے اور تہامہ کے علاقہ میں (مسلمانوں کی) اس قوم کو قتل کریں گے اور مسلمانوں پر تلواروں سے ایسی ضربیں لگائیں گے جن میں ان کے لیے عبرتناک سزا ہوگی اور تمہارے لیے بے چینی اور غم سے راحت ہوگی (یہ کافر جن مشرکوں کو جھوٹی خوشخبری دے رہا ہے)۔\" حضرت ابن عباسؓ فرماتے ہیں یہ بات سارے مکہ میں پھیل گئی اور مشرکین ایک دوسرے کو یہ اشعار سنانے لگے اور ایمان والوں کو مزید ایذاء دینے اور مار ڈالنے کے ارادے کرنے لگے۔ اس پر حضورؐ نے فرمایا یہ ایک شیطان تھا جس نے لوگوں سے بتوں کے بارے میں بات کی ہے، اسے مسعر کہا جاتا ہے، ",""],["ٱللَّٰه","a"],[" اسے رسوا کرے گا۔ چنانچہ تین دن گزرنے کے بعد اسی پہاڑ پر ایک غیبی آواز دینے والے نے یہ اشعار پڑھے",""]]],["q",[["نحن قتلنا مسعرا ۝ لما طغى واستكبرا","a"]]],["q",[["وسفه الحق وسن المنكرا ۝ قنعته سيفا جروفا مبترا","a"]]],["q",[["بشتمه نبينا المطهرا","a"]]],["p",[["ترجمہ: \"جب مسعر نے سرکشی اور تکبر کیا اور حق کو بیوقوفی کی چیز بتایا اور منکر چیز کو چلایا تو ہم نے اسے قتل کر دیا۔ میں نے ایسی تلوار سے اس کے سر پر وار کیا جو کام پورا کر دینے والی اور ٹکڑے ٹکڑے کرنے والی ہے۔ یہ سب کچھ اس وجہ سے کیا کہ اس نے ہمارے پاک نبی کی شان میں برے کلمات استعمال کیے تھے۔\" حضورؐ نے فرمایا یہ ایک قوی ہیکل جن تھا جسے سمج کہا جاتا تھا، میں نے اس کا نام عبد",""],["ٱللَّٰه","a"],[" رکھا تھا، یہ مجھ پر ایمان لایا تھا۔ اس نے مجھے بتایا کہ وہ مسعر کو تین دن سے تلاش کر رہا تھا۔ اس پر حضرت علی بن ابی طالبؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" اسے جزائے خیر دے۔",""],[" (12)","s"]]]],"f":[["(12)","Abu Nu'aym in his Dalaa'il (Pg.30). Umawi has reported a similar narration in his Maghaazi, as quoted in Al Bidaayah wan Nihaayah (Vol.2 Pg.348). Faakihi has also reported a similar narration in his Akhbaar Makkah, as quoted in Isaabah (Vol.2 Pg.78)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن محمودؒ","b"],[" کہتے ہیں مجھے یہ خبر پہنچی ہے کہ قبیلہ خثعم کے چند آدمی کہتے تھے کہ جن باتوں کی وجہ سے ہمیں اسلام کی دعوت ملی ان میں سے ایک بات یہ ہے کہ ہم بت پرست قوم تھے۔ ایک دن ہم لوگ اپنے ایک بت کے پاس تھے کہ کچھ لوگ اس بت کے پاس اپنا ایک فیصلہ لے کر آئے، انہیں امید تھی کہ جس بات میں ہمارا اختلاف ہو رہا ہے اس کا حل ہمیں اس بت سے مل جائے گا۔ اتنے میں ایک غیبی آواز دینے والے نے انہیں آواز دے کر کہا",""]]],["q",[["يَا أَيُّهَا ٱلنَّاسُ ذَوُو ٱلْأَجْسَامِ ۝ مِنْ بَيْنِ أَشْيَاخٍ إِلَى غُلَامِ","a"]]],["q",[["مَا أَنْتُمْ وَطَائِشُ ٱلْأَحْلَامِ ۝ وَمُسْنَدُ ٱلْحُكْمِ إِلَى ٱلْأَصْنَامِ","a"]]],["q",[["أَكُلُّكُمْ فِي حَيْرَةٍ نِيَامِ ۝ أَمْ لَا تَرَوْنَ مَا ٱلَّذِي أَمَامِي","a"]]],["q",[["قَدْ لَاحَ لِلنَّاظِرِ مِنْ تِهَامِ ۝ مِنْ سَاطِعٍ يَجْلُو حَيَّ ٱلظَّلَامِ","a"]]],["q",[["ذَاكَ نَبِيٌّ سَيِّدُ ٱلْأَنَامِ ۝ قَدْ جَاءَ بَعْدَ ٱلْكُفْرِ بِٱلْإِسْلَامِ","a"]]],["q",[["أَكْرَمَهُ ٱلرَّحْمَنُ مِنْ إِمَامِ ۝ وَمِنْ رَسُولٍ صَادِقِ ٱلْكَلَامِ","a"]]],["q",[["أَعْدَلُ ذِي حُكْمٍ مِنَ ٱلْأَحْكَامِ ۝ يَأْمُرُ بِٱلصَّلَاةِ وَٱلصِّيَامِ","a"]]],["q",[["وَٱلْبِرِّ وَٱلصِّلَةِ لِلْأَرْحَامِ ۝ وَيَزْجُرُ ٱلنَّاسَ عَنِ ٱلْآثَامِ","a"]]],["q",[["وَٱلرِّجْسِ وَٱلْأَوْثَانِ وَٱلْحَرَامِ ۝ مِنْ هَاشِمٍ فِي ذُرْوَةِ ٱلسَّنَامِ","a"]]],["q",[["مُسْتَعْلِنًا فِي ٱلْبَلَدِ ٱلْحَرَامِ","a"]]],["p",[["ترجمہ: \"اے جسم والے انسانو! اے بوڑھے، بچے، چھوٹے، بڑے تمام انسانو! تم بالکل بے عقل ہو اور اپنے فیصلے تم نے بتوں کے سپرد کر رکھے ہیں۔ کیا تم سب حیرت میں سوئے ہوئے ہو؟ کیا تمہیں وہ چیز نظر نہیں آ رہی جو میرے سامنے ہے؟ وہ ایک روشن نور ہے جو اندھیرے کی تاریکی کو بھی دور کر رہا ہے۔ وہ نور دیکھنے والوں کے لیے تہامہ کے پہاڑوں سے ظاہر ہو رہا ہے۔ یہ وہ نبی ہیں جو تمام مخلوق کے سردار ہیں اور کفر کے بعد اسلام لے کر آئے ہیں، رحمان نے ان کا خاص اکرام فرمایا ہے۔ یہ امام، رسول، سچی گفتگو کرنے والے اور سب سے زیادہ انصاف والا فیصلہ کرنے والے ہیں۔ وہ نماز، روزے، نیکی اور صلہ رحمی کا حکم دیتے ہیں اور لوگوں کو گناہوں سے، پلیدی سے، بتوں سے اور حرام کاموں سے روکتے ہیں اور وہ قبیلہ بنو ہاشم میں سے ہیں اور سب سے اعلیٰ نسب والے ہیں اور ",""],["ٱللَّٰه","a"],[" کے قابل احترام شہر مکہ میں وہ سارے کام علی الاعلان کر رہے ہیں۔\" جب ہم نے یہ سنا تو ہم اس بت کے پاس سے اٹھ کر آ گئے اور نبی کریمؐ کی خدمت میں حاضر ہو کر مسلمان ہو گئے۔",""],[" (13)","s"]]]],"f":[["(13)","Kharaa'iti, as quoted in Al Bidaayah wan Nihaayah (Vol.2 Pg.343). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.33)."]]},{"b":[["n",[["حضرت تمیم داریؓ","b"],[" فرماتے ہیں جب نبی کریمؐ مبعوث ہوئے اس وقت میں شام میں تھا، میں اپنی کسی ضرورت سے سفر میں نکلا تو راستہ میں رات آ گئی۔ میں نے کہا آج رات اس وادی کے بڑے سردار (جن) کی پناہ میں ہوں (زمانہ جاہلیت میں عربوں کا خیال تھا کہ ہر جنگل اور ہر وادی پر کسی جن کی حکومت ہوتی ہے)۔ جب میں بستر پر لیٹا تو ایک منادی نے آواز لگائی، وہ مجھے نظر نہیں آ رہا تھا، اس نے کہا تم ",""],["ٱللَّٰه","a"],[" کی پناہ مانگو کیونکہ جنات ",""],["ٱللَّٰه","a"],[" کے مقابلہ میں کسی کو پناہ نہیں دے سکتے۔ میں نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! تم کیا کہہ رہے ہو؟ اس نے کہا ان پڑھوں میں ",""],["ٱللَّٰه","a"],[" کی طرف سے آنے والے رسولؐ ظاہر ہو چکے ہیں۔ ہم نے (مکہ میں) حجون مقام پر ان کے پیچھے نماز پڑھی ہے اور ہم مسلمان ہو گئے ہیں اور ہم نے ان کا اتباع اختیار کر لیا ہے اور اب جنات کے تمام مکر و فریب ختم ہو گئے ہیں، اب (وہ آسمان پر جانا چاہتے ہیں تو) ان کو ستارے مارے جاتے ہیں۔ تم محمدؐ کے پاس جاؤ جو رب العالمین کے رسول ہیں اور مسلمان ہو جاؤ۔ حضرت تمیمؓ کہتے ہیں میں صبح کو دیر ایوب بستی میں گیا اور وہاں ایک پادری کو سارا قصہ سنا کر اس سے اس کے بارے میں پوچھا۔ اس نے کہا جنات نے تم سے سچ کہا ہے، وہ نبی حرم (مکہ) میں ظاہر ہوں گے اور ہجرت کر کے حرم (مدینہ) جائیں گے۔ وہ تمام انبیاء سے بہتر ہیں، کوئی اور تم ان تک پہنچنے سے پہلے نہ پہنچ جائے اس لیے جلدی جاؤ۔ حضرت تمیمؓ کہتے ہیں میں ہمت کر کے چل پڑا اور حضورؐ کی خدمت میں حاضر ہو کر مسلمان ہو گیا۔",""],[" (14)","s"]]]],"f":[["(14)","Abu Nu'aym, as quoted in Al Bidaayah wan Nihaayah (Vol.2 Pg.350)."]]},{"b":[["n",[["حضرت واثلہ بن اسقعؓ","b"],[" فرماتے ہیں حضرت حجاج بن علاط بہزی سلمیؓ کے مسلمان ہونے کی صورت یہ ہوئی کہ وہ اپنی قوم کے کچھ سواروں کے ساتھ مکہ کے ارادے سے نکلے، رات کو یہ لوگ ایک وحشت ناک اور خوفناک وادی میں پہنچے تو گھبرا گئے۔ ان کے ساتھیوں نے ان سے کہا اے ابوکلاب! (یہ حضرت حجاجؓ کی کنیت ہے) اٹھو اور اپنے لیے اور اپنے ساتھیوں کے لیے (اس وادی کے سردار جن سے) امن مانگو۔ حضرت حجاجؓ نے کھڑے ہو کر یہ اشعار پڑھے",""]]],["q",[["أُعِيذُ نَفْسِي وَأُعِيذُ صَحْبِي ۝ مِنْ كُلِّ جِنِّيٍّ بِهَذَا ٱلنَّقَبِ","a"]]],["q",[["حَتَّى أَؤُوبَ وَيَؤُوبَ سَالِمًا رَكْبِي","a"]]],["p",[["ترجمہ: \"میں اپنے آپ کو اور اپنے ساتھیوں کو ہر اس جن سے پناہ دیتا ہوں جو اس پہاڑی راستے میں موجود ہے تاکہ میں اور میرے ساتھی صحیح سالم اپنے گھر واپس پہنچ جائیں۔\" اس کے بعد حضرت حجاجؓ نے کسی نظر نہ آنے والے کو یہ آیت پڑھتے ہوئے سنا",""]]],["q",[["يَـٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ إِنِ ٱسْتَطَعْتُمْ أَن تَنفُذُوا۟ مِنْ أَقْطَارِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ فَٱنفُذُوا۟ ۚ لَا تَنفُذُونَ إِلَّا بِسُلْطَـٰنٍ","a"]]],["p",[["ترجمہ: \"اے جن اور انسان کے گروہ! اگر تم کو یہ قدرت ہے کہ آسمان اور زمین کی حدود سے کہیں باہر نکل جاؤ تو (ہم بھی دیکھیں) نکلو، مگر بدون زور کے نہیں نکل سکتے (اور زور ہے نہیں، پس نکلنے کا وقوع بھی متحمل نہیں)۔\" (سورۂ رحمٰن، آیت 33)۔ جب یہ لوگ مکہ پہنچے تو انہوں نے قریش کی ایک مجلس میں یہ بات بتائی۔ قریش نے کہا اے ابوکلاب! آپ ٹھیک کہہ رہے ہو، ",""],["ٱللَّٰه","a"],[" کی قسم! یہ کلام بھی اسی کلام میں سے ہے جس کے بارے میں محمدؐ دعویٰ کرتے ہیں کہ ان پر یہ کلام ",""],["ٱللَّٰه","a"],[" کی طرف سے نازل ہوا ہے۔ حضرت حجاجؓ نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! خود میں نے بھی سنا ہے اور میرے ساتھ ان لوگوں نے بھی سنا ہے۔ یہ باتیں ہو رہی تھیں کہ اتنے میں عاصی بن وائل آیا، لوگوں نے اس سے کہا اے ابو ہشام! ابوکلاب جو کہہ رہا ہے کیا آپ نے وہ نہیں سنا؟ اس نے پوچھا ابوکلاب کیا کہہ رہا ہے؟ لوگوں نے اسے ساری بات بتائی۔ اس نے کہا آپ لوگ اس پر تعجب کیوں کر رہے ہیں؟ جس جن نے ان کو وہاں یہ کلام سنایا ہے وہی جن یہ کلام محمد (",""],["ﷺ","a"],[") کی زبان پر جاری کرتا ہے۔ حضرت حجاجؓ کہتے ہیں عاصی کی اس بات کی وجہ سے میرے ساتھی میری رائے سے یعنی اسلام لانے سے رک گئے لیکن اس سب سے میری بصیرت میں اضافہ ہوا۔ (پھر ہم لوگ اپنے علاقہ میں واپس آ گئے۔) ایک عرصہ کے بعد میں نے حضورؐ کے بارے میں پوچھا تو مجھے بتایا گیا کہ وہ مدینہ تشریف لے جا چکے ہیں، میں اونٹنی پر سوار ہو کر چل دیا اور مدینہ حضورؐ کی خدمت میں پہنچ گیا اور وادی میں جو سنا تھا وہ حضورؐ کو بتایا۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! تم نے حق بات سنی ہے، ",""],["ٱللَّٰه","a"],[" کی قسم! یہ اسی کلام میں سے ہے جو میرے رب نے مجھ پر نازل کیا ہے۔ اے ابوکلاب! تم نے حق بات سنی ہے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ مجھے اسلام سکھا دیں۔ حضورؐ نے مجھ سے کلمہ اخلاص کی گواہی طلب فرمائی اور فرمایا تم اپنی قوم کے پاس جاؤ اور انہیں ان تمام باتوں کی دعوت دو جن کی میں نے تمہیں دعوت دی ہے کیونکہ یہ حق ہیں۔",""],[" (15)","s"]]]],"f":[["(15)","Ibn Abi Dunya in his Hawaatiful Jinn and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.163). In its chain is Ayyoob bin Suwayd and Muhammad bin Abdullaah Laythi, who are both weak."]]},{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" فرماتے ہیں کچھ لوگ مکہ کے ارادے سے چلے اور راستہ سے بھٹک گئے۔ جب انہوں نے دیکھا کہ اب تو موت آنے والی ہے تو انہوں نے کفن پہنے اور مرنے کے لیے لیٹ گئے۔ اتنے میں درختوں کے بیچ میں سے ایک جن نکل کر ان کے پاس آیا اور کہنے لگا میں ان لوگوں میں سے اکیلا باقی رہ گیا ہوں جنہوں نے نبی کریمؐ کو قرآن پڑھتے ہوئے سنا ہے۔ میں نے حضورؐ کو یہ بھی فرماتے ہوئے سنا کہ مومن مومن کا بھائی ہے اور سفر میں آگے جا کر حالات معلوم کر کے اسے بتانے والا ہے اور راستہ بھٹک جانے کی صورت میں اسے راستہ بتانے والا ہے، وہ اسے بے یار و مددگار نہیں چھوڑتا۔ یہ ہے پانی اور یہ ہے تمہارا راستہ۔ پھر اس نے انہیں پانی کی جگہ بتائی اور راستہ دکھایا۔",""],[" (16)","s"]]]],"f":[["(16)","Abu Nu'aym in his Dalaa'il (Pg.128)."]]},{"b":[["n",[["حضرت سعید بن شییمؒ","b"],[" جو قبیلہ بنو سہم بن مرہ کے ہیں کہتے ہیں میرے والد گرامی نے مجھے یہ واقعہ بیان کیا کہ عیینہ بن حصن جو لشکر خیبر کے یہودیوں کی مدد کے لیے لے کر گیا تھا، میں بھی اس لشکر میں تھا۔ ہم نے عیینہ کے لشکر میں یہ آواز سنی اے لوگو! اپنے گھر والوں کی خبر لو، دشمن نے ان پر حملہ کر دیا ہے۔ یہ سنتے ہی سارے لشکر والے واپس چلے گئے، ایک دوسرے کا انتظار بھی نہیں کیا۔ ہمیں اس آواز کا کچھ پتہ نہ چلا کہ کہاں سے آئی تھی، اس لیے ہمیں یقین ہے کہ یہ آواز آسمان سے آئی تھی۔",""],[" (17)","s"]]]],"f":[["(17)","Baghawi, as quoted in Isaabah (Vol.2 Pg.162)."]]}]},"242":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا ایک دفعہ میں سویا ہوا تھا، ایک شیطان میرے سامنے آیا، میں نے اس کا گلا پکڑ کر اس زور سے گھونٹا کہ اس کی زبان باہر نکل آئی اور اپنے انگوٹھے پر مجھے اس کی زبان کی ٹھنڈک محسوس ہونے لگی۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ حضرت سلیمان علیہ السلام پر رحم فرمائے، اگر ان کی دعا نہ ہوتی تو وہ شیطان بندھا ہوا ہوتا اور تم سب اسے دیکھتے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Dalaa'il (Pg.130). He has also reported the narration of Abu Dardaa in full."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا آج رات ایک سرکش جن چھوٹ کر میرے پاس نماز خراب کرنے آ گیا، ",""],["ٱللَّٰه","a"],[" نے مجھے اسے پکڑنے کی قدرت دے دی۔ میں نے اسے پکڑ لیا۔ میرا ارادہ ہوا کہ میں اسے مسجد کے کسی ستون سے باندھ دوں تاکہ صبح کو آپ سب لوگ اسے دیکھ لیں لیکن مجھے اپنے بھائی حضرت سلیمان علیہ السلام کی یہ دعا یاد آ گئی",""]]],["q",[["رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًا لَّا يَنۢبَغِى لِأَحَدٍ مِّنۢ بَعْدِىٓ","a"]]],["p",[["ترجمہ: \"اے میرے رب! میرا (پچھلا) قصور معاف کر اور (آئندہ کے لیے) مجھ کو ایسی سلطنت دے کہ میرے سوا (میرے زمانے میں) کسی کو میسر نہ ہو۔\" (سورۂ ص، آیت 35)۔ آپؐ نے فرمایا میں نے اسے ذلیل اور رسوا کر کے واپس کر دیا۔ حضرت ابوالدرداءؓ کی روایت میں یہ ہے کہ اگر ہمارے بھائی حضرت سلیمانؑ کی دعا نہ ہوتی تو وہ بندھا ہوا ہوتا اور مدینہ والوں کے بچے اس سے کھیل رہے ہوتے۔",""]]]],"f":[]},{"b":[["n",[["حضرت بریدہؓ","b"],[" فرماتے ہیں مجھے یہ خبر پہنچی کہ حضرت معاذ بن جبلؓ نے حضورؐ کے زمانے میں شیطان کو پکڑا تھا، میں حضرت معاذؓ کے پاس گیا اور میں نے کہا مجھے یہ خبر پہنچی ہے کہ آپ نے حضورؐ کے زمانے میں شیطان کو پکڑا تھا۔ انہوں نے کہا جی ہاں۔ حضورؐ نے صدقہ کی کھجوریں جمع کر کے مجھے دیں، میں نے وہ کھجوریں اپنے ایک کمرے میں رکھ دیں۔ مجھے روزانہ ان کھجوروں میں کمی نظر آتی تھی، میں نے حضورؐ سے اس کی شکایت کی۔ حضورؐ نے فرمایا یہ شیطان کا کام ہے، تم اس کی گھات لگاؤ۔ چنانچہ میں رات کو اس کی گھات میں بیٹھا، جب کچھ رات گزر گئی تو شیطان ہاتھی کی صورت میں آیا۔ جب دروازے کے پاس پہنچا تو شکل بدل کر دروازے کی درزوں سے اندر داخل ہو گیا اور کھجوروں کے پاس جا کر انہیں لقمہ بنا کر کھانے لگ گیا۔ میں نے اپنے کپڑے اچھی طرح باندھے اور جا کر اسے درمیان سے پکڑ لیا اور میں نے کہا اشہد ان ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" وان محمدا عبدہ و رسولہ۔ اے ",""],["ٱللَّٰه","a"],[" کے دشمن! تو صدقہ کی کھجوروں میں سے لے رہا ہے حالانکہ فقراء صحابہ تجھ سے زیادہ ان کھجوروں کے حقدار ہیں۔ میں تجھے حضورؐ کے پاس لے جاؤں گا، وہ تجھے رسوا کریں گے۔ اس نے مجھ سے عہد کیا کہ وہ دوبارہ نہیں آئے گا۔ میں صبح حضورؐ کی خدمت میں گیا، حضورؐ نے فرمایا تمہارے قیدی نے کیا کیا؟ میں نے کہا اس نے مجھ سے عہد کیا کہ وہ دوبارہ نہیں آئے گا۔ حضورؐ نے فرمایا وہ دوبارہ ضرور آئے گا، اس لیے اس کی گھات لگانا۔ چنانچہ میں نے دوسری رات بھی اس کی گھات لگائی تو اس نے پہلی رات کی طرح پھر کیا، میں نے بھی اس کے ساتھ وہی معاملہ کیا، اس نے پھر مجھ سے عہد کیا کہ وہ دوبارہ نہیں آئے گا، اس پر میں نے اسے چھوڑ دیا اور میں صبح صبح بتانے کے لیے حضورؐ کی خدمت میں گیا تو حضورؐ کا اعلانچی یہ اعلان کر رہا تھا معاذ کہاں ہے؟ (میں حضورؐ کی خدمت میں گیا) حضورؐ نے مجھ سے فرمایا اے معاذ! تمہارے قیدی کا کیا ہوا؟ میں نے سارا قصہ بتایا۔ حضورؐ نے فرمایا وہ ضرور آئے گا، تم اس کی گھات میں رہنا۔ میں تیسری رات پھر اس کی گھات میں بیٹھا تو اس نے اسی طرح کیا، میں نے بھی اس کے ساتھ اسی طرح کیا اور پکڑ کر اس سے کہا اے ",""],["ٱللَّٰه","a"],[" کے دشمن! تو دو دفعہ مجھ سے عہد کر چکا ہے، اب تیسری مرتبہ ہے، میں تجھے حضورؐ کی خدمت میں ضرور لے جاؤں گا، وہ تجھے رسوا کریں گے۔ اس نے کہا میں عیالدار شیطان ہوں اور نصیبین سے آپ کے پاس آتا ہوں (جو کہ ملک شام کی ایک جگہ ہے)، اگر مجھے ان کھجوروں کے علاوہ کچھ اور مل جاتا تو میں آپ کے پاس نہ آتا۔ ہم آپ کے اسی شہر میں رہا کرتے تھے لیکن جب آپ کے پاس حضرتؐ مبعوث ہوئے اور ان پر دو آیتیں نازل ہوئیں تو ان آیتوں نے ہمیں یہاں سے بھگا دیا اور ہم جا کر نصیبین رہنے لگے۔ اور جس گھر میں یہ دونوں آیتیں پڑھی جاتی ہیں اس گھر میں شیطان تین دن تک داخل نہیں ہوتا۔ اگر آپ مجھے چھوڑ دیں تو میں آپ کو وہ دونوں آیتیں سکھا دوں گا۔ اس نے کہا آیت الکرسی اور سورۃ بقرہ کی آخری آیات امن الرسول سے لے کر آخر تک۔ میں نے کہا ٹھیک ہے۔ میں نے اسے چھوڑ دیا اور صبح حضورؐ کو بتانے کے لیے گیا تو حضورؐ کا اعلانچی اعلان کر رہا تھا کہ معاذ بن جبل کہاں ہے؟ جب میں آپ کی خدمت میں پہنچا تو آپ نے فرمایا تمہارے قیدی کا کیا بنا؟ میں نے کہا اس نے مجھ سے عہد کیا کہ وہ دوبارہ نہیں آئے گا اور اس نے جو کچھ کہا تھا وہ بھی میں نے حضورؐ کو بتایا۔ حضورؐ نے فرمایا خبیث ہے تو جھوٹا لیکن اس دفعہ اس نے تم سے سچی بات کہی ہے۔ حضرت معاذؓ کہتے ہیں میں بعد میں یہ آیتیں پڑھنے لگ گیا تو پھر کھجوروں کا کام ہونا ختم ہو گیا۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani. Haythami (Vol.6 Pg.322) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.217)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے رمضان کے صدقہ فطر کی حفاظت میرے ذمہ لگائی۔ ایک دن ایک آدمی آ کر اس میں سے لپیں بھر کر لینے لگا۔ میں نے اسے پکڑ لیا اور کہا میں تمہیں حضورؐ کے پاس ضرور لے جاؤں گا۔ اس نے کہا میں محتاج ہوں اور مجھ پر بچوں کی ذمہ داری ہے اور مجھے بہت ہی زیادہ ضرورت ہے۔ میں نے اسے چھوڑ دیا۔ صبح حضورؐ نے فرمایا اے ابوہریرہ! آج رات تمہارے قیدی کا کیا ہوا؟ میں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! اس نے سخت ضرورت مند ہونے اور اہل و عیال کی شکایت کی، مجھے اس پر ترس آ گیا، میں نے اسے چھوڑ دیا۔ حضورؐ نے فرمایا غور سے سن لو! اس نے تم سے جھوٹ بولا ہے اور وہ پھر آئے گا۔ چونکہ حضورؐ نے فرمایا تھا کہ وہ پھر آئے گا اس لیے مجھے یقین ہو گیا کہ وہ ضرور آئے گا، میں اس کی گھات میں بیٹھ گیا، وہ آ کر لپیں بھر بھر کر لینے لگ گیا۔ میں نے اسے پکڑ کر کہا میں تمہیں حضورؐ کے پاس ضرور لے جاؤں گا۔ اس نے کہا مجھے چھوڑ دو کیونکہ میں محتاج ہوں، بہت سے بچوں کی مجھ پر ذمہ داری ہے، اب میں دوبارہ نہیں آؤں گا۔ مجھے اس پر ترس آ گیا، اس لیے میں نے اسے چھوڑ دیا۔ صبح حضورؐ نے مجھ سے فرمایا اے ابوہریرہ! تمہارے قیدی کا کیا ہوا؟ میں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! اس نے سخت ضرورتمند ہونے کی اور بچوں کی شکایت کی، مجھے اس پر ترس آ گیا، میں نے اسے چھوڑ دیا۔ حضورؐ نے فرمایا غور سے سن! اس نے تم سے جھوٹ کہا ہے، وہ پھر آئے گا۔ چنانچہ حضورؐ نے فرمایا تھا کہ وہ پھر آئے گا اس لیے میں سمجھ گیا کہ وہ پھر ضرور آئے گا۔ میں اس کی گھات میں بیٹھ گیا، وہ آ کر پھر لپیں بھر کر لینے لگا۔ میں نے اسے پکڑ کر کہا میں تمہیں حضورؐ کے پاس ضرور لے جاؤں گا، تم دو دفعہ کہہ چکے ہو کہ دوبارہ نہیں آؤں گا لیکن تم پھر آ جاتے ہو، اب یہ تیسری مرتبہ ہے اور آخری مرتبہ ہے۔ اس نے کہا اب مجھے چھوڑ دو، میں تمہیں ایسے کلمات سکھاؤں گا جن سے ",""],["ٱللَّٰه","a"],[" تمہیں نفع پہنچائے گا۔ جب تم بستر پر لیٹا کرو تو آیت الکرسی",""]]],["q",[["ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ آخر تک پڑھا کرو تو صبح تک اللہ کی طرف سے تمہارے لیے ایک حفاظت کرنے والا فرشتہ مقرر رہے گا اور صبح تک کوئی شیطان تمہارے قریب نہیں آ سکے گا۔ میں نے اس کا راستہ چھوڑ دیا۔ صبح حضورؐ نے مجھ سے فرمایا تمہارے قیدی کا کیا ہوا؟ میں نے کہا اس نے کہا تھا کہ وہ مجھے چند ایسے کلمات سکھائے گا جن سے اللہ تعالیٰ مجھے نفع دیں گے۔ آپؐ نے فرمایا غور سے سنو! ہے تو وہ جھوٹا لیکن تم سے اس نے بات سچی کہی ہے، اور تم جانتے ہو تم تین راتوں سے کس سے باتیں کر رہے ہو؟ میں نے کہا نہیں۔ آپؐ نے فرمایا یہ ایک شیطان ہے۔","a"],[" (3)","s"]]]],"f":[["(3)","Bukhaari, as quoted in Mishkaat (Pg.185)."]]},{"b":[["n",[["حضرت ابو ایوب انصاریؓ","b"],[" فرماتے ہیں میرا ایک طاق تھا جس میں کھجوریں رکھی رہتی تھیں، ایک بھوتنی آ کر ان میں سے کھجوریں لے جایا کرتی تھی۔ میں نے نبی کریمؐ سے اس کی شکایت کی۔ حضورؐ نے فرمایا جاؤ، جب تم اسے دیکھو تو کہنا بسم ",""],["ٱللَّٰه","a"],["، حضورؐ تمہیں بلا رہے ہیں، ان کے پاس چلو! میں نے اسے پکڑ لیا تو اس نے قسم کھائی کہ وہ دوبارہ نہیں آئے گی۔ پھر آگے پچھلی حدیث جیسا مضمون ذکر کیا ہے۔ اور اسی تیسری جلد میں صفحہ 207 پر حضرت ابی بن کعبؓ کی اسی جیسی حدیث گزر چکی ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Tirmidhi, who said that it is a hasan ghareeb hadith, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.33). Abu Nu'aym has reported it in his Dalaa'il (Pg.217) from Abu Ayyoob, and Tabraani from Abu Usayd Saa'idi; Haythami (Vol.6 Pg.323) has said that its narrators are reliable."]]},{"b":[["n",[["حضرت ابوالوائلؒ","b"],[" فرماتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا حضورؐ کے ایک صحابیؓ کو ایک شیطان ملا تو انہوں نے اس شیطان سے کشتی کی اور اسے گرا کر اس کے انگوٹھے کو دانتوں سے کاٹا۔ اس شیطان نے کہا مجھے چھوڑ دو، میں تمہیں ایسی آیت سکھاؤں گا کہ ہم میں سے جو بھی اس آیت کو سنتا ہے وہ پیٹھ پھیر کر بھاگ جاتا ہے۔ اس مسلمان نے اسے چھوڑ دیا تو شیطان نے وہ آیت سکھانے سے انکار کر دیا۔ اس مسلمان نے اس سے پھر کشتی کی اور اسے گرا کر اس کے انگوٹھے کو کاٹا اور اسے کہا مجھے وہ آیت بتا (اس نے کہا مجھے چھوڑ دو میں بتاؤں گا، مسلمان نے اسے چھوڑ دیا لیکن) اس نے بتانے سے انکار کر دیا۔ جب مسلمان نے تیسری مرتبہ اسے کشتی میں گرا دیا تو اس شیطان نے کہا یہ سورت بقرہ کی آیت",""]]],["q",[["ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ آخر تک ہے۔ حضرت عبداللہؓ سے کسی نے پوچھا اے ابو عبدالرحمٰن! وہ مسلمان کون تھا؟ حضرت عبداللہؓ نے فرمایا حضرت عمرؓ کے علاوہ اور کون ہو سکتا ہے۔","a"],[" (5)","s"]]]],"f":[["(5)","Tabraani. Haythami has said that its narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا نبی کریمؐ کے ایک صحابیؓ کو ایک جن ملا، انہوں نے اس جن سے کشتی لڑی اور اسے گرا دیا۔ جن نے ان سے کہا دوبارہ کشتی لڑو، تو پھر انہوں نے اس کو گرا دیا۔ ان صحابیؓ نے اس جن سے کہا تم مجھے دبلے پتلے نظر آ رہے ہو اور تمہارا رنگ بھی بدلا ہوا ہے اور تمہارے بازو کتے کے بازوؤں کی طرح چھوٹے ہیں، تو کیا تم سب جن ایسے ہی ہوتے ہو یا ان میں سے تم ہی ایسے ہو؟ اس جن نے کہا نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! میں تو ان میں بڑے جسم والا اور طاقتور ہوں۔ آپ مجھ سے تیسری مرتبہ کشتی کریں، اس دفعہ آپ نے مجھے گرا دیا تو میں آپ کو ایسی چیز سکھاؤں گا جس سے آپ کو فائدہ ہوگا۔ چنانچہ تیسری مرتبہ کشتی ہوئی تو اس مسلمان نے اس کو پھر گرا دیا اور اس سے کہا لاؤ مجھے سکھاؤ۔ اس جن نے کہا کیا آپ آیت الکرسی پڑھتے ہیں؟ اس مسلمان نے کہا جی ہاں۔ اس جن نے کہا آپ اس آیت کو جس گھر میں پڑھیں گے اس گھر سے شیطان نکل جائے گا اور نکلتے ہوئے گدھے کی طرح اس کی ہوا خارج ہو رہی ہوگی اور صبح تک پھر اس گھر میں نہیں آئے گا۔ حاضرین میں سے ایک آدمی نے کہا اے ابو عبدالرحمٰن! یہ نبی کریمؐ کے کون سے صحابی تھے؟ اس سوال پر چیں بہ جبیں ہو کر حضرت عبد",""],["ٱللَّٰه","a"],["ؓ اس کی طرف متوجہ ہوئے اور فرمایا یہ حضرت عمرؓ کے سوا کون ہو سکتا ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani. Haythami (Vol.9 Pg.71) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.131)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" نے فرمایا ہمیں یہ بتایا جاتا تھا کہ حضرت عمرؓ کے زمانہ خلافت میں شیاطین زنجیروں میں بندھے ہوئے تھے، جب وہ شہید ہو گئے تو پھر یہ آزاد ہو کر پھیل گئے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.385)."]]},{"b":[["n",[["حضرت عامر بن عبد","b"],["ٱللَّٰه","a"],[" بن الزبیرؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن زبیرؓ قریش کے سواروں کی ایک جماعت کے ساتھ عمرہ سے واپس آ رہے تھے، جب یناصب پہاڑ کے پاس پہنچے تو انہیں ایک درخت کے پاس ایک آدمی نظر آیا۔ حضرت ابن زبیرؓ اپنے ساتھیوں سے آگے بڑھ کر اس آدمی کے پاس پہنچے اور اسے سلام کیا، اس آدمی نے ان کی پرواہ نہ کی اور ہلکی آواز سے سلام کا جواب دیا۔ حضرت ابن زبیرؓ سواری سے نیچے اترے، اس پر اس آدمی نے کوئی اثر نہ لیا اور اپنی جگہ سے بالکل نہ ہلا۔ حضرت ابن زبیرؓ نے کہا سائے سے پرے ہٹ جاؤ، وہ ناگواری کے ساتھ ایک طرف ہٹ گیا۔ حضرت ابن زبیرؓ فرماتے ہیں میں وہاں بیٹھ گیا اور میں نے اس کا ہاتھ پکڑ کر کہا تو کون ہے؟ اس نے کہا میں جن ہوں۔ اس کے یہ کہتے ہی (غصے کی وجہ سے) میرے جسم کا ہر بال کھڑا ہو گیا۔ میں نے اسے زور سے کھینچ کر کہا تم جن ہو کر اس طرح میرے سامنے آتے ہو۔ اب جو میں نے غور سے دیکھا تو اس کے پاؤں جانور جیسے تھے۔ میں نے جو ذرا زور دکھایا تو وہ نرم پڑ گیا، میں نے اسے ڈانٹا اور کہا تم ذمی ہو کر میرے سامنے آتے ہو۔ وہ وہاں سے بھاگ گیا، اتنے میں میرے ساتھی بھی آ گئے۔ انہوں نے مجھ سے پوچھا کہ آپ کے پاس جو آدمی تھا وہ کہاں گیا؟ میں نے کہا یہ جن تھا جو بھاگ گیا۔ یہ سنتے ہی ان میں سے ہر ایک اپنی سواری سے نیچے گر گیا، پھر میں نے سب کو اٹھا کر ان کی سواری سے باندھ دیا اور میں ان کو لے کر حج کرا کر لایا لیکن اس وقت تک ان کی عقلیں ٹھیک نہیں ہوئی تھیں۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Mubaarak."]]},{"b":[["n",[["حضرت احمد بن ابی الحواریؒ","b"],[" کہتے ہیں میں نے حضرت ابو سلیمان دارانیؒ کو یہ واقعہ بیان کرتے ہوئے سنا کہ حضرت ابن زبیرؓ چاندنی رات میں اپنی سواری پر نکلے اور جا کر تبوک میں پڑاؤ ڈالا۔ ان کی اچانک نظر پڑی تو انہیں اپنی سواری پر ایک بوڑھا بیٹھا ہوا نظر آیا جس کے سر اور داڑھی کے بال سفید تھے۔ حضرت ابن زبیرؓ نے اس پر حملہ کیا جس سے وہ سواری سے ایک طرف ہو گیا اور حضرت ابن زبیرؓ اپنی سواری پر سوار ہو کر آگے چل دیے۔ اس بوڑھے نے بلند آواز سے کہا اے ابن زبیر! ",""],["ٱللَّٰه","a"],[" کی قسم! اگر آپ کے دل میں میرا ڈر بال کے برابر بھی بیٹھ جاتا تو میں آپ کی عقل خراب کر دیتا۔ حضرت ابن زبیرؓ نے فرمایا اے ملعون! کیا تیری وجہ سے میرے دل میں ذرہ برابر ڈر پیدا ہو سکتا ہے؟",""],[" (9)","s"]]]],"f":[["(9)","Al Bidaayah wan Nihaayah (Vol.8 Pg.335)."]]}]},"243":{"lead":[],"stories":[{"b":[["n",[["حضرت سوید بن یزیدؒ","b"],[" کہتے ہیں میں نے ایک دن حضرت ابوذرؓ کو مسجد میں اکیلے بیٹھے ہوئے دیکھا، میں نے موقع غنیمت سمجھا اور جا کر ان کے پاس بیٹھ گیا اور ان سے حضرت عثمانؓ کا تذکرہ کیا۔ انہوں نے فرمایا میں تو حضرت عثمانؓ کے بارے میں ہمیشہ خیر کی بات کہتا ہوں کیونکہ میں نے حضورؐ کے پاس ان کے بارے میں ایک خاص چیز دیکھی ہے۔ میں حضورؐ کی تنہائی کے مواقع تلاش کرتا رہتا تھا اور اس تنہائی میں حضورؐ سے سیکھا کرتا تھا۔ چنانچہ ایک دن میں گیا تو حضورؐ باہر تشریف لائے اور ایک طرف چل دیے، میں بھی آپؐ کے پیچھے ہو لیا۔ ایک جگہ جا کر آپؐ بیٹھ گئے، میں بھی آپؐ کے پاس بیٹھ گیا۔ آپؐ نے فرمایا اے ابوذر! کیوں آئے ہو؟ میں نے عرض کیا ",""],["ٱللَّٰه","a"],[" اور رسول کی محبت کی وجہ سے۔ پھر حضرت ابوبکرؓ آئے اور سلام کر کے حضورؐ کے دائیں طرف بیٹھ گئے۔ حضورؐ نے ان سے پوچھا اے ابوبکر! کیسے آنا ہوا؟ انہوں نے کہا ",""],["ٱللَّٰه","a"],[" اور رسول کی محبت کی وجہ سے۔ پھر حضرت عمرؓ آئے اور حضرت ابوبکرؓ کے دائیں طرف بیٹھ گئے۔ حضورؐ نے فرمایا اے عمر! کیسے آنا ہوا؟ انہوں نے کہا ",""],["ٱللَّٰه","a"],[" اور رسول کی محبت کی وجہ سے۔ پھر حضرت عثمانؓ آئے اور حضرت عمرؓ کے دائیں جانب بیٹھ گئے۔ حضورؐ نے فرمایا اے عثمان! کیسے آنا ہوا؟ انہوں نے کہا ",""],["ٱللَّٰه","a"],[" اور رسول کی محبت کی وجہ سے۔ پھر حضورؐ نے سات یا نو کنکریاں اپنے ہاتھ میں لیں اور وہ کنکریاں تسبیح پڑھنے لگیں اور میں نے شہد کی مکھی کی طرح ان کی بھنبھناہٹ سنی، پھر حضورؐ نے انہیں رکھ دیا تو وہ خاموش ہو گئیں۔ پھر حضورؐ نے وہ کنکریاں اٹھا کر حضرت ابوبکرؓ کے ہاتھ میں رکھ دیں تو وہ کنکریاں پھر تسبیح پڑھنے لگیں اور میں نے شہد کی مکھی جیسی ان کی بھنبھناہٹ سنی، پھر حضورؐ نے انہیں رکھ دیا تو وہ خاموش ہو گئیں۔ پھر حضورؐ نے انہیں لے کر حضرت عثمانؓ کے ہاتھ میں رکھ دیا، وہ کنکریاں پھر تسبیح پڑھنے لگیں اور میں نے شہد کی مکھی جیسی بھنبھناہٹ سنی، پھر حضورؐ نے انہیں رکھ دیا تو وہ خاموش ہو گئیں۔",""],[" (1)","s"]]]],"f":[["(1)","Bazzaar. Haythami (Vol.8 Pg.299) has commented on the chain of narrators."]]},{"b":[["n",[["بیہقی کی روایت میں یہ بھی ہے کہ پھر حضورؐ نے وہ کنکریاں لے کر حضرت عمرؓ کے ہاتھ میں رکھ دیں، وہ تسبیح پڑھنے لگیں اور میں نے شہد کی مکھی جیسی بھنبھناہٹ سنی، پھر حضورؐ نے انہیں رکھ دیا تو وہ خاموش ہو گئیں۔ اس روایت کے آخر میں یہ بھی ہے کہ حضورؐ نے فرمایا یہ نبوت کی خلافت ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.132). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.215)."]]},{"b":[["n",[["طبرانی کی روایت میں یہ بھی ہے کہ پھر حضورؐ نے وہ کنکریاں حضرت علیؓ کو دیں (تو وہ تسبیح پڑھنے لگیں)، پھر حضورؐ نے وہ کنکریاں رکھ دیں تو وہ خاموش ہو گئیں۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani in his Awsat. Haythami (Vol.5 Pg.179) has commented on the chain of narrators."]]},{"b":[["n",[["طبرانی کی دو سندوں میں سے ایک سند میں یہ بھی ہے کہ حلقہ میں جتنے آدمی تھے ان سب نے ہر ایک کے ہاتھ میں ان کنکریوں کی تسبیح سنی، پھر حضورؐ نے وہ کنکریاں ہمیں دے دیں تو ہم میں سے کسی کے پاس بھی ان کنکریوں نے تسبیح نہ پڑھی۔",""]]]],"f":[]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں ہم قرآنی آیات کو اور حضورؐ کے معجزوں کو برکت سمجھا کرتے تھے لیکن آپ لوگ یہ سمجھتے ہو کہ یہ کفار کو ڈرانے کے لیے ہوا کرتے تھے۔ ہم ایک سفر میں نبی کریمؐ کے ساتھ تھے، پانی کم ہو گیا۔ حضورؐ نے فرمایا بچا ہوا پانی لاؤ۔ صحابہؓ ایک برتن میں تھوڑا سا پانی لائے۔ حضورؐ نے اس برتن میں اپنا ہاتھ مبارک ڈالا پھر فرمایا آ جاؤ پاک اور برکت والے پانی کی طرف، اور برکت ",""],["ٱللَّٰه","a"],[" کی طرف سے آ رہی ہے۔ حضرت ابن مسعودؓ کہتے ہیں میں نے دیکھا کہ حضورؐ کی انگلیوں کے درمیان سے پانی پھوٹ رہا ہے۔ اور (یہ حضورؐ کا معجزہ تھا، اسی طرح دوسرا معجزہ یہ ہے کہ) کبھی کھانا کھایا جا رہا تھا اور ہم اس کی تسبیح سن رہے ہوتے تھے۔ حضرت عباسؓ کے لیے حضورؐ کے دعا کرنے کے باب میں یہ گزر چکا ہے کہ دروازے کی چوکھٹ اور کمرے کی دیواروں نے تین دفعہ آمین آمین آمین کہا۔",""],[" (4)","s"]]]],"f":[["(4)","Bukhaari. Tirmidhi has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.97)."]]},{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں حضورؐ جمعہ کے دن کھجور کے تنے کے سہارے سے خطبہ دیا کرتے تھے۔ ایک انصاری عورت یا مرد نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! کیا ہم آپ کے لیے منبر نہ بنا دیں؟ آپؐ نے فرمایا اگر تم چاہو تو بنا دو۔ چنانچہ انہوں نے حضورؐ کے لیے منبر بنایا (جو مسجد میں محراب کے پاس رکھ دیا گیا)۔ جب جمعہ کے دن حضورؐ منبر کے پاس پہنچے تو وہ تنا بچے کی طرح چیخنے لگا۔ حضورؐ منبر سے نیچے اتر کر اس کے پاس آئے اور اسے اپنے سے چمٹا لیا تو وہ اس بچے کی طرح رونے لگا جسے چپ کرایا جا رہا ہو۔ حضرت جابرؓ نے فرمایا وہ تنا اس وجہ سے رو رہا تھا کہ وہ پہلے اپنے پاس ",""],["ٱللَّٰه","a"],[" کا ذکر سنا کرتا تھا (اور اب نہیں سن سکے گا)۔",""],[" (5)","s"]]]],"f":[["(5)","Bukhaari, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.127)."]]},{"b":[["n",[["حضرت جابرؓ کی دوسری روایت میں یہ ہے کہ جب حضورؐ کے لیے منبر بن گیا اور اسے مسجد میں لا کر رکھا گیا اور حضورؐ اس پر تشریف فرما ہو گئے تو ہم نے اس تنے میں سے حاملہ اونٹنی جیسی آواز سنی۔ حضورؐ اس کے پاس تشریف لائے اور اپنا ہاتھ اس پر رکھا جس سے اسے سکون ہوا اور وہ خاموش ہو گیا۔",""],[" (6)","s"]]]],"f":[["(6)","Bukhaari. Ahmad and Bazzaar have reported a similar narration."]]},{"b":[["n",[["احمد کی ایک روایت میں یہ ہے کہ جب حضورؐ کا منبر بن گیا اور آپؐ اس پر تشریف فرما ہوئے تو وہ تنا بے چین ہو گیا اور اونٹنی کی طرح رونے لگا جسے تمام مسجد والوں نے سنا۔ آپؐ منبر سے اتر کر اس کے پاس تشریف لے گئے اور اسے گلے لگایا جس سے وہ خاموش ہو گیا۔",""],[" (7)","s"]]]],"f":[["(7)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.129). Ibn Abdul Barr has reported a similar narration in his Jaami'u Bayaanil Ilm (Vol.2 Pg.197)."]]},{"b":[["n",[["ابونعیم کی روایت میں یہ ہے کہ حضورؐ نے فرمایا اگر میں اسے اپنی بغل میں نہ لیتا تو قیامت تک روتا رہتا۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Dalaa'il (Pg.142)."]]},{"b":[["n",[["امام احمدؒ نے ",""],["حضرت انسؓ","b"],[" سے بھی منبر بنانے کی حدیث نقل کی ہے، اس میں حضرت انسؓ فرماتے ہیں کہ جب حضورؐ خطبہ دینے کے لیے اس لکڑی کی بجائے منبر پر تشریف فرما ہوئے تو میں نے اس لکڑی کو پریشان حال عاشق کی طرح روتے ہوئے سنا اور وہ لکڑی روتی ہی رہی یہاں تک کہ حضورؐ منبر سے نیچے اترے اور چل کر اس کے پاس تشریف لائے اور اسے سینہ سے لگایا تو پھر اس لکڑی کو سکون ہوا۔",""],[" (9)","s"]]]],"f":[["(9)","Ahmad."]]},{"b":[["n",[["علامہ بغویؒ نے بھی اس حدیث کو حضرت انسؓ سے ذکر کیا ہے اور اس میں یہ بھی ہے کہ جب حضرت حسنؒ اس حدیث کو بیان کیا کرتے تو رویا کرتے اور فرماتے اے ",""],["ٱللَّٰه","a"],[" کے بندو! چونکہ حضورؐ کا ",""],["ٱللَّٰه","a"],[" کے ہاں بڑا درجہ ہے اس وجہ سے یہ لکڑی حضورؐ کے شوق میں روئی تھی تو آپ لوگوں کو حضورؐ کی زیارت کا شوق اس سے زیادہ ہونا چاہیے۔",""],[" (10)","s"]]]],"f":[["(10)","Baghawi. Abu Nu'aym has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.127). Ibn Abdul Barr has reported a similar narration in his Jaami' (Vol.2 Pg.197)."]]},{"b":[["n",[["ابویعلیٰ کی روایت میں ہے کہ حضورؐ نے فرمایا اس ذات کی قسم جس کے قبضے میں محمدؐ کی جان ہے! اگر میں اسے اپنے سے نہ چمٹاتا تو یہ ",""],["ٱللَّٰه","a"],[" کے رسول کی جدائی کے غم میں یونہی قیامت تک روتا رہتا۔ پھر حضورؐ کے فرمانے پر اسے دفن کر دیا گیا۔",""],[" (11)","s"]]]],"f":[["(11)","Abu Ya'la and Tirmidhi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.126). Narrations of this kind have also been reported from Ubay bin Ka'b, Sahl bin Sa'd, Abdullaah bin Abbaas, Abdullaah bin Umar, Abu Sa'eed Khudri, Aa'isha and Ummu Salamah, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.125)."]]},{"b":[["n",[["حضرت ابوالبختریؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت ابوالدرداءؓ اپنی ہنڈیا کے نیچے آگ جلا رہے تھے اور حضرت سلمانؓ ان کے ہاں آئے ہوئے تھے۔ حضرت ابوالدرداءؓ نے ہنڈیا میں سے ایک آواز سنی، پھر وہ آواز اونچی ہوئی اور وہ بچے کی طرح تسبیح پڑھنے کی آواز تھی، پھر وہ ہنڈیا نیچے گر پڑی اور الٹی ہو گئی، پھر اپنی جگہ واپس چلی گئی لیکن اس میں سے کوئی چیز نہ گری۔ حضرت ابوالدرداءؓ پکار کر کہنے لگے اے سلمان! عجیب کام دیکھو، ایسا عجیب کام تو نہ آپ نے دیکھا ہوگا اور نہ آپ کے ابا جان نے۔ حضرت سلمانؓ نے کہا اگر آپ خاموش رہتے تو ",""],["ٱللَّٰه","a"],[" کی اور بڑی بڑی نشانیاں سنتے۔",""],[" (12)","s"]]]],"f":[["(12)","Abu Nu'aym in his Hilyah (Vol.1 Pg.224)."]]},{"b":[["n",[["حضرت قیسؒ","b"],[" کہتے ہیں جب حضرت ابوالدرداءؓ حضرت سلمانؓ کو خط لکھتے یا حضرت سلمانؓ حضرت ابوالدرداءؓ کو خط لکھتے تو پیالے والی نشانی انہیں ضرور یاد دلاتے۔ حضرت قیسؒ کہتے ہیں ہم یہ بات بیان کرتے تھے کہ یہ دونوں حضرات پیالہ میں سے کھانا کھا رہے تھے تو پیالے اور پیالے کے اندر کا کھانا دونوں تسبیح پڑھتے رہے۔",""],[" (13)","s"]]]],"f":[["(13)","Abu Nu'aym in his Hilyah (Vol.1 Pg.224)."]]},{"b":[["n",[["حضرت جعفر بن ابی عمرانؒ","b"],[" کہتے ہیں ہمیں روایت پہنچی ہے کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرو بن عاصؓ نے ایک مرتبہ آگ کو یہ کہتے ہوئے سنا کہ میں بھی۔ کسی نے پوچھا اے ابن عمرو! آپ نے یہ کیا کہا؟ انہوں نے کہا اس ذات کی قسم جس کے قبضے میں میری جان ہے! یہ آگ جہنم کی بڑی آگ میں واپس لوٹائے جانے سے پناہ مانگ رہی ہے۔",""],[" (14)","s"]]]],"f":[["(14)","Abu Nu'aym in his Hilyah (Vol.1 Pg.289)."]]}]},"244":{"lead":[],"stories":[{"b":[["n",[["حضرت یحییٰ بن ابی ایوب خزاعیؒ","b"],[" کہتے ہیں میں نے ایک صاحب کو یہ واقعہ بیان کرتے ہوئے سنا کہ حضرت عمرؓ کے زمانے میں ایک عبادت گزار نوجوان تھا جو ہر وقت مسجد میں رہتا تھا اور حضرت عمرؓ کو بہت پسند تھا۔ اس کا ایک بوڑھا باپ تھا، وہ نوجوان عشاء کی نماز پڑھ کر اپنے باپ کے پاس چلا جاتا تھا، اس کے گھر کا راستہ ایک عورت کے دروازے پر پڑتا تھا، وہ عورت اس پر فریفتہ ہو گئی اور اس نوجوان کی وجہ سے اس کے راستہ پر کھڑی رہتی۔ ایک رات وہ نوجوان اس عورت کے پاس سے گزرا تو وہ عورت اسے بہلانے پھسلانے لگی۔ آخر نوجوان اس کے پیچھے چل پڑا۔ جب اس عورت کے گھر کا دروازہ آیا تو وہ اندر چلی گئی لیکن جب یہ نوجوان اندر جانے لگا تو اسے ایک دم ",""],["ٱللَّٰه","a"],[" کا دھیان آ گیا اور وہ غلط خیال دل سے سب جاتا رہا اور یہ آیت اس کی زبان پر جاری ہو گئی",""]]],["q",[["إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَـٰٓئِفٌ مِّنَ ٱلشَّيْطَـٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ","a"]]],["p",[["ترجمہ: \"یقیناً جو لوگ خدا ترس ہیں جب ان کو کوئی خطرہ شیطان کی طرف سے آ جاتا ہے تو وہ یاد میں لگ جاتے ہیں، سو یکایک ان کی آنکھیں کھل جاتی ہیں۔\" (سورۂ اعراف، آیت 201)۔ یہ آیت پڑھتے ہی وہ نوجوان بے ہوش ہو کر گر گیا تو اس عورت نے اپنی ایک باندی کو بلایا اور دونوں نے مل کر اسے اٹھایا اور اس کے گھر کے دروازے پر جا کر اسے بٹھا دیا اور دروازہ کھٹکھٹا کر واپس آ گئیں۔ اس کا باپ اس کی تلاش میں باہر نکلا تو دیکھا کہ وہ بے ہوش پڑا ہوا ہے۔ باپ نے اپنے گھر والوں کو بلایا اور اسے اٹھا کر اندر پہنچایا۔ کافی رات گزرنے کے بعد اسے ہوش آیا تو اس کے باپ نے اس سے پوچھا اے بیٹے! تجھے کیا ہوا؟ اس نے کہا خیر ہے ابا۔ باپ نے کہا تجھے ",""],["ٱللَّٰه","a"],[" کا واسطہ دیتا ہوں، ضرور بتا۔ اس نے سارا واقعہ بتایا۔ باپ نے کہا تم نے کون سی آیت پڑھی تھی؟ اس نے وہی آیت پڑھی۔ پڑھتے ہی بے ہوش ہو کر پھر گر گیا، اب اسے ہلا کر دیکھا تو اس کی روح پرواز کر چکی تھی۔ اسے غسل دے کر باہر لائے اور رات ہی میں اسے دفن کر دیا۔ صبح کچھ لوگوں نے حضرت عمرؓ کو سارا قصہ سنایا۔ حضرت عمرؓ نے اس کے والد کے پاس جا کر تعزیت کی اور فرمایا مجھے کیوں خبر نہ کی؟ باپ نے کہا اے امیر المومنین! رات تھی۔ حضرت عمرؓ نے فرمایا ہمیں اس کی قبر پر لے جاؤ۔ چنانچہ حضرت عمرؓ اور ان کے ساتھی قبر پر گئے۔ حضرت عمرؓ نے کہا اے فلانے!",""]]],["q",[["وَلِمَنْ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ","a"]]],["p",[["ترجمہ: \"اور جو شخص اپنے رب کے سامنے کھڑے ہونے سے (ہر وقت) ڈرتا رہتا ہے اس کے لیے (جنت میں) دو باغ ہوں گے۔\" (سورۂ رحمٰن، آیت 46)۔ تو اس نوجوان نے قبر کے اندر سے جواب دیا اور دو دفعہ کہا اے عمر! میرے رب نے مجھے جنت میں وہ باغ دے دیے ہیں۔ بیہقی کی روایت میں ہے کہ اس نوجوان نے کہا اے چچا جان! حضرت عمرؓ کو جا کر میرا اسلام کہو اور ان سے پوچھو کہ جو اپنے رب کے سامنے کھڑے ہونے سے ڈرے اس کو کیا بدلہ ملے گا؟ اس روایت کے آخر میں ہے کہ حضرت عمرؓ نے اس کی قبر پر کھڑے ہو کر کہا تمہارے لیے دو باغ ہیں، تمہارے لیے دو باغ ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim, as quoted in Kanzul Ummaal (Vol.1 Pg.267), and Ibn Asaakir in the biography of Amr bin Jaami' in his Taareekh, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.279). Bayhaqi has reported it briefly from Hasan, as quoted in Kanzul Ummaal (Vol.1 Pg.267)."]]},{"b":[["n",[["حضرت محمد بن حمیرؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت عمر بن خطابؓ کا بقیع الغرقد قبرستان پر گزر ہوا تو انہوں نے فرمایا السلام علیکم! اے قبرستان والو! ہمارے ہاں کی خبریں تو یہ ہیں کہ تمہاری عورتوں نے اور شادی کر لی، تمہارے گھروں میں دوسرے لوگ رہنے لگ گئے، تمہارا سارا مال تقسیم کر دیا گیا۔ جواب میں غیب سے یہ آواز آئی کہ ہمارے ہاں کی خبریں یہ ہیں کہ ہم نے جو نیک اعمال آگے بھیجے تھے ان کا اجر و ثواب ہم نے پا لیا اور جو مال ہم نے ",""],["ٱللَّٰه","a"],[" کے لیے دوسروں پر خرچ کیا اس کا ہمیں نفع مل گیا اور جو مال ہم پیچھے چھوڑ آئے اتنا ہمیں نقصان ہوا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abi Dunya and Ibn Sam'aani, as quoted in Kanzul Ummaal (Vol.8 Pg.123)."]]}]},"245":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں ایک دفعہ میں میدان بدر کے کنارے چلا جا رہا تھا کہ اتنے میں ایک آدمی ایک گڑھے سے باہر نکلا، اس کی گردن میں زنجیر پڑی ہوئی تھی۔ اس نے مجھے پکار کر کہا اے عبد",""],["ٱللَّٰه","a"],["! مجھے پانی پلا دے، اے عبد",""],["ٱللَّٰه","a"],["! مجھے پانی پلا دے، اے عبد",""],["ٱللَّٰه","a"],["! مجھے پانی پلا دے۔ اب مجھے معلوم نہیں کہ اسے میرا نام معلوم تھا یا اس نے ویسے ہی عربوں کے دستور کے مطابق عبد",""],["ٱللَّٰه","a"],[" کہہ کر پکارا اور نام معلوم نہیں تھا۔ پھر اسی گڑھے سے ایک اور آدمی باہر نکلا، اس کے ہاتھ میں کوڑا تھا، اس نے مجھے پکار کر کہا اے عبد",""],["ٱللَّٰه","a"],["! اسے پانی نہ پلانا کیونکہ یہ کافر ہے۔ پھر اسے کوڑا مارا جس پر وہ آدمی اپنے گڑھے میں واپس چلا گیا۔ میں جلدی سے حضورؐ کی خدمت میں گیا اور سارا واقعہ حضورؐ کو بتایا۔ آپؐ نے مجھ سے فرمایا کیا تم نے اسے دیکھا ہے؟ میں نے کہا جی ہاں! حضورؐ نے فرمایا یہ ",""],["ٱللَّٰه","a"],[" کا دشمن ابوجہل تھا اور اسے قیامت کے دن تک یونہی عذاب ہوتا رہے گا۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani. Haythami (Vol.6 Pg.81) has commented on the chain of narrators."]]}]},"246":{"lead":[],"stories":[{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں قبیلہ بنو حارث بن خزرج کے حضرت زید بن خارجہ انصاریؓ کا حضرت عثمان بن عفانؓ کے زمانہ میں انتقال ہوا تو لوگوں نے ان پر کپڑا ڈال دیا۔ پھر لوگوں نے ان کے سینے میں آواز کی حرکت سنی، پھر وہ بول پڑے اور کہنے لگے حضرت احمد، حضرت احمد (صلی ",""],["ٱللَّٰه","a"],[" علیہ وسلم) کا نام لوح محفوظ میں ہے۔ حضرت ابوبکر صدیقؓ نے سچ کہا، سچ کہا، وہ اپنی ذات کے بارے میں کمزور تھے لیکن ",""],["ٱللَّٰه","a"],[" کے معاملے میں طاقتور تھے، یہ سب کچھ لوح محفوظ میں ہے۔ حضرت عمر بن خطابؓ نے سچ کہا، سچ کہا، وہ طاقتور اور امانت دار تھے اور یہ بات بھی لوح محفوظ میں ہے۔ حضرت عثمان بن عفانؓ نے سچ کہا، سچ کہا، وہ ان تینوں حضرات کے طریقہ پر ہیں۔ امن امان کے چار سال گزر گئے، دو سال رہ گئے ہیں، پھر فتنے آئیں گے اور زور دار آدمی کمزور کو کھا جائے گا اور قیامت قائم ہو جائے گی اور عنقریب تمہارے لشکر کی طرف زبردست خبر آئے گی۔ اریس کا کنواں ایک زبردست چیز ہے اور یہ کنواں کیسی زبردست چیز ہے؟ حضرت سعیدؒ کہتے ہیں پھر بنو خطمہ کے ایک آدمی کا انتقال ہوا، لوگوں نے اس پر کپڑا ڈالا تو اس کے سینے میں بھی آواز کی حرکت سنی، پھر وہ بول پڑا کہنے لگا بنو حارث بن خزرج کے آدمی نے سچ کہا، سچ کہا۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi, reporting from reliable sources, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.156). Ibn Abi Dunya and Bayhaqi have also reported a more detailed narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.293)."]]},{"b":[["n",[["حضرت نعمان بن بشیرؓ","b"],[" فرماتے ہیں حضرت زید بن خارجہؓ ظہر، عصر کے درمیان مدینہ کے ایک راستہ پر چلے جا رہے تھے۔ چلتے چلتے ان کا انتقال ہو گیا اور وہ زمین پر گر گئے۔ اٹھا کر انہیں ان کے گھر لایا گیا اور دو کپڑوں اور ایک چادر سے انہیں ڈھانپ دیا گیا۔ مغرب عشاء کے درمیان انصار کی عورتیں ان کے پاس جمع ہو کر اونچی آواز سے رونے لگیں، اتنے میں انہوں نے چادر کے نیچے سے دو مرتبہ آواز سنی اے لوگو! خاموش ہو جاؤ۔ حضرت زیدؓ کے چہرے اور سینے سے کپڑا ہٹایا گیا تو انہوں نے کہا محمد رسول ",""],["ٱللَّٰه","a"],[" جو کہ ان پڑھ نبی ہیں اور تمام نبیوں کے لیے مہر ہیں، یہ بات لوح محفوظ میں ہے۔ (اس کے بعد وہ خاموش ہو گئے۔) پھر کچھ دیر کے بعد ان کی زبان پر یہ الفاظ جاری ہوئے حضرت ابوبکر صدیقؓ نے سچ کہا، سچ کہا جو کہ ",""],["ٱللَّٰه","a"],[" کے رسولؐ کے خلیفہ ہیں۔ وہ اپنے بدن کے اعتبار سے تو کمزور تھے لیکن ",""],["ٱللَّٰه","a"],[" کے معاملے میں بہت مضبوط اور طاقتور تھے اور یہ بات پہلی کتاب یعنی لوح محفوظ میں ہے۔ پھر ان کی زبان سے یہ الفاظ تین مرتبہ ادا ہوئے سچ کہا، سچ کہا۔ اور درمیانے جو کہ ",""],["ٱللَّٰه","a"],[" کے بندے امیر المومنین حضرت عمرؓ ہیں جو ",""],["ٱللَّٰه","a"],[" کے بارے میں کسی کی ملامت سے نہیں ڈرتے تھے اور طاقتور کو کمزور کے کھا جانے سے روکتے تھے، یہ بات بھی پہلی کتاب یعنی لوح محفوظ میں ہے۔ پھر ان کی زبان سے یہ الفاظ ادا ہوئے سچ کہا، سچ کہا۔ پھر انہوں نے کہا حضرت عثمانؓ امیر المومنین جو کہ مسلمانوں پر بہت مہربان ہیں۔ دو گزر گئے، چار رہ گئے، پھر لوگوں میں اختلاف ہو جائے گا اور جوڑ باقی نہ رہ سکے گا اور درخت بھی روئیں گے یعنی کسی کا احترام و اکرام باقی نہ رہے گا اور قیامت قریب آ جائے گی اور لوگ ایک دوسرے کو کھانے لگیں گے۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani."]]},{"b":[["n",[["دوسری روایت میں ہے کہ ",""],["حضرت نعمان بن بشیرؓ","b"],[" فرماتے ہیں جب حضرت زید بن خارجہؓ کا انتقال ہوا تو میں حضرت عثمانؓ کا انتظار کر رہا تھا، میں نے سوچا کہ دو رکعت نماز ہی پڑھ لوں (اور نماز شروع کر دی)۔ اتنے میں حضرت زیدؓ نے اپنے چہرے سے کپڑا ہٹا کر کہا السلام علیکم! السلام علیکم! گھر والے باتیں کر رہے تھے، میں نے نماز میں ہی کہا سبحان ",""],["ٱللَّٰه","a"],["! سبحان ",""],["ٱللَّٰه","a"],["! پھر حضرت زیدؓ نے کہا سب خاموش ہو جائیں، سب خاموش ہو جائیں۔ باقی حدیث پچھلی حدیث جیسی ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani in his Kabeer and Awsat, reporting from reliable sources as confirmed by Haythami (Vol.5 Pg.180)."]]},{"b":[["n",[["طبرانی نے اوسط میں یہ روایت ذکر کی ہے کہ تین خلفاء میں سب سے زیادہ مضبوط جو ",""],["ٱللَّٰه","a"],[" کے بارے میں کسی کی ملامت کی پرواہ نہیں کرتے تھے اور کسی طاقتور کو کسی کمزور کو کھانے نہیں دیتے تھے وہ ",""],["ٱللَّٰه","a"],[" کے بندے اور امیر المومنین تھے، انہوں نے سچ کہا، سچ کہا، یہ لوح محفوظ میں ہے۔ پھر حضرت زیدؓ نے کہا حضرت عثمانؓ امیر المومنین ہیں اور وہ لوگوں کے بہت زیادہ قصور معاف کر دیتے ہیں۔ دو گزر گئے ہیں، چار باقی ہیں۔ پھر لوگوں میں اختلاف ہو جائے گا اور ایک دوسرے کو کھانے لگ جائیں گے اور کوئی نظم برقرار نہ رہ سکے گا اور بڑے بڑے بہادر روئیں گے، پھر مسلمانوں کی ترقی رک جائے گی۔ اور یہ بھی کہا کہ یہ بات ",""],["ٱللَّٰه","a"],[" نے لکھی ہوئی ہے اور اسے مقدر فرما رکھا ہے۔ اے لوگو! اپنے امیر کی طرف متوجہ ہو جاؤ، اس کی بات سنو اور مانو، پھر جسے والی بنایا جائے گا اس کا خون محفوظ رہے گا اور ",""],["ٱللَّٰه","a"],[" کا فیصلہ مقدر ہو چکا ہے۔ ",""],["ٱللَّٰه","a"],[" اکبر! یہ جنت ہے اور یہ جہنم ہے اور سارے نبی اور صدیق سلام علیکم کہہ رہے ہیں۔ اے عبد",""],["ٱللَّٰه","a"],[" بن رواحہ! کیا آپ کو میرے والد خارجہؓ اور حضرت سعدؓ کا کچھ پتہ چلا؟ یہ دونوں حضرات جنگ احد میں شہید ہوئے تھے۔ پھر آواز بند ہونے سے پہلے انہوں نے یہ آیات پڑھیں",""]]],["q",[["كَلَّآ ۖ إِنَّهَا لَظَىٰ ۝ نَزَّاعَةً لِّلشَّوَىٰ ۝ تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ ۝ وَجَمَعَ فَأَوْعَىٰ","a"]]],["p",[["ترجمہ: \"یہ ہرگز نہ ہوگا (بلکہ) وہ آگ ایسی شعلہ زن ہے جو کھال (تک) اتار دے گی (اور) اس شخص کو (خود) بلاوے گی جس نے (دنیا میں حق سے) پیٹھ پھیری ہوگی اور (اطاعت سے) بے رخی کی ہوگی اور جمع کیا ہوگا پھر اس کو اٹھا کر رکھا ہوگا۔\" (سورۂ معارج، آیات 15 تا 18)۔ حضرت زیدؓ کی آواز بند ہو گئی۔ اس حدیث میں یہ بھی ہے کہ حضرت زیدؓ نے یہ بھی کہا یہ حضرت احمدؐ ",""],["ٱللَّٰه","a"],[" کے رسول ہیں۔ سلام علیک یا رسول ",""],["ٱللَّٰه","a"],["! و رحمۃ ",""],["ٱللَّٰه","a"],[" و برکاتہ۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani, who has reported all of it in his Kabeer and Awsat in abridged form, with reliable narrators, as confirmed by Haythami (Vol.5 Pg.180). Bayhaqi has also reported it from Ibn Abi Dunya from Nu'maan bin Basheer."]]},{"b":[["n",[["حضرت نعمان بن بشیرؓ","b"],[" فرماتے ہیں ہم میں سے ایک آدمی کا انتقال ہوا جنہیں حضرت زید بن خارجہؓ کہا جاتا تھا، ہم نے ایک کپڑے سے انہیں ڈھانک دیا اور میں کھڑے ہو کر نماز پڑھنے لگا۔ اتنے میں کچھ شور سنائی دیا تو میں ان کی طرف متوجہ ہوا، میں نے دیکھا کہ ان کا جسم حرکت کر رہا ہے، پھر وہ لوگوں سے کہنے لگے (تین خلفاء میں) سب سے زیادہ طاقتور درمیان والے ",""],["ٱللَّٰه","a"],[" کے بندے امیر المومنین حضرت عمرؓ ہیں جو اپنے کام میں بھی خوب طاقتور تھے اور ",""],["ٱللَّٰه","a"],[" کے کام میں بھی خوب طاقتور تھے اور امیر المومنین حضرت عثمان بن عفانؓ پاکدامن اور انتہائی باکیاز ہیں جو بہت سے قصور معاف کر دیتے ہیں، دو سال گزر گئے ہیں اور چار باقی ہیں، پھر لوگوں میں اختلاف ہو جائے گا اور ان میں کوئی نظم برقرار نہیں رہ سکے گا۔ اے لوگو! اپنے امام کی طرف متوجہ ہو جاؤ اور سنو اور مانو۔ یہ حضورؐ اور عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ ہیں۔ پھر (حضرت ابن رواحہؓ سے) کہا میرے والد حضرت خارجہ بن زیدؓ کا کیا بنا؟ پھر کہا اریس کنواں ظلماً لے لیا گیا۔ اس کے بعد ان کی آواز بند ہو گئی۔",""],[" (5)","s"]]]],"f":[["(5)","Bayhaqi, reporting from Ibn Abi Dunya. Bayhaqi has also reported the narration from others apart from Ibn Abi Dunya, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.157). Ibn Mandah and Abu Nu'aym have reported a similar narration, as quoted in Isaabah (Vol.2 Pg.24)."]]}]},"247":{"lead":[],"stories":[{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں ہم ایک انصاری جوان کی عیادت کے لیے گئے، جلد ہی اس کا انتقال ہو گیا۔ ہم نے اس کی آنکھیں بند کر کے اس پر کپڑا ڈال دیا۔ ہم میں سے ایک آدمی نے اس کی والدہ سے کہا اپنے بیٹے کے صدمہ پر صبر کرو اور اس پر ثواب کی امید رکھو۔ اس کی والدہ نے کہا کیا اس کا انتقال ہو گیا ہے؟ ہم نے کہا جی ہاں۔ اس پر اس کی والدہ نے اپنے دونوں ہاتھ آسمان کی طرف اٹھائے اور یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! میں تجھ پر ایمان لائی اور میں ہجرت کر کے تیرے پاس آئی اور جب بھی مجھ پر کوئی مصیبت آئی تو میں نے تجھ سے دعا کی، تو نے وہ مصیبت اور سختی ضرور ہٹائی۔ میں تجھ سے سوال کرتی ہوں کہ تو مجھ پر یہ مصیبت مت ڈال۔ اس کے یہ دعا مانگتے ہی (اس کا بیٹا زندہ ہو گیا اور) چہرے سے کپڑا ہٹا کر بیٹھ گیا اور تھوڑی دیر بعد جب ہم نے کھانا کھایا تو اس نے بھی ہمارے ساتھ کھایا۔ بیہقی کی روایت میں یہ ہے کہ یہ حضرت ام السائبؓ تھیں جو بوڑھی اور نابینا تھیں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Dunya. Bayhaqi has also reported it."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عونؒ","b"],[" کہتے ہیں حضرت انسؓ نے فرمایا میں نے اس امت میں ایسی تین باتیں پائی ہیں کہ وہ اگر بنی اسرائیل میں ہوتیں تو کوئی امت ان کا مقابلہ اور ان کی برابری نہ کر سکتی۔ ہم نے کہا اے ابو حمزہ! وہ تین باتیں کیا ہیں؟ انہوں نے فرمایا ایک مرتبہ ہم لوگ صفہ میں حضورؐ کے پاس بیٹھے ہوئے تھے کہ اتنے میں ایک مہاجر عورت حضورؐ کی خدمت میں آئی اور اس کے ساتھ اس کا ایک بیٹا بھی تھا جو کہ بالغ تھا۔ حضورؐ نے اس عورت کو (مدینہ کی) عورتوں کے سپرد کر دیا اور اس کے بیٹے کو ہمارے ساتھ شامل کر دیا۔ کچھ ہی عرصے کے بعد وہ مدینہ کی وبا میں مبتلا ہو گیا اور چند دن بیمار رہ کر فوت ہو گیا۔ حضورؐ نے اس کی آنکھیں بند کیں اور ہمیں اس کا جنازہ تیار کرنے کا حکم دیا۔ جب ہم نے اسے غسل دینا چاہا تو حضورؐ نے فرمایا جا کر اس کی والدہ کو بتا دو۔ چنانچہ میں نے اسے بتا دیا، وہ آئی اور بیٹے کے پیروں کے پاس بیٹھ گئی اور اس کے دونوں پاؤں پکڑ کر اس نے یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! میں اپنی خوشی سے مسلمان ہوئی اور میرے دل کا میلان بتوں سے بالکل ہٹ گیا، اس لیے میں نے انہیں چھوڑا ہے اور تیری وجہ سے بڑے شوق سے میں نے ہجرت کی ہے اور مجھ پر یہ مصیبت بھیج کر بتوں کے پوجنے والوں کو خوش نہ کرنا اور جو مصیبت میں اٹھا نہیں سکتی وہ مجھ پر نہ ڈال۔ حضرت انسؓ فرماتے ہیں ابھی اس کی والدہ کی دعا ختم نہیں ہوئی تھی کہ اس کے بیٹے نے اپنے قدموں کو ہلایا اور اپنے چہرے سے کپڑا ہٹایا (اور زندہ ہو کر بیٹھ گیا) اور بہت عرصہ تک زندہ رہا یہاں تک کہ حضورؐ کا انتقال ہو گیا اور اس کے سامنے اس کی ماں کا بھی انتقال ہوا۔ پھر آگے اور حدیث ذکر کی جیسے کہ ہم عنقریب ذکر کریں گے۔",""],[" (2)","s"]]]],"f":[["(2)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.154 and 259). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.224)."]]}]},"248":{"lead":[],"stories":[{"b":[["n",[["حضرت ابونضرہؒ","b"],[" کہتے ہیں حضرت جابر بن عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا جب جنگ احد کا وقت ہوا تو رات کو میرے والد نے بلا کر کہا میرا خیال یہی ہے کہ میں کل حضورؐ کے صحابہؓ میں سب سے پہلے شہید ہو جاؤں گا اور ",""],["ٱللَّٰه","a"],[" کی قسم! میں کسی کو ایسا نہیں چھوڑ کر جا رہا ہوں جو حضورؐ کی ذات کے بعد مجھے تم سے زیادہ پیارا ہو اور مجھ پر قرضہ بھی ہے، وہ میری طرف سے ادا کر دینا اور اپنی بہنوں کے بارے میں حسن سلوک کی وصیت قبول کرو۔ چنانچہ صبح کو سب سے پہلے وہی شہید ہوئے اور میں نے انہیں ایک اور صحابیؓ کے ساتھ ایک قبر میں دفن کر دیا۔ پھر میرا جی نہ مانا کہ میں انہیں ایک قبر میں کسی دوسرے کے ساتھ رہنے دوں تو میں نے انہیں چھ مہینے کے بعد قبر سے نکالا تو وہ بالکل ایسے تھے جیسے کہ اس دن جس دن میں نے انہیں قبر میں رکھا تھا، صرف ان کے کان میں کچھ فرق آیا ہوا تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim (Vol.3 Pg.203), who said that the chain is authentic on the conditions of Muslim."]]},{"b":[["n",[["ابن سعد کی روایت اس طرح سے ہے کہ چھ مہینے گزرنے کے بعد میری طبیعت میں شدید تقاضا ہوا کہ میں انہیں الگ دفن کروں، چنانچہ میں نے انہیں قبر سے نکالا تو میں دیکھ کر حیران رہ گیا کہ زمین نے ان کے جسم کو بالکل نہیں کھایا تھا، صرف کان کی لو پر کچھ اثر تھا۔ اور ابن سعد کی دوسری روایت میں یہ ہے کہ مجھے ان کے جسم میں کوئی فرق نظر نہ آیا البتہ ان کی داڑھی کے چند بالوں میں کچھ فرق تھا جو زمین سے لگے ہوئے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.563); and Ibn Sa'd, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.43)."]]},{"b":[["n",[["حضرت ابوزبیرؒ","b"],[" کہتے ہیں حضرت جابرؓ نے فرمایا جب حضرت معاویہؓ نے پانی کا چشمہ جاری کیا تو اعلان کیا گیا کہ ہم اپنے جنگ احد کے شہیدوں کو منتقل کر لیں، چنانچہ ہم نے انہیں چالیس سال کے بعد نکالا تو ان کے جسم بالکل نرم تھے اور ان کے ہاتھ پاؤں مڑ جاتے تھے۔ ابونعیم کی ایک روایت میں یہ ہے کہ حضرت ابوزبیرؒ کہتے ہیں کہ حضرت جابرؓ نے فرمایا لوگوں نے اپنے شہیدوں کو چالیس سال کے بعد قبروں سے نکالا تو وہ بالکل تر و تازہ تھے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Sa'd (Vol.3 Pg.563). Abu Nu'aym has reported it in his Dalaa'il (Pg.207), as quoted in Kanzul Ummaal (Vol.5 Pg.274)."]]},{"b":[["n",[["ابن اسحاقؒ نے مغازی میں اس قصہ کو ذکر کیا ہے، وہ کہتے ہیں میرے والد نے انصار کے چند مشائخ سے نقل کیا ہے کہ جب حضرت معاویہؓ نے پانی کا وہ چشمہ چلایا جو شہداء کی قبروں کے پاس سے گزرتا تھا تو اس کا پانی ان قبروں میں جانے لگا۔ ہم نے جا کر حضرت عمروؓ اور حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کو نکالا تو ان پر دو چادریں تھیں جن سے ان کے چہروں کو ڈھانکا ہوا تھا اور دونوں کے پیروں پر کچھ گھاس پڑی ہوئی تھی اور ان کے جسم ادھر ادھر مڑ جاتے تھے اور ایسے معلوم ہوتا تھا جیسے کل ہی یہ دونوں دفن کیے گئے ہوں۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Is'haaq in his Maghaazi, as quoted in Fat'hul Baari (Vol.3 Pg.142)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضرت معاویہ بن ابی سفیانؓ کے زمانہ خلافت میں ایک آدمی میرے پاس آیا اور اس نے کہا حضرت معاویہؓ کے کارندوں نے آپ کے والد کی قبر کو اکھاڑ پھینکا اور ان کے جسم کا کچھ حصہ ظاہر ہو گیا ہے۔ میں نے جا کر دیکھا تو وہ بالکل ویسے ہی تھے جیسے کہ میں نے ان کو دفن کیا تھا۔ ان کے جسم میں کوئی تبدیلی نہیں آئی تھی۔ میدان جنگ میں جو زخم ان کو آئے تھے بس وہی تھے، اس کے بعد میں نے ان کو پھر دفن کر دیا۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad, in a lengthy narration; Haythami has said that its narrators are reliable, as quoted in Wafaa'ul Wafaa (Vol.3 Pg.116). Daarimi has also reported it."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن عبد","b"],["ٱللَّٰه","a"],[" بن عبدالرحمٰن بن ابی صعصعہؒ","b"],[" کہتے ہیں مجھے یہ بات پہنچی ہے کہ حضرت عمرو بن جموح انصاری سلمیؓ اور حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرو انصاری سلمیؓ دونوں جنگ احد میں شہید ہوئے اور دونوں کو ایک قبر میں دفن کیا گیا تھا۔ دونوں کی قبروں کے پاس سے ایک برساتی نالہ گزرتا تھا، ایک مرتبہ برساتی نالے کے پانی سے ان حضرات کی قبر کھل گئی۔ اس پر جگہ بدلنے کے لیے ان کی قبر کو کھودا گیا تو ان حضرات کے جسموں میں کوئی تبدیلی نہیں آئی تھی اور ایسے معلوم ہوتا تھا کہ جیسے کل ہی دفن کیے گئے ہوں۔ دونوں میں سے ایک صاحب زخمی ہوئے تھے اور ان کا ہاتھ زخم پر رکھ کر انہیں دفن کر دیا گیا تھا، اب ان کا ہاتھ زخم سے ہٹا کر چھوڑا گیا تو وہ اپنی جگہ زخم پر واپس آ گیا جیسے کہ پہلے تھا۔ قبر کھودنے کا یہ واقعہ جنگ احد کے چھیالیس سال بعد پیش آیا تھا۔",""],[" (6)","s"]]]],"f":[["(6)","Maalik in his Muwatta, as quoted in Awjazul Masaalik (Vol.3 Pg.107)."]]},{"b":[["n",[["حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمروؓ سرخ رنگ کے تھے اور ان کے سر پر بال نہیں تھے اور ان کا قد لمبا نہیں تھا اور حضرت عمرو بن جموحؓ لمبے قد والے تھے، اس لیے جنگ احد کے دن صحابہؓ نے دونوں حضرات کو پہچان لیا تھا اور دونوں کو ایک ہی قبر میں دفن کیا گیا تھا۔ ان حضرات کی قبر ایک برساتی نالہ کے قریب تھی، ایک مرتبہ اس کا پانی ان کی قبر میں داخل ہو گیا تھا جس کی وجہ سے ان کی قبر کھودی گئی تو دونوں حضرات پر دو کالی سفید دھاریوں والی چادریں تھیں۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کے چہرے پر زخم تھا اور ان کا ہاتھ ان کے زخم پر رکھا ہوا تھا۔ جب ان کا ہاتھ زخم سے ہٹایا گیا تو خون پھر بہنے لگا اور جب زخم پر رکھا گیا تو خون رک گیا۔ حضرت جابرؓ نے فرمایا میں نے دیکھا تو ایسے لگا کہ جیسے میرے والد اپنی قبر میں سو رہے ہوں اور ان کی جسمانی حالت میں کسی قسم کی تبدیلی نہیں آئی تھی۔ حضرت جابرؓ سے پوچھا گیا کہ آپ نے ان کا کفن بھی دیکھا تھا؟ انہوں نے کہا ہاں، انہیں صرف ایک دھاری دار چادر میں کفن دیا گیا تھا جس سے ان کا چہرہ چھپ گیا تھا اور ان کے پاؤں پر حرمل پودے ڈال دیے گئے تھے، وہ چادر بھی اسی حال میں ٹھیک تھی اور ان کے پیروں پر حرمل پودے بھی اپنی اصلی حالت پر تھے، حالانکہ دفنانے کے چھیالیس سال بعد ان کی قبر کھودی گئی تھی۔",""]]]],"f":[]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں جب حضرت معاویہؓ نے جنگ احد کے چالیس سال بعد احد کے شہداء کے پاس سے نہر چلانی چاہی تو شہداء کے ورثاء میں اعلان کیا گیا کہ ہم اپنے شہداء کو سنبھال لیں۔ ہم نے وہاں جا کر انہیں نکالا، کدال حضرت حمزہؓ کے پاؤں کو لگا تو اس میں سے خون بہنے لگا۔ حضرت عمرو بن دینارؒ اور حضرت ابوزبیرؒ کہتے ہیں کہ کدال حضرت حمزہؓ کے پاؤں کو لگا تو اس میں سے خون بہنے لگا، حالانکہ ان کو دفن ہوئے چالیس سال ہو چکے تھے۔ شیخ سمہودیؒ کی تحقیق یہ ہے کہ یہ واقعہ تین مرتبہ پیش آیا: ایک مرتبہ دفن کے چھ مہینے بعد، دوسری مرتبہ چالیس سال بعد جب وہاں نہر چلائی گئی اور تیسری مرتبہ چھیالیس سال بعد جب برساتی نالہ کا پانی قبر میں داخل ہوا تھا۔ اس کی وجہ یہ ہے کہ ہر واقعہ کے بارے میں متعدد روایات منقول ہیں اور یہ صحابہؓ کی کھلی کرامت ہے اور اسی وجہ سے یہ واقعہ بار بار پیش آیا ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Sa'd (Vol.3 Pg.563) and Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.43). Shaykh Samhoodi has verified this in Wafaa'ul Wafaa (Vol.2 Pg.116-117)."]]}]},"249":{"lead":[],"stories":[{"b":[["n",[["حضرت محمد بن شرحبیلؒ","b"],[" کہتے ہیں ایک آدمی نے حضرت سعد بن معاذؓ کی قبر سے ایک مٹھی مٹی لی۔ جب اس نے مٹھی کھولی تو وہ مشک تھی، اس پر حضورؐ نے خوش ہو کر فرمایا سبحان ",""],["ٱللَّٰه","a"],["، سبحان ",""],["ٱللَّٰه","a"],["، اور خوشی کے آثار حضورؐ کے چہرے پر نظر آ رہے تھے۔ ابن سعد میں دوسری روایت میں یہ ہے کہ حضرت محمد بن شرحبیلؒ کہتے ہیں ایک آدمی نے حضرت سعد بن معاذؓ کی قبر سے مٹھی بھر مٹی لی اور مٹی لے کر چلا گیا، پھر کچھ دیر بعد اس نے مٹھی کو دیکھا تو وہ مشک تھی۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Ma'rifah, as quoted in Kanzul Ummaal (Vol.7 Pg.41). Ibn Sa'd (Vol.3 Pg.431) has reported a similar narration."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں میں بھی ان لوگوں میں تھا جنہوں نے بقیع میں حضرت سعدؓ کی قبر کھودی تھی، ہم جب بھی مٹی کھودتے تو اس میں سے ہمیں مشک کی خوشبو آتی اور یہ خوشبو کا سلسلہ یوں ہی چلتا رہا یہاں تک کہ ہم لحد تک پہنچ گئے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.431)."]]}]},"250":{"lead":[],"stories":[{"b":[["n",[["حضرت عروہؒ","b"],[" کہتے ہیں جب صحابہؓ غزوہ بئر معونہ میں شہید ہو گئے اور حضرت عمرو بن امیہ ضمریؓ قید ہو گئے تو عامر بن طفیل نے ایک شہید صحابیؓ کی طرف اشارہ کر کے پوچھا کہ یہ کون ہے؟ حضرت عمرو بن امیہؓ نے کہا یہ حضرت عامر بن فہیرہؓ ہیں۔ عامر بن طفیل کہتا ہے میں نے ان کے شہید ہونے کے بعد دیکھا کہ ان کو آسمان کی طرف اٹھایا جا رہا ہے، پھر میں نے آسمان کی طرف دیکھا تو آسمان ان کے اور زمین کے درمیان تھا، پھر ان کی لاش کو واپس زمین پر رکھ دیا گیا۔ پھر حضورؐ کے پاس ان شہید صحابہؓ کی خبر پہنچی تو آپؐ نے صحابہؓ کو ان کی شہادت کی خبر دی اور فرمایا تمہارے ساتھی شہید کر دیے گئے ہیں اور انہوں نے اپنے رب سے یہ سوال کیا ہے کہ اے ہمارے رب! ہمارے بھائیوں کو ہماری خبر کر دے اور یہ بھی بتا دے کہ ہم تجھ سے راضی ہیں اور تو ہم سے راضی ہے۔ اس طرح حضورؐ نے صحابہؓ کو ان شہید ہونے والوں کی خبر دی۔ ان شہید ہونے والوں میں حضرت عروہ بن اسماء بن صلتؓ اور حضرت منذر بن عمروؓ بھی تھے، تو نیک فال لینے کی نیت سے حضرت زبیر بن عوامؓ نے اپنے ایک بیٹے کا نام عروہ اور دوسرے کا نام منذر رکھا۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari. Bayhaqi has reported a similar narration, as has Abu Nu'aym in his Hilyah (Vol.1 Pg.110)."]]},{"b":[["n",[["واقدی نے ذکر کیا کہ حضرت عامر بن فہیرہؓ کے قاتل جبار بن سلمی کلابی تھے، وہ کہتے ہیں جب میں نے انہیں نیزہ مارا تو انہوں نے کہا رب کعبہ کی قسم! میں کامیاب ہو گیا۔ میں نے کہا یہ تو خود قتل ہو رہے ہیں لیکن یہ کہہ رہے ہیں میں کامیاب ہو گیا، تو اس کامیابی کا کیا مطلب؟ لوگوں نے کہا وہ کامیابی جنت کی ہے۔ میں نے کہا انہوں نے سچ کہا، پھر اسی بات پر میں مسلمان ہو گیا۔",""],[" (2)","s"]]]],"f":[["(2)","Waaqidi."]]},{"b":[["n",[["حضرت عروہؒ","b"],[" کہتے ہیں بعد میں حضرت عامر بن فہیرہؓ کا جسم وہاں کہیں نہ ملا، صحابہؓ یہی سمجھتے ہیں کہ فرشتوں نے انہیں دفن کر دیا تھا۔ واقدی میں ہے کہ حضورؐ نے فرمایا فرشتوں نے ان کے جسم کو دفن کیا اور ان کو علیین میں جگہ دی گئی۔",""],[" (3)","s"]]]],"f":[["(3)","Moosa bin Uqba in his Maghaazi, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.72). Abu Nu'aym has reported a similar narration in his Hilyah (Vol.1 Pg.110)."]]},{"b":[["n",[["حضرت عروہؒ","b"],[" کہتے ہیں عامر بن طفیل نے شہید ہونے والے صحابہؓ میں سے ایک کے بارے میں کہا تھا کہ جب وہ قتل ہو گئے تو انہیں آسمان اور زمین کے درمیان میں اٹھا لیا گیا یہاں تک کہ آسمان مجھے ان کے نیچے نظر آ رہا تھا۔ لوگوں نے بتایا کہ وہ حضرت عامر بن فہیرہؓ تھے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Dalaa'il (Pg.186). Ibn Sa'd (Vol.3 Pg.231) has reported a similar narration."]]},{"b":[["n",[["حضرت زہریؒ","b"],[" کہتے ہیں مجھے یہ بات پہنچی ہے کہ ان لوگوں نے حضرت عامر بن فہیرہؓ کے جسم کو بہت تلاش کیا لیکن انہیں کہیں نہ ملا، اس لیے لوگوں کو یقین ہے کہ فرشتوں نے انہیں دفن کر دیا ہے۔",""]]]],"f":[]}]},"251":{"lead":[],"stories":[{"b":[["n",[["حضرت عمرو بن امیہؓ","b"],[" فرماتے ہیں نبی کریمؐ نے مجھے اکیلے کو جاسوس بنا کر قریش کی طرف بھیجا۔ میں حضرت خبیبؓ کی (اس) لکڑی کے پاس گیا (جس پر حضرت خبیبؓ کو سولی پر چڑھایا گیا تھا اور ان کا جسم ابھی تک اس پر لٹک رہا تھا) اور مجھے جاسوسوں کا بھی ڈر تھا کہ کہیں ان کو پتہ نہ لگ جائے، چنانچہ لکڑی پر چڑھ کر میں نے حضرت خبیبؓ کو کھولا جس سے وہ زمین پر گر گئے، پھر میں (چھپنے کے لیے) تھوڑی دور ایک طرف کو چلا گیا۔ پھر میں نے آ کر دیکھا تو حضرت خبیبؓ مجھے کہیں نظر نہ آئے اور ایسے لگا کہ جیسے زمین انہیں نگل گئی ہو اور اس وقت تک ان کا کوئی نشان نہیں آیا۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Tabraani; Haythami (Vol.5 Pg.321) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عمرو بن امیہؓ","b"],[" فرماتے ہیں مجھے حضورؐ نے اکیلے کو جاسوس بنا کر بھیجا تھا۔ میں حضرت خبیبؓ کی لکڑی کے پاس گیا۔ پھر آگے پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (2)","s"]]]],"f":[["(2)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.67). Abu Nu'aym has reported it in his Dalaa'il (Pg.227)."]]},{"b":[["n",[["حضرت ضحاکؒ","b"],[" فرماتے ہیں نبی کریمؐ نے حضرت مقدادؓ اور حضرت زبیرؓ کو حضرت خبیبؓ کو سولی کی لکڑی سے نیچے اتارنے کے لیے بھیجا۔ وہ دونوں تنعیم پہنچے۔ وہ دونوں (جہاں مکہ سے باہر حضرت خبیبؓ کو سولی دی گئی تھی) تو انہیں وہاں حضرت خبیبؓ کے اردگرد چالیس آدمی نشہ میں بدمست ملے۔ ان دونوں نے حضرت خبیبؓ کو لکڑی سے اتارا، پھر حضرت زبیرؓ نے ان کی نعش کو اپنے گھوڑے پر رکھ لیا۔ ان کا جسم بالکل تر و تازہ تھا، اس میں کوئی تبدیلی نہیں آئی تھی۔ پھر مشرکوں کو ان حضرات کا پتہ چل گیا، انہوں نے ان حضرات کا پیچھا کیا۔ جب مشرک ان کے پاس پہنچ گئے تو حضرت زبیرؓ نے (مجبور ہو کر) حضرت خبیبؓ کی نعش کو نیچے پھینک دیا جسے فوراً زمین نے نگل لیا۔ اسی وجہ سے حضرت خبیبؓ کا نام بلیع الارض رکھا گیا (اس کا ترجمہ ہے وہ آدمی جسے زمین نے نگل لیا تھا)۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Yusuf in his Kitaabul Lataa'if, as quoted in Isaabah (Vol.1 Pg.419)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں میں نے اس امت میں ایسی تین باتیں پائی ہیں کہ وہ اگر بنی اسرائیل میں ہوتیں تو کوئی امت ان کا مقابلہ اور ان کی برابری نہ کر سکتی۔ اس کے بعد حدیث کا کچھ حصہ ابھی گزرا ہے، اس کے بعد یہ مضمون ہے کہ کچھ عرصہ ہی گزرا تھا کہ حضرت ابن حضرمیؓ کا انتقال ہو گیا اور ہم نے غسل دے کر ان کا جنازہ تیار کیا، پھر قبر کھود کر انہیں دفن کر دیا۔ دفن کے بعد ایک آدمی آیا اور اس نے پوچھا یہ کون ہیں؟ ہم نے کہا یہ اس زمانہ کے انسانوں میں سب سے بہترین ہیں، یہ حضرت ابن حضرمیؓ ہیں۔ اس نے کہا یہ زمین مردوں کو باہر پھینک دیتی ہے۔ اگر آپ لوگ ان کو ایک دو میل دور لے جا کر دفن کر دو تو اچھا ہے کیونکہ وہاں کی زمین مردوں کو قبول کر لیتی ہے۔ ہم نے کہا ہمارے اس ساتھی کے احسانات اور نیکی کا یہ بدلہ تو مناسب نہیں ہے کہ ہم انہیں یہاں دفن رہنے دیں، اس طرح تو ان کی نعش باہر آ جائے گی اور انہیں درندے کھا جائیں گے۔ چنانچہ ہم سب نے اس پر اتفاق کیا کہ قبر کھود کر انہیں نکالا جائے اور دوسری جگہ دفن کیا جائے۔ ہم نے قبر کھودنی شروع کر دی۔ جب ہم لحد پر پہنچے تو ہم دیکھ کر حیران رہ گئے کیونکہ لحد میں ان کی نعش موجود نہیں تھی اور اس میں تا حد نگاہ نور چمک رہا تھا۔ ہم نے لحد پر دوبارہ مٹی ڈال دی اور وہاں سے چل دیے۔",""],[" (4)","s"]]]],"f":[["(4)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.155 and 292)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" نے بھی اس واقعہ کو بیان کیا ہے، اس میں یہ مضمون ہے کہ حضرت ابن حضرمیؓ کو ہم لوگوں نے ریت میں دفن کر دیا۔ وہاں سے کچھ دور ہی ہم گئے تھے تو ہم نے کہا کہیں کوئی درندہ آ کر انہیں کھا نہ جائے۔ ہم نے واپس آ کر انہیں قبر میں دیکھا تو وہ ہمیں وہاں نظر نہ آئے۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani in all three works. Haythami (Vol.9 Pg.376) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.208)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں ہم نے ان کے لیے تلواروں سے قبر کھودی لیکن لحد نہ بنائی اور انہیں دفن کر کے آگے چل دیے۔ حضورؐ کے ایک صحابیؓ نے کہا ہم نے ان کو دفن تو کر دیا ہے لیکن قبر میں ان کے لیے لحد نہیں بنائی، یہ ہم نے اچھا نہیں کیا۔ اس پر ہم لحد بنانے کے لیے واپس آئے تو ہمیں ان کی قبر کی جگہ ہی نہ ملی۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Sa'd (Vol.4 Pg.363)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے ایک لشکر بھیجا اور ان پر حضرت عاصم بن ثابت بن ابی الافلحؓ کو امیر بنایا۔ پھر آگے حضرت خبیب بن عدیؓ کا لمبا قصہ ذکر کیا ہے اور اس کے بعد یہ ہے کہ حضرت عاصمؓ نے کہا میں کسی مشرک کے عہد میں آنا نہیں چاہتا (آخر شہید ہو گئے)۔ انہوں نے ",""],["ٱللَّٰه","a"],[" سے یہ عہد کیا تھا کہ یہ کسی مشرک کو ہاتھ نہیں لگائیں گے اور نہ کوئی مشرک انہیں ہاتھ لگا سکے۔ حضرت عاصمؓ نے جنگ بدر کے دن قریش کے ایک بڑے سردار کو قتل کیا تھا، اس لیے قریش نے ایک جماعت بھیجی جو ان کے جسم کا کچھ حصہ کاٹ کر لائے۔ تو ",""],["ٱللَّٰه","a"],[" تعالیٰ نے شہد کی مکھیوں یا بھڑوں کا ایک غول بھیج دیا جس نے ان کے بدن کو چاروں طرف سے گھیر کر انہیں کافروں سے بچا لیا۔ اسی وجہ سے انہیں حمی الدبر کہا جاتا تھا (اس کا ترجمہ ہے وہ آدمی جسے شہد کی مکھیوں یا بھڑوں نے دشمن سے بچایا)۔",""],[" (7)","s"]]]],"f":[["(7)","Bukhaari and Muslim, as quoted in Isaabah (Vol.2 Pg.245)."]]},{"b":[["n",[["حضرت عروہؒ","b"],[" بھی اسی قصہ میں یہ ذکر کرتے ہیں کہ مشرکوں نے اس بات کا ارادہ کیا کہ ان کا سر کاٹ کر مشرکین مکہ کے پاس بھیج دیں لیکن ",""],["ٱللَّٰه","a"],[" تعالیٰ نے شہد کی مکھیاں یا بھڑیں بھیج دیں جنہوں نے انہیں ہر طرف سے گھیر لیا، وہ مشرکوں کے چہروں پر اڑتی تھیں اور انہیں کاٹتی تھیں، اس طرح انہوں نے مشرکوں کو حضرت عاصمؓ کا سر کاٹنے نہ دیا۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Dalaa'il (Pg.183)."]]}]},"252":{"lead":[],"stories":[{"b":[["n",[["حضرت حمزہ بن ابی اسیدؓ","b"],[" فرماتے ہیں حضورؐ ایک انصاری کے جنازے کے لیے بقیع تشریف لے گئے، راستہ میں ایک بھیڑیا اپنے بازو پھیلائے ہوئے بیٹھا تھا۔ حضورؐ نے فرمایا یہ تمہاری بکریوں میں سے اپنا حصہ مقرر کروانے آیا ہے، لہٰذا اس کا حصہ مقرر کر دو۔ صحابہؓ نے عرض کیا جو آپ کی رائے ہو یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نے فرمایا ہر چرنے والے ریوڑ میں سے ہر سال ایک بکری (اسے دے دیا کرو)۔ صحابہؓ نے عرض کیا یہ تو زیادہ ہے۔ حضورؐ نے اشارہ کر کے بھیڑیے سے کہا تم چھینا جھپٹی کر کے لے جایا کرو۔ پھر وہ بھیڑیا چلا گیا۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi."]]},{"b":[["n",[["حضرت مطلب بن عبد","b"],["ٱللَّٰه","a"],[" بن حنطبؒ","b"],[" کہتے ہیں حضورؐ مدینہ میں تھے کہ ایک بھیڑیا آ کر آپ کے سامنے کھڑا ہو گیا۔ حضورؐ نے فرمایا یہ درندوں کی طرف سے نمائندہ بن کر آیا ہے، اگر تم چاہو تو اس کے لیے کچھ حصہ مقرر کر دو، یہ اس سے لے گا اور اس سے زیادہ لینے کی کوشش نہیں کرے گا اور اگر چاہو تو اسے اس کے حال پر چھوڑ دو اور اپنے جانوروں کو اس سے بچانے کی کوشش کرو اور یہ داؤ لگا کر تمہارے جانور جتنے لے گیا وہ اس کا حصہ۔ صحابہؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ہمارا دل تو نہیں چاہتا کہ ہم اس کے لیے کچھ حصہ مقرر کریں، ہم اسے کچھ اپنے ہاتھ سے خود دیں۔ حضورؐ نے تین انگلیوں سے اشارہ کر کے بھیڑیے سے کہا تم چھینا جھپٹی کر کے لے جایا کرو۔ چنانچہ وہ بھیڑیا آواز نکالتا ہوا واپس چلا گیا۔",""],[" (2)","s"]]]],"f":[["(2)","Waaqidi, from a man whom he named."]]},{"b":[["n",[["قبیلہ جہینہ کے ایک صاحب کہتے ہیں جب حضورؐ نماز پڑھ چکے تو سو کے قریب بھیڑیے بھیڑیوں کے نمائندے بن کر آئے اور آ کر بیٹھ گئے۔ حضورؐ نے فرمایا یہ بھیڑیوں کا وفد آپ لوگوں کے پاس آیا ہے، یہ چاہتے ہیں کہ آپ لوگ اپنے جانوروں میں سے ان کا حصہ مقرر کر کے انہیں دے دیا کریں اور باقی جانوروں کے بارے میں آپ لوگ بالکل بے فکر اور بے خوف ہو کر رہا کریں۔ صحابہؓ نے حضورؐ سے فقر و فاقہ اور تنگی کی شکایت کی۔ حضورؐ نے فرمایا انہیں واپس بھیج دو (اور بتا دو کہ آپ لوگ ان کی تجویز پر عمل نہیں کر سکتے)۔ چنانچہ وہ بھیڑیے آوازیں نکالتے ہوئے مدینہ سے چلے گئے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Dalaa'il. Bayhaqi and Bazzaar have reported it briefly from Abu Hurayrah, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.131)."]]},{"b":[["n",[["حضورؐ کے آزاد کردہ غلام ",""],["حضرت سفینہؓ","b"],[" فرماتے ہیں میں سمندر میں سفر کر رہا تھا، جس کشتی میں میں تھا وہ ٹوٹ گئی۔ میں اس کے ایک تختہ پر بیٹھ گیا۔ اس تختہ نے مجھے ایسے گھنے جنگل میں لا پھینکا جس میں شیر تھے، ایک شیر مجھے کھانے کے لیے آیا۔ میں نے کہا اے ابوالحارث! (یہ شیر کی کنیت ہے) میں حضورؐ کا غلام ہوں۔ اس پر اس نے اپنا سر جھکا دیا اور آگے بڑھ کر مجھے کندھا مارا (اور میرے آگے آگے چل پڑا) یہاں تک کہ مجھے جنگل سے باہر لا کر راستہ پر ڈال دیا، پھر آہستہ سے آواز نکالی جس سے میں سمجھا کہ یہ مجھے رخصت کر رہا ہے۔ یہ میری اس شیر سے آخری ملاقات تھی۔",""],[" (4)","s"]]]],"f":[["(4)","Haakim (Vol.3 Pg.606), who said that the chain is authentic on the conditions of Muslim although they did not report it, and Dhahabi agreed. Bukhaari has also reported it in his Taareekh."]]},{"b":[["n",[["حضرت سفینہؓ","b"],[" فرماتے ہیں سمندر میں سفر کر رہا تھا، ہماری کشتی ٹوٹ گئی (ہم ایک جنگل میں پہنچ گئے)، ہمیں آگے راستہ نہیں مل رہا تھا، وہاں ایک شیر ایک دم ہمارے سامنے آیا، تب دیکھ کر میرے ساتھی پیچھے ہٹ گئے، میں نے شیر کے قریب جا کر کہا میں حضورؐ کا صحابی سفینہ ہوں، ہم راستے سے بھٹک گئے ہیں (ہمیں راستہ بتاؤ)۔ وہ میرے آگے چل پڑا اور چلتے چلتے ہمیں راستے پر لا کھڑا کیا، پھر اس نے مجھے ذرا دھکا دیا گویا کہ وہ مجھے راستہ دکھا رہا تھا، پھر ایک طرف کو بیٹھ گیا۔ میں سمجھ گیا کہ یہ اب ہمیں رخصت کر رہا ہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابن منکدرؒ","b"],[" کہتے ہیں حضورؐ کے آزاد کردہ غلام حضرت سفینہؓ ملک روم میں اپنے لشکر سے بچھڑ گئے یا ان کو وہاں رومیوں نے قید کر لیا تھا، کسی طرح قید سے بھاگ نکلے اور اپنا لشکر تلاش کر رہے تھے تو وہ اچانک ایک شیر کے پاس پہنچے۔ انہوں نے کہا اے ابوالحارث! میں حضورؐ کا غلام ہوں اور میرے ساتھ ایسے اور ایسے ہوا (انہوں نے لشکر سے بچھڑنے اور قید سے بھاگنے کا سارا واقعہ تفصیل سے اسے سنایا)۔ وہ شیر دم ہلاتا ہوا آگے آ کر ان کے پاس کھڑا ہو گیا (اور اس طرح سے اپنے تعلق اور فرمانبرداری کا اظہار کیا، پھر آگے آگے چل پڑا) اور راستہ میں جب کسی جانور کی آواز کسی طرف سے سنتا تو دوڑ کر اس کی طرف جاتا اور اسے بھگا دیتا، پھر ان کے پاس ان کے پہلو میں آ جاتا۔ سارے راستے میں وہ ایسے ہی کرتا رہا یہاں تک کہ اس نے انہیں ان کے لشکر تک پہنچا دیا اور پھر واپس چلا گیا۔",""],[" (5)","s"]]]],"f":[["(5)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.147)."]]},{"b":[["n",[["حضرت وہب بن ابان قریشیؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت ابن عمرؓ ایک سفر میں گئے۔ وہ چلے جا رہے تھے کہ راستہ میں انہیں ایک جگہ کچھ لوگ کھڑے ہوئے ملے، انہوں نے پوچھا کیا بات ہے؟ یہ لوگ کیوں کھڑے ہیں؟ لوگوں نے بتایا آگے راستہ پر ایک شیر ہے جس سے یہ خوفزدہ ہیں۔ حضرت ابن عمرؓ اپنی سواری سے نیچے اترے اور چل کر اس شیر کے پاس گئے اور اس کے کان کو پکڑ کر اس کی گردن پر تھپڑ مار کر اسے راستہ سے ہٹا دیا۔ پھر (واپس آتے ہوئے) آپ نے فرمایا حضورؐ نے تمہیں غلط بات نہیں فرمائی، میں نے حضورؐ کو فرماتے ہوئے سنا ابن آدم جس چیز سے ڈرتا ہے وہی چیز اس پر مسلط ہوتی ہے، اگر ابن آدم ",""],["ٱللَّٰه","a"],[" کے سوا کسی اور چیز سے نہ ڈرے تو ",""],["ٱللَّٰه","a"],[" کے علاوہ اس پر اور کوئی چیز مسلط نہ ہو اور ابن آدم اسی چیز کے حوالے کر دیا جاتا ہے جس سے اسے نفع یا نقصان ملنے کا یقین ہوتا ہے۔ اگر ابن آدم ",""],["ٱللَّٰه","a"],[" کے علاوہ کسی اور چیز سے نفع یا نقصان کا یقین نہ رکھے تو ",""],["ٱللَّٰه","a"],[" اسے کسی اور چیز کے بالکل حوالہ نہ کرے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Asaakir, from Naafi', as quoted in Kanzul Ummaal (Vol.7 Pg.59)."]]},{"b":[["n",[["حضرت عوف بن مالکؓ","b"],[" فرماتے ہیں ریحا مقام کے ایک گرجا گھر میں میں دوپہر کو سو رہا تھا (اب تو یہ مسجد بن چکا ہے اور اس میں نماز پڑھی جاتی ہے)۔ جب میری آنکھ کھلی تو میں نے دیکھا کہ کمرہ میں ایک شیر ہے جو میری طرف آ رہا ہے۔ میں گھبرا کر اپنے ہتھیاروں کی طرف اٹھا، شیر نے مجھ سے کہا ٹھہر جاؤ، ایک پیغام دے کر تمہارے پاس بھیجا گیا ہے تاکہ تم اسے آگے پہنچا دو۔ میں نے کہا تمہیں کس نے بھیجا ہے؟ اس نے کہا مجھے ",""],["ٱللَّٰه","a"],[" نے آپ کے پاس اس لیے بھیجا ہے تاکہ آپ بہت سفر کرنے والے معاویہؓ کو یہ بتا دیں کہ وہ جنت والوں میں سے ہیں۔ میں نے کہا یہ معاویہ کون سے ہیں؟ اس نے کہا حضرت ابوسفیانؓ کے بیٹے (رضی ",""],["ٱللَّٰه","a"],[" عنہ)۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani. Haythami (Vol.9 Pg.357) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں ایک بھیڑیے نے ایک بکری پر حملہ کر کے اسے پکڑ لیا، بکری کا چرواہا بھیڑیے کے پیچھے بھاگا اور اس نے زور لگا کر بھیڑیے سے بکری کو چھڑا لیا تو بھیڑیا اپنی دم پر بیٹھ کر کہنے لگا کیا تم ",""],["ٱللَّٰه","a"],[" سے نہیں ڈرتے؟ جو روزی ",""],["ٱللَّٰه","a"],[" نے مجھے پہنچائی وہ تم مجھ سے چھینتے ہو۔ اس چرواہے نے کہا کیا عجیب بات ہے کہ بھیڑیا مجھ سے انسانوں کی طرح بات کر رہا ہے۔ بھیڑیے نے کہا کیا میں تمہیں اس سے زیادہ عجیب بات نہ بتاؤں؟ یثرب میں حضرت محمدؐ گزشتہ زمانے کی خبریں لوگوں کو بتا رہے ہیں۔ یہ سنتے ہی وہ چرواہا اپنی بکریاں ہانک کر مدینہ پہنچ گیا اور بکریوں کو مدینہ کے ایک کونے میں ایک جگہ اکٹھا کر کے حضورؐ کی خدمت میں حاضر ہوا اور آپؐ کو سارا قصہ سنایا۔ حضورؐ کے فرمانے پر مدینہ میں اعلان کیا گیا کہ آج سب (مسجد نبوی میں) نماز اکٹھے پڑھیں (اپنی مسجدوں میں نہ پڑھیں)۔ جب لوگ جمع ہو گئے تو آپؐ نے باہر آ کر اس چرواہے سے فرمایا انہیں وہ واقعہ سناؤ۔ اس نے تمام لوگوں کے سامنے وہ واقعہ بیان کیا۔ حضورؐ نے فرمایا اس نے سچ کہا ہے، اس ذات کی قسم جس کے قبضے میں محمدؐ کی جان ہے! اس وقت تک قیامت قائم نہ ہوگی جب تک درندے انسانوں سے باتیں نہ کرنے لگیں اور آدمی سے اس کے کوڑے کا سرا اور اس کی جوتی کا تسمہ بات نہ کرنے لگے اور اس کی ران اسے یہ نہ بتائے کہ اس کے بعد اس کے گھر والوں نے کیا کیا ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Ahmad and Tirmidhi, reporting from reliable sources as confirmed by Bayhaqi and quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.143). Ahmad, Bayhaqi, Haakim and Abu Nu'aym have also reported similar narrations, as quoted in detail in Al Bidaayah wan Nihaayah (Vol.6 Pg.144, 145)."]]},{"b":[["n",[["قاضی عیاضؒ نے ذکر کیا ہے کہ بھیڑیے سے حضرت اہبان بن اوسؓ نے بات کی تھی، اس لیے انہیں بھیڑیے سے بات کرنے والا کہہ کر پکارا جاتا تھا۔ اور ابن وہبؒ نے روایت کی ہے کہ بھیڑیے سے بات کرنے کا واقعہ حضرت ابوسفیان بن حرب اور حضرت صفوان بن امیہؓ کے ساتھ بھی پیش آیا تھا۔ انہوں نے دیکھا کہ ایک بھیڑیا ایک ہرن کو پکڑنے کی کوشش کر رہا ہے، اتنے میں ہرن حرم میں داخل ہو گیا تو بھیڑیا واپس جانے لگا۔ اس سے ان دونوں کو تعجب ہوا، اس پر اس بھیڑیے نے کہا اس سے زیادہ عجیب بات یہ ہے کہ حضرت محمد بن عبد",""],["ٱللَّٰه","a"],[" (",""],["ﷺ","a"],[") مدینہ میں تمہیں جنت کی دعوت دے رہے ہیں اور تم انہیں جہنم کی آگ کی طرف دعوت دے رہے ہو۔ (یہ دونوں حضرات اس وقت تک اسلام میں داخل نہیں ہوئے تھے، اس لیے حضرت صفوانؓ سے) حضرت ابوسفیانؓ نے کہا لات و عزیٰ کی قسم! اگر تم نے مکہ میں اس بات کا تذکرہ کر دیا تو سارے مکہ والے مکہ چھوڑ دیں گے (اور مدینہ چلے جائیں گے)۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Wahab, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.146)."]]}]},"253":{"lead":[],"stories":[{"b":[["n",[["حضرت قیس بن حجاجؒ","b"],[" اپنے استاد سے نقل کرتے ہیں کہ حضرت عمرو بن عاصؓ نے جب مصر فتح کر لیا تو عجمی مہینوں میں سے بونہ مہینے کے شروع ہونے پر مصر والے ان کے پاس آئے اور کہا امیر صاحب! ہمارے اس دریائے نیل کی ایک عادت ہے جس کے بغیر یہ چلتا نہیں۔ حضرت عمروؓ نے ان سے پوچھا وہ عادت کیا ہے؟ انہوں نے کہا جب اس مہینے کی بارہ راتیں گزر جاتی ہیں تو ہم ایسی کنواری لڑکی تلاش کرتے ہیں جو اپنے والدین کی اکلوتی لڑکی ہوتی ہے۔ اس کے والدین کو راضی کرتے ہیں اور اسے سب سے اچھے کپڑے اور زیور پہنا کر دریائے نیل میں ڈال دیتے ہیں۔ حضرت عمروؓ نے کہا یہ کام اسلام میں تو ہو نہیں سکتا کیونکہ اسلام اپنے سے پہلے کے تمام (غلط) طریقے ختم کر دیتا ہے۔ چنانچہ مصر والے بونہ، ابیب اور مسری تین مہینے ٹھہرے رہے اور آہستہ آہستہ دریائے نیل کا پانی ختم ہو گیا۔ یہ دیکھ کر مصر والوں نے مصر چھوڑ کر کہیں اور چلے جانے کا ارادہ کر لیا۔ جب حضرت عمروؓ نے یہ دیکھا تو انہوں نے اس بارے میں حضرت عمر بن خطابؓ کو خط لکھا۔ حضرت عمرؓ نے جواب میں لکھا آپ نے بالکل ٹھیک کیا، بیشک اسلام اپنے سے پہلے کے تمام غلط طریقے ختم کر دیتا ہے۔ میں آپ کو ایک پرچہ بھیج رہا ہوں، جب آپ کو میرا خط ملے تو آپ میرا وہ پرچہ دریائے نیل میں ڈال دیں۔ جب خط حضرت عمروؓ کے پاس پہنچا تو انہوں نے وہ پرچہ کھولا، اس میں لکھا ہوا تھا: \"",""],["ٱللَّٰه","a"],[" کے بندے امیر المومنین عمرؓ کی طرف سے مصر کے دریائے نیل کے نام۔ اما بعد! اگر تم اپنے پاس سے چلتے ہو تو مت چلو اور اگر تمہیں ",""],["ٱللَّٰه","a"],[" واحد قہار چلاتے ہیں تو ہم ",""],["ٱللَّٰه","a"],[" واحد قہار سے سوال کرتے ہیں کہ وہ تجھے چلا دے۔\" چنانچہ حضرت عمروؓ نے صلیب کے دن سے ایک دن پہلے یہ پرچہ دریائے نیل میں ڈالا۔ ادھر مصر والے مصر سے جانے کی تیاری کر چکے تھے کیونکہ ان کی ساری معیشت اور زراعت کا انحصار دریائے نیل کے پانی پر تھا۔ صلیب کے دن صبح لوگوں نے دیکھا کہ دریائے نیل میں سولہ ہاتھ پانی چل رہا ہے، اس طرح ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مصر والوں کی اس بری رسم کو ختم کر دیا (اس دن سے لے کر آج تک دریائے نیل مسلسل چل رہا ہے)۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abdul Hakam in Futooh Misr, and Abu Shaykh in Al Azamah, and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.3 Pg.280); also Abul Qaasim Laalka'i in Kitaabus Sunnah."]]},{"b":[["n",[["حضرت عروہ اعمیؒ","b"],[" جو قبیلہ بنو سعد کے غلام ہیں کہتے ہیں حضرت ابو ریحانہؓ ایک مرتبہ سمندر کا سفر کر رہے تھے، اپنا کچھ کپڑا سی رہے تھے کہ اچانک ان کی سوئی سمندر میں گر گئی۔ انہوں نے اسی وقت یوں دعا مانگی اے میرے رب! میں تجھے قسم دیتا ہوں کہ تو میری سوئی ضرور واپس کر دے۔ چنانچہ اسی وقت وہ سوئی (سطح سمندر پر) ظاہر ہوئی اور حضرت ابو ریحانہؓ نے وہ سوئی پکڑ لی۔",""],[" (2)","s"]]]],"f":[["(2)","Ibraaheem bin Junayd in Kitaabul Awliyaa, as quoted in Isaabah (Vol.2 Pg.157)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں جب نبی کریمؐ نے حضرت علاء بن الحضرمیؓ کو بحرین کی طرف بھیجا تو میں بھی ان کے پیچھے ہو لیا۔ میں نے ان کی تین باتیں دیکھیں، مجھے پتہ نہیں چلا کہ ان میں سے سب سے زیادہ عجیب بات کونسی ہے۔ ایک بات تو یہ ہے کہ جب ہم سمندر کے کنارے پر پہنچے تو انہوں نے کہا بسم ",""],["ٱللَّٰه","a"],[" پڑھ کر سمندر میں گھس جاؤ۔ چنانچہ ہم بسم ",""],["ٱللَّٰه","a"],[" پڑھ کر (بغیر کشتیوں کے) سمندر میں گھس گئے اور ہم نے (اپنے جانوروں پر سوار ہو کر) سمندر پار کر لیا اور ہمارے اونٹوں کے پاؤں بھی گیلے نہیں ہوئے۔ دوسری بات یہ ہے کہ جب ہم وہاں سے واپس آ رہے تھے تو ایک وسیع بیابان میں ہمارا گزر ہوا، ہمارے پاس پانی بالکل نہیں تھا۔ ہم نے ان سے شکایت کی، انہوں نے دو رکعت نماز پڑھ کر دعا مانگی تو ایک دم آسمان پر ڈھال کی طرح کا بادل آیا اور خوب برسا اور اس نے اپنے سارے دہانے کھول دیے۔ ہم نے خود بھی پانی پیا اور اپنے جانوروں کو بھی پلایا۔ تیسری بات یہ ہے کہ ان کا انتقال ہو گیا، ہم نے ان کو ریت میں دفن کر دیا۔ ابھی ہم وہاں سے تھوڑا سا آگے گئے تھے کہ ہمیں خیال آیا کہ اس علاقہ کی زمین پکی نہیں ہے، ریتیلا علاقہ ہے، کوئی درندہ آ کر ان کی قبر کھود کر انہیں کھا جائے گا۔ اس خیال سے ہم واپس آئے تو قبر ان کی صحیح سالم تھی لیکن جب ہم نے ان کی قبر کھودی تو ہمیں ان کی نعش قبر میں نظر نہ آئی۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Dalaa'il (Pg.208) and Hilyah (Vol.1 Pg.8) briefly from Abu Hurayrah. Tabraani has reported it too; Haythami (Vol.9 Pg.367) has said that its narrators are reliable."]]},{"b":[["n",[["ابونعیم کی روایت میں یہ بھی ہے کہ جب (ہم سمندر پار کر کے جزیرہ میں پہنچ گئے اور) ہمیں کسریٰ کی طرف سے مقرر کردہ گورنر ابن مکعبر نے یوں جانوروں پر آتے دیکھا تو اس نے کہا نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! نہیں۔ ہم ان کا مقابلہ نہیں کر سکتے۔ پھر وہ کشتی میں بیٹھ کر ایران چلا گیا۔",""]]]],"f":[]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں میں نے اس امت میں تین باتیں پائی ہیں، پھر اس کے بعد لمبی حدیث ذکر کی ہے۔ اس میں یہ مضمون بھی ہے کہ پھر حضرت عمر بن خطابؓ نے ایک لشکر تیار کیا اور حضرت علاء بن حضرمیؓ کو ان کا امیر بنایا۔ میں بھی اس غزوہ میں گیا تھا۔ جب ہم غزوہ کی جگہ پہنچے تو ہم نے دیکھا کہ دشمن کو ہمارا پتہ چل گیا تھا اور وہ پانی کے تمام نشان مٹا کر وہاں سے جا چکا تھا۔ گرمی پڑ رہی تھی اور پیاس کے مارے ہمارا اور ہمارے جانوروں کا برا حال ہو گیا تھا اور جمعہ کا دن تھا جب سورج غروب ہونے لگا تو حضرت علاءؓ نے ہمیں دو رکعت نماز پڑھائی۔ پھر انہوں نے آسمان کی طرف ہاتھ اٹھائے اور ہمیں آسمان میں بادل کا کہیں نام و نشان نظر نہیں آ رہا تھا۔ ",""],["ٱللَّٰه","a"],[" کی قسم! حضرت علاءؓ نے ابھی ہاتھ نیچے نہیں کیے تھے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہوا بھیج دی اور ایک بادل ظاہر کر دیا اور وہ بادل اتنے زور سے برسا کہ سارے نالے، تالاب اور وادیاں پانی سے بھر گئیں اور ہم نے خود پانی پیا اور اپنے جانوروں کو بھی پلایا اور اپنے مشکیزوں اور برتنوں کو بھر لیا۔ پھر ہم اپنے دشمن کے پاس پہنچے، وہ لوگ اپنی جگہ چھوڑ کر خلیج پار کر کے سمندر میں ایک جزیرے میں جا چکے تھے۔ اس خلیج کے کنارے کھڑے ہو کر حضرت علاءؓ نے ان الفاظ سے ",""],["ٱللَّٰه","a"],[" کو پکارا یا علی! یا عظیم! یا حلیم! یا کریم! پھر ہم سے کہا ",""],["ٱللَّٰه","a"],[" کا نام لے کر اس سمندر کو پار کرو۔ چنانچہ ہم وہ سمندر پار کرنے لگے، ہمارے جانوروں کے کھر بھی گیلے نہیں ہوئے تھے، تھوڑی ہی دیر میں ہم نے دشمن کو جا لیا۔ ہم نے انہیں قتل بھی کیا اور گرفتار بھی کیا اور انہیں غلام بھی بنایا۔ اس کے بعد ہم پھر اسی خلیج کے کنارے پر آئے اور حضرت علاءؓ نے ",""],["ٱللَّٰه","a"],[" کو پھر انہی ناموں سے پکارا اور ہم پھر اس خلیج کو اس طرح پار کرنے لگے کہ ہمارے جانوروں کے کھر گیلے نہیں ہو رہے تھے۔ آگے اور حدیث بھی ذکر کی۔",""],[" (4)","s"]]]],"f":[["(4)","Bayhaqi."]]},{"b":[["n",[["حضرت سہم بن منجابؒ","b"],[" کہتے ہیں ہم حضرت علاء بن حضرمیؓ کے ساتھ غزوے میں گئے، پھر سارا قصہ ذکر کیا اور دعا میں یہ الفاظ ذکر کیے یا علیم! یا حلیم! یا علی! یا عظیم! ہم تیرے بندے ہیں اور تیرے راستے میں اور تیرے دشمن سے لڑنے کے ارادے سے نکلے ہیں، ہمیں ایسی بارش عطا کر جس سے ہمارے پینے اور وضو کے پانی کا انتظام ہو جائے اور جب ہم اسے چھوڑ کر جائیں تو ہمارے علاوہ اور کسی کا اس میں حصہ نہ ہو۔ اور سمندر کی دعا میں یہ الفاظ ہیں اور ہمارے لیے اپنے دشمن تک پہنچنے کا راستہ بنا دے۔",""],[" (5)","s"]]]],"f":[["(5)","Bukhaari in his Taareekh."]]},{"b":[["n",[["ابونعیم کی روایت میں ہے کہ حضرت علاءؓ ہمیں لے کر سمندر میں گھس گئے، جب ہم اندر گئے تو پانی ہماری سواریوں کے نمدوں تک بھی نہیں پہنچا اور ہم دشمن تک پہنچ گئے۔ اور ابن جریرؒ نے اپنی تاریخ میں اور ابن کثیرؒ نے البدایہ میں یہ قصہ یوں بیان کیا ہے کہ حضرت ابوبکرؓ نے حضرت علاء بن حضرمیؓ کو بحرین کے مرتدین سے لڑنے کے لیے بھیجا اور اس میں یہ قصہ بھی ذکر کیا ہے کہ جن اونٹوں پر لشکر کا زاد سفر اور خیمے اور پینے کا پانی لدا ہوا تھا وہ سارے اونٹ سامان سمیت بھاگ گئے تھے اور پھر خود ہی سامان سمیت آ گئے۔ اور یہ قصہ بھی ذکر کیا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مسلمانوں کے پڑاؤ کی جگہ کے ساتھ ہی صاف و شفاف خالص پانی کا حوض پیدا فرما دیا اور یہ بھی ذکر کیا کہ ان حضرات نے مرتدین سے جنگ کی۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilyah (Vol.1 Pg.7)."]]},{"b":[["n",[["ابن کثیرؒ نے یہ قصہ یوں ذکر کیا ہے کہ حضرت علاءؓ نے مسلمانوں سے کہا آؤ (بحرین کے جزیرے کے علاقے) دارین چلتے ہیں تاکہ وہاں جا کر دشمن سے جنگ کریں۔ اس پر سارے مسلمان فوراً تیار ہو گئے اور وہ ان مسلمانوں کو لے کر چل پڑے یہاں تک کہ ساحل سمندر پر پہنچ گئے۔ پہلے تو ان کا خیال ہوا کہ کشتیوں کے ذریعے دارین کا سفر کر لیں لیکن پھر یہ سوچا کہ سفر کافی لمبا ہے، کشتیوں میں جاتے جاتے دیر لگ جائے گی، اتنے میں ",""],["ٱللَّٰه","a"],[" کے دشمن وہاں سے آگے چلے جائیں گے۔ اور پھر یہ دعا پڑھتے ہوئے اپنے گھوڑے کو لے کر سمندر میں گھس گئے",""]]],["q",[["يَا أَرْحَمَ ٱلرَّاحِمِينَ يَا حَكِيمُ يَا كَرِيمُ يَا أَحَدُ يَا صَمَدُ يَا حَيُّ يَا مُحْيِي يَا قَيُّومُ يَا ذَا ٱلْجَلَالِ وَٱلْإِكْرَامِ لَا إِلَـٰهَ إِلَّا أَنْتَ يَا رَبَّنَا اور لشکر کو بھی حکم دیا کہ وہ یہ دعا پڑھتے ہوئے سمندر میں گھس جائیں۔ چنانچہ انہوں نے بھی ایسا ہی کیا اور اس طرح اللہ کے حکم سے ان سب کو لے کر حضرت علاءؓ خلیج کو پار کر گئے۔ وہ سمندر میں نرم ریت جیسی جگہ پر چل رہے تھے جس پر اتنا کم پانی تھا کہ اونٹوں کے پاؤں بھی نہیں ڈوبے تھے اور وہ پانی گھوڑوں کے گھٹنوں تک بھی نہیں پہنچ رہا تھا۔ یہ سفر کشتی میں ایک رات ایک دن میں طے ہوتا تھا لیکن حضرت علاءؓ نے سمندر پار کیا اور جزیرہ کے ساحل پر پہنچ گئے، وہاں جا کر دشمن سے جنگ کی اور ان پر غلبہ حاصل کیا اور ان کا مال غنیمت سمیٹا اور پھر اپنی پہلی جگہ واپس بھی آ گئے اور یہ سارے کام صرف ایک دن میں ہو گئے۔","a"],[" (7)","s"]]]],"f":[["(7)","Ibn Jareer (Vol.2 Pg.522) and Al Bidaayah wan Nihaayah (Vol.6 Pg.328). Al Bidaayah wan Nihaayah (Vol.6 Pg.329); Ibn Jareer (Vol.2 Pg.526) has reported a similar narration."]]},{"b":[["n",[["حضرت ابن رفیلؒ","b"],[" کہتے ہیں بہر سیر قریب والا شہر تھا اور دریائے دجلہ کے پار دور والا شہر تھا۔ جب حضرت سعدؓ نے بہر سیر کو فتح کر کے اس میں پڑاؤ ڈال لیا تو انہوں نے کشتیاں تلاش کیں تاکہ لوگ دریائے دجلہ پار کر کے دور والے شہر جا سکیں اور اسے فتح کر سکیں لیکن انہیں کوئی کشتی نہ مل سکی کیونکہ ایرانی لوگ تمام کشتیاں سمیٹ کر وہاں سے لے جا چکے تھے۔ چنانچہ مسلمان صفر مہینے کے کئی دن بہر سیر میں ٹھہرے رہے اور حضرت سعدؓ کے سامنے اس بات کا اظہار کرتے رہے کہ (کشتیوں کے بغیر ہی) دریا پار کر لیا جائے لیکن شفقت کی وجہ سے وہ مسلمانوں کو ایسا کرنے نہیں دیتے تھے۔ وہاں کے کچھ عجمی کافروں نے انہیں دریا پار کرنے کے لیے ایک گھاٹ بتایا جو وادی کی سخت جگہ پہنچا دیتا تھا لیکن حضرت سعدؓ تردد میں پڑ گئے اور اس گھاٹ میں سے جانے سے انکار کر دیا۔ اتنے میں دریا کا پانی چڑھ گیا۔ پھر حضرت سعدؓ نے خواب دیکھا کہ دریا میں پانی بہت زیادہ چڑھا ہوا ہے لیکن مسلمانوں کے گھوڑے دریا میں گھسے ہیں اور پار ہو گئے ہیں۔ اس خواب کو دیکھ کر انہوں نے دریا پار کرنے کا پختہ ارادہ کر لیا اور لوگوں کو جمع کر کے بیان کیا اور ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء کے بعد فرمایا تمہارا دشمن اس دریا کی وجہ سے تم سے محفوظ ہو گیا ہے، تم لوگ تو ان تک نہیں پہنچ سکتے لیکن وہ لوگ کشتیوں میں بیٹھ کر تم پر حملہ آور ہو سکتے ہیں۔ تمہارے پیچھے ایسی کوئی چیز نہیں ہے جس سے تم پر حملہ کا خطرہ ہو، میں نے پکا ارادہ کر لیا ہے کہ دریا پار کر کے دشمن پر حملہ کیا جائے۔ تمام مسلمانوں نے بیک زبان کہا آپ ضرور ایسا کریں، ",""],["ٱللَّٰه","a"],[" ہمیں اور آپ کو ہدایت پر پکا رکھے۔ پھر حضرت سعدؓ نے لوگوں کو دریا پار کرنے کی دعوت دیتے ہوئے فرمایا آپ لوگوں میں سے کون اس بات کے لیے تیار ہے کہ پہل کرے اور دریا پار کر کے گھاٹ کے دوسرے کنارے پر قبضہ کر لے اور اس کنارے کی دشمن سے حفاظت کرے تاکہ دشمن مسلمانوں کو اس کنارے تک پہنچنے سے روک نہ سکے۔ اس پر حضرت عاصم بن عمروؓ فوراً تیار ہو گئے اور ان کے بعد اور چھ سو (600) بہادر آدمی تیار ہو گئے۔ حضرت سعدؓ نے حضرت عاصمؓ کو ان کا امیر بنایا، حضرت عاصمؓ ان کو لے کر چلے، پھر دجلہ کے کنارے کھڑے ہو کر اپنے ساتھیوں سے کہا آپ میں سے کون میرے ساتھ چلنے کو تیار ہے تاکہ ہم گھاٹ کے پرلے کنارے کو دشمن سے محفوظ کر لیں؟ اس پر ان میں سے ساٹھ (60) آدمی تیار ہو گئے۔ حضرت عاصمؓ نے ان کو دو حصوں میں تقسیم کیا، آدھے لوگوں کو گھوڑوں پر اور آدھے لوگوں کو گھوڑیوں پر بٹھایا تاکہ گھوڑوں کے لیے تیرنے میں آسانی رہے، پھر وہ جلد دجلہ میں داخل ہو گئے (اور دریا کو ",""],["ٱللَّٰه","a"],[" کی مدد سے پار کر لیا)۔ جب حضرت سعدؓ نے دیکھا کہ حضرت عاصمؓ نے گھاٹ کے پرلے کنارے پر قبضہ کر کے محفوظ کر لیا ہے تو انہوں نے تمام لوگوں کو دریا میں گھس جانے کا حکم دے دیا اور فرمایا یہ دعا پڑھو",""]]],["q",[["نَسْتَعِينُ بِٱللَّهِ وَنَتَوَكَّلُ عَلَيْهِ وَحَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّهِ ٱلْعَلِيِّ ٱلْعَظِيمِ اور لشکر کے اکثر لوگ ایک دوسرے کے پیچھے چلنے لگے اور گہرے پانی پر بھی چلتے رہے حالانکہ دریائے دجلہ بہت جوش میں تھا اور بہت جھاگ پھینک رہا تھا اور ریت اور مٹی کی وجہ سے اس کا رنگ سیاہ ہو رہا تھا اور لوگوں کی دو دو کی جوڑیاں بنی ہوئی تھیں اور وہ دریا پار کرتے ہوئے آپس میں اس طرح باتیں کر رہے تھے جس طرح زمین پر چلتے ہوئے کیا کرتے تھے۔ ایران والے یہ منظر دیکھ کر حیران رہ گئے کیونکہ انہیں اس کا وہم و گمان بھی نہیں تھا، وہ لوگ گھبرا کر ایسے جلدی سے بھاگے کہ اپنا اکثر مال وہیں چھوڑ گئے۔ اور 16 ہجری صفر کے مہینہ میں مسلمان اس شہر میں داخل ہوئے اور کسریٰ کے خزانوں میں جو تین ارب تھے ان پر بھی مسلمانوں کا قبضہ ہو گیا اور شیرویہ اور اس کے بعد کے بادشاہوں نے جو کچھ جمع کیا تھا اس پر بھی قبضہ ہو گیا۔","a"],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Dalaa'il (Pg.208). Tabari has reported it in his Taareekh (Vol.3 Pg.119) from Sayf."]]},{"b":[["n",[["حضرت ابوبکر بن حفص بن عمرؒ","b"],[" کہتے ہیں گھوڑے مسلمانوں کو لے کر پانی پر تیر رہے تھے، حضرت سعدؓ کے ساتھ حضرت سلمانؓ چل رہے تھے اور سعدؓ کہہ رہے تھے ہمیں ",""],["ٱللَّٰه","a"],[" کافی ہے اور وہ بہترین کارساز ہے۔ ",""],["ٱللَّٰه","a"],[" کی قسم! اگر ہمارے لشکر میں بدکاری اور گناہ اتنے نہیں ہیں جو نیکیوں پر غالب آ جائیں تو ",""],["ٱللَّٰه","a"],[" ضرور اپنے دوست کی مدد کریں گے اور اپنے دین کو غالب کریں گے اور اپنے دشمن کو شکست دیں گے۔ حضرت سلمانؓ نے ان سے کہا اسلام ابھی نیا ہے اور ",""],["ٱللَّٰه","a"],[" کی قسم! مسلمانوں کے لیے آج سمندر اور دریا ایسے مسخر کر دیے گئے ہیں جیسے ان کے لیے خشکی مسخر تھی۔ غور سے سنیں! اس ذات کی قسم جس کے قبضے میں سلمان کی جان ہے، مسلمان جیسے دریا میں فوج در فوج داخل ہوئے ہیں ایسے ہی اس سے فوج در فوج نکل بھی ضرور جائیں گے۔ چنانچہ مسلمان دریا کے ایک کنارے سے دوسرے کنارے تک ایسے چھا گئے کہ پانی کسی جگہ بھی نظر نہیں آ رہا تھا اور خشکی پر چلتے ہوئے وہ جتنی باتیں آپس میں کر رہے تھے اب اس سے زیادہ کر رہے تھے اور جیسے حضرت سلمانؓ نے کہا تھا مسلمان آخر دریا سے باہر نکل گئے۔ نہ ان کی کوئی چیز کم ہوئی اور نہ ان میں سے کوئی ڈوبا۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Dalaa'il (Pg.209). Tabari (Vol.3 Pg.121) has reported a similar narration with some additions in the beginning."]]},{"b":[["n",[["حضرت ابو عثمان نہدیؓ","b"],[" فرماتے ہیں سارے مسلمان صحیح سالم پار ہو گئے، البتہ بارق کے رہنے والا ایک آدمی جسے غرقدہ کہا جاتا تھا اپنی سرخ گھوڑی کی پشت سے نیچے گر گیا اور وہ منظر اب تک میری آنکھوں کے سامنے ہے کہ اس کی گھوڑی اپنی گردن کے بالوں سے پسینہ جھاڑ رہی تھی اور وہ صاحب پانی کے اوپر تیر رہے تھے۔ حضرت قعقاع بن عمروؓ نے اپنے گھوڑے کی لگام ان کی طرف موڑی اور اپنے ہاتھ سے انہیں پکڑ کر کھینچتے رہے یہاں تک کہ وہ دریا کے پار ہو گئے۔ اور لشکر میں سے کسی کی بھی کوئی چیز پانی میں نہیں گری، صرف ایک پیالہ گرا تھا جو ایک پرانی رسی سے بندھا ہوا تھا، وہ رسی ٹوٹ گئی اس لیے پیالہ گر گیا اور پانی اسے بہا کر لے گیا۔ پیالے والے کے جوڑی دار نے عار دلاتے ہوئے اس سے کہا تمہارے پیالے کو تقدیر کا ایسا تیر لگا کہ وہ پانی میں گر گیا۔ پیالے والے نے کہا نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! مجھے اس بات کا یقین ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ پورے لشکر میں صرف میرا پیالہ ہرگز نہیں لیں گے۔ چنانچہ دریا کی موجوں نے وہ پیالہ ساحل پر پھینک دیا اور گھاٹ کے پرلے کنارے کے پہرہ دینے والوں میں سے ایک آدمی کی نگاہ اس پیالے پر پڑی، اس نے اپنے نیزے سے اسے اٹھا لیا اور جب سارا لشکر دریا پار کر گیا تو وہ پیالہ لے کر لشکر میں آ گیا اور پیالے کے مالک کو تلاش کرنے لگا۔ آخر وہ مالک مل گیا اور اس نے پیالہ لے لیا۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Nu'aym in his Dalaa'il (Pg.209). Ibn Jareer (Vol.3 Pg.122) has reported a similar narration."]]},{"b":[["n",[["حضرت عمیر صائدیؒ","b"],[" کہتے ہیں جب حضرت سعدؓ لوگوں کو لے کر دجلہ میں داخل ہونے لگے تو سب لوگوں نے جوڑیاں بنا لیں، حضرت سلمانؓ حضرت سعدؓ کے جوڑی دار تھے اور پانی پر ان کے ساتھ ساتھ چل رہے تھے۔ حضرت سعدؓ نے یہ آیت پڑھی",""]]],["q",[["ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ","a"]]],["p",[["ترجمہ: \"یہ اندازہ باندھا ہوا ہے اس (خدا) کا جو زبردست، علم والا ہے۔\" (سورۂ یٰسین، آیت 38)۔ دریا میں پانی بہت چڑھا ہوا تھا اور گھوڑا کچھ دیر سیدھا کھڑا رہتا، جب تھک جاتا تو دریا میں ایک ٹیلہ ظاہر ہو جاتا جس پر وہ زمین کی طرح کھڑے ہو کر آرام کر لیتا۔ مدائن شہر میں اس سے زیادہ عجیب منظر کبھی پیش نہیں آیا تھا۔ چونکہ پانی کی بہت زیادتی ہونے کے باوجود جگہ جگہ ٹیلے ظاہر ہوئے تھے اس وجہ سے اس دن کو ٹیلوں کا دن کہا جاتا تھا۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Jareer (Vol.3 Pg.122). Abu Nu'aym has also reported it in his Dalaa'il (Pg.209)."]]},{"b":[["n",[["ابونعیم نے بھی حضرت عمیر صائدیؒ سے اسی جیسی روایت نقل کی ہے لیکن اس کی روایت میں مضمون اس طرح سے ہے کہ مدائن میں اس سے زیادہ عجیب واقعہ کبھی پیش نہیں آیا تھا اور چونکہ جو بھی تھک جاتا تھا اس کے سامنے فوراً ایک ٹیلہ نمودار ہو جاتا تھا جس پر وہ آرام کر لیتا تھا، اس لیے اس دن کو ٹیلوں والا دن کہا جاتا تھا۔",""]]]],"f":[]},{"b":[["n",[["حضرت قیس بن ابی حازمؓ","b"],[" فرماتے ہیں جب ہم دجلہ میں داخل ہوئے تو وہ کناروں تک لبالب بھرا ہوا تھا۔ جب ہم اس جگہ پہنچے جہاں پانی سب سے زیادہ تھا وہاں گھوڑے سوار کچھ دیر کھڑا رہا تو پانی اس کی پیٹی تک بھی نہ پہنچا۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Jareer (Vol.3 Pg.123) and Abu Nu'aym in his Dalaa'il (Pg.210)."]]},{"b":[["n",[["حضرت حبیب بن صہبانؒ","b"],[" کہتے ہیں مسلمانوں میں سے ایک آدمی جن کا نام حجر بن عدی تھا، انہوں نے کہا کیا تمہیں پار کر کے دشمن تک جانے سے صرف پانی کا یہ قطرہ ہی روک رہا ہے؟ پانی کے قطرے سے مراد وہ دریائے دجلہ لے رہے تھے، حالانکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَـٰبًا مُّؤَجَّلًا","a"]]],["p",[["ترجمہ: \"اور کسی شخص کو موت آنا ممکن نہیں بدون حکم خدا تعالیٰ کے، اس طور سے کہ اس کی میعاد معین لکھی ہوئی رہتی ہے۔\" (سورۂ آل عمران، آیت 145)۔ پھر انہوں نے اپنا گھوڑا دریائے دجلہ میں ڈال دیا۔ جب انہوں نے ڈالا تو تمام لوگوں نے اپنے گھوڑے ڈال دیے۔ جب دشمن نے انہیں یوں دریا پار کرتے ہوئے دیکھا تو کہنے لگے یہ تو دیو ہیں دیو، اور پھر وہ سارے بھاگ گئے۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Jareer (Vol.3 Pg.123)."]]},{"b":[["n",[["حضرت حبیب بن صہبان ابو مالکؒ","b"],[" کہتے ہیں جب مسلمان مدائن والے دن دریائے دجلہ پار کر رہے تھے تو دشمن انہیں دریا پار کرتا ہوا دیکھ کر فارسی میں کہنے لگا یہ تو دیو ہیں، اور پھر آپس میں ایک دوسرے سے کہنے لگے ",""],["ٱللَّٰه","a"],[" کی قسم! تمہیں اب انسانوں سے نہیں بلکہ جنات سے لڑنا ہوگا۔ اس سے وہ مرعوب ہو گئے اور انہیں شکست ہو گئی۔",""],[" (14)","s"]]]],"f":[["(14)","Ibn Abi Haatim, as quoted in the Tafseer of Ibn Katheer (Vol.1 Pg.210)."]]},{"b":[["n",[["حضرت اعمشؒ","b"],[" اپنے ایک ساتھی سے نقل کرتے ہیں کہ جب ہم دجلہ کے پاس پہنچے تو وہ بہت چڑھا ہوا تھا اور عجمی لوگ دریا کے اس پار تھے۔ ایک مسلمان نے بسم ",""],["ٱللَّٰه","a"],[" پڑھ کر اپنا گھوڑا دریا میں ڈال دیا اور وہ ڈوبا نہیں بلکہ اس کا گھوڑا پانی کے اوپر چلنے لگا۔ یہ دیکھ کر باقی تمام لوگوں نے بھی بسم ",""],["ٱللَّٰه","a"],[" پڑھ کر اپنے گھوڑے دریا میں ڈال دیے اور وہ سب پانی کے اوپر چلنے لگے۔ جب عجمی لوگوں نے انہیں دیکھا تو کہنے لگے یہ تو دیو ہیں، دیو ہیں۔ پھر ان کا جدھر منہ اٹھا ادھر بھاگ گئے۔",""],[" (15)","s"]]]],"f":[["(15)","Abu Nu'aym in his Dalaa'il (Pg.210)."]]}]},"254":{"lead":[],"stories":[{"b":[["n",[["حضرت معاویہ بن حرملؒ","b"],[" کہتے ہیں میں مدینہ منورہ گیا تو حضرت تمیم داریؓ مجھے اپنے ساتھ کھانے کے لیے لے گئے، میں نے کھانا تو خوب کھایا لیکن مجھے بھوک بہت زیادہ تھی اس وجہ سے میرا پیٹ پوری طرح نہیں بھرا کیونکہ میں تین دن سے مسجد میں ٹھہرا ہوا تھا اور کچھ نہیں کھایا تھا۔ ایک دن اچانک مدینہ کے پتھریلے میدان میں آگ ظاہر ہوئی، حضرت عمرؓ نے آ کر حضرت تمیمؓ سے کہا اٹھو اور اس آگ کے بجھانے کا انتظام کرو۔ حضرت تمیمؓ نے کہا اے امیر المومنین! میں کون ہوتا ہوں؟ اور میری کیا حیثیت ہے؟ لیکن حضرت عمرؓ اصرار فرماتے رہے جس پر وہ حضرت عمرؓ کے ساتھ چل دیے۔ میں بھی ان دونوں حضرات کے پیچھے چل دیا اور وہ دونوں حضرات آگ کے پاس گئے۔ وہاں جا کر حضرت تمیمؓ اپنے ہاتھ سے آگ کو اس طرح دھکے دینے لگے یہاں تک کہ آگ گھاٹی میں اسی جگہ واپس داخل ہو گئی جہاں سے نکلی تھی۔ آگ کے پیچھے حضرت تمیمؓ بھی اندر داخل ہو گئے اور حضرت عمرؓ فرما رہے تھے (یہ ایمانی منظر) نہ دیکھنے والا دیکھنے والے جیسا نہیں ہو سکتا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Dalaa'il (Pg.212), and Bayhaqi from Mu'aawiya bin Harmal, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.153)."]]},{"b":[["n",[["حضرت معاویہ بن حرملؒ","b"],[" کہتے ہیں میں نے حضرت عمرؓ کی خدمت میں حاضر ہو کر عرض کیا اے امیر المومنین! آپ کے لشکر کے قابو پانے سے پہلے ہی میں نے توبہ کر لی۔ حضرت عمرؓ نے پوچھا تم کون ہو؟ میں نے کہا میں مسلمہ کذاب کا داماد معاویہ بن حرمل ہوں۔ حضرت عمرؓ نے فرمایا جاؤ اور جو مدینہ والوں میں سب سے بہترین آدمی ہے اس کے مہمان بن جاؤ یعنی حضرت تمیم داریؓ کے مہمان بن جاؤ۔ چنانچہ میں حضرت تمیم داریؓ کا مہمان بن گیا۔ ایک دفعہ مدینہ کے پتھریلے میدان میں آگ نکل آئی، اس وقت ہم لوگ باتیں کر رہے تھے، حضرت عمرؓ نے آ کر حضرت تمیمؓ سے کہا (چلو اور اس آگ کا انتظام کرو)۔ حضرت تمیمؓ نے کہا میری کیا حیثیت ہے؟ اور کیا آپ اس بات سے نہیں ڈرتے کہ میرے پوشیدہ عیوب آپ پر ظاہر ہوں؟ اس طرح حضرت تمیمؓ کسر نفسی کر رہے تھے۔ (لیکن حضرت عمرؓ نے اصرار فرمایا تو) حضرت تمیمؓ کھڑے ہوئے اور آگ کو دھکے دیتے رہے یہاں تک کہ جس دروازے سے نکلی تھی اسی میں اسے واپس کر دیا اور پھر خود بھی آگ کے پیچھے اس دروازے کے اندر چلے گئے، پھر باہر آ گئے اور اس سب کے باوجود آگ انہیں کچھ نقصان نہ پہنچا سکی۔ اور ابونعیم کی روایت میں یہ بھی ہے کہ حضرت عمرؓ نے حضرت تمیمؓ سے فرمایا ان ہی جیسے کاموں کے لیے ہم نے تمہیں چھپا رکھا ہے اے ابو رقیہ (یہ حضرت تمیمؓ کی کنیت ہے)۔",""],[" (2)","s"]]]],"f":[["(2)","Baghawi, as quoted in Isaabah (Vol.3 Pg.497). Abu Nu'aym has reported it in his Dalaa'il (Pg.212)."]]}]},"255":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں ہم لوگ حضورؐ کے ساتھ عشاء کی نماز پڑھ رہے تھے، حضورؐ جب سجدے میں جاتے تو حضرت حسن اور حضرت حسینؓ کود کر آپؐ کی پیٹھ پر چڑھ جاتے۔ جب آپؐ سجدے سے سر اٹھاتے تو نرمی سے پکڑ کر ان دونوں کو پیٹھ سے اتار دیتے۔ آپؐ جب دوبارہ سجدے میں جاتے تو یہ دونوں پھر چڑھ جاتے۔ حضورؐ نے جب نماز پوری کر لی تو دونوں کو اپنی ران پر بٹھا لیا۔ میں کھڑے ہو کر حضورؐ کی خدمت میں گیا اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ان دونوں کو گھر چھوڑ آؤں؟ اتنے میں بجلی چمکی تو حضورؐ نے ان دونوں سے فرمایا اپنی ماں کے پاس چلے جاؤ۔ بجلی کی روشنی اتنی دیر رہی کہ یہ دونوں اپنی والدہ کے پاس پہنچ گئے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.181). Bayhaqi has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.152)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ کو حضرت حسنؓ سے بہت زیادہ محبت تھی۔ ایک دفعہ اندھیری رات میں حضرت حسنؓ حضورؐ کے پاس تھے، حضرت حسنؓ نے کہا میں اپنی امی کے پاس چلا جاؤں؟ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں اس کے ساتھ چلا جاؤں؟ آپؐ نے فرمایا نہیں۔ اتنے میں آسمان میں بجلی چمکی اور اس کی روشنی اتنی دیر رہی کہ اس میں چل کر حضرت حسنؓ اپنی والدہ کے پاس پہنچ گئے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Dalaa'il (Pg.205)."]]},{"b":[["n",[["امام احمدؒ نے جمعہ کی خاص گھڑی کے قصہ میں ",""],["حضرت ابوسعید خدریؓ","b"],[" سے ایک لمبی حدیث نقل کی ہے جس میں یہ بھی ہے کہ پھر اس رات کو آسمان پر بہت زیادہ بادل آئے۔ حضورؐ جب عشاء کی نماز کے لیے باہر تشریف لائے تو ایکدم بجلی چمکی جس میں حضورؐ کو حضرت قتادہ بن نعمانؓ نظر آئے۔ حضورؐ نے ان سے پوچھا کہ اے قتادہ! رات کے اندھیرے میں کیسے آنا ہوا؟ انہوں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے خیال آیا کہ بارش کی وجہ سے آج لوگ نماز میں کم آئیں گے، اس لیے میں آ گیا۔ حضورؐ نے فرمایا جب تم نماز پڑھ چکو تو میرے آنے تک ٹھہرے رہنا۔ جب حضورؐ نماز پڑھ کر واپس آئے تو انہیں کھجور کی ایک ٹہنی دی اور فرمایا یہ لے لو، یہ راستہ میں تمہارے آگے دس ہاتھ اور پیچھے دس ہاتھ روشنی کرے گی۔ جب تم گھر میں داخل ہو جاؤ اور وہاں تمہیں ایک کونے میں کالی چیز نظر آئے تو بات کرنے سے پہلے اسے اس ٹہنی سے مارنا کیونکہ وہ شیطان ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad and Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.167)."]]},{"b":[["n",[["طبرانی کی روایت میں یہ ہے کہ نماز کے بعد حضورؐ نے مجھے کھجور کی ایک ٹہنی دی اور فرمایا تمہارے پیچھے تمہارے گھر والوں کے پاس شیطان آیا ہے۔ تم یہ ٹہنی لے جاؤ اور گھر پہنچنے تک مضبوطی سے اسے پکڑے رہنا اور گھر کے کونے میں شیطان کو پکڑ کر اس ٹہنی سے خوب مارنا۔ چنانچہ میں مسجد سے نکلا تو اس ٹہنی سے موم بتی کی طرح روشنی نکلنے لگی اور میں اس کی روشنی میں چلنے لگا۔ میں گھر پہنچا تو گھر والے سو رہے تھے۔ میں نے کونے میں دیکھا تو اس میں ایک سیہ بیٹھا ہوا تھا، میں اسے اس ٹہنی سے مارنے لگا یہاں تک کہ وہ گھر سے نکل گیا۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.40)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں نبی کریمؐ کے دو صحابیؓ ایک اندھیری رات میں حضورؐ کے پاس سے نکلے تو ان دونوں کے ساتھ دو چراغ سے تھے جو ان دونوں کے سامنے روشنی کر رہے تھے۔ جب دونوں الگ ہوئے تو ہر ایک کے ساتھ ایک ایک چراغ ہو گیا یہاں تک کہ وہ دونوں اپنے گھر پہنچ گئے۔",""],[" (5)","s"]]]],"f":[["(5)","Bukhaari."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضرت اسید بن حضیر انصاریؓ اور ایک انصاری صحابیؓ حضورؐ سے اپنی کسی ضرورت کے بارے میں بات کر رہے تھے، اس میں رات کا ایک حصہ گزر گیا۔ اس رات اندھیرا بھی بہت تھا۔ جب یہ دونوں واپس جانے کے لیے حضورؐ کے پاس سے نکلے تو دونوں کے پاس ایک ایک چھوٹی لاٹھی تھی۔ ان میں سے ایک کی لاٹھی میں سے روشنی نکلنے لگی، وہ دونوں اس کی روشنی میں چلنے لگے۔ جب دونوں کے راستے الگ ہو گئے تو پھر دوسرے کی لاٹھی میں سے بھی روشنی نکلنے لگی اور وہ اس کی روشنی میں چلنے لگے۔ یونہی روشنی میں چلتے چلتے دونوں اپنے گھر پہنچ گئے۔",""],[" (6)","s"]]]],"f":[["(6)","Abdur Razzaaq."]]},{"b":[["n",[["بخاری کی ایک روایت میں ہے کہ حضرت انسؓ فرماتے ہیں حضرت عباد بن بشر اور حضرت اسید بن حضیرؓ حضورؐ کے پاس سے باہر نکلے، اور پھر پچھلی حدیث جیسی ذکر کی۔",""],[" (7)","s"]]]],"f":[["(7)","Bukhaari. Nasa'ee and Bayhaqi have reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.152). Ibn Sa'd (Vol.3 Pg.606) has reported a similar narration, as has Abu Nu'aym in his Dalaa'il (Pg.205)."]]},{"b":[["n",[["حضرت حمزہ بن عمرو اسلمیؓ","b"],[" فرماتے ہیں ہم لوگ ایک سفر میں حضورؐ کے ساتھ تھے، سخت اندھیری رات تھی، اس میں ہم لوگ ادھر ادھر بکھر گئے تو میری انگلیوں میں سے روشنی نکلنے لگی یہاں تک کہ لوگوں نے اپنی سواریاں بھی جمع کیں اور ان کا جو سامان گر گیا تھا اسے بھی جمع کیا اور اتنی دیر میری انگلیوں میں سے روشنی نکلتی رہی۔",""],[" (8)","s"]]]],"f":[["(8)","Bukhaari in his Taareekh, Bayhaqi and Tabraani, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.152 and Vol.8 Pg.213). Tabraani has reported from reliable sources, as confirmed by Haythami (Vol.9 Pg.411). Abu Nu'aym has also reported it in his Dalaa'il (Pg.206)."]]},{"b":[["n",[["حضرت حمزہ بن عمروؓ فرماتے ہیں جب ہم تبوک میں تھے تو وہاں گھاٹی میں منافقوں نے حضورؐ کی اونٹنی کو چھیڑا جس سے وہ بدکی اور حضورؐ کا کچھ سامان نیچے گر گیا، پھر میری پانچوں انگلیاں روشن ہو گئیں اور ان کی روشنی میں میں نے گرا ہوا سامان کوڑا، رسی وغیرہ اٹھایا۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Sa'd (Vol.4 Pg.315)."]]},{"b":[["n",[["حضرت میمون بن زید بن عبسؒ","b"],[" کہتے ہیں مجھے میرے والد نے بتایا کہ حضرت ابوعبسؓ تمام نمازیں حضورؐ کے ساتھ پڑھا کرتے تھے، پھر قبیلہ بنو حارثہ کے محلے میں واپس چلے جاتے۔ ایک رات سخت اندھیرا تھا اور بارش ہو چکی تھی، وہ مسجد سے نکلے تو ان کی لاٹھی میں سے روشنی نکلنے لگی اور وہ اس روشنی میں چل کر بنو حارثہ کے محلہ میں پہنچ گئے۔ امام بیہقیؒ کہتے ہیں حضرت ابوعبسؓ بدری صحابہ میں سے تھے۔",""],[" (10)","s"]]]],"f":[["(10)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.152). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.205), as has Haakim (Vol.3 Pg.350)."]]},{"b":[["n",[["حضرت ضحاکؒ","b"],[" فرماتے ہیں حضرت ابوعبس بن جبرؓ کی بینائی کمزور ہو گئی تو حضورؐ نے ان کو ایک لاٹھی دی اور فرمایا اس سے روشنی حاصل کرو۔ چنانچہ اس لاٹھی سے ان کے لیے یہاں سے وہاں تک کی ساری جگہ روشن ہو جاتی تھی۔",""],[" (11)","s"]]]],"f":[["(11)","Isaabah (Vol.4 Pg.130)."]]},{"b":[["n",[["حضرت طفیل بن عمرو دوسیؓ","b"],[" نور والے حضورؐ کے صحابہؓ میں سے تھے۔ حضورؐ نے ان کے لیے دعا فرمائی تھی تو ان کے کوڑے میں سے روشنی نکلنے لگی تھی جس میں وہ چلتے رہے۔ جلد اول صفحہ 292 پر ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ کی طرف دعوت دینے کے باب میں حضرت طفیل بن عمرو دوسیؓ کے دعوت دینے کے عنوان میں یہ گزر چکا ہے کہ انہوں نے حضورؐ سے نشانی مانگی جس سے اپنی قوم کو دعوت دینے میں مدد ملے۔ آپؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اس کو کوئی نشانی عطا فرما۔ حضرت طفیلؓ کہتے ہیں، چنانچہ میں اپنی قوم کی طرف چل پڑا۔ جب میں اس گھاٹی پر پہنچا جہاں سے میں اپنی آبادی والوں کو نظر آنے لگا تو میری دونوں آنکھوں کے درمیان چراغ کی مانند ایک چمکتا ہوا نور ظاہر ہوا۔ میں نے دعا مانگی اے ",""],["ٱللَّٰه","a"],["! اس نور کو میرے چہرے کے علاوہ کسی اور جگہ ظاہر کر دے کیونکہ مجھے خطرہ ہے کہ میری قوم والے آنکھوں کے درمیان نور دیکھ کر یہ سمجھیں گے کہ ان کے دین کو چھوڑنے کی وجہ سے میرا چہرہ بدل گیا ہے۔ چنانچہ وہ نور بدل کر میرے کوڑے کے سرے پر آ گیا۔ جب میں گھاٹی سے آبادی کی طرف اتر رہا تھا تو آبادی والوں کو میرے کوڑے کا یہ نور لٹکے ہوئے قندیل کی طرح نظر آ رہا تھا جسے وہ ایک دوسرے کو دکھا رہے تھے یہاں تک کہ میں ان کے پاس پہنچ گیا۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Mandah and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.78)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضرت عباس بن عبدالمطلبؓ اکثر فرمایا کرتے تھے میں نے تو یہی دیکھا ہے کہ جب بھی میں نے کسی کے ساتھ اچھا سلوک کیا تو میرے اور اس کے درمیان روشنی پیدا ہو گئی اور جب بھی میں نے کسی کے ساتھ برا سلوک کیا تو میرے اور اس کے درمیان اندھیرا پیدا ہو گیا، اس لیے تم حسن سلوک اور نیکی کرنے کو لازم پکڑو کیونکہ یہ بری موت سے بچاتا ہے۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.3 Pg.312)."]]}]},"256":{"lead":[],"stories":[{"b":[["n",[["حضرت کعبؓ کے آزاد کردہ غلام","b"],[" کہتے ہیں ہم حضرت مقداد بن اسود، حضرت عمرو بن عبسہ اور حضرت شافع بن حبیب ہذلیؓ کے ساتھ ایک سفر میں گئے۔ حضرت عمرو بن عبسہؓ اپنی باری پر ایک جانور چرانے گئے۔ میں دوپہر کے وقت انہیں دیکھنے گیا تو میں نے دیکھا کہ ایک بادل ان پر سایہ کیے ہوئے ہے جو ان سے جدا ہی نہیں ہوتا (وہ جدھر جاتے ہیں بادل بھی ادھر جاتا ہے)۔ میں نے یہ بات انہیں بتائی تو انہوں نے فرمایا یہ میرا خاص راز ہے، کسی کو مت بتانا، اگر مجھے پتہ چلا کہ تم نے کسی کو بتایا ہے تو پھر تمہاری خیر نہیں۔ وہ غلام کہتے ہیں چنانچہ ان کے انتقال تک میں نے یہ بات کسی کو نہیں بتائی۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym, as quoted in Isaabah (Vol.3 Pg.6)."]]}]},"257":{"lead":[],"stories":[{"b":[["n",[["بخاری میں ہے کہ ",""],["حضرت انسؓ","b"],[" فرماتے ہیں ایک دفعہ جمعہ کے دن حضورؐ کھڑے ہوئے خطبہ دے رہے تھے، منبر کے سامنے ایک دروازہ تھا، اس سے ایک آدمی داخل ہوا اور آ کر حضورؐ کے سامنے کھڑا ہو گیا اور اس نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! سارے جانور ہلاک ہو گئے (کیونکہ بہت دنوں سے بارش نہیں ہوئی) اور خشک سالی اور پانی کی کمی کی وجہ سے سارے راستے بند ہو گئے، لوگوں نے سفر کرنا چھوڑ دیا، اس لیے آپ ",""],["ٱللَّٰه","a"],[" سے دعا کریں کہ ",""],["ٱللَّٰه","a"],[" ہمیں بارش دے دے۔ آپؐ نے اسی وقت دونوں ہاتھ اٹھا کر یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! ہمیں بارش دے دے، اے ",""],["ٱللَّٰه","a"],["! ہمیں بارش دے دے، اے ",""],["ٱللَّٰه","a"],["! ہمیں بارش دے دے۔ حضرت انسؓ فرماتے ہیں ",""],["ٱللَّٰه","a"],[" کی قسم! ہمیں آسمان میں بادل وغیرہ کچھ نظر نہیں آ رہا تھا اور ہمارے اور سلع پہاڑ کے درمیان کوئی مکان یا گھر وغیرہ بھی نہیں تھا یعنی مطلع نظر آنے میں کوئی رکاوٹ نہیں تھی اور مطلع بالکل صاف تھا کہ اتنے میں سلع پہاڑ کے پیچھے سے ڈھال جتنا ایک بادل نمودار ہوا جو آسمان کے بیچ میں پہنچ کر پھیل گیا اور برسنے لگا اور پھر مسلسل بارش ہوتی رہی۔ ",""],["ٱللَّٰه","a"],[" کی قسم! ہم نے چھ دن تک سورج ہی نہیں دیکھا یہاں تک کہ اگلا جمعہ آ گیا اور حضورؐ کھڑے ہو کر خطبہ دے رہے تھے کہ اسی دروازے سے ایک آدمی داخل ہوا اور حضورؐ کے سامنے کھڑے ہو کر کہنے لگا یا رسول ",""],["ٱللَّٰه","a"],["! بارش اتنی زیادہ ہو گئی ہے کہ سارے جانور ہلاک ہو گئے، سارے راستے بند ہو گئے، آپؐ ",""],["ٱللَّٰه","a"],[" سے دعا کریں کہ وہ بارش روک لے۔ حضورؐ نے دونوں ہاتھ اٹھا کر دعا مانگی اے ",""],["ٱللَّٰه","a"],["! اردگرد بارش ہو، ہم پر بارش نہ ہو، اے ",""],["ٱللَّٰه","a"],["! ٹیلوں، پہاڑیوں، پہاڑوں، درخت اور گھاس کے اگنے کی جگہ پر بارش ہو۔ چنانچہ اسی وقت بارش رک گئی اور مسجد سے باہر نکلے تو ہم دھوپ میں چل رہے تھے۔ بخاری کی ایک روایت میں ہے کہ میں نے دیکھا کہ بادل پھٹ کر دائیں بائیں چلا گیا اور سب جگہ تو بارش ہوتی تھی، مدینہ میں نہیں ہوتی تھی۔ بخاری کی ایک روایت میں اس طرح ہے کہ حضورؐ نے دعا کے لیے اپنے دونوں ہاتھ اٹھائے، ہمیں آسمان میں بادل کا ایک ٹکڑا بھی نظر نہیں آ رہا تھا، اس ذات کی قسم جس کے قبضۂ قدرت میں میری جان ہے! ابھی حضورؐ نے ہاتھ نیچے نہیں کیے تھے کہ ایک دم آسمان پر پہاڑوں جیسے بادل چھا گئے اور آپؐ منبر سے نیچے نہیں اترے تھے کہ میں نے بارش کا پانی حضورؐ کی داڑھی سے ٹپکتے ہوئے دیکھا۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari. Muslim, Abu Dawood and Ahmad have reported similar narrations, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.88). Abu Nu'aym has also reported a similar narration in his Dalaa'il (Pg.160), as has Ibn Sa'd (Vol.1 Pg.176)."]]},{"b":[["n",[["حضرت ابولبابہ بن عبدالمنذرؓ","b"],[" فرماتے ہیں ایک دفعہ حضورؐ جمعہ کے دن لوگوں میں خطبہ دے رہے تھے۔ آپؐ نے فرمایا اے ",""],["ٱللَّٰه","a"],["! ہمیں بارش دے دے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کھجوریں کھلیانوں میں پڑی ہوئی ہیں۔ حضورؐ نے فرمایا اے ",""],["ٱللَّٰه","a"],["! جب تک ابولبابہ کپڑے اتار کر اپنے کھلیان کا نالہ اپنی لنگی سے بند نہ کرے اس وقت تک تو ہم پر بارش برساتا رہ۔ اس وقت ہمیں آسمان میں کوئی بادل نظر نہیں آ رہا تھا لیکن تھوڑی ہی دیر میں زبردست بارش ہوئی تو حضرات انصار نے مجھے گھیر لیا اور کہنے لگے اس وقت تک بارش نہیں رکے گی جب تک کہ آپ وہ کام نہ کر لیں جو حضورؐ نے فرمایا تھا۔ چنانچہ میں اٹھا اور کپڑے اتار کر اپنی لنگی سے اپنے کھلیان کا نالہ بند کیا تو بارش رکی۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Dalaa'il (Pg.160). Bayhaqi has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.92)."]]},{"b":[["n",[["جلد اول صفحہ 351 پر مشقتیں برداشت کرنے کے باب میں حضرت عمرؓ کی حدیث گزر چکی ہے جس میں یہ ہے کہ حضورؐ نے اپنے دونوں ہاتھ آسمان کی طرف اٹھائے (اور ",""],["ٱللَّٰه","a"],[" سے دعا مانگی) اور ابھی ہاتھ نیچے نہیں کیے تھے کہ آسمان میں بادل آ گئے، پہلے بوندا باندی ہوئی پھر موسلا دھار بارش شروع ہو گئی۔ صحابہ کرامؓ نے جتنے برتن ساتھ تھے وہ سارے بھر لیے، پھر بارش (بند ہونے کے بعد) ہم دیکھنے گئے (کہ کہاں تک بارش ہوئی ہے) تو دیکھا کہ جہاں تک لشکر تھا صرف وہاں تک بارش ہوئی ہے، لشکر کے باہر بارش نہیں ہوئی۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Jareer, Bazzaar and Tabraani."]]},{"b":[["n",[["حضرت عباس بن سہلؒ","b"],[" فرماتے ہیں جب صبح ہوئی تو لوگوں کے پاس پانی بالکل نہیں تھا۔ لوگوں نے حضورؐ سے شکایت کی۔ آپؐ نے ",""],["ٱللَّٰه","a"],[" سے دعا کی تو ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اسی وقت ایک بادل بھیجا جو خوب زور سے برسا یہاں تک کہ لوگ سیراب ہو گئے اور انہیں جتنے پانی کی ضرورت تھی وہ بھی انہوں نے برتنوں میں ساتھ لے لیا۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Dalaa'il (Pg.190)."]]},{"b":[["n",[["حضرت خوات بن جبیرؓ","b"],[" فرماتے ہیں حضرت عمرؓ کے زمانے میں بڑا سخت قحط پڑا تو حضرت عمرؓ لوگوں کو لے کر شہر سے باہر گئے اور انہیں دو رکعت نماز استسقاء پڑھائی اور اپنی چادر کے دونوں کناروں کو بدلا، دائیں کو بائیں اور بائیں کو دائیں طرف کیا، پھر اپنے دونوں ہاتھ پھیلا کر یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! ہم تجھ سے معافی مانگتے ہیں اور تجھ سے بارش مانگتے ہیں۔ حضرت عمرؓ کے اس جگہ سے ہٹنے سے پہلے ہی بارش شروع ہو گئی اور خوب بارش ہوئی۔ کچھ دنوں کے بعد دیہاتی لوگوں نے آ کر حضرت عمرؓ کی خدمت میں عرض کیا اے امیر المومنین! فلاں دن فلاں وقت ہم اپنے کھیت اور جنگلوں میں تھے کہ اچانک بادل ہمارے سروں پر آ گئے۔ ہم نے ان میں سے یہ آواز سنی اے ابوحفص! (یہ حضرت عمرؓ کی کنیت ہے) آپ کے پاس مدد آ گئی، اے ابوحفص! آپ کے پاس مدد آ گئی۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Dunya and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.4 Pg.290)."]]},{"b":[["n",[["حضرت مالک الدارؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ کے زمانہ میں زبردست قحط پڑا۔ ایک آدمی نے حضورؐ کی قبر اطہر پر حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! اپنی امت کے لیے (",""],["ٱللَّٰه","a"],[" سے بارش مانگیے کیونکہ وہ ہلاک ہو رہی ہے)۔ پھر اسے خواب میں حضورؐ کی زیارت ہوئی۔ حضورؐ نے ارشاد فرمایا جا کر عمر کو میرا سلام کہو اور اسے بتا دو کہ بارش ہوگی اور اسے کہہ دو کہ سمجھداری سے کام لے اور عقلمندی اختیار کرے۔ اس آدمی نے آ کر حضرت عمرؓ کو سارا واقعہ سنایا۔ حضرت عمرؓ رونے لگے اور کہنے لگے اے میرے رب! میں محنت کرنے اور سمجھداری سے کام لینے میں کسی طرح کمی نہیں کرتا ہوں، البتہ کوئی کام ہی میرے بس سے باہر ہو تو اور بات ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.289), reporting from reliable sources as confirmed in Al Bidaayah wan Nihaayah (Vol.7 Pg.92)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن کعب بن مالکؒ","b"],[" کہتے ہیں مدینہ منورہ اور اس کے آس پاس کی بستیوں میں ایک عرصہ تک بارش بند رہی جس سے کھانے کی تمام چیزیں ختم ہو گئیں اور سارے علاقہ میں زبردست قحط پھیل گیا۔ لوگ بھوکوں مرنے لگے۔ اس قحط کا نام قحط الرمادہ پڑ گیا (رمادہ کے معنی راکھ کے ہیں، اس قحط سے لوگوں کے رنگ راکھ جیسے ہو گئے تھے)۔ یہاں تک کہ جنگلی جانور بھوک کے مارے بستیوں کا رخ کرنے لگے تھے اور پالتو جانوروں کو بھی گھاس اور پانی نہیں ملتا تھا جس کی وجہ سے ان کے جسم میں گوشت ختم ہو گیا تھا، بالکل سوکھے اور دبلے پتلے ہو گئے تھے۔ یہاں تک کہ آدمی کو سخت بھوک لگی ہوتی تھی اور وہ بکری ذبح کرنا چاہتا لیکن بکری کی بری حالت دیکھ کر اس کا ذبح کرنے کو دل نہ کرتا اور اسے چھوڑ دیتا۔ لوگ اسی حال میں تھے اور مصر، شام اور عراق جیسے ملکوں کے مسلمانوں سے غذائی امداد منگوانے کی طرف حضرت عمرؓ کی توجہ نہیں تھی۔ ایک دن حضرت بلال بن حارث مزنیؓ آئے اور ان الفاظ سے حضرت عمرؓ سے اندر آنے کی اجازت مانگی کہ میں آپ کے پاس ",""],["ٱللَّٰه","a"],[" کے رسولؐ کا قاصد بن کر آیا ہوں۔ ",""],["ٱللَّٰه","a"],[" کے رسولؐ آپ سے فرما رہے ہیں میں تو تم کو بڑا سمجھدار سمجھتا تھا اور اب تک تم بالکل ٹھیک چلتے رہے، اب تمہیں کیا ہو گیا ہے؟ حضرت عمرؓ نے پوچھا تم نے یہ خواب کب دیکھا؟ حضرت بلالؓ نے کہا آج رات۔ حضرت عمرؓ نے باہر جا کر لوگوں میں اعلان کیا الصلوٰۃ جامعۃ، آج سب مسجد نبوی میں اکٹھے نماز پڑھیں، اپنی مسجدوں میں نہ پڑھیں۔ لوگ جمع ہو گئے تو انہیں دو رکعت نماز پڑھائی، پھر کھڑے ہو کر فرمایا اے لوگو! میں تمہیں ",""],["ٱللَّٰه","a"],[" کا واسطہ دے کر پوچھتا ہوں کہ میں تو اپنی سمجھ کے مطابق ہر کام کی سب سے بہتر صورت اختیار کرتا ہوں، تو کیا آپ لوگوں کے خیال میں میں نے کوئی ایسا کام کیا ہے جو بہتر نہ ہو بلکہ دوسرا کام اس سے بہتر ہو؟ لوگوں نے کہا نہیں۔ پھر حضرت عمرؓ نے فرمایا لیکن بلال بن حارث تو یہ اور یہ کہہ رہے ہیں (حضرت عمرؓ حضورؐ کے فرمان کا مطلب نہ سمجھ سکے لیکن لوگ سمجھ گئے)۔ لوگوں نے کہا حضرت بلالؓ ٹھیک کہہ رہے ہیں، آپ ",""],["ٱللَّٰه","a"],[" سے بھی مدد مانگیں اور (مصر، شام، عراق کے) مسلمانوں سے بھی مدد مانگیں۔ چنانچہ مسلمانوں سے غلہ منگوانے کی طرف حضرت عمرؓ کی توجہ نہ تھی، اب ہو گئی اور انہیں اس سلسلہ میں خط بھیجے۔ بہرحال لوگوں کی بات سن کر حضرت عمرؓ نے خوش ہو کر فرمایا ",""],["ٱللَّٰه","a"],[" اکبر، قحط کی آزمائش اپنے خاتمہ پر پہنچ گئی۔ حضرت عمرؓ پر یہ حقیقت کھلی کہ جس قوم کو ",""],["ٱللَّٰه","a"],[" سے مانگنے کی توفیق مل جاتی ہے اس کی آزمائش ختم ہو جاتی ہے۔ چنانچہ حضرت عمرؓ نے تمام شہروں کے گورنروں کو یہ خط لکھا کہ مدینہ اور اس کے آس پاس کے لوگ سخت قحط کی مصیبت میں ہیں، لہٰذا ان کی مدد کرو۔ اور لوگوں کو نماز استسقاء کے لیے شہر سے باہر لے گئے اور حضرت عباسؓ کو بھی ساتھ لے گئے اور پیدل تشریف لے گئے۔ پہلے مختصر بیان کیا پھر نماز پڑھائی، پھر گھٹنوں کے بل بیٹھ کر یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! ہم تیری ہی عبادت کرتے ہیں اور تجھ سے ہی مدد مانگتے ہیں۔ اے ",""],["ٱللَّٰه","a"],["! ہماری مغفرت فرما اور ہم پر رحم فرما اور ہم سے راضی ہو جا۔ پھر وہاں سے واپس آئے تو زوردار بارش شروع ہو گئی اور راستے کے تمام گڑھے اور چھوٹے تالاب بارش کے پانی سے بھر گئے اور ان سب میں سے گزر کر یہ لوگ اپنے گھروں کو پہنچ سکے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Jareer in his Taareekh (Vol.3 Pg.192), in whose chain is Sayf."]]},{"b":[["n",[["تاریخ طبری میں ہی حضرت عاصم بن عمر بن خطابؒ سے بھی یہ قصہ منقول ہے، اس میں یہ بھی ہے کہ قبیلہ مزینہ کا ایک گھرانہ دیہات میں رہتا تھا، انہوں نے اپنے گھر والے سے کہا فاقہ کی انتہا ہو گئی ہے، ہمارے لیے ایک بکری ذبح کر دو۔ اس نے کہا ان بکریوں میں کچھ نہیں ہے لیکن گھر والے اصرار کرتے رہے، آخر اس نے ایک بکری ذبح کی اور اس کی کھال اتاری تو صرف سرخ ہڈی تھی، گوشت کا نام و نشان نہیں تھا، تو اس کی ایک دم چیخ نکلی ہائے محمد علیہ السلام! (اگر وہ ہوتے تو ایسا نہ ہوتا)۔ پھر اس نے خواب دیکھا کہ حضورؐ اس کے پاس تشریف لائے ہیں اور فرما رہے ہیں تمہیں بارش کی خوشخبری ہو، جا کر عمر کو میرا سلام کہو اور ان سے کہو اے عمر! میں نے تو یہی دیکھا ہے کہ تم عہد کے پورا کرنے والے اور بات کے پکے تھے، اب تمہیں کیا ہو گیا ہے؟ لہٰذا عقلمندی اختیار کرو۔ وہ صاحب دیہات سے چلے اور حضرت عمرؓ کے دروازے پر پہنچے اور حضرت عمرؓ کے غلام سے کہا ",""],["ٱللَّٰه","a"],[" کے رسولؐ کے قاصد کو اندر جانے کی اجازت دو۔ پھر آگے پچھلی حدیث جیسی ذکر کی۔",""]]]],"f":[]},{"b":[["n",[["حضرت سلیم بن عامر خبائریؒ","b"],[" کہتے ہیں ایک دفعہ بارشیں بند ہو گئیں تو حضرت معاویہ بن ابی سفیانؓ اور دمشق والے نماز استسقاء کے لیے شہر سے باہر گئے۔ جب حضرت معاویہؓ منبر پر بیٹھ گئے تو فرمایا حضرت یزید بن اسود جرشیؒ کہاں ہیں؟ اس پر لوگوں نے انہیں زور سے پکارا تو وہ پھلانگتے ہوئے آئے اور حضرت معاویہؓ کے فرمانے پر ان کے قدموں کے پاس منبر پر بیٹھ گئے۔ حضرت معاویہؓ نے یوں دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! آج ہم تیرے سامنے اپنے سب سے بہترین اور سب سے افضل آدمی کو سفارشی بنا کر لائے ہیں۔ اے ",""],["ٱللَّٰه","a"],["! ہم یزید بن اسود جرشی کو سفارشی بنا کر لائے ہیں۔ اے یزید! اپنے دونوں ہاتھ ",""],["ٱللَّٰه","a"],[" کے سامنے اٹھاؤ۔ چنانچہ حضرت یزیدؒ نے اپنے ہاتھ اٹھائے اور لوگوں نے بھی اٹھائے تو تھوڑی ہی دیر میں مغرب کی طرف زور سے بادل آ گئے اور ہوا انہیں جلدی سے ہمارے اوپر لے آئی اور بارش شروع ہو گئی اور اتنی زیادہ ہوئی کہ لوگوں کو اپنے گھر پہنچنا مشکل ہو گیا۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Sa'd (Vol.7 Pg.444)."]]},{"b":[["n",[["حضرت ثمامہ بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں ایک دفعہ گرمی کے زمانے میں حضرت انسؓ کے باغ کے مالی نے آ کر ان سے بارش کے نہ ہونے اور زمین کے پیاسی ہونے کی شکایت کی۔ حضرت انسؓ نے پانی منگوا کر وضو کیا اور نماز پڑھی، پھر اس سے کہا کیا آسمان میں تمہیں کچھ بادل نظر آ رہا ہے؟ اس نے کہا مجھے تو کچھ نظر نہیں آ رہا۔ حضرت انسؓ اندر گئے اور پھر نماز پڑھی۔ پھر تیسری یا چوتھی دفعہ میں فرمایا اب جا کر دیکھو۔ اس نے کہا پرندے کے پر کے برابر بادل نظر آ رہا ہے۔ حضرت انسؓ پھر نماز پڑھتے رہے اور دعا کرتے رہے یہاں تک کہ باغ کے منتظم نے اندر آ کر کہا سارے آسمان پر بادل چھائے ہوئے ہیں اور خوب بارش ہو چکی ہے۔ حضرت انسؓ نے اس سے کہا جو گھوڑا بشر بن شغاف نے بھیجا ہے اس پر سوار ہو کر جاؤ اور دیکھو کہاں تک بارش ہوئی ہے؟ وہ اس پر سوار ہو کر گیا اور دیکھ کر آیا اور بتایا کہ بارش مسیرین کے محلات سے آگے اور غضبان کے محلات سے آگے نہیں ہوئی۔ (یہاں حضرت انسؓ کی زمین ختم ہو جاتی ہے) طبقات ابن سعد میں یہی روایت حضرت ثابت بنانی سے ذرا مختصر منقول ہے اور اس میں یہ ہے کہ حضرت انس بن مالکؓ کی زمین کے منتظم نے حضرت انسؓ سے بارش نہ ہونے اور زمین کے پیاسا ہونے کی شکایت کی۔ اس روایت کے آخر میں یہ بھی ہے کہ اس منتظم نے جا کر دیکھا تو بارش صرف ان کی زمین پر ہی ہوئی تھی، آگے نہیں ہوئی تھی۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Sa'd (Vol.7 Pg.21)."]]},{"b":[["n",[["حضرت حجر بن عدیؓ","b"],[" کو ایک مرتبہ (حضرت معاویہؓ کی قید میں) نہانے کی حاجت ہو گئی۔ جو آدمی ان کی نگرانی کے لیے مقرر تھا اس سے انہوں نے کہا پینے والا پانی مجھے دے دو تاکہ میں اس سے غسل کر لوں اور کل مجھے پینے کے لیے کچھ نہ دینا۔ اس نے کہا مجھے ڈر ہے کہ آپ پیاس سے مر جائیں گے تو حضرت معاویہؓ مجھے قتل کر دیں گے۔ انہوں نے ",""],["ٱللَّٰه","a"],[" سے پانی کے لیے دعا مانگی۔ فوراً ایک بادل آیا جس سے بارش برسنے لگی۔ انہوں نے اپنی ضرورت کے مطابق اس میں سے پانی لیا۔ پھر اس کے ساتھیوں نے ان سے کہا آپ ",""],["ٱللَّٰه","a"],[" سے دعا کریں کہ وہ ہمیں قید سے خلاصی دے دے۔ انہوں نے یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! جو ہمارے لیے خیر ہو اسے مقدر فرما (قید سے خلاصی یا شہادت)۔ چنانچہ انہیں اور ان کے ساتھیوں میں سے ایک جماعت کو شہید کر دیا گیا۔",""],[" (10)","s"]]]],"f":[["(10)","Ibraheem bin Junayd in Kitaabul Awliyaa, as quoted in Isaabah (Vol.1 Pg.315)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں انصار کے ایک قبیلہ کو حضورؐ کی یہ دعا حاصل تھی کہ جب بھی ان میں سے کوئی مرے گا تو اس کی قبر پر بادل آ کر ضرور برسے گا۔ ایک دفعہ اس قبیلہ کے ایک آزاد کردہ غلام کا انتقال ہوا تو مسلمانوں نے کہا آج ہم حضورؐ کے اس فرمان کو بھی دیکھ لیں گے کہ قوم کا آزاد کردہ غلام قوم والوں میں سے ہی شمار ہوتا ہے۔ چنانچہ جب اس غلام کو دفن کر دیا گیا تو ایک بادل آ کر اس کی قبر پر برسا۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.136)."]]}]},"258":{"lead":[],"stories":[{"b":[["n",[["حضرت عثمان بن قاسمؒ","b"],[" کہتے ہیں حضرت ام ایمنؓ نے ہجرت کی تو روحا سے پہلے ہی منصرف مقام پر انہیں شام ہو گئی۔ یہ روزے سے تھیں اور ان کے پاس پانی بھی نہیں تھا اور پیاس کے مارے ان کا برا حال تھا تو آسمان سے سفید رسی سے بندھا ہوا پانی کا ایک ڈول آیا۔ حضرت ام ایمنؓ نے وہ ڈول لے کر اس میں سے خوب پانی پیا یہاں تک کہ اچھی طرح سیراب ہو گئیں۔ وہ فرمایا کرتی تھیں اس کے بعد مجھے کبھی پیاس نہیں لگی، حالانکہ میں سخت گرمیوں میں روزہ رکھا کرتی تھی تاکہ مجھے پیاس لگے لیکن پھر بھی پیاس نہیں لگتی تھی۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.8 Pg.224)."]]}]},"259":{"lead":[],"stories":[{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں عصر کا وقت ہو گیا تو لوگوں نے وضو کے لیے پانی تلاش کیا لیکن پانی بالکل نہ ملا۔ میں نے دیکھا حضورؐ کے پاس وضو کا تھوڑا سا پانی لایا گیا۔ حضورؐ نے اس پانی میں اپنا ہاتھ رکھ دیا اور لوگوں سے فرمایا کہ وہ اس برتن سے پانی لے کر وضو کریں۔ میں نے دیکھا کہ حضورؐ کی انگلیوں کے نیچے سے پانی پھوٹ رہا تھا اور اس تھوڑے سے پانی سے تمام لوگوں نے وضو کر لیا۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari, Muslim, Tirmidhi, Nasa'ee and Ahmad."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں نماز کے لیے اذان ہوئی تو جن کے گھر مسجد سے قریب تھے وہ اٹھ کر اپنے گھر وضو کرنے چلے گئے اور جن کے گھر مسجد سے دور تھے وہ مسجد میں باقی رہ گئے۔ حضورؐ کے پاس پتھر کا ایک پیالہ لایا گیا، وہ اتنا چھوٹا تھا کہ اس میں حضورؐ کا ہاتھ پھیل کر نہیں آ سکتا تھا۔ آخر حضورؐ نے انگلیاں سمیٹ کر اس میں ہاتھ ڈالا (تو ان میں سے پانی نکلنے لگا اور) جتنے آدمی باقی رہ گئے تھے ان سب نے اس پانی سے وضو کر لیا۔ حضرت حمید راوی کہتے ہیں کہ حضرت انسؓ سے پوچھا گیا کہ یہ وضو کرنے والے کتنے تھے؟ فرمایا اسی یا اس سے بھی زیادہ تھے۔ یہ روایت بخاری میں ہے۔ بخاری میں اس جیسی ایک اور روایت بھی ہے، ایک اور روایت میں اس طرح ہے کہ حضرت انسؓ نے فرمایا حضورؐ مدینہ میں زوراء نامی جگہ میں تھے، وہاں آپؐ کے پاس ایک برتن لایا گیا۔ آپؐ نے اس برتن میں اپنا ہاتھ رکھا تو پانی آپؐ کی انگلیوں کے درمیان میں سے پھوٹنے لگا جس سے سب نے وضو کر لیا۔ حضرت قتادہ کہتے ہیں میں نے حضرت انسؓ سے پوچھا آپ لوگ کتنے تھے؟ انہوں نے فرمایا تین سو یا تین سو کے قریب۔",""],[" (2)","s"]]]],"f":[["(2)","Bukhaari, Muslim and Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.93). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.145), as has Ibn Sa'd (Vol.1 Pg.178)."]]},{"b":[["n",[["حضرت براء بن عازبؓ","b"],[" فرماتے ہیں صلح حدیبیہ کے موقع پر ہم لوگ چودہ سو تھے۔ حدیبیہ ایک کنواں ہے، ہم نے اس میں سے پانی نکالا اور اتنا نکالا کہ اس میں ایک قطرہ پانی نہ بچا۔ حضورؐ (کو پتہ چلا کہ کنویں میں پانی بالکل ختم ہو گیا ہے تو آپؐ) اس کنویں کے ایک کنارے پر بیٹھ گئے اور پانی منگوا کر اس سے کلی کی اور کلی کا پانی کنویں میں پھینک دیا تو تھوڑی ہی دیر میں کنواں پانی سے بھر گیا۔ ہم نے خود بھی پیا اور اپنی سواریوں کو بھی پلایا یہاں تک کہ ہم بھی سیراب ہو گئے اور ہماری سواریاں بھی۔ جلد اول صفحہ 214 پر بخاری کے حوالہ سے صلح حدیبیہ کا یہ قصہ حضرت مسور اور حضرت مروان کی روایت سے گزر چکا ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Bukhaari, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.94). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.145). Muslim has reported a similar narration from Hadhrat Salamah bin Akwa, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.97), as has Ibn Sa'd (Vol.1 Pg.179)."]]},{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں صلح حدیبیہ کے دن لوگوں کو پیاس لگی اور حضورؐ کے سامنے ایک پیالہ رکھا ہوا تھا جس سے آپؐ وضو فرما رہے تھے۔ لوگ رونی صورت بنا کر حضورؐ کے پاس آئے۔ حضورؐ نے پوچھا آپ لوگوں کو کیا ہوا؟ لوگوں نے عرض کیا نہ وضو کے لیے پانی ہے اور نہ پینے کے لیے، صرف یہی پانی ہے جو آپؐ کے سامنے ہے۔ حضورؐ نے اس پیالہ میں اپنا ہاتھ رکھا تو چشمہ کی طرح حضورؐ کی انگلیوں کے درمیان سے پانی ابلنے لگا۔ چنانچہ ہم نے وہ پانی پیا بھی اور اس سے وضو بھی کیا۔ راوی کہتے ہیں میں نے پوچھا آپ لوگ کتنے تھے؟ حضرت جابرؓ نے فرمایا ہم تھے تو پندرہ سو لیکن اگر ہم ایک لاکھ بھی ہوتے تو وہ پانی ہمیں کافی ہو جاتا۔",""],[" (4)","s"]]]],"f":[["(4)","Bukhaari and Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.96). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.144), and Ibn Sa'd in his Tabaqaat (Vol.2 Pg.98)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں ہم حضورؐ کے ساتھ ایک سفر میں تھے کہ اتنے میں نماز کا وقت ہوا اور ہمارے پاس تھوڑا سا پانی تھا۔ حضورؐ نے پانی منگوا کر ایک پیالہ میں ڈالا، پھر حضورؐ نے اس پیالہ میں اپنا ہاتھ ڈالا تو حضورؐ کی انگلیوں کے درمیان میں سے پانی پھوٹنے لگا۔ پھر حضورؐ نے اعلان فرمایا غور سے سنو! آؤ وضو کر لو اور ",""],["ٱللَّٰه","a"],[" کی طرف سے آئی ہوئی برکت حاصل کر لو۔ لوگ آ کر وضو کرنے لگے اور میں لوگوں سے آگے بڑھ بڑھ کر وہ پانی پینے لگا کیونکہ حضورؐ نے فرمایا تھا ",""],["ٱللَّٰه","a"],[" کی طرف سے آئی ہوئی برکت حاصل کر لو۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Dalaa'il (Pg.144). Bukhaari has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.97)."]]},{"b":[["n",[["حضرت ابوقتادہؓ","b"],[" فرماتے ہیں ہم ایک سفر میں حضورؐ کے ساتھ تھے۔ حضورؐ نے پوچھا کیا تمہارے پاس پانی ہے؟ میں نے کہا جی ہاں، میرے پاس وضو کا برتن ہے جس میں تھوڑا سا پانی ہے۔ حضورؐ نے فرمایا اسے لاؤ۔ میں وہ برتن حضورؐ کی خدمت میں لے گیا۔ حضورؐ نے فرمایا اس میں سے تھوڑا تھوڑا پانی لے لو۔ پھر حضورؐ نے وضو فرمایا، پھر اس برتن میں ایک گھونٹ پانی بچ گیا۔ حضورؐ نے فرمایا اے ابوقتادہ! اسے سنبھال کر رکھو، عنقریب اس پانی کے ساتھ عجیب و غریب واقعہ پیش آئے گا۔ جب دوپہر کو گرمی سخت ہوئی تو حضورؐ اٹھے اور حضورؐ پر لوگوں کی نظر پڑی۔ لوگوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہم تو پیاس کے مارے ہلاک ہو گئے، ہماری گردنیں ٹوٹ گئیں۔ حضورؐ نے فرمایا نہیں، تم ہلاک نہیں ہو سکتے۔ پھر فرمایا اے ابوقتادہ! وہ وضو کا برتن لے آؤ۔ میں برتن حضورؐ کی خدمت میں لے آیا۔ حضورؐ نے فرمایا میرا پیالہ کھول کر لے آؤ، میں کھول کر لے آیا۔ حضورؐ برتن میں سے اس پیالے میں ڈال کر لوگوں کو پلانے لگے اور حضورؐ کے اردگرد لوگوں کی بہت زیادہ بھیڑ ہو گئی۔ آپؐ نے فرمایا اے لوگو! اچھے اخلاق اختیار کرو (ایک دوسرے کو دھکے مت مارو)، تم میں سے ہر ایک سیراب ہو کر ہی واپس جائے گا۔ چنانچہ سب نے پانی پی لیا، میرے اور حضورؐ کے علاوہ اور کوئی نہ بچا۔ آپؐ نے میرے لیے پانی ڈال کر فرمایا اے ابوقتادہ! تم بھی پی لو۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نوش فرمائیں۔ آپؐ نے فرمایا نہیں، لوگوں کو جو پلاتا ہے وہ سب سے آخر میں پیتا ہے۔ چنانچہ پہلے میں نے پیا، پھر میرے بعد حضورؐ نے پیا اور وضو کے برتن میں اتنا پانی بچا ہوا تھا جتنا پہلے تھا اور ان پینے والوں کی تعداد تین سو تھی۔ ابراہیم بن حجاج راوی کی حدیث میں یہ ہے کہ پینے والے سات سو تھے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Dalaa'il (Pg.144). Ahmad and Muslim have reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.98)."]]},{"b":[["n",[["مسلم میں غزوۂ تبوک کے بارے میں ",""],["حضرت معاذ بن جبلؓ","b"],[" کی حدیث منقول ہے جس میں پہلے تو دو نماز کو جمع کرنے کا ذکر ہے، اس کے بعد یہ ہے کہ پھر حضورؐ نے فرمایا انشاء ",""],["ٱللَّٰه","a"],[" کل تم لوگ تبوک کے چشمے پر پہنچ جاؤ گے اور وہاں تک پہنچتے پہنچتے چاشت کا وقت ہو ہی جائے گا۔ تم میں سے جو بھی اس چشمہ پر پہنچ جائے وہ میرے آنے تک اس کے پانی کو ہاتھ بالکل نہ لگائے۔ چنانچہ جب ہم چشمہ پر پہنچے تو ہم سے پہلے دو آدمی وہاں پہنچے ہوئے تھے اور چشمہ سے جوتے کے تسمہ کی طرح تھوڑا تھوڑا پانی بہہ رہا تھا۔ حضورؐ نے ان دونوں سے پوچھا کیا تم دونوں نے اس چشمے کے پانی کو ہاتھ لگایا ہے؟ انہوں نے کہا جی ہاں لگایا ہے۔ اس پر آپؐ نے ان دونوں کو کچھ برا بھلا کہا۔ پھر (حضورؐ کے فرمانے پر) لوگوں نے چلوؤں سے تھوڑا تھوڑا پانی ایک برتن میں جمع کیا۔ پھر حضورؐ نے اس برتن میں اپنا چہرہ اور ہاتھ دھوئے، پھر وہ پانی اس چشمے میں ڈال دیا۔ پانی ڈالتے ہی اس چشمہ میں سے زور و شور سے بہت زیادہ پانی بہنے لگا جسے پی کر سب لوگ سیراب ہو گئے۔ پھر حضورؐ نے فرمایا اے معاذ! اگر تمہاری زندگی لمبی ہوئی تو تم دیکھو گے کہ یہ ساری جگہ باغوں سے بھری ہوئی ہوگی۔",""],[" (7)","s"]]]],"f":[["(7)","Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.100)."]]},{"b":[["n",[["حضرت عمران بن حصینؓ","b"],[" فرماتے ہیں صحابہ کرامؓ حضورؐ کے ساتھ ایک سفر میں تھے، پھر آگے اور حدیث ذکر کی۔ اس کے بعد حضرت عمرانؓ فرماتے ہیں کہ ہمیں بہت زیادہ پیاس لگی، ہم حضورؐ کے ساتھ جا رہے تھے کہ اتنے میں ہمیں ایک عورت ملی جو دو بڑی مشکوں کے درمیان پاؤں لٹکائے ہوئے اونٹنی پر بیٹھی ہوئی تھی۔ ہم نے اس سے پوچھا پانی کہاں ہے؟ اس نے کہا یہاں تو کہیں پانی نہیں ہے۔ ہم نے اس سے کہا تمہارے گھر سے پانی کتنے فاصلے پر ہے؟ اس نے کہا ایک دن ایک رات کی مسافت پر ہے۔ ہم نے کہا ",""],["ٱللَّٰه","a"],[" کے رسولؐ کے پاس چلو۔ اس نے کہا ",""],["ٱللَّٰه","a"],[" کے رسول کون ہوتے ہیں؟ ہم نے اسے نہ کچھ کرنے دیا، نہ بولنے دیا اور نہ بھاگنے دیا بلکہ اس پر قابو پا کر حضورؐ کی خدمت میں لے آئے۔ اس نے حضورؐ کے سامنے بھی ویسی باتیں کیں جیسی ہمارے سامنے کی تھیں، البتہ اس نے یہ بھی حضورؐ کو بتایا کہ اس کے بچے یتیم ہیں۔ حضورؐ کے فرمانے پر اس کی دونوں بڑی مشکیں ہم حضورؐ کی خدمت میں لے آئے۔ حضورؐ نے ان مشکوں کے منہ پر دستِ مبارک پھیرا۔ ہم چالیس آدمی تھے اور سخت پیاسے تھے، پہلے تو ان مشکوں سے ہم سب نے خوب سیر ہو کر پیا، پھر ہمارے ساتھ جتنے مشکیزے اور برتن تھے وہ سب بھر لیے اور اتنے زیادہ بھرے کہ بالکل پھٹنے والے ہو گئے تھے۔ پھر حضورؐ نے فرمایا جو کچھ تم لوگوں کے پاس ہے وہ لے آؤ۔ چنانچہ ہم نے روٹی کے ٹکڑے اور کھجوریں جمع کر کے اس عورت کو دے دیں۔ پھر وہ عورت اپنے گھر والوں کے پاس گئی اور انہیں بتایا کہ میں یا تو سب سے بڑے جادوگر سے مل کر آئی ہوں یا پھر وہ سچ مچ نبی ہیں جیسے کہ ان کے ساتھی کہہ رہے تھے۔ چنانچہ اس عورت کے ذریعہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس ڈیرے والوں کو ہدایت عطا فرمائی اور وہ عورت بھی مسلمان ہو گئی اور ڈیرے والے بھی مسلمان ہو گئے۔ اس حدیث کو بخاری اور مسلم دونوں نے ذکر کیا ہے۔ ان دونوں کی دوسری حدیث میں یہ ہے کہ حضورؐ نے اس عورت سے فرمایا یہ کھانے کا سامان اپنے ساتھ اپنے بچوں کے لیے لے جاؤ اور تمہیں معلوم ہونا چاہیے کہ ہم نے تمہارے پانی میں سے کچھ نہیں لیا، ہمیں تو یہ سارا پانی ",""],["ٱللَّٰه","a"],[" نے اپنے غیبی خزانے سے پلایا ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Bukhaari and Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.98). Abu Nu'aym has reported a similar narration in detail in his Dalaa'il (Pg.146)."]]},{"b":[["n",[["حضرت زیاد بن حارث صدائیؓ","b"],[" فرماتے ہیں میں حضورؐ کے ساتھ ایک سفر میں تھا۔ آپؐ نے پوچھا کیا تمہارے پاس پانی ہے؟ میں نے کہا ہے لیکن تھوڑا ہے، آپؐ کو کافی نہیں ہوگا۔ حضورؐ نے فرمایا کسی برتن میں ڈال کر میرے پاس لے آؤ۔ میں آپؐ کی خدمت میں لے آیا۔ آپؐ نے اپنا دستِ مبارک اس میں رکھا تو میں نے دیکھا کہ حضورؐ کی ہر دو انگلیوں کے درمیان میں سے پانی پھوٹ رہا ہے۔ حضورؐ نے فرمایا اگر مجھے اپنے رب سے حیا نہ آتی تو ہم یوں ہی پانی پیتے پلاتے رہتے (کیونکہ یوں جسم سے پانی نکلنے میں شانِ ربوبیت کا شائبہ ہے، اس لیے اس معجزہ کا تھوڑی دیر کے لیے ہونا ہی مناسب ہے)۔ جاؤ اور جا کر میرے صحابہؓ میں اعلان کر دو کہ جو بھی پانی لینا چاہتا ہے وہ جتنا چاہے آ کر چلو بھر بھر کر لے لے۔ حضرت زیادؓ کہتے ہیں میری قوم کا ایک وفد مسلمان ہو کر فرمانبردار بن کر حضورؐ کی خدمت میں آیا۔ وفد کے ایک آدمی نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہمارا ایک کنواں ہے، سردیوں میں تو وہ ہمیں کافی ہو جاتا ہے، اس لیے سردیوں میں تو ہم اس کنویں کے پاس جمع ہو جاتے ہیں اور گرمیوں میں اس کا پانی کم ہو جاتا ہے تو پھر ہم اپنے اردگرد کے چشموں پر بکھر جاتے ہیں لیکن اب ہم بکھر نہیں سکتے کیونکہ ہمارے اردگرد کے تمام لوگ (اسلام لانے کی وجہ سے) ہمارے دشمن ہو گئے ہیں۔ آپ ",""],["ٱللَّٰه","a"],[" سے دعا کریں کہ اس کا پانی ہمیں گرمیوں میں بھی کافی ہو جایا کرے۔ حضورؐ نے سات کنکریاں منگوائیں اور ان کو اپنے ہاتھ پر الگ الگ رکھ کر دعا کی، پھر فرمایا جب تم لوگ کنویں کے پاس پہنچو تو کنکریاں ایک ایک کر کے اس میں ڈال دو اور ان پر ",""],["ٱللَّٰه","a"],[" کا نام لیتے رہو۔ چنانچہ واپس جا کر انہوں نے ایسے ہی کیا تو ",""],["ٱللَّٰه","a"],[" نے اس کنویں کا پانی اتنا زیادہ کر دیا کہ پھر انہیں اس کنویں کی گہرائی کبھی نظر نہیں آئی۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Dalaa'il (Pg.147). Bayhaqi, Ahmad, Abu Dawood, Tirmidhi and Ibn Maajah have all reported similar narrations, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.101)."]]},{"b":[["n",[["حضرت ابوعونؒ","b"],[" کہتے ہیں جب حضرت حسین بن علیؓ مکہ کے ارادے سے مدینہ سے نکلے تو وہ ابن مطیع کے پاس سے گزرے جو اپنا کنواں کھود رہے تھے، آگے اور حدیث ذکر کی ہے جس میں یہ بھی ہے کہ ابن مطیع نے ان سے کہا میں نے اپنے اس کنویں کو اس لیے ٹھیک کیا ہے تاکہ اس میں دوبارہ پانی آ جائے لیکن ابھی تک ڈول خالی ہی نکلا ہے، اس میں کچھ پانی نہیں آیا۔ اگر آپ ہمارے لیے اس کنویں میں ",""],["ٱللَّٰه","a"],[" سے برکت کی دعا کر دیں تو آپ کی بہت مہربانی ہوگی۔ حضرت حسینؓ نے فرمایا کنویں کا تھوڑا سا پانی لاؤ۔ ابن مطیع ڈول میں اس کنویں کا تھوڑا سا پانی لائے۔ حضرت حسینؓ نے اس میں سے کچھ پانی پیا، پھر کلی کی، پھر وہ پانی اسی کنویں میں ڈال دیا تو اس کنویں کا پانی میٹھا بھی ہو گیا اور زیادہ بھی ہو گیا۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Sa'd (Vol.5 Pg.144)."]]}]},"260":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوعمرہ انصاریؓ","b"],[" فرماتے ہیں ہم ایک غزوے میں حضورؐ کے ساتھ تھے۔ لوگوں کو سخت بھوک لگی تو لوگوں نے حضورؐ سے کچھ اونٹ ذبح کرنے کی اجازت لی اور عرض کیا یہ گوشت کھانے سے ",""],["ٱللَّٰه","a"],[" ہمیں اتنی طاقت دے دیں گے جس سے ہم منزل تک پہنچ جائیں گے۔ حضرت عمر بن خطابؓ نے دیکھا کہ حضورؐ نے کچھ اونٹ ذبح کرنے کی اجازت دینے کا ارادہ کر لیا ہے تو عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کل جب ہم بھوکے اور پیدل دشمن کا مقابلہ کریں گے تو ہمارا کیا حال ہوگا؟ اس لیے میری رائے یہ ہے کہ اگر آپ مناسب سمجھیں تو لوگوں کے پاس جو توشے بچے ہوئے ہیں وہ منگوا کر جمع کر لیں اور پھر ",""],["ٱللَّٰه","a"],[" سے اس میں برکت کی دعا کریں۔ ",""],["ٱللَّٰه","a"],[" آپ کی دعا کی برکت سے کھانے میں برکت بھی دے دیں گے اور منزل تک بھی پہنچا دیں گے۔ چنانچہ حضورؐ نے لوگوں سے ان کے بچے ہوئے توشے منگوائے تو لوگ لانے لگے، کوئی مٹھی بھر کھانے کی چیز لایا، کوئی اس سے زیادہ۔ سب سے زیادہ ایک آدمی ساڑھے تین سیر کھجور لایا۔ حضورؐ نے ان تمام چیزوں کو جمع کیا، پھر کھڑے ہو کر کچھ دیر دعا کی، پھر لشکر والوں سے فرمایا اپنے اپنے برتن لے آؤ اور اس میں سے لپیں بھر کر برتنوں میں ڈال لو۔ چنانچہ لشکر والوں نے اپنے تمام برتن بھر لیے اور کھانے کا جتنا سامان پہلے تھا اتنا پھر بچ گیا۔ اسے دیکھ کر حضورؐ اتنا ہنسے کہ دندانِ مبارک نظر آنے لگے۔ آپؐ نے فرمایا میں اس بات کی گواہی دیتا ہوں کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور میں اس بات کی گواہی دیتا ہوں کہ میں ",""],["ٱللَّٰه","a"],[" کا رسول ہوں۔ جو بندہ ان دونوں گواہیوں پر ایمان رکھتا ہوگا وہ قیامت کے دن ",""],["ٱللَّٰه","a"],[" سے اس حال میں ملے گا کہ جہنم کے اس سے دور رہنے کا فیصلہ ہو چکا ہوگا۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad. Nasa'ee has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.114), as has Ibn Sa'd (Vol.1 Pg.180). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.148) from Hadhrat Abu Hurayrah and Hadhrat Jaabir, as have Muslim, Ahmad and Nasa'ee, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.113)."]]},{"b":[["n",[["حضرت ابوخنیس غفاریؓ","b"],[" فرماتے ہیں میں غزوۂ تہامہ میں حضورؐ کے ساتھ تھا۔ جب ہم عسفان پہنچے تو صحابہؓ حضورؐ کے پاس آئے، آگے پچھلی حدیث جیسا مضمون ذکر کیا لیکن حضورؐ کے ہنسنے سے لے کر آخر تک کا مضمون ذکر نہیں کیا، بلکہ ذکر کیا ہے کہ پھر حضورؐ نے وہاں سے کوچ کا حکم دیا۔ جب عسفان سے آگے چلے گئے تو پھر بارش ہوئی اور حضورؐ اور صحابہؓ نیچے اترے اور سب نے بارش کا پانی پیا۔",""],[" (2)","s"]]]],"f":[["(2)","Bazzaar and Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.114). Tabraani has reported a similar narration in his Awsat, as quoted in Majma'uz Zawaa'id (Vol.8 Pg.303), as has Haakim, as quoted in Isaabah (Vol.4 Pg.53)."]]},{"b":[["n",[["حضرت ابوہریرہؓ اور حضرت ابوسعیدؓ","b"],[" فرماتے ہیں غزوۂ تبوک کے سفر میں لوگوں کو سخت بھوک لگی تو صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! اگر آپ ہمیں اجازت دیں تو ہم اپنے اونٹ ذبح کر کے ان کا گوشت کھا لیں اور ان کی چربی کا تیل استعمال کر لیں۔ حضورؐ نے فرمایا کر لو۔ اس پر حضرت عمرؓ حضورؐ کی خدمت میں حاضر ہوئے، پھر آگے حضرت ابوعمرہؓ جیسی حدیث ذکر کی۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Dalaa'il (Pg.149). Muslim and others have reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.114)."]]},{"b":[["n",[["حضرت سلمہؓ","b"],[" فرماتے ہیں ہم لوگ غزوۂ خیبر میں حضورؐ کے ساتھ تھے۔ ہمارے توشوں میں جتنی کھجوریں تھیں حضورؐ نے ہمیں انہیں جمع کرنے کا حکم دیا اور چمڑے کا ایک دسترخوان بچھا دیا۔ ہم نے اپنے توشوں کی کھجوریں لا کر اس پر پھیلا دیں۔ پھر میں نے انگڑائی لی اور (مجمع کی زیادتی کی وجہ سے) لمبے ہو کر دیکھا اور اندازہ لگایا تو بیٹھی ہوئی بکری جتنا ڈھیر تھا۔ ہم چودہ سو آدمی تھے، ہم نے وہ کھجوریں کھائیں، پھر میں نے لمبے ہو کر دیکھا تو اب بھی بیٹھی ہوئی بکری جتنا ڈھیر تھا۔ اس کے بعد پانی میں برکت کا قصہ ذکر کیا۔ ایک روایت میں ہے کہ ہم نے اتنی کھجوریں کھائیں کہ ہم سیر ہو گئے اور پھر اپنے چمڑے کے تمام تھیلے کھجوروں سے بھر لیے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Ya'la. Muslim has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.115)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ نے خندق کھودی اور آپؐ کے صحابہؓ نے بھوک کی وجہ سے اپنے پیٹ پر پتھر باندھے ہوئے تھے۔ جب حضورؐ نے یہ حالت دیکھی تو فرمایا کیا تمہیں ایسا آدمی معلوم ہے جو ہمیں ایک وقت کا کھانا کھلا دے؟ ایک آدمی نے کہا جی ہاں، میں جانتا ہوں۔ حضورؐ نے فرمایا اگر اس کے علاوہ اور کوئی صورت نہیں ہے تو پھر تم آگے بڑھو اور اس آدمی کے گھر چلو۔ چنانچہ یہ حضرات اس آدمی کے گھر تشریف لے گئے تو گھر والا وہاں گھر میں نہیں تھا بلکہ وہ اپنے حصے کی خندق کھود رہا تھا۔ اس کی بیوی نے پیغام بھیجا کہ جلدی سے آؤ کیونکہ حضورؐ ہمارے ہاں تشریف لائے ہیں۔ وہ آدمی دوڑتا ہوا آیا اور کہنے لگا آپ پر میرے ماں باپ قربان ہوں۔ اس آدمی کی ایک بکری تھی جس کا ایک بچہ بھی تھا۔ وہ آدمی (ذبح کرنے کے لیے) بکری کی طرف جلدی سے بڑھا۔ حضورؐ نے فرمایا بکری کے بعد اس کے بچے کا کیا ہوگا؟ اس لیے بکری ذبح نہ کرو۔ چنانچہ اس نے بکری کا بچہ ذبح کیا اور اس کی بیوی نے تھوڑا سا آٹا لے کر گوندھا اور اس کی روٹی پکائی، اتنے میں ہنڈیا بھی تیار ہو گئی۔ اس کی بیوی نے پیالہ میں ثرید بنا کر حضورؐ اور حضورؐ کے ساتھیوں کے سامنے پیش کیا۔ حضورؐ نے اپنی انگلی اس ثرید میں رکھ کر فرمایا بسم ",""],["ٱللَّٰه","a"],["، اے ",""],["ٱللَّٰه","a"],["! اس میں برکت عطا فرما۔ (پھر ساتھیوں سے فرمایا) کھاؤ۔ چنانچہ صحابہؓ نے اس میں سے پیٹ بھر کر کھایا لیکن صرف ایک حصہ کھا سکے اور دو حصے پھر بھی بچ گئے۔ آپؐ کے ساتھ جو دس صحابیؓ تھے آپؐ نے ان سے فرمایا اب آپ لوگ جاؤ اور اپنے جتنے اور آدمی بھیج دو۔ چنانچہ وہ دس صحابیؓ چلے گئے اور دوسرے دس آ گئے اور انہوں نے بھی خوب سیر ہو کر کھایا۔ پھر آپؐ کھڑے ہوئے اور اس گھر والی عورت اور باقی تمام افراد کے لیے برکت کی دعا فرمائی۔ پھر یہ حضرات خندق کی طرف چل پڑے۔ آپؐ نے فرمایا ہمیں سلمانؓ کے پاس لے چلو۔ وہاں پہنچے تو دیکھا کہ حضرت سلمانؓ کے سامنے ایک سخت چٹان ہے جو ان سے ٹوٹ نہیں رہی۔ حضورؐ نے فرمایا چھوڑو، میں اسے سب سے پہلے توڑتا ہوں اور بسم ",""],["ٱللَّٰه","a"],[" پڑھ کر آپؐ نے اس چٹان پر زور سے کدال ماری جس سے اس کا ایک تہائی ٹکڑا ٹوٹ کر گر گیا۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" اکبر! رب کعبہ کی قسم! شام کے محلات فتح ہوں گے۔ آپؐ نے پھر زور سے کدال ماری تو ایک اور ٹکڑا ٹوٹ کر گر گیا۔ آپؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" اکبر! رب کعبہ کی قسم! فارس کے محلات فتح ہوں گے۔ اس پر منافقوں نے کہا ہمیں تو اپنی حفاظت کے لیے خندق کھودنی پڑ رہی ہے اور یہ ہم سے فارس اور روم کے محلات کے وعدے کر رہے ہیں۔ اور خرچ کرنے کے باب میں یہ حدیث گزر چکی ہے کہ حضرت جابرؓ نے ساڑھے تین سیر جو کے آٹے کی روٹی پکائی اور بکری کے بچے کو ذبح کر کے اس کا سالن بنایا اور حضورؐ کو کھانے کی دعوت دی۔ حضورؐ نے تمام خندق والوں کو کھانے پر بلایا جو کہ ہزار کے قریب تھے۔ سب نے پیٹ بھر کر کھا لیا اور کھانا پھر بھی سارے کا سارا ویسے ہی بچ گیا۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.100). Haythami (Vol.6 Pg.132) has commented on the chain of narrators."]]}]},"261":{"lead":[],"stories":[{"b":[["n",[["حضرت سمرہ بن جندبؓ","b"],[" فرماتے ہیں ہم لوگ حضورؐ کے پاس بیٹھے ہوئے تھے کہ اتنے میں حضورؐ کی خدمت میں ثرید کا ایک پیالہ پیش کیا گیا۔ حضورؐ نے بھی وہ ثرید کھایا اور لوگوں نے بھی کھایا اور تقریباً ظہر تک لوگ آ کر باری باری کھاتے رہے۔ کچھ لوگ کھا کر چلے جاتے، پھر کچھ لوگ اور آتے اور کھا کر چلے جاتے۔ ایک آدمی نے پوچھا کیا اس میں اور ثرید لا کر ڈالا جاتا تھا؟ حضرت سمرہؓ نے فرمایا زمین سے لا کر تو نہیں ڈالا جا رہا تھا، البتہ آسمان سے ضرور ڈالا جا رہا تھا۔ دوسری روایت میں یوں ہے کہ ایک آدمی نے پوچھا کیا اس میں اور ثرید لا کر ڈالا جا رہا تھا؟ حضرت سمرہؓ نے فرمایا پھر اس میں تعجب کی کیا بات ہوتی؟ پھر آسمان کی طرف اشارہ کر کے فرمایا صرف وہاں سے لا کر ڈالا جا رہا تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, Tirmidhi and Nasa'ee, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.112). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.153)."]]},{"b":[["n",[["حضرت واثلہ بن اسقعؓ","b"],[" فرماتے ہیں میں اصحابِ صفہ میں سے تھا۔ ایک دن حضورؐ نے مجھ سے روٹی کا ایک ٹکڑا منگوایا اور اس کے ٹکڑے کر کے ایک پیالے میں ڈالے اور اس میں گرم پانی ڈالا، پھر چربی ڈالی، پھر ان کو اچھی طرح ملایا، پھر ان کی ڈھیری بنا کر بیچ میں سے اونچا کر دیا۔ پھر فرمایا جاؤ اور اپنے سمیت دس آدمی میرے پاس بلا لاؤ۔ میں دس آدمی بلا لایا۔ آپؐ نے فرمایا کھاؤ لیکن نیچے سے کھانا، اوپر سے نہ کھانا کیونکہ برکت اوپر یعنی درمیان میں اترتی ہے۔ چنانچہ ان سب نے اس میں سے پیٹ بھر کر کھایا۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.8 Pg.305). Ibn Maajah has reported the end of the narration."]]},{"b":[["n",[["حضرت واثلہ بن اسقعؓ","b"],[" فرماتے ہیں میں اصحابِ صفہ میں سے تھا۔ میرے ساتھیوں نے بھوک کی شکایت کی اور مجھ سے کہا اے واثلہ! حضورؐ کی خدمت میں جاؤ اور ہمارے لیے کچھ کھانا مانگ لاؤ۔ میں نے حضورؐ کی خدمت میں جا کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے ساتھی بھوک کی شکایت کر رہے ہیں۔ حضورؐ نے حضرت عائشہؓ سے پوچھا کیا تمہارے پاس کچھ ہے؟ حضرت عائشہؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! اور تو کچھ نہیں، البتہ روٹی کے کچھ ریزے ہیں۔ آپؐ نے فرمایا وہی میرے پاس لے آؤ۔ حضرت عائشہؓ چمڑے کا برتن لے آئیں (جس میں روٹی کے ریزے تھے)۔ حضورؐ نے ایک پیالہ منگوا کر اس میں وہ ریزے ڈالے اور اپنے ہاتھ سے ثرید بنانی شروع کر دی تو وہ روٹی بڑھنے لگی یہاں تک کہ پیالہ بھر گیا۔ پھر حضورؐ نے فرمایا اے واثلہ! جاؤ اور اپنے ساتھیوں میں سے اپنے سمیت دس آدمی بلا لاؤ۔ میں گیا اور اپنے ساتھیوں میں سے اپنے سمیت دس آدمی بلا لایا۔ حضورؐ نے فرمایا بیٹھ جاؤ اور ",""],["ٱللَّٰه","a"],[" کا نام لے کر کھانا شروع کرو لیکن پیالے کے کناروں سے کھانا، اوپر سے نہیں یعنی درمیان میں سے نہ کھانا کیونکہ درمیان میں برکت اترتی ہے۔ چنانچہ ساتھیوں نے پیٹ بھر کر کھایا اور جب وہ اٹھے تو پیالہ میں ثرید اتنا ہی باقی تھا جتنا پہلے تھا۔ حضورؐ پھر اپنے ہاتھ سے ثرید بنانے لگے اور ثرید بڑھنے لگا یہاں تک کہ پیالہ بھر گیا۔ پھر آپؐ نے فرمایا اے واثلہ! جاؤ اور اپنے ساتھیوں میں سے دس آدمی لے آؤ۔ میں دس ساتھیوں کو لے آیا۔ آپؐ نے فرمایا بیٹھ جاؤ۔ وہ لوگ بیٹھ گئے اور خوب پیٹ بھر کر کھایا، پھر اٹھ کر چلے گئے۔ آپؐ نے فرمایا جاؤ اور اپنے دس ساتھی اور لے آؤ۔ میں جا کر دس ساتھی لے آیا۔ انہوں نے پیٹ بھر کر کھایا اور چلے گئے۔ آپؐ نے پوچھا کیا کوئی اور باقی رہ گیا ہے؟ میں نے کہا جی ہاں، دس ساتھی رہ گئے ہیں۔ آپؐ نے فرمایا جاؤ اور انہیں بھی لے آؤ۔ میں جا کر انہیں لے آیا۔ آپؐ نے فرمایا بیٹھ جاؤ۔ وہ بیٹھ گئے۔ انہوں نے بھی پیٹ بھر کر کھایا، پھر اٹھ کر چلے گئے اور پیالہ میں اتنا ثرید بچ گیا جتنا پہلے تھا۔ پھر آپؐ نے فرمایا اے واثلہ! یہ عائشہ کے پاس لے جاؤ۔ ایک روایت میں ہے کہ میں صفہ میں تھا۔ ہم صفہ میں تقریباً بیس (20) آدمی تھے۔ پھر پچھلی حدیث جیسا مضمون ذکر کیا، البتہ اس حدیث میں روٹی کے ٹکڑے اور کچھ دودھ کا ذکر ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.8 Pg.305). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.150)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں کئی دن تک حضورؐ کو کھانے کو کچھ نہ ملا۔ جب بھوک نے حضورؐ کو بہت زیادہ ستایا تو آپؐ اپنی تمام ازواجِ مطہرات کے گھروں میں تشریف لے گئے لیکن آپؐ کو کسی کے ہاں کھانے کو کچھ نہ ملا۔ پھر آپؐ حضرت فاطمہؓ کے ہاں تشریف لے گئے اور فرمایا اے بٹیا! کیا تمہارے پاس کھانے کی کوئی چیز ہے؟ کیونکہ مجھے بہت بھوک لگی ہوئی ہے۔ حضرت فاطمہؓ نے کہا میرے ماں باپ آپؐ پر قربان ہوں، ",""],["ٱللَّٰه","a"],[" کی قسم! کچھ نہیں ہے۔ جب آپؐ حضرت فاطمہؓ کے ہاں سے تشریف لے گئے تو حضرت فاطمہؓ کی ایک پڑوسن نے ان کے ہاں دو روٹیاں اور گوشت کا ایک ٹکڑا بھیجا۔ حضرت فاطمہؓ نے کھانا لے کر اپنے ایک پیالے میں رکھ دیا اور اپنے دل میں کہا ",""],["ٱللَّٰه","a"],[" کی قسم! میں یہ کھانا حضورؐ کو کھلاؤں گی، نہ خود کھاؤں گی اور میرے پاس جو بچے ہیں نہ ان کو کھلاؤں گی، حالانکہ یہ سب بھوکے تھے اور پیٹ بھر کھانے کی انہیں بھی ضرورت تھی۔ انہوں نے حضرت حسن یا حضرت حسینؓ میں سے ایک کو حضورؐ کی خدمت میں بلانے بھیجا۔ حضورؐ حضرت فاطمہؓ کے ہاں دوبارہ تشریف لے آئے۔ حضرت فاطمہؓ نے عرض کیا میرے ماں باپ آپ پر قربان ہوں، ",""],["ٱللَّٰه","a"],[" نے کچھ بھیجا ہے جو میں نے آپ کے لیے چھپا کر رکھا ہے۔ آپؐ نے فرمایا بٹیا! لے آؤ۔ حضرت فاطمہؓ فرماتی ہیں میں وہ پیالہ لے آئی۔ اسے کھولا تو میں دیکھ کر حیران رہ گئی کیونکہ سارا پیالہ روٹی اور گوشت سے بھرا ہوا تھا۔ میں سمجھ گئی یہ برکت ",""],["ٱللَّٰه","a"],[" کی طرف سے ہوئی ہے۔ میں نے ",""],["ٱللَّٰه","a"],[" کی تعریف کی اور اس کے نبیؐ پر درود بھیجا اور کھانا حضورؐ کے سامنے رکھ دیا۔ جب حضورؐ نے کھانا دیکھا تو فرمایا الحمدللہ! اے بٹیا! یہ کھانا تمہیں کہاں سے ملا؟ میں نے کہا اے ابا جان! یہ کھانا ",""],["ٱللَّٰه","a"],[" کے ہاں سے آیا ہے اور ",""],["ٱللَّٰه","a"],[" جسے چاہتا ہے اس کو بے حساب اور بے گمان روزی دیتا ہے۔ آپؐ نے ",""],["ٱللَّٰه","a"],[" کی تعریف بیان کی اور فرمایا اے بٹیا! تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے تجھے بنو اسرائیل کی عورتوں کی سردار (حضرت مریمؓ) کے مشابہ بنایا ہے کیونکہ جب ",""],["ٱللَّٰه","a"],[" تعالیٰ انہیں روزی دیتے اور ان سے اس روزی کے بارے میں پوچھا جاتا تو وہ کہتیں یہ ",""],["ٱللَّٰه","a"],[" کے پاس سے آیا ہے اور ",""],["ٱللَّٰه","a"],[" جسے چاہتا ہے اسے بے حساب اور بے گمان روزی دیتا ہے۔ پھر حضورؐ نے آدمی بھیج کر حضرت علیؓ کو بلایا۔ پھر حضورؐ نے، حضرت علیؓ، حضرت فاطمہؓ، حضرت حسنؓ، حضرت حسینؓ، حضورؐ کی ازواجِ مطہرات نے اور آپؐ کے تمام گھر والوں نے پیٹ بھر کر کھانا کھایا۔ حضرت فاطمہؓ فرماتی ہیں سب کے کھا لینے کے بعد کھانا جوں کا توں باقی تھا اور وہ بچا ہوا کھانا تمام پڑوسیوں کو پورا آ گیا۔ اس کھانے میں ",""],["ٱللَّٰه","a"],[" نے بڑی خیر و برکت ڈالی۔",""]]]],"f":[]},{"b":[["n",[["جلد اول صفحہ 119 پر ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ کی طرف سے دعوت دینے کے باب میں حضرت علیؓ کی حدیث گزر چکی ہے کہ حضورؐ نے بنو ہاشم کو بلایا، وہ تقریباً چالیس آدمی تھے۔ حضورؐ نے ایک مد (14 چھٹانک) کا کھانا پکا کر ان کے سامنے رکھا۔ انہوں نے پیٹ بھر کر کھایا لیکن جب وہ کھا کر اٹھے تو کھانا اسی طرح بچا ہوا تھا جیسے پہلے تھا۔ حضورؐ نے ایک پیالہ مشروب انہیں پلایا جسے انہوں نے خوب سیر ہو کر پیا۔ جب وہ پی چکے تو وہ مشروب بھی اسی طرح بچا ہوا تھا جیسے پہلے تھا۔ آپؐ تین دن انہیں ایسے ہی کھلاتے پلاتے رہے، پھر انہیں ",""],["ٱللَّٰه","a"],[" کی طرف دعوت دی۔ اس طرح جلد اول صفحہ 341 پر سختیاں برداشت کرنے کے باب میں اہلِ صفہ کے کھانے میں برکت کے قصے گزر چکے ہیں جنہیں حضرت ابوہریرہؓ اور دیگر صحابہؓ نے روایت کیا ہے اور جلد دوم صفحہ 221 اور صفحہ 231 پر خرچ کرنے کے باب میں مہمانوں کی مہمانی کے بعض قصے گزر چکے ہیں۔ ان میں حضرت ابوطلحہ اور حضرت ابوبکرؓ کی مہمانی میں برکت اور رحمت ظاہر ہونے کے قصے بھی گزر چکے ہیں اور حضرت زینبؓ کے نکاح کے قصے میں ولیمہ میں برکت کا ظاہر ہونا بھی گزر چکا ہے۔",""]]]],"f":[]}]},"262":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں قبیلہ دوس کی ایک عورت تھیں جنہیں ام شریک کہا جاتا تھا۔ وہ رمضان میں مسلمان ہوئیں۔ پھر انہوں نے مدینہ کی طرف ہجرت کی۔ سفر میں ایک یہودی بھی ساتھ تھا۔ انہیں سخت پیاس لگی۔ یہودی کے پاس پانی تھا۔ انہوں نے اس سے پانی مانگا۔ اس نے کہا جب تک تم یہودی نہیں ہو جاؤ گی تمہیں پانی نہیں پلاؤں گا۔ یہ سو گئیں تو خواب میں دیکھا کہ کوئی انہیں پانی پلا رہا ہے۔ جب یہ اٹھیں تو یہ بالکل سیراب ہو چکی تھیں اور پیاس بالکل ختم ہو چکی تھی۔ جب یہ حضورؐ کی خدمت میں پہنچیں تو سارا قصہ حضورؐ کو سنایا۔ حضورؐ نے ان کو شادی کا پیغام دیا۔ انہوں نے اپنے آپ کو اس قابل نہ سمجھا اور عرض کیا آپؐ اپنے علاوہ جس سے چاہیں میری شادی کر دیں۔ حضورؐ نے ان کی حضرت زیدؓ سے شادی کر دی اور حضورؐ نے حکم دیا کہ انہیں تیس صاع (تقریباً اڑھائی من) جَو دیا جائے اور فرمایا اسے کھاتے رہو لیکن اسے کسی پیمانے سے مت ناپنا۔ اور ان کے ساتھ گھی کی ایک کپی تھی جسے وہ حضورؐ کے لیے ہدیہ کے طور پر لائی تھیں۔ حضرت ام شریکؓ نے اپنی باندی سے کہا کہ یہ حضورؐ کی خدمت میں لے جاؤ۔ اس باندی نے جا کر حضورؐ کے گھر میں وہ کپی خالی کر دی اور گھی حضورؐ کے برتن میں ڈال دیا۔ حضورؐ نے باندی سے کہا اس کپی کو گھر جا کر لٹکا دینا اور اس کا منہ ڈوری سے بند نہ کرنا۔ اس باندی نے ایسے ہی کیا۔ حضرت ام شریک نے اندر آ کر دیکھا تو کپی گھی سے بھری ہوئی تھی۔ انہوں نے باندی سے کہا کہ میں نے تم سے نہیں کہا تھا کہ جا کر یہ کپی حضورؐ کی خدمت میں دے آؤ۔ باندی نے کہا میں تو دے آئی ہوں۔ انہوں نے حضورؐ کو یہ بات بتائی۔ حضورؐ نے فرمایا اس کپی کا منہ کبھی بند نہ کرنا۔ چنانچہ بہت عرصہ تک یہ لوگ اس میں سے گھی نکال کر کھاتے رہے۔ آخر ایک دفعہ حضرت ام شریکؓ نے اس کپی کا منہ بند کر دیا، پھر یہ سلسلہ بند ہوا۔ پھر ان لوگوں نے جَو کو پیمانہ سے ناپا تو وہ بھی تیس صاع ہی تھے، کچھ کم نہ ہوئے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Ya'la, as quoted in the Tafseer of Ibn Katheer (Vol.1 Pg.360). Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.104)."]]},{"b":[["n",[["حضرت یحییٰ بن سعیدؒ","b"],[" کہتے ہیں حضرت ام شریک دوسیہؓ نے ہجرت کی۔ راستہ میں ایک یہودی کا ساتھ ہو گیا۔ یہ روزے سے تھیں اور شام ہو چکی تھی۔ یہودی نے اپنی بیوی سے کہا اگر تو نے اس عورت کو پانی پلایا تو میں تیری اچھی طرح خبر لوں گا۔ آخر یہ پیاسی ہی سو گئیں۔ رات کے آخری حصہ میں ان کے سینے پر ایک ڈول اور ایک تھیلا (",""],["ٱللَّٰه","a"],[" کی طرف سے) لا کر رکھا گیا۔ انہوں نے اس ڈول میں سے خوب پانی پیا، پھر انہوں نے اس یہودی کو اور اس کی بیوی کو اٹھایا تاکہ رات کے آخری حصے میں سفر شروع کر سکیں۔ یہودی نے کہا مجھے اس عورت کی آواز سے ایسا لگ رہا ہے کہ جیسے اس نے پانی پی لیا ہو۔ حضرت ام شریکؓ نے کہا پانی تو میں نے ضرور پیا ہے لیکن ",""],["ٱللَّٰه","a"],[" کی قسم! تمہاری بیوی نے مجھے پانی نہیں پلایا ہے۔ راوی کہتے ہیں حضرت ام شریکؓ کی ایک گھی کی کپی تھی۔ اس کے بعد گھی میں برکت کا قصہ ذکر کیا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.8 Pg.157)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں ایک آدمی نے آ کر حضورؐ سے غلہ مانگا۔ حضورؐ نے اسے آدھا وسق جَو دیے (ایک وسق 5 من 10 سیر کا ہوتا ہے، لہٰذا آدھا وسق 2 من 25 سیر کا ہوا)۔ وہ آدمی، اس کی بیوی اور اس کا خادم بہت عرصے تک یہ جَو کھاتے رہے۔ پھر ایک دن اسے پیمانہ سے ناپ لیا۔ حضورؐ کو پتہ لگا تو آپؐ نے فرمایا اگر تم لوگ اسے نہ ناپتے تو اسے ہمیشہ کھاتے رہتے اور یہ جَو ختم نہ ہوتے اور ہمیشہ باقی رہتے۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.104). Muslim has reported it from Hadhrat Jaabir."]]},{"b":[["n",[["حضرت نوفل بن حارث بن عبدالمطلبؓ","b"],[" فرماتے ہیں میں نے حضورؐ سے اپنی شادی کے بارے میں مدد چاہی۔ آپؐ نے ایک عورت سے میری شادی کر دی اور مجھے دینے کے لیے آپؐ نے تلاش کیا تو آپؐ کو کچھ نہ ملا۔ آپؐ نے اپنی زرہ دے کر حضرت ابورافع اور حضرت ابوایوبؓ کو بھیجا۔ انہوں نے ایک یہودی کے پاس وہ زرہ رہن رکھی اور اس سے تیس صاع (2 من 25 سیر) جَو ادھار لے کر حضورؐ کی خدمت میں آئے۔ حضورؐ نے وہ جَو مجھے دے دیے۔ ہم یہ جَو چھ مہینے تک کھاتے رہے۔ پھر ہم نے وہ جَو پیمانہ سے ناپے تو وہ اتنے ہی نکلے جتنے ہم لے کر آئے تھے، کچھ کم نہ ہوئے۔ میں نے اس بات کا حضورؐ سے ذکر کیا تو آپؐ نے فرمایا اگر تم اسے نہ ناپتے تو جب تک زندہ رہتے اس میں سے کھاتے رہتے۔",""],[" (4)","s"]]]],"f":[["(4)","Haakim (Vol.3 Pg.246). Bayhaqi has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.119)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ کا انتقال ہوا تو اس وقت میرے پاس انسان کے کھانے کے قابل کوئی چیز نہیں تھی، بس صرف کچھ جَو تھے جو میرے طاق میں رکھے ہوئے تھے جنہیں میں بہت عرصے تک کھاتی رہی۔ پھر ایک دن میں نے انہیں تولا تو اس کے بعد وہ ختم ہو گئے۔",""],[" (5)","s"]]]],"f":[["(5)","Bukhaari, Muslim and Tirmidhi, as quoted in Targheeb wat Tarheeb (Vol.5 Pg.165)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں میرے والد صاحب کا انتقال ہوا تو ان پر قرضہ تھا۔ میں نے نبی کریمؐ کی خدمت میں حاضر ہو کر عرض کیا میرے والد اپنے ذمہ قرض چھوڑ کر گئے ہیں۔ قرض ادا کرنے کے لیے میرے پاس کوئی چیز نہیں ہے۔ والد صاحب کا کھجوروں کا ایک باغ ہے، بس اس کی آمدن ہے اور اس کی آمدن اتنی کم ہے کہ کئی سالوں میں قرض ادا ہوگا۔ آپؐ میرے ساتھ تشریف لے چلیں تاکہ قرض خواہ مجھے برا بھلا نہ کہہ سکیں۔ چنانچہ آپؐ میرے ساتھ تشریف لے گئے اور کھجور کے ایک ڈھیر کے گرد چکر لگایا اور دعا فرمائی، پھر دوسرے ڈھیر کے گرد چکر لگایا، پھر اس کے پاس بیٹھ گئے اور قرض خواہوں سے فرمایا اس میں سے لینا شروع کرو (حضورؐ نے ان کو دینا شروع کیا) اور ان سب کو ان کے قرض کے مطابق پورا پورا دے دیا اور جتنا انہیں دیا اتنا بچ بھی گیا۔ ابونعیم کی روایت میں ہے کہ حضورؐ اس ڈھیر کے پاس گئے، پھر فرمایا جاؤ اور اپنے قرض مانگنے والے ساتھیوں کو بلا لاؤ۔ میں انہیں بلا لایا اور حضورؐ انہیں تول تول کر دیتے رہے یہاں تک کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے میرے والد کا سارا قرضہ ادا کروا دیا، حالانکہ ",""],["ٱللَّٰه","a"],[" کی قسم! میں تو اس بات پر بھی راضی تھا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ میرے والد کا سارا قرضہ اتروا دیتے اور میں ایک بھی کھجور اپنی بہنوں کے پاس واپس لے کر نہ جاتا لیکن ",""],["ٱللَّٰه","a"],[" تعالیٰ نے کھجور کے سارے ڈھیر بچا دیے بلکہ مجھے تو وہ ڈھیر جس پر حضورؐ بیٹھے تھے وہ بھی صحیح سالم نظر آ رہا تھا اور ایسے لگ رہا تھا کہ جیسے اس میں سے ایک کھجور بھی کم نہ ہوئی ہو۔",""],[" (6)","s"]]]],"f":[["(6)","Bukhaari, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.116). Ibn Sa'd (Vol.3 Pg.563) has reported a similar narration, and Abu Nu'aym a longer one in his Dalaa'il (Pg.156)."]]},{"b":[["n",[["حضرت سعید بن میناءؒ","b"],[" کہتے ہیں حضرت بشیر بن سعدؓ کی بیٹی جو کہ حضرت نعمان بن بشیرؓ کی بہن ہیں وہ فرماتی ہیں مجھے میری والدہ حضرت عمرہ بنت رواحہؓ نے بلایا اور مٹھی بھر کھجوریں میری جھولی میں ڈال کر فرمایا اے بیٹی! اپنے والد اور اپنے ماموں حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ کے پاس ان کا دوپہر کا کھانا لے جاؤ۔ میں وہ کھجوریں لے کر چل پڑی اور اپنے والد اور ماموں کو ڈھونڈتی ہوئی حضورؐ کے پاس سے گزری۔ حضورؐ نے فرمایا اے بیٹی! یہاں آؤ، یہ تمہارے پاس کیا ہے؟ میں نے کہا یہ کھجوریں ہیں جنہیں دے کر میری والدہ نے میرے والد اور ماموں کے پاس بھیجا ہے تاکہ وہ یہ کھا لیں۔ حضورؐ نے فرمایا مجھے دے دو۔ میں نے وہ کھجوریں حضورؐ کے دونوں ہاتھوں میں ڈال دیں۔ وہ کھجوریں اتنی تھوڑی تھیں کہ ان سے حضورؐ کے دونوں ہاتھ بھر نہ سکے۔ پھر آپؐ کے حکم پر ایک کپڑا بچھایا گیا جس پر آپؐ نے وہ کھجوریں ڈال دیں۔ وہ کھجوریں کپڑے پر بکھر گئیں۔ ایک آدمی حضورؐ کے پاس تھا، آپؐ نے اس سے فرمایا خندق والوں میں یہ اعلان کر دو کہ کھانے کے لیے آ جائیں۔ چنانچہ خندق والے سب جمع ہو گئے اور کھجوریں کھانی شروع کر دیں تو کھجوریں بڑھتی جا رہی تھیں، یہاں تک کہ سب خندق والے کھا کر واپس چلے گئے اور کھجوریں اتنی زیادہ ہو گئی تھیں کہ کپڑے سے نیچے گر رہی تھیں۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Dalaa'il (Pg.180). Ibn Is'haaq has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.116)."]]},{"b":[["n",[["حضرت عرباضؓ","b"],[" فرماتے ہیں میں سفر میں، حضر میں ہمیشہ حضورؐ کے دروازے پر پڑا رہتا تھا۔ ایک مرتبہ ہم تبوک میں تھے، ہم رات کو کسی کام سے کہیں گئے۔ جب ہم حضورؐ کی خدمت میں واپس آئے تو آپؐ بھی اور آپؐ کے پاس جتنے صحابہؓ تھے وہ سب بھی رات کا کھانا کھا چکے تھے۔ حضورؐ نے مجھ سے پوچھا آج رات تم کہاں تھے؟ میں نے آپؐ کو بتایا، اتنے میں حضرت جعال بن سراقہ اور حضرت عبد",""],["ٱللَّٰه","a"],[" بن مغفل مزنیؓ بھی آ گئے اور یوں ہم تین ہو گئے اور تینوں کو بھوک لگی ہوئی تھی۔ حضورؐ حضرت ام سلمہؓ کے خیمے میں تشریف لے گئے اور ان سے ہمارے کھانے کے لیے کوئی چیز طلب فرمائی لیکن آپؐ کو کچھ نہ ملا۔ پھر پکار کر آپؐ نے حضرت بلالؓ سے فرمایا کچھ ہے؟ حضرت بلالؓ چمڑے کے تھیلے پکڑ کر جھاڑنے لگے تو ان میں سے سات کھجوریں نکل آئیں۔ حضورؐ نے وہ کھجوریں ایک بڑے پیالے میں ڈالیں اور پھر ان پر ہاتھ مبارک رکھا اور ",""],["ٱللَّٰه","a"],[" کا نام لیا اور فرمایا ",""],["ٱللَّٰه","a"],[" کا نام لے کر کھاؤ۔ ہم نے وہ کھجوریں کھائیں۔ میں کھجوریں گنتا جا رہا تھا اور ان کی گٹھلیاں دوسرے ہاتھ میں پکڑتا جا رہا تھا۔ میں نے گنا تو میں نے 54 کھجوریں کھائی تھیں۔ میرے دونوں ساتھی بھی میری طرح ہی کر رہے تھے اور کھجوریں گن رہے تھے، انہوں نے پچاس پچاس کھجوریں کھائی تھیں۔ جب ہم نے کھانے سے ہاتھ ہٹائے تو ساتوں کھجوریں ویسی کی ویسی تھیں۔ حضورؐ نے فرمایا اے بلال! ان کو اپنے تھیلے میں رکھ لو۔ جب دوسرا دن ہوا تو حضورؐ نے وہ کھجوریں پیالہ میں ڈالیں اور فرمایا ",""],["ٱللَّٰه","a"],[" کا نام لے کر کھاؤ۔ ہم دس آدمی تھے، ہم نے پیٹ بھر کر وہ کھجوریں کھائیں۔ پھر جب ہم نے کھانے سے ہاتھ ہٹائے تو وہ کھجوریں اسی طرح سات تھیں۔ پھر آپؐ نے فرمایا اگر مجھے اپنے رب سے حیا نہ آتی تو ہم سب مدینہ پہنچنے تک یہی کھجوریں کھاتے رہتے۔ حضورؐ جب مدینہ پہنچ گئے تو مدینہ کا ایک چھوٹا سا لڑکا آپؐ کے سامنے آیا۔ آپؐ نے یہ کھجوریں اسے دے دیں، وہ کھجوریں کھاتا ہوا چلا گیا۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Asaakir, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.118)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں اسلام میں مجھ پر تین ایسی بڑی مصیبتیں آئی ہیں کہ ویسی کبھی بھی مجھ پر نہیں آئیں۔ ایک تو حضورؐ کے انتقال کا حادثہ کیونکہ میں آپؐ کا ہمیشہ ساتھ رہنے والا معمولی سا ساتھی تھا، دوسرے حضرت عثمانؓ کی شہادت کا حادثہ، تیسرے توشہ دان کا حادثہ۔ لوگوں نے پوچھا اے ابوہریرہ! توشہ دان کے حادثے کا کیا مطلب؟ فرمایا ہم ایک سفر میں حضورؐ کے ساتھ تھے۔ آپؐ نے فرمایا اے ابوہریرہ! تمہارے پاس کچھ ہے؟ میں نے کہا توشہ دان میں کچھ کھجوریں ہیں۔ آپؐ نے فرمایا لے آؤ۔ میں نے کھجوریں نکال کر آپؐ کی خدمت میں پیش کر دیں۔ آپؐ نے ان پر ہاتھ پھیرا اور برکت کے لیے دعا فرمائی، پھر فرمایا دس آدمیوں کو بلا کر لاؤ۔ میں دس آدمیوں کو بلا لایا۔ انہوں نے پیٹ بھر کر کھجوریں کھائیں، پھر اسی طرح دس دس آدمی آ کر کھاتے رہے یہاں تک کہ سارے لشکر نے کھا لیا اور توشہ دان میں پھر بھی کھجوریں بچی رہیں۔ آپؐ نے فرمایا اے ابوہریرہ! جب تم اس توشہ دان میں سے کھجوریں نکالنا چاہو تو اس میں ہاتھ ڈال کر نکالنا اور اسے الٹانا نہیں۔ حضرت ابوہریرہؓ فرماتے ہیں میں حضورؐ کی ساری زندگی میں اس سے نکال کر کھاتا رہا، پھر حضرت ابوبکرؓ کی ساری زندگی میں اس میں سے کھاتا رہا، پھر حضرت عمرؓ کی ساری زندگی میں اس میں سے کھاتا رہا، پھر حضرت عثمانؓ کی ساری زندگی میں اس میں سے کھاتا رہا۔ پھر جب حضرت عثمانؓ شہید ہو گئے تو میرا سامان بھی لٹ گیا اور وہ توشہ دان بھی لٹ گیا۔ کیا میں آپ لوگوں کو بتا نہ دوں کہ میں نے اس میں سے کتنی کھجوریں کھائی ہیں؟ میں نے اس میں سے دو سو وسق یعنی ایک ہزار پچاس من سے بھی زیادہ کھجوریں کھائی ہیں۔",""],[" (9)","s"]]]],"f":[["(9)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.117). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.155), as have Ahmad and Tirmidhi."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں میری والدہ مجھے حضورؐ کے پاس لے گئیں اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! یہ آپ کا چھوٹا سا خادم ہے، اس کے لیے دعا فرما دیں۔ تو حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اس کے مال اور اولاد کو زیادہ فرما اور اس کی عمر لمبی فرما اور اس کے تمام گناہ معاف فرما۔ حضرت انسؓ فرماتے ہیں میں اپنے دو کم سو یعنی 98 بچے دفن کر چکا ہوں یا فرمایا دو اوپر سو یعنی 102 بچے دفن کر چکا ہوں اور میرے باغ کا پھل سال میں دو مرتبہ آتا ہے اور میری زندگی اتنی لمبی ہو چکی ہے کہ اب زندگی سے دل بھر چکا ہے (93 ہجری میں ان کا بصرہ میں 103 سال کی عمر میں انتقال ہوا) اور حضورؐ کی چوتھی دعا کے پورا ہونے کا مجھے یقین ہے یعنی گناہوں کی مغفرت کی دعا۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Sa'd (Vol.7 Pg.19)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں میری والدہ حضرت ام سلیمؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! انس کے لیے دعا فرمائیں۔ حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اس کے مال اور اولاد کو زیادہ فرما اور ان میں برکت عطا فرما۔ تو میں پوتوں کے علاوہ اپنے ایک سو پچیس (125) بچے دفن کر چکا ہوں اور میری زمین سال میں دو مرتبہ پھل دیتی ہے اور سارے علاقہ میں اور کوئی زمین سال میں دو دفعہ پھل نہیں دیتی۔",""],[" (11)","s"]]]],"f":[["(11)","Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.7 Pg.9)."]]}]},"263":{"lead":[],"stories":[{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضرت ام مالک بہزیہؓ اپنی کپی میں نبی کریمؐ کی خدمت میں گھی ہدیہ بھیجا کرتی تھیں۔ ایک مرتبہ ان کے بیٹوں نے ان سے سالن مانگا۔ اس وقت ان کے پاس کوئی چیز نہیں تھی۔ وہ اپنی اس کپی کے پاس گئیں جس میں وہ حضورؐ کو گھی ہدیہ بھیجا کرتی تھیں، اس میں سے انہیں گھی مل گیا (حالانکہ اسے خالی کر کے ٹانگا تھا)۔ وہ بہت عرصہ تک اپنے بیٹوں کو یہ گھی بطور سالن کے دیتی رہیں۔ آخر ایک مرتبہ انہوں نے اس کپی کو نچوڑ لیا (جس کے بعد یہ سلسلہ ختم ہو گیا)۔ انہوں نے حضورؐ کی خدمت میں جا کر سارا واقعہ عرض کیا۔ حضورؐ نے فرمایا کیا تم نے اسے نچوڑا تھا؟ انہوں نے کہا جی ہاں۔ حضورؐ نے فرمایا اگر تو اسے اسی طرح رہنے دیتی اور نہ نچوڑتی تو تجھے اس کپی سے ہمیشہ گھی ملتا رہتا۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.104)."]]},{"b":[["n",[["حضرت ام مالک انصاریہؓ","b"],[" گھی کی ایک کپی لے کر حضورؐ کی خدمت میں گئیں۔ آپؐ نے حضرت بلالؓ کو ان سے گھی لینے کا حکم دیا۔ حضرت بلالؓ نے نچوڑ کر اس کپی میں سے سارا گھی نکال لیا اور خالی کپی حضرت ام مالکؓ کو واپس کر دی۔ جب وہ واپس گھر پہنچیں تو دیکھا کہ کپی تو گھی سے بھری ہوئی ہے۔ انہوں نے جا کر حضورؐ کی خدمت میں عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کیا میرے بارے میں آسمان سے کوئی وحی نازل ہوئی ہے؟ حضورؐ نے فرمایا اے ام مالک! کیوں؟ کیا بات پیش آئی ہے؟ انہوں نے کہا آپ نے میرا ہدیہ کیوں واپس کر دیا؟ آپؐ نے حضرت بلالؓ کو بلا کر ان سے اس بارے میں پوچھا۔ حضرت بلالؓ نے کہا اس ذات کی قسم جس نے آپ کو حق دے کر بھیجا ہے! میں نے تو کپی میں سے سارا گھی نکال لیا تھا بلکہ اسے اتنا نچوڑا تھا کہ مجھے شرم آنے لگی تھی۔ حضورؐ نے فرمایا اے ام مالک! تمہیں مبارک ہو، ",""],["ٱللَّٰه","a"],[" نے تمہیں ہدیہ کا بدلہ جلدی دے دیا۔ پھر حضورؐ نے انہیں سکھایا کہ ہر نماز کے بعد دس مرتبہ سبحان ",""],["ٱللَّٰه","a"],["، دس مرتبہ الحمدللہ اور دس مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر کہا کریں۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani; Haythami (Vol.8 Pg.309) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.204), as have Ibn Abi Aasim and Muslim, as quoted in Isaabah (Vol.4 Pg.494)."]]},{"b":[["n",[["حضرت ام اوس بہزیہؓ","b"],[" نے گھی پکا کر ایک کپی میں ڈالا، پھر حضورؐ کو ہدیہ میں پیش کیا۔ حضورؐ نے اسے قبول فرما لیا اور کپی میں جتنا گھی تھا وہ لے لیا اور ان کے لیے برکت کی دعا فرمائی اور وہ کپی انہیں واپس فرما دی۔ انہوں نے گھر جا کر دیکھا تو وہ کپی گھی سے بھری ہوئی تھی۔ وہ سمجھیں کہ شاید حضورؐ نے ان کا ہدیہ قبول نہیں فرمایا۔ وہ چیختی پکارتی حضورؐ کی خدمت میں آئیں (اور عرض کیا آپ نے میرا ہدیہ قبول نہیں فرمایا؟) حضورؐ نے فرمایا انہیں واقعہ تفصیل سے بتاؤ کہ ہم نے تو قبول کر لیا تھا (اب یہ ",""],["ٱللَّٰه","a"],[" نے برکت عطا فرمائی ہے)۔ چنانچہ وہ حضورؐ کی زندگی میں وہ گھی کھاتی رہیں، پھر حضرت ابوبکر، حضرت عمر اور حضرت عثمانؓ کے زمانۂ خلافت میں وہ گھی کھاتی رہیں، پھر جب حضرت علی اور حضرت معاویہؓ میں اختلافات پیدا ہوئے تو اس وقت تک وہ کھاتی رہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani, Ibn Mandah and Ibn Sakan, as quoted in Isaabah (Vol.4 Pg.431). Haythami (Vol.8 Pg.310) has commented on the chain of narrators. Bayhaqi has reported a similar narration in greater detail, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.104)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں میری والدہ کی ایک بکری تھی۔ وہ اس کا گھی ایک کپی میں جمع کرتی رہیں۔ جب وہ کپی بھر گئی تو اپنی لے پالک لڑکی کے ہاتھ وہ کپی بھیجی اور اس سے کہا اے بیٹی! یہ کپی حضورؐ کی خدمت میں پہنچا دو، آپؐ اسے سالن بنا لیا کریں گے۔ وہ لڑکی کپی لے کر حضورؐ کی خدمت میں پہنچی اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! یہ گھی کی کپی ام سلیم نے آپ کی خدمت میں بھیجی ہے۔ حضورؐ نے گھر والوں سے فرمایا اس کی کپی خالی کر کے دے دو۔ گھر والوں نے خالی کر کے کپی اسے دے دی۔ وہ لے کر چلی گئی اور گھر آ کر اسے ایک کھونٹی پر لٹکا دیا۔ اس وقت حضرت ام سلیمؓ گھر میں نہیں تھیں۔ جب وہ گھر واپس آئیں تو دیکھا کہ کپی بھری ہوئی ہے اور اس میں سے گھی ٹپک رہا ہے۔ انہوں نے کہا اے لڑکی! کیا میں نے تجھے نہیں کہا تھا کہ یہ کپی جا کر حضورؐ کو دے آؤ؟ اس نے کہا میں تو دے آئی ہوں، اگر آپ کو میری بات پر اطمینان نہیں ہے تو آپ خود جا کر حضورؐ سے پوچھ لیں۔ حضرت ام سلیمؓ اس لڑکی کو لے کر حضورؐ کی خدمت میں گئیں اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے اس لڑکی کے ہاتھ ایک کپی آپ کی خدمت میں بھیجی تھی جس میں گھی تھا۔ حضورؐ نے فرمایا ہاں، یہ کپی لے کر آئی تھی۔ حضرت ام سلیمؓ نے کہا اس ذات کی قسم جس نے آپ کو حق اور سچا دین دے کر بھیجا ہے! وہ کپی تو بھری ہوئی ہے اور اس میں سے گھی ٹپک رہا ہے۔ حضورؐ نے فرمایا اے ام سلیم! کیا تم اس بات پر تعجب کر رہی ہو کہ جس طرح تم نے ",""],["ٱللَّٰه","a"],[" کے نبی کو کھلایا ہے اسی طرح ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہیں کھلا رہے ہیں؟ اس سے تم خود بھی کھاؤ اور دوسروں کو بھی کھلاؤ۔ حضرت ام سلیمؓ فرماتی ہیں میں گھر واپس آئی اور ایک بڑے پیالہ میں اور دوسرے برتنوں میں ڈال ڈال کر میں نے وہ گھی تقسیم کیا اور کچھ اس میں چھوڑ دیا جسے ہم ایک یا دو مہینے تک سالن بنا کر استعمال کرتے رہے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Ya'la, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.103). Tabraani and Abu Ya'la have reported a similar narration, but Haythami (Vol.8 Pg.309) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.203), and Haafidh has commented on it in his Isaabah (Vol.4 Pg.320)."]]},{"b":[["n",[["حضرت ام شریکؓ","b"],[" فرماتی ہیں میرے پاس ایک کپی تھی جس میں میں حضورؐ کو گھی ہدیہ دیا کرتی تھی۔ ایک دن میرے بچوں نے مجھ سے گھی مانگا اور گھی تھا نہیں۔ میں دیکھنے کے لیے اٹھ کر کپی کی طرف گئی (کہ شاید اس میں سے کچھ بچا ہوا گھی مل جائے)۔ میں نے جا کر دیکھا تو کپی گھی سے بھری ہوئی تھی اور اس میں سے گھی بہہ رہا تھا۔ میں نے بچوں کے لیے انڈیل کر اس میں سے کچھ گھی نکالا جسے بچے کچھ دیر کھاتے رہے۔ پھر میں دیکھنے گئی کہ کپی میں کتنا گھی باقی رہ گیا ہے۔ میں نے اسے انڈیل کر سارا گھی نکالا جس سے وہ ختم ہو گیا۔ پھر میں حضورؐ کی خدمت میں گئی۔ حضورؐ نے مجھ سے فرمایا کیا تم نے اسے بالکل الٹا دیا تھا؟ غور سے سنو! اگر تم اسے الٹا نہ کرتیں تو ایک عرصہ تک یہ گھی باقی رہتا۔",""]]]],"f":[]},{"b":[["n",[["حضرت یحییٰ بن سعیدؒ","b"],[" کہتے ہیں حضرت ام شریکؓ کی ایک کپی تھی۔ جو ان کے پاس آتا تھا اسے وہ کپی عاریۃً دے دیتیں۔ ایک آدمی نے ان سے اس کپی کا سودا کرنا چاہا تو انہوں نے کہا اس میں کچھ نہیں ہے۔ پھر اس میں پھونک بھر کر اسے دھوپ میں لٹکا دیا (تاکہ گھی پگھل کر ایک جگہ جمع ہو جائے) تو کیا دیکھتی ہیں کہ وہ گھی سے بھری ہوئی ہے۔ اسی وجہ سے کہا جاتا تھا کہ حضرت ام شریکؓ کی کپی ",""],["ٱللَّٰه","a"],[" کی نشانیوں میں سے ایک نشانی ہے۔ اس حدیث کا کچھ حصہ پہلے گزر چکا ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Sa'd (Vol.8 Pg.157)."]]},{"b":[["n",[["حضرت حمزہ بن عمروؓ","b"],[" فرماتے ہیں حضورؐ کے صحابہؓ کا کھانا مختلف صحابہؓ باری باری پکا کر لاتے۔ ایک رات یہ لاتے، دوسرے رات دوسرے صحابیؓ لاتے۔ چنانچہ ایک رات میری باری آئی۔ میں نے حضورؐ کے صحابہؓ کا کھانا تیار کیا اور گھی کی مشک کو ایسے ہی چھوڑ دیا اور اس کے منہ کو ڈوری سے باندھا نہیں۔ جب میں کھانا حضورؐ کی خدمت میں لے جانے لگا تو مشک ہل گئی اور اس میں سے گھی گرنے لگا تو میں نے کہا کیا حضورؐ کے کھانے نے میرے ہی ہاتھوں سے گرنا تھا؟ جب میں کھانا لے کر حضورؐ کی خدمت میں پہنچا تو حضورؐ نے فرمایا قریب آ جاؤ، تم بھی کھاؤ۔ میں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! گنجائش نہیں (کھانا کم ہے)۔ کھانا کھلا کر میں اپنی جگہ واپس آیا تو دیکھا کہ مشک سے غٹ غٹ گھی کے گرنے کی آواز آ رہی تھی۔ میں نے کہا یہ آواز کیسی؟ جو گھی اس میں بچ گیا تھا وہ گر رہا ہوگا۔ میں اسے دیکھنے گیا تو مشک سینے تک بھری ہوئی تھی۔ میں وہ مشک لے کر حضورؐ کی خدمت میں گیا اور سارا واقعہ آپؐ کو بتایا۔ آپؐ نے فرمایا اگر تم اس کو ہاتھ نہ لگاتے اور ویسے ہی رہنے دیتے تو یہ منہ تک بھر جاتی، پھر اس کے منہ پر ڈوری باندھی جاتی۔ ایک روایت میں ہے کہ اگر تم اسے ایسے ہی رہنے دیتے تو ساری وادی میں گھی بہنے لگتا۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani, as quoted in Majma'uz Zawaa'id (Vol.8 Pg.310)."]]},{"b":[["n",[["حضرت حمزہ بن عمرو اسلمیؓ","b"],[" فرماتے ہیں حضورؐ غزوۂ تبوک میں تشریف لے گئے اور اس سفر میں گھی کی مشک سنبھالنے کی ذمہ داری مجھ پر تھی۔ میں نے اس مشک کو دیکھا تو اس میں تھوڑا سا گھی تھا۔ میں نے حضورؐ کے لیے کھانا تیار کیا اور اس مشک کو دھوپ میں رکھ دیا اور خود سو گیا۔ پھر (",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس مشک کو گھی سے بھر دیا اور) مشک سے گھی بہنے کی آواز سے میری آنکھ کھلی۔ میں نے اپنے ہاتھ سے اس کے سر کو پکڑا۔ حضورؐ مجھے دیکھ رہے تھے۔ آپؐ نے فرمایا اگر تم اس کا سر نہ پکڑتے ایسے ہی رہنے دیتے تو ساری وادی میں یہ گھی بہنے لگتا۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Dalaa'il (Pg.155)."]]},{"b":[["n",[["حضرت خباب بن ارتؓ","b"],[" کی صاحبزادی فرماتی ہیں میرے والد ایک غزوے میں تشریف لے گئے اور ہمارے لیے صرف ایک بکری چھوڑ کر گئے اور ہم سے کہہ کر گئے کہ جب اس کا دودھ نکالنے لگو تو اسے صفہ والوں کے پاس لے جانا، وہ دودھ نکال دیں گے۔ چنانچہ ہم وہ بکری صفہ لے گئے تو وہاں حضورؐ تشریف فرما تھے۔ حضورؐ نے اس بکری کو لیا اور اس کی ٹانگ باندھ کر اس کا دودھ نکالنے لگے اور ہم سے فرمایا تمہارے ہاں جو سب سے بڑا برتن ہے وہ لے آؤ۔ میں گئی اور تو مجھے کوئی برتن نہیں ملا، صرف ایک بڑا پیالہ ملا جس میں ہم آٹا گوندھتے تھے، میں وہ لے آئی۔ حضورؐ نے اس میں دودھ نکالا تو وہ بھر گیا۔ پھر فرمایا جاؤ خود بھی پیو اور پڑوسیوں کو بھی پلاؤ اور جب اس بکری کا دودھ نکالنا ہو تو اسے میرے پاس لے آیا کرو، میں اس کا دودھ نکال دیا کروں گا۔ ہم وہ بکری حضورؐ کے پاس لے جاتے رہے اور ہمارے خوب مزے ہو گئے۔ پھر میرے والد آ گئے اور انہوں نے اس بکری کی ٹانگ باندھ کر اس کا دودھ نکالا تو وہ اپنے پہلے دودھ پر آ گئی۔ میری والدہ نے کہا آپ نے تو ہماری بکری خراب کر دی۔ میرے والد نے کہا کیوں؟ والدہ نے کہا یہ تو آپ کے پیچھے اتنا دودھ دیا کرتی تھی جس سے یہ بڑا پیالہ بھر جاتا تھا۔ والد نے کہا اس کا دودھ کون نکالتا تھا؟ والدہ نے کہا حضورؐ۔ والد نے کہا تم تو مجھے حضورؐ کے برابر کر رہی ہو، ",""],["ٱللَّٰه","a"],[" کی قسم! ان کے ہاتھ میں تو میرے ہاتھ سے بہت زیادہ برکت ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Sa'd (Vol.8 Pg.291)."]]},{"b":[["n",[["جلد اول صفحہ 341 پر سختیاں برداشت کرنے کے باب میں حضرت ابوہریرہؓ کی حدیث اور جلد اول صفحہ 328 پر ",""],["ٱللَّٰه","a"],[" تعالیٰ کی دعوت دینے کے باب میں حضرت علیؓ کی حدیث گزر چکی ہے۔",""]]]],"f":[]}]},"264":{"lead":[],"stories":[{"b":[["n",[["حضرت مسعود بن خالدؓ","b"],[" فرماتے ہیں میں نے حضورؐ کی خدمت میں ایک بکری بھیجی اور میں خود کسی کام سے کہیں چلا گیا۔ حضورؐ نے میرے گھر بکری کا کچھ گوشت بھیجا۔ میں اپنی بیوی حضرت ام خناسؓ کے پاس واپس آیا تو میں نے دیکھا کہ اس کے پاس گوشت رکھا ہوا ہے۔ میں نے پوچھا اے ام خناس! یہ گوشت کہاں سے آیا ہے؟ میری بیوی نے کہا آپ نے اپنے خلیلؐ کو جو بکری بھیجی تھی اس میں سے انہوں نے یہ گوشت ہمیں بھیجا ہے۔ میں نے کہا کیا بات ہے تم نے بچوں کو یہ گوشت اب تک کھلایا نہیں؟ میری بیوی نے کہا میں تو سب کو کھلا چکی ہوں، یہ تو ان کا بچا ہوا ہے۔ حضرت مسعودؓ فرماتے ہیں تھوڑے سے گوشت سے سب گھر والوں نے کھا لیا اور پھر بھی گوشت بچ گیا، حالانکہ یہ لوگ دو تین بکریاں ذبح کرتے تھے اور پھر بھی کافی نہیں ہوتی تھیں۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani; Haythami (Vol.8 Pg.310) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت خالد بن عبدالعزیٰؓ","b"],[" فرماتے ہیں میں نے حضورؐ کی خدمت میں ذبح کرنے کے قابل ایک بکری پیش کی جسے حضورؐ نے بھی نوش فرمایا اور آپؐ کے بعض صحابہؓ نے بھی کھایا لیکن پھر بھی گوشت بچ گیا جو حضورؐ نے مجھے عطا فرما دیا جسے میں نے اور میرے تمام بال بچوں نے کھایا اور پھر بھی بچ گیا، حالانکہ میرے بچے بہت سارے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Ya'qoob bin Sufyaan, Hasan bin Sufyaan and Nasa'ee, as quoted in Isaabah (Vol.1 Pg.409)."]]}]},"265":{"lead":[],"stories":[{"b":[["n",[["حضرت سلمہ بن نفیلؓ","b"],[" فرماتے ہیں میں نے حضورؐ سے پوچھا کیا کبھی آپؐ کے لیے آسمان سے بھی کھانا اتارا گیا؟ آپؐ نے فرمایا ہاں۔ میں نے پوچھا کیا اس میں سے کچھ بچا تھا؟ آپؐ نے فرمایا ہاں۔ میں نے پوچھا اس کا کیا ہوا؟ آپؐ نے فرمایا اسے آسمان کی طرف اٹھا لیا گیا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.7 Pg.428)."]]},{"b":[["n",[["حضرت سلمہ بن نفیل سکونیؓ","b"],[" نبی کریمؐ کے صحابہؓ میں سے تھے، وہ فرماتے ہیں ایک دفعہ ہم لوگ حضورؐ کے پاس بیٹھے ہوئے تھے کہ اتنے میں ایک آدمی آیا اور اس نے عرض کیا اے ",""],["ٱللَّٰه","a"],[" کے نبی! کیا کبھی آپ کے پاس آسمان سے کھانا آیا ہے؟ آپؐ نے فرمایا ہاں، دیگچی میں گرم گرم آیا تھا۔ اس آدمی نے پوچھا کیا آپ کے کھانے کے بعد کچھ کھانا بچا تھا؟ حضورؐ نے فرمایا ہاں! اس نے کہا پھر اس بچے ہوئے کھانے کا کیا ہوا تھا؟ حضورؐ نے فرمایا اسے آسمان کی طرف اٹھا لیا گیا تھا اور وہ چپکے چپکے مجھے یہ کہہ رہا تھا کہ میں آپ لوگوں میں تھوڑا عرصہ ہی رہوں گا اور آپ لوگ بھی میرے بعد تھوڑا عرصہ ہی رہو گے بلکہ زندگی لمبی معلوم ہونے لگے گی اور تم لوگ کہو گے ہم یہاں دنیا میں کب تک پڑے رہیں گے؟ پھر آپ لوگ مختلف جماعتیں بن کر آؤ گے اور ایک دوسرے کو فنا کرو گے اور قیامت سے پہلے بہت زیادہ اموات واقع ہوں گی اور اس کے بعد زلزلے کے سال ہوں گے۔",""],[" (2)","s"]]]],"f":[["(2)","Haakim (Vol.4 Pg.447)."]]},{"b":[["n",[["ایک لمبی حدیث میں ",""],["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں لوگوں نے حضورؐ سے بھوک کی شکایت کی۔ حضورؐ نے فرمایا عنقریب ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہیں کھلائیں گے۔ چنانچہ ہم لوگ سمندر کے کنارے پہنچے تو سمندر میں ایک زبردست موج آئی جس سے ایک بہت بڑی مچھلی باہر آ گئی۔ ہم نے اس کا ایک ٹکڑا کاٹا اور آگ جلا کر کچھ گوشت بھونا اور باقی پکا لیا اور خوب پیٹ بھر کر کھایا۔ وہ مچھلی اتنی بڑی تھی کہ میں اس کی آنکھ کے حلقہ کے اندر داخل ہو گیا اور میرے علاوہ فلاں اور فلاں پانچ آدمی داخل ہو گئے اور وہ حلقہ اتنا بڑا تھا کہ ہم باہر کے کسی آدمی کو نظر نہیں آ رہے تھے، پھر ہم اس میں سے باہر آئے۔ اس کے جسم میں بڑے بڑے کانٹے تھے۔ ہم نے ایک کانٹا لے کر کمان کی طرح کھڑا کیا اور قافلہ کے سب سے لمبے آدمی کو اور سب سے لمبے اونٹ کو اور سب سے اونچی کاٹھی کو منگوایا۔ اس کاٹھی کو اس اونٹ پر رکھ کر اس آدمی کو اس پر بٹھایا۔ وہ آدمی اس کانٹے کے نیچے سے گزر گیا لیکن اس کا سر اس کانٹے کو نہ لگا۔",""],[" (3)","s"]]]],"f":[["(3)","Muslim (Vol.2 Pg.418)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضورؐ نے تین سو صحابہؓ کا ایک لشکر ساحلِ سمندر کی طرف بھیجا اور حضرت ابوعبیدہ بن جراحؓ کو ان کا امیر بنایا۔ چنانچہ ہم مدینہ سے چلے۔ راستہ میں توشہ ختم ہو گیا۔ حضرت ابوعبیدہؓ نے حکم دیا کہ لشکر کے تمام توشے جمع کیے جائیں۔ چنانچہ تمام توشے جمع کیے گئے تو کھجور کے دو توشے دان بن گئے۔ حضرت ابوعبیدہؓ ہمیں ان میں سے تھوڑا تھوڑا روز دیتے۔ پھر یہ توشے دان بھی ختم ہو گئے اور ہمیں روزانہ صرف ایک کھجور ملنے لگی۔ راوی نے حضرت جابرؓ سے کہا ایک کھجور سے کیا بنتا ہوگا؟ حضرت جابرؓ نے فرمایا اس ایک کھجور کا فائدہ ہمیں تب معلوم ہوا جب وہ بھی ملنی بند ہو گئی۔ پھر ہم جب ساحلِ سمندر پہنچے تو وہاں چھوٹے پہاڑ جتنی اونچی ایک مچھلی ملی جس کے گوشت کو سارا لشکر 18 دن تک کھاتا رہا (دوسری روایت سے معلوم ہوتا ہے کہ بعض صحابہؓ ایک ماہ تک کھاتے رہے)۔ پھر حضرت ابوعبیدہؓ کے فرمانے پر اس مچھلی کے دو کانٹے کھڑے کیے گئے اور ایک اونٹنی پر کجاوہ رکھا گیا، پھر وہ اونٹنی ان کانٹوں کے نیچے سے گزری اور اس کا سر یا کوہان کانٹوں کو نہ لگا۔",""],[" (4)","s"]]]],"f":[["(4)","Maalik (Pg.371). Bukhaari and Muslim have reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.276)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضورؐ نے ہمیں تین سو سواروں کے لشکر میں بھیجا۔ ہمارے امیر حضرت ابوعبیدہ بن جراحؓ تھے۔ ہم قریش کے ایک تجارتی قافلہ کی گھات میں گئے تھے۔ اس سفر میں ہمیں سخت بھوک لگی اور کھانے کے تمام سامان ختم ہو گئے اور ہمیں درختوں کے گرے ہوئے پتے کھانے پڑے اور اس وجہ سے اس لشکر کا نام پتوں والا لشکر پڑ گیا۔ ایک آدمی نے لشکر کے لیے تین اونٹ ذبح کیے اور پھر تین اونٹ ذبح کیے، پھر تین اونٹ ذبح کیے۔ پھر حضرت ابوعبیدہؓ نے اس آدمی کو اور اونٹ ذبح کرنے سے منع کر دیا۔ پھر سمندر کی تیز موج نے ایک بہت بڑی مچھلی کنارے پر لا ڈالی جسے عنبر کہا جاتا ہے۔ آدھے مہینہ تک ہم اس کا گوشت کھاتے رہے اور اس کی چربی کو جسم پر لگاتے رہے جس سے ہمارے جسموں کی کمزوری اور دبلا پن وغیرہ سب جاتا رہا اور جسم پہلے کی طرح ٹھیک ٹھاک ہو گئے۔ اس کے بعد کانٹے کا قصہ ذکر کیا۔",""],[" (5)","s"]]]],"f":[["(5)","Bukhaari and Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.276). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.214)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضورؐ نے ہمیں قریش کے ایک تجارتی قافلے پر حملہ کرنے کے لیے بھیجا اور حضرت ابوعبیدہؓ کو ہمارا امیر بنایا اور حضورؐ نے کھجوروں کا ایک تھیلہ ہمیں زادِ سفر کے لیے دیا۔ دینے کے لیے آپؐ کو اس کے علاوہ اور کچھ نہ ملا۔ حضرت ابوعبیدہؓ ہمیں روزانہ ایک کھجور دیا کرتے۔ راوی کہتے ہیں میں نے حضرت جابرؓ کی خدمت میں عرض کیا کہ آپ لوگ ایک کھجور کا کیا کرتے ہوں گے؟ حضرت جابرؓ نے کہا ہم بچے کی طرح اسے چوستے تھے، پھر اس کے بعد پانی پی لیتے اور ایک دن، ایک رات اسی پر گزار لیتے۔ پھر ہم لاٹھی مار کر درختوں کے پتے جھاڑ لیتے اور انہیں پانی میں بھگو کر کھا لیتے۔ ہم چلتے چلتے سمندر کے کنارے پر پہنچے تو ہمیں دور سے ایک بہت بڑے ٹیلے جیسی کوئی چیز نظر آئی۔ ہم نے وہاں پہنچ کر دیکھا تو وہ عنبر نامی بہت بڑی مچھلی تھی۔ پہلے تو حضرت ابوعبیدہؓ نے کہا یہ مردار ہے، اسے مت کھاؤ، پھر فرمایا اچھا نہیں، ہم تو ",""],["ٱللَّٰه","a"],[" کے رسولؐ کے بھیجے ہوئے ہیں اور ",""],["ٱللَّٰه","a"],[" کے راستے میں ہیں اور تم لوگ حالتِ اضطرار کو پہنچ چکے ہو (جس میں مردار حلال ہو جاتا ہے)، اس لیے اسے کھا لو۔ ہم تین سو آدمی تھے، ایک مہینہ تک اس کا گوشت کھاتے رہے یہاں تک کہ ہم موٹے ہو گئے اور اس کی آنکھ کے حلقہ میں سے بڑے بڑے مٹکے بھر کر چربی نکالتے تھے اور بیل جتنے بڑے اس کے گوشت کے ٹکڑے کاٹتے تھے اور حضرت ابوعبیدہؓ نے اس کی آنکھ کے حلقے میں چربی نکالنے کے لیے تیرہ آدمی داخل کیے تھے اور اس کا ایک کانٹا لے کر اسے کھڑا کیا اور سب سے لمبے اونٹ پر کجاوہ کس کر اس پر آدمی بٹھا کر اسے اس کانٹے کے نیچے سے گزارا تو وہ گزر گیا اور اس کے گوشت کے بڑے بڑے ٹکڑے ہم نے واپسی کے سفر میں اپنے ساتھ رکھ لیے۔ جب ہم مدینہ پہنچے تو حضورؐ کی خدمت میں حاضر ہو کر ہم لوگوں نے مچھلی کا سارا واقعہ ذکر کیا۔ حضورؐ نے فرمایا یہ وہ روزی ہے جو ",""],["ٱللَّٰه","a"],[" نے اپنے غیبی خزانے سے تمہیں عطا فرمائی ہے۔ ہمیں کھلانے کے لیے کیا اس مچھلی کا گوشت تم لوگوں کے پاس ہے؟ اس پر ہم نے حضورؐ کی خدمت میں کچھ گوشت بھیجا جسے آپؐ نے نوش فرمایا (آپؐ نے یہ گوشت اس لیے کھایا کہ یہ گوشت برکت والا تھا اور تاکہ صحابہ کو یہ بھی معلوم ہو جائے کہ یہ مچھلی مردار نہیں تھی بلکہ حلال تھی، مچھلی کو ذبح کرنے کی ضرورت نہیں)۔",""],[" (6)","s"]]]],"f":[["(6)","Bayhaqi, Muslim and Abu Dawood, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.276). Ibn Sa'd (Vol.3 Pg.411) has reported a shorter narration."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں ایک آدمی اپنے گھر میں داخل ہوا۔ جب اس نے گھر میں فقر و فاقہ کی حالت دیکھی تو وہ جنگل کی طرف چلا گیا۔ جب اس کی بیوی نے یہ دیکھا تو وہ اٹھی اور چکی کا اوپر والا پاٹ نیچے والے پر رکھا اور پھر تندور میں آگ جلائی، پھر دعا مانگی اے ",""],["ٱللَّٰه","a"],["! ہمیں روزی عطا فرما۔ وہ عورت کیا دیکھتی ہے کہ بڑا پیالہ آٹے سے بھرا ہوا ہے اور پھر جا کر تندور کو دیکھا تو وہ روٹیوں سے بھرا ہوا تھا۔ اتنے میں اس کا خاوند بھی واپس آ گیا۔ اس نے پوچھا کیا میرے بعد تمہیں کچھ ملا؟ اس کی بیوی نے کہا ہاں۔ ہمارے رب کی طرف سے کچھ آیا ہے۔ وہ مرد اٹھا اور اس نے چکی کا اوپر والا پاٹ اٹھا لیا (پھر چکی کا چلنا بند ہو گیا)۔ کسی نے جا کر اس بات کا حضورؐ سے ذکر کیا۔ حضورؐ نے فرمایا غور سے سنو! اگر یہ چکی کا پاٹ نہ اٹھاتا تو یہ چکی قیامت تک چلتی رہتی۔ دوسری روایت میں ہے کہ اس عورت نے یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! ہمیں وہ چیز عطا فرما جسے ہم پیسیں اور گوندھیں اور اس کی روٹی پکائیں۔ پھر اس نے دیکھا کہ بڑا پیالہ روٹیوں سے بھرا ہوا ہے اور چکی آٹا پیس رہی ہے اور تندور بھنی ہوئی چانپوں سے بھرا ہوا ہے۔ پھر اس کے خاوند نے آ کر پوچھا تمہارے پاس کچھ ہے؟ اس کی بیوی نے کہا ",""],["ٱللَّٰه","a"],[" نے روزی عطا فرمائی ہے۔ خاوند نے چکی کا پاٹ اٹھایا، چکی کے اردگرد کی جگہ کو اچھی طرح صاف کیا۔ حضورؐ کو جب معلوم ہوا تو آپؐ نے فرمایا اگر یہ چکی کو اپنے حال پر رہنے دیتے تو چکی قیامت تک پیستی رہتی۔",""],[" (7)","s"]]]],"f":[["(7)","Ahmad."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں ایک انصاری بہت ہی ضرورت مند اور غریب تھا۔ اس کے گھر والوں کے پاس کچھ نہیں تھا۔ وہ گھر سے باہر چلا گیا۔ اس کی بیوی نے اپنے دل میں کہا اگر میں چکی چلاؤں اور تندور میں کھجور کی ٹہنیاں ڈال کر آگ جلاؤں تو میرے پڑوسی چکی کی آواز سنیں گے اور دھواں دیکھیں گے، اس سے وہ یہ سمجھیں گے کہ ہمارے پاس کھانے کو کچھ ہے اور ہمارے ہاں فقر و فاقہ نہیں ہے۔ اس نے اٹھ کر تندور میں آگ جلائی اور بیٹھ کر چکی چلانے لگی۔ اتنے میں اس کا خاوند آ گیا اور اس نے باہر سے چکی کی آواز سنی، پھر دروازہ کھٹکھٹایا۔ بیوی نے کھڑے ہو کر دروازہ کھولا۔ خاوند نے پوچھا تم کیا پیس رہی ہو؟ بیوی نے ساری کارگزاری سنائی۔ وہ دونوں اندر گئے تو دیکھا کہ چکی خود بخود چل رہی ہے اور اس کے اندر سے آٹا نکل رہا ہے۔ بیوی برتنوں میں آٹا بھرنے لگی تو گھر کے سارے برتن آٹے سے بھر گئے۔ پھر اس نے باہر جا کر تندور کو دیکھا تو وہ روٹیوں سے بھرا ہوا تھا۔ خاوند نے جا کر حضورؐ کو سارا واقعہ سنایا۔ حضورؐ نے پوچھا پھر چکی کا کیا ہوا؟ خاوند نے کہا میں نے اسے اٹھا کر جھاڑ دیا تھا۔ حضورؐ نے فرمایا اگر تم چکی کو اس کے حال پر رہنے دیتے تو وہ میری زندگی تک یونہی چلتی رہتی یا فرمایا تمہاری زندگی تک یونہی چلتی رہتی۔",""],[" (8)","s"]]]],"f":[["(8)","Ahmad, Bazzaar and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.256). Bayhaqi has reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.119)."]]},{"b":[["n",[["حضرت ابوبکرؓ","b"],[" فرماتے ہیں میں حضورؐ کے ساتھ مکہ سے چلا۔ چلتے چلتے ہم عرب کے ایک قبیلہ کے پاس پہنچے۔ قبیلہ کے کنارے کے ایک گھر پر حضورؐ کی نگاہ پڑی۔ حضورؐ وہاں تشریف لے گئے۔ جب ہم وہاں پہنچ کر سواریوں سے نیچے اترے تو وہاں صرف ایک عورت تھی۔ اس عورت نے کہا اے ",""],["ٱللَّٰه","a"],[" کے بندے! میں عورت ذات ہوں، میرے ساتھ اور کوئی نہیں ہے، اکیلی ہوں۔ آپ لوگ مہمان بننا چاہتے ہیں تو قبیلہ کے سردار کے پاس چلے جائیں۔ حضورؐ نے اس کی یہ بات قبول نہ فرمائی بلکہ وہیں ٹھہر گئے۔ شام کا وقت تھا، تھوڑی دیر میں اس عورت کا بیٹا اپنی بکریاں ہانکتا ہوا آیا۔ اس عورت نے بیٹے سے کہا اے بیٹے! یہ بکری اور چھری ان دو آدمیوں کے پاس لے جاؤ اور ان سے کہو میری والدہ کہہ رہی ہیں یہ بکری ذبح کر کے آپ دونوں خود بھی کھائیں اور ہمیں بھی کھلائیں۔ جب وہ لڑکا آیا تو حضورؐ نے اس سے فرمایا چھری لے جاؤ اور (دودھ نکالنے کے لیے) پیالہ لے آؤ۔ اس لڑکے نے کہا یہ بکری تو چراگاہ سے دور رہی تھی اور اس کا دودھ بھی نہیں ہے۔ حضورؐ نے فرمایا نہیں، تم جاؤ۔ وہ جا کر پیالہ لے آیا۔ حضورؐ نے اس کے تھن پر ہاتھ پھیر کر دودھ نکالنا شروع کیا تو اتنا دودھ نکلا کہ سارا پیالہ بھر گیا۔ حضورؐ نے فرمایا جا کر اپنی والدہ کو دے آؤ۔ چنانچہ اس کی ماں نے خوب سیر ہو کر دودھ پیا۔ وہ پیالہ لے آیا۔ حضورؐ نے فرمایا یہ بکری لے جا اور دوسری بکری لے آ۔ وہ دوسری بکری لے آیا۔ حضورؐ نے اس کا دودھ نکال کر مجھے پلایا۔ پھر وہ لڑکا تیسری بکری لے آیا۔ اس کا دودھ نکال کر حضورؐ نے خود پیا۔ پھر وہ رات ہم نے وہاں گزاری اور صبح وہاں سے آگے چلے۔ اس عورت نے آپؐ کا نام مبارک رکھ دیا تھا۔ پھر ",""],["ٱللَّٰه","a"],[" نے اس کی بکریوں میں خوب برکت ڈالی اور وہ بیچنے کے لیے بکریوں کا ریوڑ لے کر مدینہ آئی۔ میرا وہاں سے گزر ہوا تو اس عورت کے بیٹے نے دیکھ کر مجھے پہچان لیا اور کہنے لگا اے اماں جان! یہ آدمی وہی ہے جو اس مبارک ہستی کے ساتھ تھا۔ وہ عورت کھڑی ہو کر میرے پاس آئی اور کہنے لگی اے ",""],["ٱللَّٰه","a"],[" کے بندے! وہ مبارک آدمی جو تمہارے ساتھ تھا وہ کون تھا؟ میں نے کہا اچھا! تمہیں معلوم نہیں کہ وہ کون ہیں؟ اس عورت نے کہا نہیں۔ میں نے کہا وہ تو نبی کریمؐ ہیں۔ اس نے کہا مجھے ان کے پاس لے چلو۔ چنانچہ اسے حضورؐ کی خدمت میں لے گیا۔ حضورؐ نے انہیں کھانا کھلایا، درہم دینار دیے اور ہدیہ میں اسے پنیر اور دیہاتیوں والا سامان دیا، پہننے کے کپڑے بھی دیے اور وہ مسلمان بھی ہو گئی۔",""],[" (9)","s"]]]],"f":[["(9)","Bayhaqi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.330)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں میں عقبہ بن ابی معیط کی بکریاں چرا رہا تھا۔ حضورؐ اور حضرت ابوبکرؓ میرے پاس سے گزرے۔ حضورؐ نے فرمایا اے لڑکے! کیا دودھ ہے؟ میں نے کہا ہے لیکن یہ بکریاں اور ان کا دودھ میرے پاس بطور امانت ہے اور میں امانتدار ہوں (مالک کی اجازت کے بغیر دودھ نہیں دے سکتا)۔ حضورؐ نے فرمایا کیا ایسی کوئی بکری ہے جو اب تک بیاہی نہ گئی ہو؟ (وہ لے آؤ)۔ میں ایسی بکری حضورؐ کی خدمت میں لے آیا۔ حضورؐ نے اس کے تھن پر ہاتھ پھیرا تو اس کے تھن میں دودھ اتر آیا۔ حضورؐ نے ایک برتن میں اس کا دودھ نکالا، خود پیا اور حضرت ابوبکرؓ کو پلایا۔ پھر آپؐ نے تھن کو فرمایا سکڑ جاؤ تو وہ سکڑ گیا۔ حضرت ابن مسعودؓ فرماتے ہیں میں اس کے بعد حضورؐ کی خدمت میں آیا اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے بھی یہ کام سکھا دیں۔ آپؐ نے میرے سر پر ہاتھ پھیر کر فرمایا ",""],["ٱللَّٰه","a"],[" تجھ پر رحم فرمائے، تو تو سیکھا سکھایا ہے۔ بیہقی میں اس جیسی روایت میں یہ ہے کہ میں حضورؐ کی خدمت میں بکری کا ایک بچہ لایا جس کی عمر ایک سال سے کم تھی۔ آپؐ نے اس کی ٹانگ کو اپنی ٹانگ سے دبایا، پھر آپؐ نے اس کے تھن پر ہاتھ پھیرا اور دعا فرمائی۔ حضرت ابوبکرؓ آپؐ کے پاس ایک پیالہ لائے۔ آپؐ نے اس میں دودھ نکالا، پھر حضرت ابوبکرؓ کو وہ دودھ پلایا، اس کے بعد آپؐ نے خود پیا۔",""],[" (10)","s"]]]],"f":[["(10)","Ahmad. Bayhaqi has reported the second narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.102)."]]},{"b":[["n",[["حضرت خبابؓ","b"],[" فرماتے ہیں حضورؐ نے ہمیں ایک لشکر میں بھیجا۔ اس سفر میں ہمیں بہت سخت پیاس لگی اور ہمارے پاس پانی بالکل نہیں تھا۔ اتنے میں ہمارے ایک ساتھی کی اونٹنی بیٹھ گئی اور اس کے تھن دودھ سے اتنے بھر گئے کہ مشکیزہ کی طرح نظر آنے لگے۔ پھر ہم نے اس کا دودھ خوب پیا۔",""],[" (11)","s"]]]],"f":[["(11)","Tabraani; Haythami (Vol.6 Pg.210) has commented on the chain of narrators."]]},{"b":[["n",[["حجیر بن ابی اہاب کی باندی ",""],["حضرت ماویہؓ","b"],[" جو کہ بعد میں مسلمان ہو گئی تھیں وہ فرماتی ہیں حضرت خبیبؓ کو میرے گھر میں قید کیا گیا تھا۔ ایک دفعہ میں نے دروازے کی درز سے جھانکا تو ان کے ہاتھ میں انسان کے سر کے برابر انگور کا ایک خوشہ تھا جس میں سے وہ کھا رہے تھے۔ میرے علم میں اس وقت روئے زمین پر کہیں بھی کھانے کے لیے انگور نہیں تھے۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Is'haaq, as quoted in Isaabah (Vol.1 Pg.419)."]]},{"b":[["n",[["حضرت سالم بن ابی الجعدؓ","b"],[" فرماتے ہیں حضورؐ نے اپنے کسی کام کے لیے دو آدمی بھیجے۔ ان دونوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہمارے پاس زادِ راہ بالکل نہیں ہے۔ حضورؐ نے فرمایا ایک مشک ڈھونڈ کر میرے پاس لاؤ۔ وہ دونوں حضورؐ کی خدمت میں ایک مشک لے آئے۔ حضورؐ نے ہمیں حکم دیا کہ اسے (پانی سے) بھر دو۔ ہم نے اسے پانی سے بھر دیا۔ پھر حضورؐ نے اس کے منہ کو رسی سے باندھ دیا اور فرمایا اسے لے جاؤ۔ جب تم چلتے چلتے فلاں جگہ پہنچو گے تو وہاں تمہیں ",""],["ٱللَّٰه","a"],[" غیب سے روزی دیں گے۔ چنانچہ وہ دونوں چل پڑے اور جب چلتے چلتے دونوں حضورؐ کی بتائی ہوئی جگہ پر پہنچے تو مشک کا منہ خود بخود کھل گیا۔ انہوں نے دیکھا تو مشک (پانی کی بجائے) بکری کے دودھ اور مکھن سے بھری ہوئی تھی۔ انہوں نے پیٹ بھر کر مکھن کھایا اور دودھ پیا۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Sa'd (Vol.1 Pg.172)."]]}]},"266":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن سلامؓ","b"],[" فرماتے ہیں حضرت عثمانؓ اپنے گھر میں محصور تھے۔ میں سلام کرنے کے لیے حضرت عثمانؓ کی خدمت میں اندر گیا تو آپؓ نے فرمایا خوش آمدید ہو میرے بھائی کو، میں نے آج رات اس کھڑکی میں حضورؐ کو دیکھا تھا۔ آپؐ نے فرمایا اے عثمان! ان لوگوں نے تمہارا محاصرہ کر رکھا ہے؟ میں نے کہا جی ہاں۔ پھر فرمایا انہوں نے تمہیں پیاسا رکھا ہوا ہے؟ میں نے کہا جی ہاں۔ پھر حضورؐ نے پانی کا ایک ڈول لٹکایا جس میں سے میں نے خوب سیر ہو کر پیا اور اب بھی میں اس کی ٹھنڈک اپنے سینے اور کندھوں کے درمیان محسوس کر رہا ہوں۔ پھر آپؐ نے مجھ سے فرمایا اگر تم چاہو (تو ",""],["ٱللَّٰه","a"],[" کی طرف سے) تمہاری مدد کی جائے اور اگر تم چاہو تو ہمارے پاس افطار کر لو۔ میں نے ان دونوں باتوں میں سے افطار کو اختیار کر لیا۔ چنانچہ اسی دن آپؓ کو شہید کر دیا گیا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Dunya, as quoted in Al Bidaayah wan Nihaayah (Vol.7 Pg.182)."]]},{"b":[["n",[["حضرت ام شریکؓ کا قصہ گزر چکا ہے کہ وہ سوئیں تو خواب میں دیکھا کہ کوئی انہیں پانی پلا رہا ہے۔ جب وہ سو کر اٹھیں تو سیراب تھیں۔",""]]]],"f":[]}]},"267":{"lead":[],"stories":[{"b":[["n",[["حضرت مقدادؓ کی بیوی ",""],["حضرت ضباعہ بنت زبیرؓ","b"],[" فرماتی ہیں لوگ دو یا تین دن کے بعد قضائے حاجت کے لیے جاتے تھے (کیونکہ کھانے کو ملتا نہیں تھا اور جو کھانے کو ملتا تھا وہ ایسا خشک ہوتا تھا کہ) اونٹ کی طرح مینگنی کیا کرتے تھے۔ ایک دن حضرت مقدادؓ قضائے حاجت کے لیے گئے۔ بقیع الغرقد میں حجبہ مقام میں ایک بے آباد جگہ قضائے حاجت کے لیے بیٹھ گئے۔ اتنے میں ایک بڑا سا چوہا ایک دینار اپنے بل میں سے باہر لایا اور ان کے سامنے رکھ کر اپنے بل میں چلا گیا اور ایک ایک دینار لاتا رہا یہاں تک کہ سترہ (17) دینار ہو گئے۔ حضرت مقدادؓ وہ سترہ دینار لے کر حضورؐ کی خدمت میں حاضر ہوئے اور سارا واقعہ عرض کیا۔ حضورؐ نے پوچھا کیا تم نے اپنا ہاتھ بل میں داخل کیا تھا؟ حضرت مقدادؓ نے کہا نہیں، اس ذات کی قسم جس نے آپ کو حق دے کر بھیجا! حضورؐ نے فرمایا (چونکہ یہ دینار تم نے اپنی محنت سے حاصل نہیں کیے ہیں بلکہ ",""],["ٱللَّٰه","a"],[" نے اپنی قدرت سے غیبی خزانے سے دیے ہیں، اس لیے) ان دیناروں میں خمس دینا تم پر لازم نہیں آتا۔ ",""],["ٱللَّٰه","a"],[" تمہیں ان دیناروں میں برکت عطا فرمائے۔ حضرت ضباعہ کہتی ہیں ",""],["ٱللَّٰه","a"],[" نے ان دیناروں میں بہت برکت عطا فرمائی اور وہ اس وقت ختم ہوئے جب میں نے حضرت مقدادؓ کے گھر میں چاندی کے درہموں کی بوریاں دیکھیں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Dalaa'il (Pg.165)."]]},{"b":[["n",[["حضرت سائب بن اقرعؓ","b"],[" کو حضرت عمرؓ نے مدائن کا گورنر بنایا۔ ایک مرتبہ وہ کسریٰ کے ایوان میں بیٹھے ہوئے تھے، ان کی نظر دیوار پر بنی ہوئی ایک تصویر پر پڑی جو اپنی انگلی سے ایک جگہ کی طرف اشارہ کر رہی تھی۔ حضرت سائبؓ فرماتے ہیں میرے دل میں یہ خیال آیا کہ یہ کسی خزانے کی طرف اشارہ کر رہی ہے۔ چنانچہ میں نے اس جگہ کو کھودا تو بہت بڑا خزانہ وہاں سے نکل آیا۔ میں نے خط لکھ کر حضرت عمرؓ کو خزانہ ملنے کی خبر دی اور یہ بھی لکھا کہ یہ خزانہ ",""],["ٱللَّٰه","a"],[" نے میری محنت سے مجھے دیا ہے، اس میں کسی مسلمان نے میری مدد نہیں کی ہے (لہٰذا یہ خزانہ میرا ہونا چاہیے)۔ حضرت عمرؓ نے جواب میں لکھا بے شک یہ خزانہ ہے تو تمہارا لیکن تم ہو مسلمانوں کے امیر، اس لیے اسے مسلمانوں میں تقسیم کر دو۔",""],[" (2)","s"]]]],"f":[["(2)","Khateeb, as quoted in Kanzul Ummaal (Vol.3 Pg.305)."]]},{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں مہرجان کی فتح میں حضرت سائبؓ شریک ہوئے تھے اور ہرمزان کے محل میں داخل ہوئے تو انہیں پتھر اور چونے کی ہرنی نظر آئی جس نے اپنا ہاتھ آگے بڑھایا ہوا تھا۔ وہ کہنے لگے میں ",""],["ٱللَّٰه","a"],[" کی قسم کھا کر کہتا ہوں کہ یہ کسی قیمتی خزانے کی طرف اشارہ کر رہی ہے۔ انہوں نے اس جگہ کو دیکھا تو انہیں وہاں ہرمزان کا خزانہ مل گیا جس میں بہت قیمتی جواہرات والی تھیلی بھی تھی۔",""],[" (3)","s"]]]],"f":[["(3)","Isaabah (Vol.2 Pg.8)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن یزید بن جابرؒ","b"],[" کہتے ہیں حضرت ابوامامہؓ کی ایک باندی (جو کہ پہلے عیسائی تھیں انہوں) نے مجھے یہ واقعہ بیان کیا کہ حضرت ابوامامہ کو دوسروں پر خرچ کرنا بہت پسند تھا اور وہ اس کے لیے مال جمع کیا کرتے تھے اور کسی سائل کو خالی ہاتھ واپس نہیں کرتے تھے اور کچھ نہ ہوتا تو ایک پیاز یا ایک کھجور یا کھانے کی کوئی چیز ہی دے دیتے۔ ایک دن ایک سائل ان کے پاس آیا۔ اس وقت ان کے پاس ان میں سے کوئی چیز نہیں تھی، صرف تین دینار تھے۔ اس سائل نے مانگا تو ایک دینار اسے دے دیا۔ پھر دوسرا آیا تو ایک دینار اسے دے دیا۔ پھر تیسرا آیا تو ایک اسے دے دیا۔ جب تینوں دے دیے تو مجھے غصہ آ گیا۔ میں نے کہا آپ نے ہمارے لیے کچھ بھی نہیں چھوڑا۔ پھر وہ دوپہر کو آرام کرنے لیٹ گئے۔ جب ظہر کی اذان ہوئی تو میں نے انہیں اٹھایا۔ وہ وضو کر کے اپنی مسجد چلے گئے۔ چونکہ ان کا روزہ تھا، اس لیے مجھے ان پر ترس آ گیا اور میرا غصہ اتر گیا۔ پھر میں نے قرض لے کر ان کے لیے رات کا کھانا تیار کیا اور شام کو ان کے لیے چراغ بھی جلایا۔ پھر میں چراغ ٹھیک کرنے کے لیے ان کے بستر کے پاس گئی اور بستر اٹھایا تو اس کے نیچے سونے کے دینار رکھے ہوئے تھے۔ میں نے انہیں گنا تو وہ پورے تین سو تھے۔ میں نے کہا چونکہ اتنے دینار رکھے ہوئے تھے اس وجہ سے انہوں نے تین دینار کی سخاوت کی ہے۔ پھر وہ عشاء کے بعد گھر واپس آئے تو دسترخوان اور چراغ دیکھ کر مسکرائے اور کہنے لگے معلوم ہوتا ہے یہ سب کچھ ",""],["ٱللَّٰه","a"],[" کے ہاں سے آیا ہے (کیونکہ ان کا خیال تھا کہ گھر میں کچھ بھی نہیں تھا، اس لیے نہ کھانا ہوگا نہ چراغ)۔ میں نے کھڑے ہو کر انہیں کھانا کھلایا، پھر میں نے کہا ",""],["ٱللَّٰه","a"],[" آپ پر رحم فرمائے، آپ اتنے سارے دینار یوں ہی چھوڑ گئے جہاں سے ان کے گم ہونے کا خطرہ تھا، مجھے بتایا بھی نہیں کہ اٹھا کر رکھ لیتی۔ کہنے لگے کونسے دینار؟ میں تو کچھ بھی نہیں چھوڑ کر گیا۔ پھر میں نے بستر اٹھا کر انہیں وہ دینار دکھائے۔ دیکھ کر وہ خوش بھی ہوئے اور بہت حیران بھی ہوئے (کہ ",""],["ٱللَّٰه","a"],[" نے اپنے غیبی خزانے سے عطا فرمائے ہیں)۔ یہ دیکھ کر میں بھی بہت متاثر ہوئی اور میں نے کھڑے ہو کر زنار کاٹ ڈالا (زنار اس دھاگے یا زنجیر کو کہتے ہیں جسے عیسائی کمر میں باندھتے تھے) اور مسلمان ہو گئی۔ حضرت ابن جابر کہتے ہیں میں نے اس باندی کو حمص کی مسجد میں دیکھا کہ وہ عورتوں کو قرآن، فرائض اور سنتیں سکھا رہی تھی اور دین کی باتیں سمجھا رہی تھی۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya (Vol.10 Pg.129)."]]}]},"268":{"lead":[],"stories":[{"b":[["n",[["حضرت سلمان فارسیؓ","b"],[" غلام تھے۔ انہیں ان کے مالک نے مکاتب بنا دیا یعنی یہ کہہ دیا کہ اتنا مال کما کر یا کسی اور طرح لا کر دے دو گے تو تم آزاد ہو جاؤ گے۔ وہ بدلِ کتابت یعنی اتنا مال نہ ادا کر سکے اور اسی دوران وہ مسلمان ہو گئے۔ وہ لمبی حدیث میں اپنے اسلام لانے کا قصہ بیان کرتے ہیں اور فرماتے ہیں کہ مالِ کتابت میرے ذمہ رہ گیا۔ پھر ایک کان سے حضورؐ کے پاس مرغی کے انڈے کے برابر سونا آیا۔ حضورؐ نے فرمایا اس فارسی مکاتب کا کیا ہوا؟ لوگوں نے مجھے بتایا کہ حضورؐ تمہیں یاد کر رہے ہیں تو میں آپؐ کی خدمت میں حاضر ہوا۔ آپؐ نے فرمایا اے سلمان! یہ لے لو اور جتنا مال تمہارے ذمہ ہے اس سے ادا کر دو۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! یہ تو تھوڑا سا ہے، میرے ذمہ جتنا مال ہے وہ کیسے ادا ہو سکتا ہے؟ آپؐ نے فرمایا یہ لے لو، ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے سارا ادا کرا دیں گے۔ میں نے وہ سونا لیا اور اپنے مالک کو تول تول کر دینے لگا۔ اس ذات کی قسم جس کے قبضہ میں سلمان کی جان ہے! چالیس اوقیہ میرے ذمہ تھے، وہ سارے کے سارے اس سے ادا ہو گئے اور میں آزاد ہو گیا۔ اور ایک روایت میں یہ ہے کہ حضرت سلمانؓ نے فرمایا جب میں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! یہ تو تھوڑا سا ہے، میرے ذمہ جتنا مال ہے وہ اس سے کیسے ادا ہو سکتا ہے؟ حضورؐ نے وہ سونا لے کر اپنی مبارک زبان پر الٹا پلٹا، پھر فرمایا یہ لے لو اور اس سے ان کا حق چالیس اوقیہ سارا ادا کر دو۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.336). Ibn Sa'd (Vol.4 Pg.75) and Bazzaar have also reported a similar narration."]]},{"b":[["n",[["حضرت عروہ بارقیؓ","b"],[" فرماتے ہیں حضورؐ کو ایک قافلہ ملا جو باہر سے سامانِ تجارت لے کر آیا تھا۔ حضورؐ نے مجھے ایک دینار دے کر فرمایا اس کی ہمارے لیے ایک بکری خرید لاؤ۔ میں نے جا کر ایک دینار کی دو بکریاں خریدیں، پھر مجھے ایک آدمی ملا، میں نے اس کے ہاتھ ایک بکری ایک دینار میں بیچ دی، پھر ایک دینار اور ایک بکری لا کر حضورؐ کی خدمت میں پیش کر دی۔ حضورؐ نے خوش ہو کر مجھے یہ دعا دی کہ ",""],["ٱللَّٰه","a"],[" تیرے ہاتھ کے سودے میں برکت عطا فرمائے۔ حضرت عروہؓ فرماتے ہیں (کوفہ کے مشہور) بازار کناسہ میں میں کاروبار کے لیے اٹھتا ہوں اور گھر جانے سے پہلے چالیس ہزار نفع کما لیتا ہوں (یہ حضورؐ کی دعا کی برکت ہے)۔ حضرت سعید بن زید کی روایت میں ہے کہ میں نے اپنے آپ کو دیکھا کہ کوفہ کے کناسہ بازار میں کھڑا ہوا اور گھر جانے سے پہلے چالیس دینار نفع کما لیا۔ عبدالرزاق اور ابن ابی شیبہ کی روایت میں ہے کہ حضورؐ نے حضرت عروہؓ کے لیے کاروبار میں برکت کی دعا فرمائی۔ چنانچہ وہ اگر مٹی بھی خریدتے تو اس میں بھی انہیں نفع ہو جاتا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Dalaa'il (Pg.165), as quoted in Isaabah (Vol.2 Pg.476). Abdur Razzaaq and Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.7 Pg.63)."]]},{"b":[["n",[["حضرت ابوعقیلؒ","b"],[" کہتے ہیں مجھے میرا دادا حضرت عبد",""],["ٱللَّٰه","a"],[" بن ہشامؓ بازار لے کر جاتے اور غلہ خریدتے۔ حضرت ابن زبیر اور حضرت عمرؓ کی میرے دادا سے ملاقات ہوتی، وہ دونوں میرے دادا سے فرماتے اپنے کاروبار میں ہمیں بھی شریک کر لیں کیونکہ حضورؐ نے آپ کے لیے برکت کی دعا فرمائی ہے۔ میرے دادا انہیں شریک کر لیتے۔ چنانچہ انہیں اونٹنی جوں کی توں ساری نفع میں مل جاتی جسے وہ گھر بھیج دیتے۔",""],[" (3)","s"]]]],"f":[["(3)","Bukhaari, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.166)."]]}]},"269":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن انیسؓ","b"],[" فرماتے ہیں مستنیر بن رزام یہودی نے شوحط درخت کی ٹیڑھی لاٹھی میرے چہرے پر ماری جس سے میرے سر کی ہڈی ٹوٹ کر اپنی جگہ سے ہٹ گئی اور زخم کا اثر دماغ تک پہنچ گیا۔ میں اسی حالت میں حضورؐ کی خدمت میں حاضر ہوا۔ حضورؐ نے کپڑا ہٹا کر اس پر دم فرمایا تو زخم اور ہڈی وغیرہ سب کچھ ایک دم ٹھیک ہو گیا۔ میں نے دیکھا تو وہاں مجھے کچھ بھی زخم وغیرہ نظر نہ آیا۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani; Haythami (Vol.8 Pg.298) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت شرحبیلؓ","b"],[" فرماتے ہیں میری ہتھیلی میں ایک غدود نکل آیا۔ میں نے حضورؐ کی خدمت میں جا کر عرض کیا اے ",""],["ٱللَّٰه","a"],[" کے نبی! اس غدود کی وجہ سے میرے سارے ہاتھ میں ورم ہو گیا ہے اور میں نہ تلوار کا دستہ پکڑ سکتا ہوں اور نہ سواری کی لگام۔ آپؐ نے فرمایا میرے قریب آ جاؤ۔ میں آپؐ کے قریب ہو گیا۔ آپؐ نے میری ہتھیلی کھول کر اس پر دم فرمایا، پھر آپؐ اپنا ہاتھ اس غدود پر رکھ کر کچھ دیر ملتے رہے۔ جب آپؐ نے ہاتھ ہٹایا تو مجھے غدود کا ذرہ بھی نشان نظر نہ آیا۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani; Haythami (Vol.8 Pg.298) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابیض بن حمال ماربیؓ","b"],[" فرماتے ہیں میرے چہرے پر داد کی بیماری تھی جس نے ناک کو گھیر رکھا تھا۔ حضورؐ نے مجھے بلایا اور میرے چہرے پر اپنا دستِ مبارک پھیرا تو شام تک اس بیماری کا کچھ بھی اثر باقی نہ رہا۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Dalaa'il (Pg.223) and Ibn Sa'd (Vol.5 Pg.524)."]]},{"b":[["n",[["حضرت رافع بن خدیجؓ","b"],[" فرماتے ہیں ایک دن میں نبی کریمؐ کی خدمت میں گیا۔ وہاں ایک ہانڈی میں گوشت پک رہا تھا۔ چربی کا ایک ٹکڑا مجھے بہت اچھا لگا۔ میں نے اسے لیا اور کھا کر نگل گیا اور اس کی وجہ سے میں سال بھر بیمار رہا۔ پھر میں نے اس کا حضورؐ سے تذکرہ کیا۔ آپؐ نے فرمایا اس چربی کو سات انسانوں کی نظر لگی ہوئی تھی۔ پھر آپؐ نے میرے پیٹ پر ہاتھ پھیرا جس کی برکت سے ",""],["ٱللَّٰه","a"],[" تعالیٰ نے چربی کا وہ ٹکڑا میرے پیٹ سے نکال دیا اور اس ذات کی قسم جس نے حضورؐ کو حق دے کر بھیجا! اس کے بعد آج تک میرے پیٹ میں کوئی تکلیف نہیں ہوئی۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Dalaa'il (Pg.223)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں ایک دفعہ میں بیمار ہوا۔ نبی کریمؐ کا میرے پاس سے گزر ہوا۔ اس وقت میں یہ دعا مانگ رہا تھا اے ",""],["ٱللَّٰه","a"],["! اگر میری موت کا وقت آ گیا ہے تو مجھے موت دے کر راحت عطا فرما اور اگر اس میں دیر ہے تو پھر مجھے شفاء عطا فرما اور اگر آزمائش ہی مقصود ہے تو پھر مجھے صبر کی توفیق عطا فرما۔ حضورؐ نے فرمایا تم نے کیا کہا؟ میں نے اپنی دعا دہرا دی۔ آپؐ نے مجھے اپنا پاؤں مار کر فرمایا اے ",""],["ٱللَّٰه","a"],["! اسے شفاء عطا فرما! اس دعا کے بعد یہ بیماری مجھے کبھی نہیں ہوئی۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Dalaa'il (Pg.161)."]]},{"b":[["n",[["جلد اول میں صفحہ 73 پر دعوت کے بارے میں ",""],["حضرت سہلؓ","b"],[" کی حدیث گزر چکی ہے کہ غزوۂ خیبر کے دن حضرت علیؓ کی آنکھیں دکھ رہی تھیں۔ حضورؐ نے ان کی آنکھوں پر دم فرمایا تو اسی وقت ان کی آنکھیں ٹھیک ہو گئیں اور اس کے بعد کبھی دکھنے نہ آئیں۔ اور نصرت کے باب میں ابورافع کے قتل کے قصہ میں جلد اول میں صفحہ 497 پر حضرت براءؓ کی حدیث گزر چکی ہے کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن عتیکؓ فرماتے ہیں کہ اس واقعہ میں میری ٹانگ ٹوٹ گئی تھی۔ جب میں نبی کریمؐ کی خدمت میں پہنچا تو میں نے آپؐ کو بتایا۔ آپؐ نے فرمایا اپنی ٹانگ پھیلاؤ۔ میں نے ٹانگ پھیلائی۔ آپؐ نے اس پر اپنا دستِ مبارک پھیرا تو وہ ایک دم ایسے ٹھیک ہو گئی کہ گویا اس میں کوئی تکلیف ہی نہیں تھی۔",""]]]],"f":[]},{"b":[["n",[["حضرت حنظلہ بن حذیم بن حنیفہؓ","b"],[" فرماتے ہیں میں اپنے والد حضرت حذیمؓ کے ساتھ ایک وفد کے ہمراہ حضورؐ کی خدمت میں حاضر ہوا۔ میرے والد نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! میرے چند بیٹے ہیں جن میں سے بعض کی داڑھی ہے اور بعض کی نہیں ہے، یہ ان میں سب سے چھوٹا ہے۔ حضورؐ نے مجھے اپنے قریب کیا اور میرے سر پر ہاتھ پھیرا اور فرمایا ",""],["ٱللَّٰه","a"],[" تجھ میں برکت عطا فرمائے۔ حضرت ذیال راوی کہتے ہیں کہ میں نے دیکھا کہ حضرت حنظلہؓ کے پاس وہ آدمی لایا جاتا جس کے چہرے پر ورم ہوتا یا وہ بکری لائی جاتی جس کا تھن سوجا ہوا ہوتا تو وہ فرماتے",""]]],["q",[["بِسْمِ اللّٰهِ عَلٰى مَوْضِعِ كَفِّ رَسُوْلِ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ","a"]]],["p",[["یعنی ",""],["ٱللَّٰه","a"],[" کے نام سے اور حضورؐ نے میرے سر پر جس جگہ ہاتھ پھیرا تھا اس جگہ کی برکت سے۔ پھر اس ورم پر ہاتھ پھیرتے اور وہ ورم اسی وقت ختم ہو جاتا۔ احمد کی ایک روایت میں ہے کہ حضرت ذیال کہتے ہیں میں نے دیکھا کہ حضرت حنظلہؓ کے پاس وہ آدمی لایا جاتا جس کے چہرے پر ورم ہوتا۔ حضرت حنظلہؓ کہتے بسم ",""],["ٱللَّٰه","a"],["، پھر اپنے سر پر اس جگہ ہاتھ پھیرتے جہاں حضورؐ نے ہاتھ رکھا تھا، پھر اپنے ہاتھ پر دم فرماتے، پھر ورم والی جگہ پر اپنا ہاتھ پھیرتے تو ورم اسی وقت چلا جاتا۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani and Ahmad, as quoted in Majma'uz Zawaa'id (Vol.9 Pg.408). Ahmad, Hasan bin Sufyaan, Tabraani, Abu Ya'la, Ya'qoob bin Sufyaan and Minjaneeqi have reported the second narration, as quoted in Isaabah (Vol.1 Pg.359). Ibn Sa'd (Vol.7 Pg.72) has reported a similar narration."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن قرطؓ","b"],[" فرماتے ہیں ایک دفعہ میرا ایک اونٹ چلتے چلتے تھک کر کھڑا ہو گیا۔ میں حضرت خالد بن ولیدؓ کے ساتھ تھا۔ پہلے تو میرا ارادہ ہوا کہ اونٹ کو وہیں چھوڑ دوں لیکن پھر میں نے ",""],["ٱللَّٰه","a"],[" سے دعا کی تو ",""],["ٱللَّٰه","a"],[" نے اونٹ کو اسی وقت ٹھیک کر دیا اور میں اس پر سوار ہو کر چل پڑا۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.185)."]]}]},"270":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوسفرؒ","b"],[" کہتے ہیں حضرت خالد بن ولیدؓ فارس کے ایک گورنر کے ہاں مہمان بنے۔ لوگوں نے ان سے کہا ان عجمی لوگوں سے بچ کے رہنا، کہیں یہ آپ کو زہر نہ پلا دیں۔ انہوں نے فرمایا ذرا وہ زہر میرے پاس لاؤ۔ لوگ زہر لے آئے۔ انہوں نے وہ زہر ہاتھ میں لیا اور بسم ",""],["ٱللَّٰه","a"],[" پڑھ کر سارا نگل گئے۔ ان پر زہر کا کچھ بھی اثر نہ ہوا۔ اصابہ کی روایت میں یہ ہے کہ زہر حضرت خالدؓ کے پاس لایا گیا۔ انہوں نے اسے اپنی ہتھیلی پر رکھا اور بسم ",""],["ٱللَّٰه","a"],[" پڑھ کر اسے پی گئے۔ ان پر اس کا کچھ بھی اثر نہ ہوا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Ya'la and Tabraani, as quoted in Majma'uz Zawaa'id (Vol.9 Pg.350). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.159). Abu Ya'la has reported the second narration, as quoted in Isaabah (Vol.1 Pg.414)."]]},{"b":[["n",[["حضرت ذی الجوشن ضبابیؓ","b"],[" وغیرہ حضرات فرماتے ہیں (عمرو) ابن بقیلہ کے ساتھ اس کا ایک خادم تھا جس کی پیٹی میں ایک تھیلی لٹکی ہوئی تھی۔ حضرت خالدؓ نے وہ تھیلی لی اور اس میں جو کچھ تھا وہ اپنی ہتھیلی پر ڈالا اور عمرو سے کہا اے عمرو! یہ کیا ہے؟ اس نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! یہ ایسا زہر ہے جو انسان کو فوراً مار دیتا ہے۔ حضرت خالدؓ نے کہا تم نے زہر اپنے ساتھ کیوں رکھا ہوا ہے؟ اس نے کہا مجھے یہ خطرہ تھا کہ آپ لوگوں کو میری رائے کے خلاف فتح مل جائے گی تو میں اس سے پہلے ہی زہر کھا کر مر جاؤں گا کیونکہ یوں خود کشی کر لینا مجھے اپنی قوم اور اپنے شہر والوں کی ذلت آمیز شکست کا ذریعہ بننے سے زیادہ محبوب ہے۔ حضرت خالدؓ نے فرمایا کوئی انسان اپنے وقت سے پہلے نہیں مر سکتا۔ پھر حضرت خالدؓ نے یہ دعا پڑھی",""]]],["q",[["بِسْمِ اللّٰهِ خَيْرِ الْأَسْمَاءِ رَبِّ الْأَرْضِ وَرَبِّ السَّمَاءِ الَّذِيْ لَيْسَ يَضُرُّ مَعَ اسْمِهٖ دَاءٌ الرَّحْمٰنِ الرَّحِيْمِ","a"]]],["p",[["(",""],["ٱللَّٰه","a"],[" کا نام لے کر میں یہ زہر پیتا ہوں۔ لفظ ",""],["ٱللَّٰه","a"],[" اس کے ناموں میں سب سے بہترین نام ہے جو زمین اور آسمان کا رب ہے اور اس کے نام کے ساتھ کوئی بیماری نقصان نہیں پہنچا سکتی اور وہ نہایت مہربان اور بہت رحم کرنے والا ہے) اس پر لوگ حضرت خالدؓ کو روکنے کے لیے آگے بڑھے لیکن حضرت خالدؓ لوگوں کے آنے سے پہلے ہی جلدی سے وہ زہر پی گئے اور انہیں کچھ بھی نہ ہوا۔ یہ دیکھ کر عمرو نے کہا اے جماعتِ عرب! جب تک تم صحابہؓ میں سے ایک آدمی بھی باقی رہے گا اس وقت تک تم جو چاہو گے حاصل کر لو گے۔ پھر عمرو نے حیرہ والوں کی طرف متوجہ ہو کر کہا میں نے آج جیسا واضح اقبال والا دن نہیں دیکھا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Jareer (Vol.2 Pg.567)."]]}]},"271":{"lead":[],"stories":[{"b":[["n",[["حضرت عبدالرحمٰن بن ابی لیلیٰؒ","b"],[" کہتے ہیں حضرت علیؓ سردیوں میں ایک لنگی اور ایک چادر اوڑھ کر باہر نکلا کرتے تھے اور یہ دونوں کپڑے پتلے ہوتے تھے اور گرمیوں میں موٹے کپڑے اور ایسا جبہ پہن کر نکلا کرتے تھے جس میں روئی بھری ہوئی ہوتی تھی۔ لوگوں نے مجھ سے کہا آپ کے ابا جان رات کو حضرت علیؓ سے باتیں کرتے ہیں، آپ اپنے ابا جان سے کہیں کہ وہ حضرت علیؓ سے اس بارے میں پوچھیں۔ میں نے اپنے والد سے کہا لوگوں نے امیر المومنین کا ایک کام دیکھا ہے جس سے وہ حیران ہیں۔ میرے والد نے کہا وہ کیا ہے؟ میں نے کہا وہ سخت گرمی میں روئی والے جبہ میں اور موٹے کپڑوں میں باہر آتے ہیں اور انہیں گرمی کی کوئی پرواہ نہیں ہوتی اور سخت سردی میں پتلے کپڑوں میں باہر آتے ہیں، نہ انہیں سردی کی کوئی پرواہ ہوتی ہے اور نہ وہ سردی سے بچنے کی کوشش کرتے ہیں تو کیا آپ نے ان سے اس بارے میں کچھ سنا ہے؟ لوگوں نے مجھے کہا ہے کہ آپ جب رات کو ان سے باتیں کریں تو یہ بات بھی ان سے پوچھ لیں۔ چنانچہ جب رات کو میرے والد حضرت علیؓ کے پاس گئے تو ان سے کہا اے امیر المومنین! لوگ آپ سے ایک چیز کے بارے میں پوچھنا چاہتے ہیں۔ حضرت علیؓ نے کہا وہ کیا ہے؟ میرے والد نے کہا آپ سخت گرمی میں روئی والا جبہ اور موٹے کپڑے پہن کر باہر آتے ہیں اور سخت سردی میں دو پتلے کپڑے پہن کر باہر آتے ہیں، نہ آپ کو سردی کی پرواہ ہوتی ہے اور نہ اس سے بچنے کی کوشش کرتے ہیں۔ حضرت علیؓ نے فرمایا اے ابولیلیٰ! کیا آپ خیبر میں ہمارے ساتھ نہیں تھے؟ میرے والد نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! میں آپ لوگوں کے ساتھ تھا۔ حضرت علیؓ نے فرمایا حضورؐ نے پہلے حضرت ابوبکرؓ کو بھیجا، وہ لوگوں کو لے کر قلعہ پر حملہ آور ہوئے لیکن قلعہ فتح نہ ہو سکا، وہ واپس آ گئے۔ حضورؐ نے پھر حضرت عمرؓ کو بھیجا، وہ لوگوں کو لے کر حملہ آور ہوئے لیکن قلعہ فتح نہ ہو سکا، وہ بھی واپس آ گئے۔ اس پر حضورؐ نے فرمایا اب میں جھنڈا ایسے آدمی کو دوں گا جسے ",""],["ٱللَّٰه","a"],[" اور اس کے رسول سے بہت محبت ہے، ",""],["ٱللَّٰه","a"],[" اس کے ہاتھوں فتح نصیب فرمائے گا اور وہ بھگوڑا بھی نہیں ہے۔ چنانچہ حضورؐ نے آدمی بھیج کر مجھے بلایا۔ میں آپؐ کی خدمت میں حاضر ہوا۔ میری آنکھیں دکھ رہی تھیں، مجھے کچھ نظر نہیں آ رہا تھا۔ حضورؐ نے میری آنکھوں پر اپنا لعاب لگایا اور یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! گرمی اور سردی سے اس کی حفاظت فرما۔ اس کے بعد مجھے نہ کبھی گرمی لگی اور نہ کبھی سردی۔ ابونعیم کی روایت میں یہ ہے کہ حضورؐ نے اپنی دونوں ہتھیلیوں پر لعاب لگایا اور پھر دونوں ہتھیلیاں میری آنکھوں پر مل دیں اور یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اس سے گرمی اور سردی دور کر دے۔ اس ذات کی قسم جس نے حضورؐ کو حق دے کر بھیجا ہے! اس کے بعد سے آج تک گرمی اور سردی نے مجھے کچھ تکلیف نہیں پہنچائی۔ طبرانی کی ایک روایت میں یہ ہے کہ حضرت سوید بن غفلہؓ فرماتے ہیں ہماری حضرت علیؓ سے سردیوں میں ملاقات ہوئی۔ انہوں نے صرف دو کپڑے پہنے ہوئے تھے۔ ہم نے ان سے کہا آپ ہمارے علاقہ سے دھوکہ نہ کھائیں، ہمارا علاقہ آپ کے علاقہ جیسا نہیں ہے، یہاں سردی بہت زیادہ پڑتی ہے۔ حضرت علیؓ نے فرمایا مجھے سردی بہت لگا کرتی تھی، جب حضورؐ مجھے خیبر بھیجنے لگے تو میں نے عرض کیا کہ میری آنکھیں دکھ رہی ہیں۔ آپؐ نے میری آنکھوں پر لعاب لگایا اور اس کے بعد مجھے نہ کبھی گرمی لگی اور نہ کبھی سردی اور نہ کبھی میری آنکھیں دکھنے آئیں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Shaybah, Ahmad, Ibn Maajah, Bazzaar, Ibn Jareer, Tabraani, Haakim and Bayhaqi, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.44). Abu Nu'aym has reported it in his Dalaa'il (Pg.166). Tabraani and Bazzaar have reported the narration of Suwayd bin Ghafalah; Haythami (Vol.9 Pg.122-124) has commented on the chains."]]},{"b":[["n",[["حضرت بلالؓ","b"],[" فرماتے ہیں میں نے سردی کی ایک رات میں صبح کی اذان دی لیکن کوئی آدمی نہ آیا۔ میں نے پھر اذان دی لیکن پھر بھی کوئی نہ آیا۔ اس پر حضورؐ نے فرمایا اے بلال! لوگوں کو کیا ہوا؟ میں نے عرض کیا میرے ماں باپ آپ پر قربان ہوں، سردی بہت زیادہ ہے، اس وجہ سے لوگ ہمت نہیں کر رہے ہیں۔ اس پر حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! لوگوں سے سردی دور کر دے۔ حضرت بلالؓ کہتے ہیں پھر میں نے دیکھا کہ لوگ صبح کی نماز میں اور اشراق کی نماز میں بڑے آرام سے آ رہے ہیں، انہیں سردی محسوس نہیں ہو رہی، بلکہ کچھ لوگ تو پنکھا کرتے ہوئے آ رہے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Dalaa'il (Pg.166) and Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.166)."]]}]},"272":{"lead":[],"stories":[{"b":[["n",[["حضرت عمران بن حصینؓ","b"],[" فرماتے ہیں ایک مرتبہ میں حضورؐ کے پاس بیٹھا ہوا تھا کہ اتنے میں حضرت فاطمہؓ آئیں اور آ کر حضورؐ کے سامنے کھڑی ہو گئیں۔ حضورؐ نے فرمایا اے فاطمہ! قریب آ جاؤ۔ وہ قریب آ گئیں۔ حضورؐ نے فرمایا اے فاطمہ! اور قریب آ جاؤ۔ وہ اور قریب آ گئیں۔ حضورؐ نے فرمایا اے فاطمہ! اور قریب ہو جاؤ۔ وہ بالکل قریب ہو کر سامنے کھڑی ہو گئیں۔ میں نے دیکھا کہ ان کے چہرے پر بھوک اور کمزوری کی وجہ سے زردی چھائی ہوئی ہے اور خون کا نام و نشان نہیں ہے (اس وقت تک عورتوں کے لیے پردہ کا حکم نہیں آیا تھا)۔ حضورؐ نے اپنی انگلیاں پھیلا کر ہاتھ ان کے سینے پر رکھا اور سر اٹھا کر یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! اے بھوکوں کا پیٹ بھرنے والے! اے حاجتوں کو پورا کرنے والے! اور اے گرے پڑے لوگوں کو اونچا کرنے والے! محمد کی بیٹی فاطمہ کو بھوکا مت رکھ۔ میں نے دیکھا کہ حضرت فاطمہؓ کے چہرے سے وہ زردی چلی گئی اور خون کی سرخی آ گئی۔ پھر میں نے اس کے بعد حضرت فاطمہؓ سے پوچھا، انہوں نے کہا اے عمران! اس کے بعد مجھے کبھی بھوک نہیں لگی۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani; Haythami (Vol.9 Pg.204) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.166)."]]}]},"273":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوزید انصاریؓ","b"],[" فرماتے ہیں حضورؐ نے مجھ سے فرمایا میرے قریب آ جاؤ۔ آپؐ نے میرے سر پر ہاتھ پھیرا اور یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اسے خوبصورت بنا دے اور پھر اس کی خوبصورتی ہمیشہ باقی رکھ۔ راوی کہتے ہیں حضرت ابوزیدؓ کی عمر سو سال سے زیادہ ہو گئی تھی اور ان کی داڑھی میں تھوڑے سے سفید بال تھے اور ان کا چہرہ کھلا رہتا تھا اور موت تک ان کے چہرے پر جھریاں نہیں پڑی تھیں۔ امام احمد کی ایک روایت میں یہ ہے کہ حضرت ابونہیکؒ کہتے ہیں مجھ سے حضرت ابوزیدؓ نے بیان کیا کہ مجھ سے حضورؐ نے پانی طلب فرمایا۔ میں ایک پیالے میں پانی لے کر حضورؐ کی خدمت میں گیا۔ اس میں ایک بال تھا، وہ میں نے پکڑ کر نکال دیا۔ اس پر حضورؐ نے دعا دی اے ",""],["ٱللَّٰه","a"],["! اسے خوبصورت بنا دے۔ حضرت ابونہیک کہتے ہیں میں نے حضرت ابوزیدؓ کو دیکھا کہ ان کی عمر چورانوے 94 سال ہو چکی تھی اور ان کی داڑھی میں ایک بھی سفید بال نہیں تھا۔ ابونعیم کی روایت میں یہ ہے کہ حضرت ابونہیک کہتے ہیں میں نے انہیں دیکھا کہ ان کی عمر ترانوے 93 سال ہو چکی تھی اور ان کے سر اور داڑھی میں ایک بھی سفید بال نہیں تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.166) and Isaabah (Vol.4 Pg.78). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.164)."]]},{"b":[["n",[["حضرت ابوالعلاءؒ","b"],[" کہتے ہیں حضرت قتادہ بن ملحانؓ کا جس جگہ انتقال ہوا میں اس جگہ ان کے پاس تھا۔ گھر کے پچھلے حصے میں ایک آدمی گزرا، اس کا عکس مجھے حضرت قتادہ کے چہرے میں نظر آیا۔ اس کی وجہ یہ تھی کہ ایک مرتبہ حضورؐ نے ان کے چہرے پر ہاتھ پھیرا تھا (اس کی برکت سے ہر وقت ایسے لگتا تھا کہ ان کے چہرے پر تیل لگا ہوا ہے)۔ اس سے پہلے جب بھی میں نے حضرت قتادہؓ کو دیکھا تو ایسے لگتا تھا کہ ان کے چہرے پر تیل لگا ہوا ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.166)."]]},{"b":[["n",[["حضرت حیان بن عمیرؒ","b"],[" کہتے ہیں ایک مرتبہ نبی کریمؐ نے حضرت قتادہ بن ملحانؓ کے چہرے پر اپنا ہاتھ پھیرا۔ اس کا اثر یہ ہوا کہ جب وہ بہت بوڑھے ہو گئے تھے اور ان کے جسم کے ہر حصے پر بڑھاپے کے آثار ہو گئے تھے تو چہرے پر کوئی اثر نہیں تھا۔ چنانچہ میں وفات کے وقت ان کے پاس تھا۔ ان کے پاس سے ایک عورت گزری تو مجھے اس عورت کا عکس ان کے چہرے میں اس طرح نظر آیا جیسے شیشے میں نظر آتا ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Shaaheen, as quoted in Isaabah (Vol.3 Pg.225)."]]},{"b":[["n",[["حضرت نابغہ جعدیؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو یہ شعر سنایا جو حضورؐ کو بہت پسند آیا۔",""]]],["q",[["بَلَغْنَا السَّمَاءَ مَجْدُنَا وَثَرَانَا ۝ وَإِنَّا لَنَرْجُوْ فَوْقَ ذٰلِكَ مَظْهَرًا","a"]]],["p",[["ہماری بزرگی اور بلندی آسمان تک پہنچ گئی ہے اور ہمیں اس سے بھی اوپر چڑھنے کا یقین ہے۔ حضورؐ نے فرمایا اے ابولیلیٰ! اور اوپر کہاں چڑھنا ہے؟ میں نے کہا جنت میں۔ آپؐ نے فرمایا ٹھیک ہے انشاء ",""],["ٱللَّٰه","a"],["، اور شعر پڑھو۔ پھر میں نے یہ شعر پڑھے",""]]],["q",[["وَلَا خَيْرَ فِيْ حِلْمٍ إِذَا لَمْ يَكُنْ لَّهٗ ۝ بَوَادِرُ تَحْمِيْ صَفْوَهٗ أَنْ يُّكَدَّرَا","a"]]],["q",[["وَلَا خَيْرَ فِيْ جَهْلٍ إِذَا لَمْ يَكُنْ لَّهٗ ۝ حَلِيْمٌ إِذَا مَا أَوْرَدَ الْأَمْرَ أَصْدَرَا","a"]]],["p",[["بردباری میں اس وقت تک خیر نہیں ہو سکتی جب تک کہ جلدی جلدی کیے جانے والے کچھ کام ایسے نہ ہوں جو بردباری کو گدلا ہونے سے بچائیں اور سخت کلامی میں اس وقت تک خیر نہیں ہو سکتی جب تک کہ انسان بردبار نہ ہو کہ وہ جب کوئی کام شروع کرے تو اسے پورا کر کے چھوڑے۔ حضورؐ نے فرمایا تم نے بہت عمدہ شعر کہے ہیں، ",""],["ٱللَّٰه","a"],[" تمہارے دانتوں کو گرنے نہ دے۔ یعلی راوی کہتے ہیں میں نے حضرت نابغہ کو دیکھا کہ ان کی عمر سو سال سے زیادہ ہو چکی تھی لیکن ان کا ایک بھی دانت نہیں گرا تھا۔ حضرت عبد",""],["ٱللَّٰه","a"],[" بن جراد کہتے ہیں بنو جعدہ قبیلہ کے حضرت نابغہؓ کو میں نے یہ فرماتے ہوئے سنا کہ میں نے نبی کریمؐ کو اپنا یہ شعر ",""],["علونا السماء","b"],[" سنایا۔ حضورؐ کو غصہ آ گیا۔ آپؐ نے فرمایا اے ابولیلیٰ! چڑھ کر اوپر کہاں جانا ہے؟ میں نے کہا جنت میں۔ آپؐ نے فرمایا ہاں ٹھیک ہے انشاء ",""],["ٱللَّٰه","a"],["۔ مجھے اپنے اور اشعار سناؤ۔ اس پر میں نے ",""],["ولا خیر فی حلم","b"],[" والے دونوں شعر سنائے تو آپؐ نے مجھ سے فرمایا تم نے بہت اچھے شعر کہے ہیں، ",""],["ٱللَّٰه","a"],[" تمہارے دانتوں کو گرنے نہ دے۔ حضرت عبد",""],["ٱللَّٰه","a"],[" کہتے ہیں میں نے دیکھا تو مجھے حضرت نابغہؓ کے دانت مسلسل گرنے والے اور اولوں کی طرح چمکدار نظر آئے اور نہ کوئی دانت ٹوٹا ہوا تھا اور نہ کوئی مڑا ہوا۔ عاصم لیثی کی روایت میں ہے کہ حضرت نابغہؓ کے دانت عمر بھر بڑے خوبصورت رہے، جب بھی ان کا کوئی دانت گر جاتا تو اس کی جگہ دوسرا نکل آتا اور ان کی عمر بہت زیادہ ہوئی تھی۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Dalaa'il (Pg.164). Bayhaqi and Bazzaar have reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.168). See also Isaabah (Vol.3 Pg.539)."]]}]},"274":{"lead":[],"stories":[{"b":[["n",[["حضرت ام اسحاقؓ","b"],[" فرماتی ہیں میں اپنے بھائی کے ساتھ مدینہ منورہ حضورؐ کی خدمت میں ہجرت کے لیے چلی۔ راستہ میں ایک جگہ پہنچ کر میرے بھائی نے مجھ سے کہا اے ام اسحاق! تم ذرا یہاں بیٹھو، میں اپنا خرچہ مکہ میں بھول آیا ہوں، جا کر لے آتا ہوں۔ میں نے اپنے خاوند کے بارے میں کہا مجھے تم پر اس غنڈے سے خطرہ ہے، تمہیں وہ کہیں قتل نہ کر دے۔ اس نے کہا نہیں، انشاء ",""],["ٱللَّٰه","a"],[" ایسے نہیں ہوگا۔ میں چند دن وہاں ٹھہری رہی، پھر ایک آدمی میرے پاس سے گزرا جسے میں نے پہچان لیا، اب میں اس کا نام نہیں لیتی۔ اس نے کہا اے ام اسحاق! تم یہاں کیوں بیٹھی ہو؟ میں نے کہا میں اپنے بھائی کا انتظار کر رہی ہوں۔ اس نے کہا آج کے بعد سے تمہارا کوئی بھائی نہیں، اسے تمہارے خاوند نے قتل کر دیا ہے۔ میں نے صبر سے کام لیا اور وہاں سے چل دی اور مدینہ پہنچ گئی۔ جب حضورؐ کی خدمت میں پہنچی تو آپؐ وضو کر رہے تھے۔ میں جا کر آپؐ کے سامنے کھڑی ہو گئی اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرا بھائی اسحاق قتل ہو گیا ہے۔ جب بھی میں حضورؐ کو دیکھتی آپؐ وضو کے پانی کی طرف سر جھکا لیتے۔ پھر آپؐ نے پانی لے کر میرے چہرے پر چھڑکا۔ بشار راوی کہتے ہیں میری دادی نے بتایا کہ (حضورؐ کے پانی چھڑکنے کی برکت یہ ہوئی کہ) حضرت ام اسحاق پر جب بھی کوئی مصیبت آتی تو ان کی آنکھوں میں تو آنسو نظر آتے لیکن رخساروں پر نہ گرتے۔ ایک روایت میں ہے کہ حضرت ام اسحاقؓ فرماتی ہیں میں نے روتے ہوئے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! (میرا بھائی) اسحاق قتل ہو گیا ہے تو حضورؐ نے ایک چلو پانی لے کر میرے چہرے پر چھڑکا۔ حضرت ام حکیم کہتی ہیں حضرت ام اسحاقؓ پر بڑی سے بڑی مصیبت بھی آتی تو آنسو ان کی آنکھوں میں نظر آتے لیکن رخسار پر نہ گرتے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Dalaa'il (Pg.168). Bukhaari has reported a similar narration in his Taareekh, as have Samway, Abu Ya'la and others, as quoted in Isaabah (Vol.1 Pg.32 and Vol.4 Pg.430)."]]}]},"275":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضرت عمر بن خطابؓ نے ایک مرتبہ فرمایا آؤ اپنی قوم کی زمین پر چلتے ہیں یعنی ذرا اپنے دیہات دیکھ لیتے ہیں۔ چنانچہ ہم لوگ چل پڑے۔ میں اور حضرت ابی بن کعبؓ جماعت سے کچھ پیچھے رہ گئے تھے۔ اتنے میں ایک بادل تیزی سے آیا اور برسنے لگا۔ حضرت ابیؓ نے دعا مانگی اے ",""],["ٱللَّٰه","a"],["! اس بارش کی تکلیف ہم سے دور فرما دے (چنانچہ ہم بارش میں چلتے رہے لیکن ہماری کوئی چیز بارش سے نہ بھیگی)۔ جب ہم حضرت عمرؓ اور باقی ساتھیوں کے پاس پہنچے تو ان کے جانور، کجاوے اور سامان وغیرہ سب بھیگا ہوا تھا۔ حضرت عمرؓ نے فرمایا ہمیں تو راستہ میں بہت بارش ملی تو کیا آپ لوگوں کو نہیں ملی؟ میں نے کہا ابوالمنذر یعنی حضرت ابیؓ نے ",""],["ٱللَّٰه","a"],[" سے یہ دعا کی تھی کہ اس بارش کی تکلیف ہم سے دور فرما دے۔ حضرت عمرؓ نے فرمایا تم لوگوں نے اپنے ساتھ ہمارے لیے دعا کیوں نہیں کی؟",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Dunya and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.132)."]]}]},"276":{"lead":[],"stories":[{"b":[["n",[["حضرت زید بن اسلم","b"],[" وغیرہ حضرات فرماتے ہیں جنگِ بدر کے دن حضرت عکاشہ بن محصنؓ کی تلوار ٹوٹ گئی تھی۔ حضورؐ نے ان کو درخت کی ایک ٹہنی دی جو ان کے ہاتھ میں جاتے ہی کاٹنے والی تلوار بن گئی جس کا لوہا بڑا صاف اور مضبوط تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.1 Pg.188)."]]}]},"277":{"lead":[],"stories":[{"b":[["n",[["حضرت خیثمہؒ","b"],[" کہتے ہیں حضرت خالد بن ولیدؓ کے پاس ایک آدمی آیا۔ اس کے پاس شراب کی ایک مشک تھی۔ حضرت خالدؓ نے دعا کی اے ",""],["ٱللَّٰه","a"],["! اسے شہد بنا دے۔ چنانچہ وہ شراب اسی وقت شہد بن گئی۔ دوسری روایت میں یہ ہے کہ حضرت خالدؓ کے پاس سے ایک آدمی گزرا جس کے پاس شراب کی ایک مشک تھی۔ حضرت خالدؓ نے پوچھا یہ کیا ہے؟ اس آدمی نے کہا سرکہ ہے۔ حضرت خالد نے کہا ",""],["ٱللَّٰه","a"],[" اسے سرکہ ہی بنا دے۔ لوگوں نے اسے دیکھا تو وہ واقعی سرکہ ہی تھا، حالانکہ اس سے پہلے وہ شراب تھی۔ ایک روایت میں یہ ہے کہ حضرت خالدؓ کے پاس سے ایک آدمی گزرا جس کے پاس شراب کی مشک تھی۔ حضرت خالدؓ نے اس سے پوچھا یہ کیا ہے؟ اس نے کہا شہد ہے۔ حضرت خالدؓ نے دعا کی اے ",""],["ٱللَّٰه","a"],["! اسے سرکہ بنا دے۔ وہ آدمی جب اپنے ساتھیوں کے پاس واپس پہنچا تو اس نے کہا میں آپ لوگوں کے پاس ایسی شراب لے کر آیا ہوں کہ اس جیسی شراب عربوں نے کبھی نہیں پی ہوگی۔ پھر اس آدمی نے مشک کھولی تو اس میں سرکہ تھا۔ تو اس نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! اس کو حضرت خالدؓ کی دعا لگی ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Dunya, as quoted in Isaabah (Vol.1 Pg.414); see also Al Bidaayah wan Nihaayah (Vol.7 Pg.114)."]]}]},"278":{"lead":[],"stories":[{"b":[["n",[["حضرت محمد بن اسحاق","b"],[" کہتے ہیں حضرت مالک اشجعیؓ نے نبی کریمؐ کی خدمت میں حاضر ہو کر عرض کیا کہ میرا بیٹا عوف قید ہو گیا ہے۔ حضورؐ نے فرمایا اس کے پاس یہ پیغام بھیج دو کہ حضورؐ اسے فرما رہے ہیں کہ وہ لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],[" کثرت سے پڑھے۔ چنانچہ قاصد نے جا کر حضرت عوفؓ کو حضورؐ کا پیغام پہنچا دیا۔ حضرت عوفؓ نے لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],[" خوب کثرت سے پڑھنا شروع کر دیا۔ کافروں نے حضرت عوفؓ کو تانت سے باندھا ہوا تھا۔ ایک دن وہ تانت ٹوٹ کر گر گئی تو حضرت عوفؓ قید سے باہر نکل آئے۔ باہر آ کر انہوں نے دیکھا کہ ان لوگوں کی اونٹنی وہاں موجود ہے۔ حضرت عوفؓ اس پر سوار ہو گئے۔ آگے گئے تو دیکھا کہ ان کافروں کے سارے جانور ایک جگہ جمع ہیں۔ انہوں نے ان جانوروں کو ایک آواز لگائی تو سارے جانور ان کے پیچھے چل پڑے اور انہوں نے اچانک اپنے ماں باپ کے گھر کے دروازے پر جا کر آواز لگائی تو ان کے والد نے کہا ربِ کعبہ کی قسم! یہ تو عوف ہے۔ ان کی والدہ نے کہا ہائے! یہ عوف کیسے ہو سکتا ہے؟ عوف تو تانت کی تکلیف میں گرفتار ہے۔ بہرحال والد اور خادم دوڑ کر دروازے پر گئے تو دیکھا کہ واقعی حضرت عوفؓ موجود ہیں اور سارا میدان اونٹوں سے بھرا ہوا ہے۔ حضرت عوفؓ نے اپنے والد کو اپنا اور اونٹوں کا سارا قصہ سنایا۔ ان کے والد نے جا کر حضورؐ کو یہ سب کچھ بتایا۔ حضورؐ نے ان سے فرمایا ان اونٹوں کے ساتھ تم جو چاہے کرو (یہ اونٹ تمہارے ہیں، اس لیے) اپنے اونٹوں کے ساتھ جو کچھ تم کرتے ہو وہی ان کے ساتھ کرو۔ پھر یہ آیت نازل ہوئی",""]]],["q",[["﴿وَمَنْ يَّتَّقِ اللّٰهَ يَجْعَلْ لَّهٗ مَخْرَجًا ۙ وَّيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ؕ وَمَنْ يَّتَوَكَّلْ عَلَى اللّٰهِ فَهُوَ حَسْبُهٗ﴾","a"]]],["p",[["ترجمہ: \"جو شخص ",""],["ٱللَّٰه","a"],[" سے ڈرتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے لیے (مضرتوں سے) نجات کی شکل نکال دیتا ہے اور اس کو ایسی جگہ سے رزق پہنچاتا ہے جہاں اس کا گمان بھی نہیں ہوتا اور جو شخص ",""],["ٱللَّٰه","a"],[" پر توکل کرے گا تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اس (کی اصلاحِ مہمات) کے لیے کافی ہے۔\" (سورۂ طلاق، آیت 2، 3)۔ ابن جریر کی روایت میں یہ بھی ہے کہ عوف کے والد حضورؐ کی خدمت میں حاضر ہوتے اور اپنے بیٹے کے قید میں ہونے اور اس کی پریشانی کی شکایت کرتے۔ حضورؐ انہیں صبر کی تلقین فرماتے اور ارشاد فرماتے ",""],["ٱللَّٰه","a"],[" تعالیٰ عنقریب اس کے لیے اس پریشانی سے نکلنے کا راستہ بنائیں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Aadam bin Abu Ayaas in his Tafseer, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.105). Ibn Abi Haatim has reported a similar narration, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.380)."]]}]},"279":{"lead":[],"stories":[{"b":[["n",[["حضرت عباس بن سہیل بن سعد ساعدیؒ یا حضرت عباس بن سعدؒ","b"],[" فرماتے ہیں جب حضورؐ (حضرت صالح علیہ السلام کی قوم ثمود کے علاقے) حجر کے پاس سے گزرے اور وہاں پڑاؤ ڈالا تو لوگوں نے وہاں کے کنویں سے پانی نکال کر برتنوں میں بھر لیا۔ جب وہاں سے آگے روانہ ہوئے تو حضورؐ نے لوگوں سے فرمایا اس کنویں کا پانی بالکل نہ پیو اور نہ اس سے نماز کے لیے وضو کرو اور اس کے پانی سے جو آٹا گوندھا ہے وہ اونٹوں کو کھلا دو، خود اسے بالکل نہ کھاؤ۔ آج رات جو بھی باہر نکلے وہ اپنے ساتھ اپنے کسی ساتھی کو ضرور لے کر جائے، اکیلے نہ نکلے۔ تمام لوگوں نے حضورؐ کی تمام باتوں پر عمل کیا، البتہ قبیلہ بنو ساعدہ کے دو آدمی اکیلے باہر نکل گئے۔ ایک قضائے حاجت کے لیے گیا تھا، دوسرا اپنا اونٹ ڈھونڈنے گیا تھا۔ جو قضائے حاجت کے لیے گیا تھا راستہ میں اس کا کسی (جن) نے گلا گھونٹ دیا اور جو اپنا اونٹ ڈھونڈنے گیا تھا اسے آندھی نے اٹھا کر قبیلہ طے کے دو پہاڑوں کے درمیان (یمن میں) جا پھینکا۔ جب حضورؐ کو ان دونوں کے بارے میں بتایا گیا تو آپؐ نے فرمایا ساتھی کے بغیر اکیلے باہر نکلنے سے کیا تم لوگوں کو منع نہیں کیا تھا؟ پھر آپؐ نے اس کے لیے دعا فرمائی جس کا راستہ میں کسی نے گلا گھونٹا، وہ ٹھیک ہو گیا۔ دوسرا آدمی تبوک سے حضورؐ کے پاس پہنچا۔ ابن اسحاق سے زیاد نے جو روایت کی ہے اس میں یہ ہے کہ جب حضورؐ مدینہ منورہ واپس پہنچے تو قبیلہ طے والوں نے اس آدمی کو حضورؐ کے پاس بھیجا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Is'haaq, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.11). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.190)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں حضرت عثمانؓ منبر پر بیان فرما رہے تھے۔ حضرت جہجاہ غفاریؓ نے کھڑے ہو کر حضرت عثمانؓ کے ہاتھ سے لاٹھی لی اور اس زور سے ان کے گھٹنے پر ماری کہ گھٹنا پھٹ گیا اور لاٹھی بھی ٹوٹ گئی۔ ابھی سال بھی نہیں گزرا تھا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت جہجاہ کے ہاتھ پر جسم کو کھا جانے والی بیماری لگا دی جس سے ان کا انتقال ہو گیا۔ ابن سکن کی روایت میں ہے کہ حضرت جہجاہ بن سعید غفاریؓ اٹھ کر حضرت عثمانؓ کی طرف گئے اور ان کے ہاتھ سے چھڑی لے لی اور حضرت عثمانؓ کے گھٹنے پر اس زور سے ماری کہ وہ ٹوٹ گئی۔ اس پر لوگوں نے شور مچا دیا۔ حضرت عثمانؓ منبر سے اتر کر اپنے گھر تشریف لے گئے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت غفاریؓ کے گھٹنے میں بیماری پیدا کر دی اور سال گزرنے سے پہلے ہی اسی بیماری میں ان کا انتقال ہو گیا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Dalaa'il (Pg.211). Ibnus Sakan and Baawardi, as quoted in Isaabah (Vol.1 Pg.253)."]]},{"b":[["n",[["حضرت عبدالملک بن عمیرؒ","b"],[" کہتے ہیں مسلمانوں میں سے ایک آدمی حضرت سعد بن ابی وقاصؓ کے پاس آیا اور اس نے یہ شعر پڑھے (حضرت سعدؓ بیماری کی وجہ سے اس لڑائی میں شریک نہیں ہو سکے تھے جس پر اس نے یہ اشعار طنزاً پڑھے)",""]]],["q",[["نُقَاتِلُ حَتّٰى يُنْزِلَ اللّٰهُ نَصْرَهٗ ۝ وَسَعْدٌ بِبَابِ الْقَادِسِيَّةِ مُعْصِمُ","a"]]],["q",[["فَأُبْنَا وَقَدْ آمَتْ نِسَاءٌ كَثِيْرَةٌ ۝ وَنِسْوَةُ سَعْدٍ لَيْسَ فِيْهِنَّ أَيِّمُ","a"]]],["p",[["\"ہم تو اس لیے جنگ کر رہے تھے تاکہ ",""],["ٱللَّٰه","a"],[" اپنی مدد نازل کر دے اور (حضرت) سعد قادسیہ کے دروازے سے چمٹے کھڑے رہے۔ جب ہم واپس آئے تو بہت سی عورتیں بیوہ ہو چکی تھیں لیکن (حضرت) سعد کی بیویوں میں سے کوئی بھی بیوہ نہیں ہوئی۔\" جب حضرت سعدؓ کو ان شعروں کا پتہ چلا تو انہوں نے ہاتھ اٹھا کر یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! اس کی زبان اور ہاتھ کو مجھ سے تو جس طرح چاہے روک دے۔ چنانچہ جنگِ قادسیہ کے دن اسے ایک تیر لگا جس سے اس کی زبان بھی کٹ گئی اور ہاتھ بھی کٹ گیا اور وہ قتل بھی ہو گیا۔ حضرت قبیصہ بن جابرؒ کہتے ہیں ہمارے ایک چچا زاد بھائی نے جنگِ قادسیہ کے موقع پر (حضرت سعدؓ پر طنز کرنے کے لیے) یہ دو شعر کہے جو گزر گئے، البتہ پہلے شعر میں الفاظ دوسرے ہیں جن کا ترجمہ یہ ہے کہ کیا تم نے نہیں دیکھا کہ ",""],["ٱللَّٰه","a"],[" نے اپنی مدد کو کیسے اتارا؟ جب حضرت سعدؓ کو ان اشعار کا پتہ چلا تو انہوں نے فرمایا خدا کرے اس کی زبان اور ہاتھ بیکار ہو جائیں۔ چنانچہ ایک تیر اس کے منہ پر لگا جس سے وہ گونگا ہو گیا، پھر جنگ میں اس کا ہاتھ بھی کٹ گیا۔ اپنا عذر لوگوں کو بتانے کے لیے حضرت سعدؓ نے فرمایا مجھے اٹھا کر دروازے کے پاس لے چلو۔ چنانچہ لوگ انہیں اٹھا کر باہر لائے، پھر انہوں نے اپنی پشت سے کپڑا ہٹایا تو اس پر بہت سے زخم تھے جنہیں دیکھ کر تمام لوگوں کو پورا یقین ہو گیا کہ یہ واقعی معذور تھے اور کوئی بھی انہیں بزدل نہیں سمجھتا تھا۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Dalaa'il (Pg.207). Tabraani has reported the second narration, from reliable sources as confirmed by Haythami (Vol.9 Pg.154)."]]},{"b":[["n",[["اپنے بڑوں کی وجہ سے ناراض ہونے کے باب میں (طبرانی والی) حضرت عامر بن سعد کی روایت میں حضرت سعدؓ کا حضرت علی، حضرت طلحہ اور حضرت زبیرؓ کو برا بھلا کہنے والے کو بددعا دینا گزر چکا ہے جس میں یہ بھی ہے کہ ایک بختی اونٹنی تیزی سے آئی، لوگ اسے دیکھ کر ادھر ادھر ہٹ گئے۔ اس اونٹنی نے اس آدمی کو روند ڈالا۔ اور حضرت قیس بن ابی حازم کی روایت میں حضرت سعدؓ کا حضرت علیؓ کو برا بھلا کہنے والے کے لیے بددعا کرنا بھی گزر چکا ہے جس میں یہ بھی ہے کہ ہمارے بکھرنے سے پہلے ہی ",""],["ٱللَّٰه","a"],[" کی قدرت ظاہر ہوئی اور اس کی سواری کے پاؤں زمین میں دھنسنے لگے جس سے وہ سر کے بل ان پتھروں پر زور سے گرا جس سے اس کا سر پھٹ گیا اور اس کا بھیجا باہر نکل آیا اور وہ وہیں مر گیا۔ ابونعیم کی روایت میں ہے کہ حضرت سعید بن مسیبؒ فرماتے ہیں کہ ایک بھڑکا ہوا اونٹ آیا اور لوگوں کے درمیان میں سے گزرتا ہوا اس آدمی کے پاس پہنچ گیا اور اسے مار کر نیچے گرایا اور پھر اس پر بیٹھ کر اپنے سینے سے اسے زمین پر رگڑتا رہا یہاں تک کہ اس کے ٹکڑے ٹکڑے کر دیے۔ حضرت سعید بن مسیب کہتے ہیں میں نے لوگوں کو دیکھا کہ وہ دوڑتے ہوئے حضرت سعدؓ کے پاس جا رہے تھے اور کہہ رہے تھے آپ کو دعا کا قبول ہونا مبارک ہو۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Dalaa'il (Pg.206)."]]},{"b":[["n",[["حضرت ابن شوذبؒ","b"],[" کہتے ہیں حضرت ابن عمرؓ کو یہ خبر ملی کہ زیاد حجازِ مقدس کا بھی والی بننا چاہتا ہے۔ انہیں اس کی بادشاہت میں رہنا پسند نہ آیا تو انہوں نے یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! تو اپنی مخلوق میں سے جس کے بارے میں چاہتا ہے اسے قتل کروا کر اس کے گناہوں کے کفارے کی صورت بنا دیتا ہے۔ (زیاد) ابن سمیہ اپنی موت مرے، قتل نہ ہو۔ چنانچہ زیاد کے انگوٹھے میں اسی وقت طاعون کی گلٹی نکل آئی اور جمعہ آنے سے پہلے ہی مر گیا۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.231)."]]},{"b":[["n",[["حضرت (عبدالجبار) بن وائل یا حضرت علقمہ بن وائل","b"],[" کہتے ہیں جو کچھ وہاں (کربلا میں) ہوا تھا میں اس موقع پر وہاں موجود تھا۔ چنانچہ ایک آدمی نے کھڑے ہو کر پوچھا کیا آپ لوگوں میں حسین (رضی ",""],["ٱللَّٰه","a"],[" عنہ) ہیں؟ لوگوں نے کہا ہاں ہیں۔ اس آدمی نے حضرت حسینؓ کو گستاخی کے انداز میں کہا آپ کو جہنم کی بشارت ہو۔ حضرت حسینؓ نے فرمایا مجھے دو بشارتیں حاصل ہیں: ایک تو نہایت مہربان رب وہاں ہوں گے، دوسرے وہ نبیؐ وہاں ہوں گے جو سفارش کریں گے اور ان کی سفارش قبول کی جائے گی۔ لوگوں نے پوچھا تو کون ہے؟ اس نے کہا میں ابن جویرہ یا ابن جویزہ ہوں۔ حضرت حسینؓ نے یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! اس کے ٹکڑے ٹکڑے کر کے اسے جہنم میں ڈال دے۔ چنانچہ اس کی سواری زور سے بدکی جس سے وہ سواری سے اس طرح نیچے گرا کہ اس کا پاؤں رکاب میں پھنسا رہ گیا اور سواری تیز بھاگتی رہی اور اس کا جسم اور سر زمین پر گھسٹتا رہا جس سے اس کے جسم کے ٹکڑے ٹکڑے ہو کر گرتے رہے۔ ",""],["ٱللَّٰه","a"],[" کی قسم! آخر میں صرف اس کی ٹانگ رکاب میں لٹکی رہ گئی۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani; Haythami (Vol.9 Pg.193) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت کلبیؒ","b"],[" کہتے ہیں حضرت حسینؓ پانی پی رہے تھے۔ ایک آدمی نے ان کو تیر مارا جس سے ان کے دونوں جبڑے شل ہو گئے تو حضرت حسینؓ نے کہا ",""],["ٱللَّٰه","a"],[" تجھے کبھی سیراب نہ کرے۔ چنانچہ اس نے پانی پیا لیکن پیاس نہ بجھی۔ آخر اتنا پانی پیا کہ اس کا پیٹ پھٹ گیا۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.193)."]]},{"b":[["n",[["عبید","b"],["ٱللَّٰه","a"],[" بن زیاد کا دربان","b"],[" بیان کرتا ہے کہ جب عبید",""],["ٱللَّٰه","a"],[" بن زیاد حضرت حسینؓ کو شہید کر کے آیا تو میں اس کے پیچھے محل میں داخل ہوا۔ میں نے دیکھا کہ محل میں ایک دم آگ بھڑک اٹھی جو اس کے چہرے کی طرف بڑھی۔ اس نے فوراً اپنی آستین چہرے کے سامنے کر دی اور مجھ سے پوچھا تم نے بھی یہ آگ دیکھی ہے؟ میں نے کہا ہاں۔ اس نے کہا اسے چھپا کر رکھنا، کسی کو مت بتانا۔",""],[" (8)","s"]]]],"f":[["(8)","Tabraani; Haythami (Vol.9 Pg.196) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت سفیانؒ","b"],[" کہتے ہیں میری دادی نے مجھے بتایا کہ قبیلہ جعفی کے دو آدمی حضرت حسین بن علیؓ کی شہادت کے وقت وہاں موجود تھے۔ ان میں سے ایک کی شرمگاہ اتنی لمبی ہو گئی تھی کہ وہ اسے لپیٹا کرتا تھا اور دوسرے کو اتنی زیادہ پیاس لگتی تھی کہ مشک کو منہ لگا کر ساری پی جایا کرتا تھا۔ حضرت سفیان کہتے ہیں میں نے ان دونوں میں سے ایک کا بیٹا دیکھا وہ بالکل پاگل نظر آ رہا تھا۔",""],[" (9)","s"]]]],"f":[["(9)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.197)."]]},{"b":[["n",[["حضرت اعمشؒ","b"],[" کہتے ہیں ایک آدمی نے حضرت حسینؓ کی قبر پر پاخانہ کرنے کی گستاخی کی تو اس سے اس کے گھر والوں میں پاگل پن، کوڑھ اور خارش کی وجہ سے کھال سفید ہو جانے کی بیماریاں پیدا ہو گئیں اور سارے گھر والے فقیر ہو گئے۔",""],[" (10)","s"]]]],"f":[["(10)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.197)."]]}]},"280":{"lead":[],"stories":[{"b":[["n",[["حضرت ربیعہ بن لقیطؒ","b"],[" کہتے ہیں جس سال حضرت علی اور حضرت معاویہؓ کی جماعتوں میں جنگ ہوئی اس سال میں حضرت عمرو بن عاصؓ کے ساتھ تھا۔ ان کی جماعت واپس جا رہی تھی۔ راستہ میں تازہ خون کی بارش ہوئی۔ میں برتن بارش میں رکھتا تھا تو وہ تازہ خون سے بھر جاتا تھا۔ لوگ سمجھ گئے کہ لوگوں نے جو ایک دوسرے کا خون بہایا ہے اس کی وجہ سے یہ بارش ہوئی ہے۔ حضرت عمرو بن عاصؓ بیان کے لیے کھڑے ہوئے۔ پہلے ",""],["ٱللَّٰه","a"],[" کی شایانِ شان حمد و ثناء بیان کی، پھر فرمایا اگر تم اپنے اور ",""],["ٱللَّٰه","a"],[" کے درمیان کا تعلق ٹھیک کر لو گے (ہر حال میں اس کا حکم پورا کرو گے) تو اگر یہ دو پہاڑ بھی آپس میں ٹکرا جائیں گے تو بھی تمہارا کچھ نقصان نہیں ہوگا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.4 Pg.291)."]]},{"b":[["n",[["حضرت زہریؒ","b"],[" کہتے ہیں عبدالملک نے مجھ سے کہا اگر آپ مجھے یہ بتا دیں کہ حضرت حسینؓ کی شہادت کے دن کونسی نشانی پائی گئی تھی تو پھر آپ واقعی بہت بڑے عالم ہیں۔ میں نے کہا اس دن بیت المقدس میں جو بھی کنکری اٹھائی جاتی اس کے نیچے تازہ خون ملتا۔ عبدالملک نے کہا اس بات کو روایت کرنے میں میں اور آپ دونوں برابر ہیں (مجھے بھی یہ بات معلوم ہے)۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.196)."]]},{"b":[["n",[["حضرت زہریؒ","b"],[" کہتے ہیں جس دن حضرت حسین بن علیؓ کو شہید کیا گیا اس دن شام میں جو بھی پتھر اٹھایا جاتا اس کے نیچے خون ہوتا۔",""]]]],"f":[]},{"b":[["n",[["حضرت ام حکیمؒ","b"],[" کہتے ہیں جس دن حضرت حسینؓ کو شہید کیا گیا اس دن میں کم عمر لڑکی تھی تو کئی دن تک آسمان خون کی طرح سرخ رہا۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.197)."]]},{"b":[["n",[["حضرت ابوقبیلؒ","b"],[" کہتے ہیں جب حضرت حسین بن علیؓ کو شہید کیا گیا تو اسی وقت سورج کو اتنا زیادہ گرہن لگا کہ عین دوپہر کے وقت ستارے نظر آنے لگے اور ہم لوگ سمجھے کہ قیامت آ گئی۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.197). In Al Bidaayah wan Nihaayah (Vol.8 Pg.201), Allaama Ibn Katheer has cited all the above narrations apart from the first as weak, categorising them as fabrications of the Shias. Allaah knows best."]]}]},"281":{"lead":[],"stories":[{"b":[["n",[["حضرت مالک بن دینارؒ","b"],[" کہتے ہیں جب حضرت عمر بن خطابؓ کو شہید کیا گیا تو یمن کے تبالہ پہاڑ پر ایک آواز سنی گئی کہ کسی نے یہ دو شعر پڑھے",""]]],["q",[["لِيَبْكِ عَلَى الْإِسْلَامِ مَنْ كَانَ بَاكِيًا ۝ فَقَدْ أَوْشَكُوْا هَلْكٰى وَمَا قَدُمَ الْعَهْدُ","a"]]],["q",[["وَأَدْبَرَتِ الدُّنْيَا وَأَدْبَرَ خَيْرُهَا ۝ وَقَدْ مَلَّهَا مَنْ كَانَ يُوْقِنُ بِالْوَعْدِ","a"]]],["p",[["\"اسلام پر جس نے رونا ہے وہ رو لے کیونکہ سب لوگ ہلاک ہو گئے، حالانکہ ابھی اسلام کو زیادہ عرصہ نہیں ہوا تھا۔ اور دنیا اور دنیا کی خیر نے پیٹھ پھیر لی ہے اور جو آخرت کے وعدوں پر یقین رکھتا ہے اس کا دل دنیا سے اکتا گیا ہے۔\" لوگوں نے ادھر ادھر بہت دیکھا لیکن انہیں پہاڑ پر کوئی بولنے والا نظر نہ آیا (کیونکہ یہ اشعار جن نے پڑھے تھے)۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim (Vol.3 Pg.94). Abu Nu'aym has reported a similar narration from Hadhrat Ma'roof Mowsili in his Dalaa'il (Pg.210), as has Tabraani, as quoted in Majma'uz Zawaa'id (Vol.9 Pg.79)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ میں نے رات کے وقت کسی کو ان اشعار کے ذریعہ حضرت عمرؓ کی وفات کی خبر دیتے ہوئے سنا اور مجھے یقین ہے کہ وہ خبر دینے والا انسان نہیں تھا (بلکہ جن تھا)",""]]],["q",[["جَزَى اللّٰهُ خَيْرًا مِنْ أَمِيْرٍ وَبَارَكَتْ ۝ يَدُ اللّٰهِ فِيْ ذَاكَ الْأَدِيْمِ الْمُمَزَّقِ","a"]]],["q",[["فَمَنْ يَمْشِ أَوْ يَرْكَبْ جَنَاحَيْ نَعَامَةٍ ۝ لِيُدْرِكَ مَا قَدَّمْتَ بِالْأَمْسِ يُسْبَقِ","a"]]],["q",[["قَضَيْتَ أُمُوْرًا ثُمَّ غَادَرْتَ بَعْدَهَا ۝ بَوَائِقَ فِيْ أَكْمَامِهَا لَمْ تُفَتَّقِ","a"]]],["p",[["\"",""],["ٱللَّٰه","a"],[" تعالیٰ امیر المومنین کو جزائے خیر عطا فرمائے اور ",""],["ٱللَّٰه","a"],[" اپنی قدرت سے اس کھال میں برکت عطا فرمائے جس کو ٹکڑے کر دیا گیا۔ (اے امیر المومنین!) آپ جو کارنامہ سرانجام دے گئے ہیں ان تک پہنچنے کے لیے کوئی تھوڑی محنت کرے یا زیادہ وہ کبھی بھی ان تک نہیں پہنچ سکتا بلکہ پیچھے رہ جائے گا۔ بہت بڑے کام تو آپ پورے کر گئے لیکن ان کے بعد ایسی مصیبتیں چھوڑ گئے جو ایسی کلیوں میں ہیں جو ابھی پھوٹی نہیں۔\"",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.374)."]]},{"b":[["n",[["حضرت سلیمان بن یسارؒ","b"],[" کہتے ہیں ایک جن نے حضرت عمرؓ پر نوحہ کرتے ہوئے یہ اشعار پڑھے",""]]],["q",[["عَلَيْكَ سَلَامٌ مِنْ أَمِيْرٍ وَبَارَكَتْ ۝ يَدُ اللّٰهِ فِيْ ذَاكَ الْأَدِيْمِ الْمُخَرَّقِ","a"]]],["p",[["\"اے امیر المومنین! آپ پر سلامتی ہو اور ",""],["ٱللَّٰه","a"],[" اپنی قدرت سے اس کھال میں برکت عطا فرمائے جس کو پھاڑ دیا گیا۔\"",""]]],["q",[["قَضَيْتَ أُمُوْرًا ثُمَّ غَادَرْتَ بَعْدَهَا ۝ بَوَائِقَ فِيْ أَكْمَامِهَا لَمْ تُفَتَّقِ","a"]]],["q",[["فَمَنْ يَسْعَ أَوْ يَرْكَبْ جَنَاحَيْ نَعَامَةٍ ۝ لِيُدْرِكَ مَا قَدَّمْتَ بِالْأَمْسِ يُسْبَقِ","a"]]],["p",[["ان دونوں شعروں کا ترجمہ گزر چکا ہے۔",""]]],["q",[["أَبَعْدَ قَتِيْلٍ بِالْمَدِيْنَةِ أَظْلَمَتْ ۝ لَهُ الْأَرْضُ تَهْتَزُّ الْعِضَاهُ بِأَسْوُقِ","a"]]],["p",[["\"وہ شخصیت جن کے قتل ہونے کی وجہ سے ساری زمین تاریک ہو گئی ہے کیا ان کے قتل ہونے کے بعد کیکر کے درخت اپنے تنوں پر لہلہا رہے ہیں؟\" یعنی نہیں، بلکہ یہ درخت بھی ان کی شہادت پر افسردہ ہیں اور انہوں نے لہلہانا چھوڑ دیا ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Sa'd (Vol.3 Pg.374)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضرت عمر بن خطابؓ کے انتقال کے تین دن بعد جنات نے یہ اشعار پڑھ کر ان کی شہادت پر نوحہ کیا اور پھر یہی پچھلے چار شعر دوسری ترتیب سے ذکر کیے اور پھر پانچواں شعر یہ ذکر کیا",""]]],["q",[["فَلَقَّاكَ رَبِّيْ فِي الْجِنَانِ تَحِيَّةً ۝ وَمِنْ كُسْوَةِ الْفِرْدَوْسِ مَا لَمْ يُمَزَّقِ","a"]]],["p",[["\"میرا رب آپ کو جنتوں میں سلام پہنچائے اور آپ کو جنت الفردوس کے ایسے کپڑے پہنائے جو کبھی نہیں پھٹیں گے۔\"",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Dalaa'il (Pg.210)."]]},{"b":[["n",[["حضرت ام سلمہؓ","b"],[" فرماتی ہیں میں نے جنات کو حضرت حسین بن علیؓ پر نوحہ کرتے ہوئے سنا ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.199)."]]},{"b":[["n",[["ایک مرتبہ ",""],["حضرت ام سلمہؓ","b"],[" نے فرمایا جب سے حضورؐ کا انتقال ہوا ہے میں نے کبھی بھی جن کو کسی کے مرنے پر نوحہ کرتے ہوئے نہیں سنا لیکن آج رات میں نے سنا ہے اور میرا خیال یہ ہے کہ میرا بیٹا (حضرت حسینؓ) فوت ہو گیا ہے۔ چنانچہ انہوں نے اپنی باندی سے کہا باہر جا اور پتہ کر کے آ۔ چنانچہ باندی نے آ کر بتایا کہ واقعی حضرت حسینؓ شہید ہو گئے ہیں۔ پھر حضرت ام سلمہؓ نے بتایا کہ ایک جننی یہ شعر پڑھ کر نوحہ کر رہی تھی۔",""]]],["q",[["أَلَا يَا عَيْنُ فَاحْتَفِلِيْ بِجَهْدِيْ ۝ وَمَنْ يَّبْكِيْ عَلَى الشُّهَدَاءِ بَعْدِيْ","a"]]],["q",[["عَلٰى رَهْطٍ تَقُوْدُهُمُ الْمَنَايَا ۝ إِلٰى مُتَجَبِّرٍ فِيْ مُلْكِ عَبْدِ","a"]]],["p",[["\"اے آنکھ! غور سے سن اور جو رونے کی کوشش اور محنت کر رہی ہوں اس کا اہتمام کر۔ میں اگر نہیں روؤں گی تو میرے بعد شہداء پر کون روئے گا؟ شہداء کی وہ جماعت جن کو موت کھینچ کر ایسے ظالم اور جابر انسان کے پاس لے گئی (یعنی عبید",""],["ٱللَّٰه","a"],[" بن زیاد) جو کہ ایک غلام یعنی یزید کی بادشاہت میں فوج کا سپہ سالار ہے۔\"",""],[" (6)","s"]]]],"f":[["(6)","Tabraani; Haythami (Vol.9 Pg.199) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت میمونہؓ","b"],[" فرماتی ہیں میں نے جنات کو حضرت حسین بن علیؓ پر نوحہ کرتے ہوئے سنا۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.199)."]]}]},"282":{"lead":[],"stories":[{"b":[["n",[["(",""],["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں) حضرت ابوموسیٰ اشعریؓ نے فرمایا میں نے خواب میں دیکھا کہ میں ایک ایسی جگہ ہوں جہاں بہت سے راستے ہیں، پھر سارے راستے ختم ہو گئے اور صرف ایک راستہ رہ گیا۔ میں نے اس پر چلنا شروع کر دیا اور چلتے چلتے ایک پہاڑ پر پہنچ گیا جس کے اوپر حضورؐ تشریف فرما تھے اور ان کے پاس حضرت ابوبکرؓ بیٹھے ہوئے تھے اور حضورؐ حضرت عمرؓ کو اشارہ فرما رہے تھے کہ یہاں آ جاؤ۔ یہ خواب دیکھ کر میں نے کہا انا للہ وانا الیہ راجعون، ",""],["ٱللَّٰه","a"],[" کی قسم! امیر المومنین (حضرت عمرؓ) کے انتقال کا وقت آ گیا ہے۔ حضرت انسؓ کہتے ہیں میں نے کہا آپ یہ خواب حضرت عمرؓ کو نہیں لکھ دیتے؟ انہوں نے فرمایا میں خود ان کو ان کی موت کی خبر کیوں دوں؟",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.3 Pg.332)."]]},{"b":[["n",[["حضرت کثیر بن صلتؒ","b"],[" کہتے ہیں جس دن حضرت عثمان بن عفانؓ شہید ہوئے اس دن وہ سوئے اور اٹھنے کے بعد فرمایا اگر لوگ یہ نہ کہیں کہ عثمانؓ فتنہ پیدا کرنا چاہتا ہے تو میں آپ لوگوں کو ایک بات بتاؤں۔ ہم نے کہا آپ ہمیں بتا دیں، ہم وہ بات نہیں کہیں گے جس کا دوسرے لوگوں سے خطرہ ہے۔ انہوں نے فرمایا میں نے ابھی خواب میں حضورؐ کو دیکھا۔ آپؐ نے مجھ سے فرمایا تم اس جمعہ میں ہمارے پاس پہنچ جاؤ گے۔ ابن سعد کی روایت میں یہ بھی ہے کہ یہی جمعہ کا دن تھا۔",""],[" (2)","s"]]]],"f":[["(2)","Haakim (Vol.3 Pg.99), reporting from reliable sources as confirmed by Dhahabi. Ibn Sa'd (Vol.3 Pg.75). Abu Ya'la has reported a similar narration, but Haythami (Vol.7 Pg.232) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں صبح کے وقت حضرت عثمانؓ نے فرمایا آج رات میں نے نبی کریمؐ کو خواب میں دیکھا ہے۔ حضورؐ نے فرمایا اے عثمان! ہمارے پاس افطاری کرنا۔ چنانچہ اس دن حضرت عثمان نے روزہ رکھا اور اسی دن ان کو شہید کر دیا گیا۔",""],[" (3)","s"]]]],"f":[["(3)","Haakim (Vol.3 Pg.103), reporting from reliable sources as confirmed by Dhahabi. Abu Ya'la and Bazzaar have reported a similar narration, as quoted in Majma'uz Zawaa'id (Vol.7 Pg.232). Ibn Sa'd (Vol.3 Pg.74) has also reported a similar narration."]]},{"b":[["n",[["حضرت عثمان بن عفانؓ کے آزاد کردہ غلام ",""],["حضرت مسلم ابوسعیدؒ","b"],[" کہتے ہیں حضرت عثمانؓ نے بیس 20 غلام آزاد کیے اور شلوار منگوا کر اسے پہنا اور اسے اچھی طرح باندھ لیا، حالانکہ انہوں نے اس سے پہلے نہ جاہلیت میں شلوار پہنی تھی اور نہ اسلام میں۔ اور فرمایا گزشتہ رات میں نے حضورؐ کو اور حضرت ابوبکر اور حضرت عمرؓ کو خواب میں دیکھا۔ ان حضرات نے مجھ سے فرمایا صبر کرو کیونکہ تم کل رات ہمارے پاس آ کر افطار کرو گے۔ پھر قرآن شریف منگوایا اور کھول کر اپنے سامنے رکھ لیا۔ چنانچہ جب وہ شہید ہوئے تو قرآن اسی طرح ان کے سامنے تھا۔",""],[" (4)","s"]]]],"f":[["(4)","Abdullaah and Abu Ya'la, reporting from reliable sources as confirmed by Haythami (Vol.7 Pg.232)."]]},{"b":[["n",[["حضرت حسن یا حضرت حسینؓ","b"],[" فرماتے ہیں حضرت علیؓ نے فرمایا خواب میں مجھے میرے محبوب نبی یعنی نبی کریمؐ ملے۔ میں نے حضورؐ سے ان کے بعد عراق والوں کی طرف سے پیش آنے والی تکلیفوں کی شکایت کی تو آپؐ نے مجھ سے وعدہ فرمایا کہ عنقریب تمہیں ان سے راحت مل جائے گی۔ چنانچہ اس کے بعد حضرت علیؓ صرف تین دن ہی زندہ رہے۔",""],[" (5)","s"]]]],"f":[["(5)","Adani."]]},{"b":[["n",[["حضرت ابوصالحؒ","b"],[" کہتے ہیں حضرت علیؓ نے فرمایا میں نے خواب میں نبی کریمؐ کو دیکھا تو میں نے آپؐ سے آپؐ کی امت کی شکایت کی کہ وہ مجھے جھٹلاتے ہیں اور تکلیف پہنچاتے ہیں۔ پھر میں رونے لگا۔ آپؐ نے فرمایا مت روؤ اور ادھر دیکھو۔ میں نے ادھر دیکھا تو مجھے دو آدمی نظر آئے جو بیڑیوں میں بندھے ہوئے تھے (بظاہر یہ حضرت علیؓ کا قاتل ابن ملجم اور اس کا ساتھی ہوگا) اور بڑے بڑے پتھر ان دونوں کے سر پر مارے جا رہے تھے جس سے ان کے سر ریزہ ریزہ ہو جاتے، پھر سر ٹھیک ہو جاتے (یوں ہی ان دونوں کو مسلسل عذاب دیا جا رہا تھا)۔ حضرت ابوصالح کہتے ہیں میں اگلے دن اپنے روزانہ کے معمول کے مطابق صبح کے وقت گھر سے حضرت علیؓ کی طرف چلا۔ جب میں قصائیوں کے محلے میں پہنچا تو مجھے کچھ لوگ ملے جنہوں نے بتایا کہ امیر المومنین کو شہید کر دیا گیا ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Ya'la, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.61)."]]},{"b":[["n",[["حضرت فلفلہ جعفیؒ","b"],[" کہتے ہیں میں نے حضرت حسن بن علیؓ کو فرماتے ہوئے سنا کہ میں نے خواب میں دیکھا کہ نبی کریمؐ عرش سے چمٹے ہوئے ہیں اور حضرت ابوبکرؓ حضورؐ کی کمر کو پکڑے ہوئے ہیں اور حضرت عمرؓ حضرت ابوبکرؓ کی کمر کو پکڑے ہوئے ہیں اور حضرت عثمانؓ حضرت عمرؓ کی کمر کو پکڑے ہوئے ہیں اور میں نے دیکھا کہ آسمان سے زمین پر خون گر رہا ہے۔ جب حضرت حسنؓ نے یہ خواب سنایا تو وہاں کچھ شیعہ لوگ بھی بیٹھے ہوئے تھے۔ انہوں نے پوچھا کیا آپ نے حضرت علیؓ کو خواب میں نہیں دیکھا؟ حضرت حسنؓ نے فرمایا مجھے سب سے زیادہ تو یہی پسند ہے کہ میں حضرت علیؓ کو حضورؐ کی کمر پکڑے ہوئے دیکھتا لیکن کیا کروں، میں نے خواب میں دیکھا ہی وہی ہے جو میں نے آپ لوگوں کو سنایا ہے۔ آگے اور بھی حدیث ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani in his Awsat and Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.96)."]]},{"b":[["n",[["حضرت حسنؓ","b"],[" نے فرمایا اے لوگو! میں نے آج رات عجیب خواب دیکھا۔ میں نے دیکھا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اپنے عرش پر ہیں۔ اتنے میں حضورؐ تشریف لائے اور آ کر عرش کے ایک پائے کے پاس کھڑے ہو گئے۔ پھر حضرت ابوبکرؓ آئے اور آ کر حضورؐ کے کندھے پر ہاتھ رکھ کر کھڑے ہو گئے۔ پھر حضرت عمرؓ آئے اور حضرت ابوبکرؓ کے کندھے پر ہاتھ رکھ کر کھڑے ہو گئے۔ پھر حضرت عثمانؓ آئے اور انہوں نے ہاتھ سے اشارہ کر کے عرض کیا اے میرے رب! اپنے بندوں سے پوچھیں انہوں نے مجھے کس وجہ سے قتل کیا؟ اس کے بعد آسمان سے زمین کی طرف خون کے دو پرنالے بہنے لگے۔ جب حضرت حسنؓ خواب بیان کر چکے تو کسی نے حضرت علیؓ سے کہا کیا آپ نے دیکھا نہیں کہ حضرت حسنؓ کیا بیان کر رہے ہیں؟ حضرت علیؓ نے فرمایا جو انہوں نے خواب میں دیکھا ہے وہی بیان کر رہے ہیں۔ ایک روایت میں ہے کہ حضرت حسنؓ نے فرمایا اس خواب کو دیکھنے کے بعد اب میں کسی جنگ میں شرکت نہیں کروں گا۔ اس روایت میں یہ بھی ہے کہ حضرت حسنؓ نے فرمایا میں نے دیکھا کہ حضرت عثمانؓ نے حضرت عمرؓ پر اپنا ہاتھ رکھا ہوا تھا۔ میں نے ان حضرات کے پیچھے بہت سا خون دیکھا۔ میں نے پوچھا یہ خون کیا ہے؟ کسی نے جواب میں کہا یہ حضرت عثمانؓ کا خون ہے جس کا وہ ",""],["ٱللَّٰه","a"],[" سے مطالبہ کر رہے ہیں۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Ya'la; Haythami (Vol.9 Pg.96) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں میں نے دوپہر کے وقت حضورؐ کو خواب میں دیکھا کہ آپؐ کے بال بکھرے ہوئے ہیں اور آپؐ پر گرد و غبار پڑا ہوا ہے اور آپؐ کے ہاتھ میں ایک شیشی ہے۔ میں نے پوچھا یہ شیشی کیسی؟ آپؐ نے فرمایا اس میں حسینؓ اور اس کے ساتھیوں کا خون ہے جسے میں صبح سے جمع کر رہا ہوں۔ پھر ہم نے دیکھا تو واقعی حضرت حسینؓ اسی دن شہید ہوئے تھے۔ ابن عبدالبر کی روایت میں یہ بھی ہے کہ آپؐ کے ہاتھ میں ایک شیشی ہے جس میں خون ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Khateeb in his Taareekh (Vol.1 Pg.142). Ibn Abdul Birr has reported a similar narration in his Istee'aab (Vol.1 Pg.381)."]]}]},"283":{"lead":[],"stories":[{"b":[["n",[["حضرت عباس بن عبدالمطلبؓ","b"],[" فرماتے ہیں میں حضرت عمر بن خطابؓ کا پڑوسی تھا۔ میں نے ان سے بہتر کبھی کوئی آدمی نہیں دیکھا۔ رات بھر نماز پڑھتے اور دن بھر روزہ رکھتے اور لوگوں کے کاموں میں لگے رہتے۔ جب ان کا انتقال ہوا تو میں نے ",""],["ٱللَّٰه","a"],[" سے دعا کی کہ وہ مجھے خواب میں حضرت عمرؓ کی زیارت کرا دے۔ چنانچہ میں نے انہیں خواب میں دیکھا کہ وہ کندھے پر چادر ڈالے ہوئے مدینہ کے بازار سے آ رہے ہیں۔ میں نے انہیں سلام کیا۔ انہوں نے میرے سلام کا جواب دیا۔ میں نے پوچھا کیا حال ہے؟ فرمایا خیریت ہے۔ پھر میں نے پوچھا آپ نے کیا پایا؟ فرمایا اب حساب سے فارغ ہوا ہوں۔ اگر میں رحم کرنے والے رب کو نہ پاتا تو میرا وقار گر جاتا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilya (Vol.1 Pg.54)."]]},{"b":[["n",[["حضرت عباسؓ","b"],[" فرماتے ہیں حضرت عمرؓ میرے بڑے گہرے دوست تھے۔ جب ان کا انتقال ہوا تو میں سال بھر ",""],["ٱللَّٰه","a"],[" سے دعا کرتا رہا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ خواب میں حضرت عمرؓ کی زیارت کرا دے۔ آخر سال گزرنے کے بعد میں نے انہیں خواب میں دیکھا کہ وہ اپنی پیشانی سے پسینہ پونچھ رہے ہیں۔ میں نے کہا اے امیر المومنین! آپ کے رب نے آپ کے ساتھ کیا معاملہ کیا؟ انہوں نے کہا اب میں (حساب سے) فارغ ہوا ہوں۔ اگر میرا رب شفقت اور مہربانی کا معاملہ نہ کرتا تو میری عزت اور وقار سب گر جاتا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.375)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں میں نے ایک سال سے دعا کی کہ مجھے خواب میں حضرت عمر بن خطابؓ کی زیارت کرا دے۔ چنانچہ میں نے انہیں خواب میں دیکھا تو میں نے عرض کیا آپ کے ساتھ کیا ہوا؟ فرمایا بڑے شفیق اور نہایت مہربان رب سے واسطہ پڑا۔ اگر میرے رب کی رحمت نہ ہوتی تو میری عزت خاک میں مل جاتی۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Sa'd (Vol.3 Pg.375)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں مجھے اس بات کا بہت شوق تھا کہ مجھے کسی طرح یہ پتہ چل جائے کہ مرنے کے بعد حضرت عمرؓ کے ساتھ کیا ہوا۔ آخر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فضل فرمایا اور میں نے خواب میں ایک محل دیکھا۔ میں نے پوچھا یہ کس کا ہے؟ لوگوں نے بتایا کہ یہ حضرت عمر بن خطابؓ کا ہے۔ اتنے میں حضرت عمرؓ محل سے باہر تشریف لائے۔ انہوں نے چادر اوڑھی ہوئی تھی۔ ایسے لگ رہا تھا کہ ابھی غسل کر کے آئے ہوں۔ میں نے پوچھا آپ کے ساتھ کیسا معاملہ ہوا؟ فرمایا اچھا معاملہ ہوا۔ اگر میرا رب بخشنے والا نہ ہوتا تو میری عزت خاک میں مل جاتی۔ پھر حضرت عمرؓ نے پوچھا آپ لوگوں سے جدا ہوئے مجھے کتنا عرصہ ہو گیا ہے؟ میں نے کہا بارہ سال۔ فرمایا اب میں حساب سے چھوٹا ہوں۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya (Vol.1 Pg.54)."]]},{"b":[["n",[["حضرت سالم بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں میں نے ایک انصاری صحابیؓ کو کہتے ہوئے سنا کہ میں نے ",""],["ٱللَّٰه","a"],[" سے دعا کی کہ مجھے خواب میں حضرت عمرؓ کی زیارت کرا دے۔ میں نے دس سال کے بعد انہیں خواب میں دیکھا کہ پیشانی سے پسینہ پونچھ رہے ہیں۔ میں نے عرض کیا اے امیر المومنین! آپ کا کیا بنا؟ فرمایا اب میں حساب سے فارغ ہوا ہوں۔ اگر میرے رب کی مہربانی نہ ہوتی تو میں ہلاک ہو جاتا۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Sa'd (Vol.3 Pg.376)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن عوفؓ","b"],[" فرماتے ہیں حج سے واپسی پر میں (مکہ اور مدینہ کے درمیان) سقیا مقام پر سو رہا تھا۔ میں نے خواب میں حضرت عمرؓ کو دیکھا کہ چلتے ہوئے میرے پاس آئے اور (میری بیوی) حضرت ام کلثوم بنت عقبہؓ میرے پہلو میں سو رہی تھیں۔ حضرت عمرؓ نے آ کر اسے پاؤں سے ہلا کر جگایا۔ پھر وہ پیٹھ پھیر کر چل دیے۔ لوگ ان کی تلاش میں چل پڑے۔ میں نے اپنے کپڑے منگوا کر پہنے اور میں بھی لوگوں کے ساتھ انہیں ڈھونڈنے لگا اور سب سے پہلے میں ان تک پہنچا لیکن ",""],["ٱللَّٰه","a"],[" کی قسم! انہیں ڈھونڈنے میں میں بے حد تھک گیا۔ میں نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! اے امیر المومنین! آپ نے تو لوگوں کو مشقت میں ڈال دیا۔ جب تک تھک نہ جائے اس وقت تک وہ آپ کو ڈھونڈ نہیں سکتا۔ ",""],["ٱللَّٰه","a"],[" کی قسم! جب میں اچھی طرح تھک گیا تب آپ مجھے ملے۔ انہوں نے فرمایا میرے خیال میں میں تو کوئی خاص تیز نہیں چلا (یہاں تک تو خواب ہے، اس کے بعد حضرت عبدالرحمٰنؓ فرماتے ہیں) اس ذات کی قسم جس کے قبضے میں عبدالرحمٰن کی جان ہے! یہ حضرت عمرؓ کا سب سے آگے نکل جانا ان کے اعمال کی وجہ سے ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Sa'd (Vol.3 Pg.376)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن سلامؓ","b"],[" فرماتے ہیں حضرت سلمانؓ نے مجھ سے کہا اے میرے بھائی! ہم دونوں میں سے جو پہلے مر جائے وہ اس بات کی کوشش کرے کہ جو ساتھی دنیا میں رہ گیا ہے وہ جانے والا اسے خواب میں نظر آئے۔ میں نے کہا کیا ایسے ہو سکتا ہے؟ حضرت سلمانؓ نے کہا ہاں کیونکہ مومن کی روح آزاد رہتی ہے، زمین پر جہاں چاہے چلی جاتی ہے اور کافر کی روح قید میں ہوتی ہے۔ چنانچہ حضرت سلمان کا پہلے انتقال ہو گیا۔ ایک دن دوپہر کو میں اپنی چارپائی پر سونے کے لیے لیٹا۔ ابھی مجھے ہلکی سی نیند آئی تھی کہ ایک دم خواب میں حضرت سلمانؓ آ گئے۔ انہوں نے کہا السلام علیک ورحمۃ ",""],["ٱللَّٰه","a"],["۔ میں نے کہا اے ابوعبد",""],["ٱللَّٰه","a"],["! السلام علیک ورحمۃ ",""],["ٱللَّٰه","a"],["، آپ کو کیسا ٹھکانہ ملا؟ فرمایا بہت عمدہ، اور توکل کو لازم پکڑے رہنا کیونکہ توکل بہت عمدہ چیز ہے، توکل کو لازم پکڑے رہنا کیونکہ توکل بہت عمدہ چیز ہے، توکل کو لازم پکڑے رہنا کیونکہ توکل بہت عمدہ چیز ہے۔ ابونعیم کی روایت میں اس طرح ہے کہ پھر حضرت سلمانؓ کا پہلے انتقال ہو گیا تو حضرت عبد",""],["ٱللَّٰه","a"],[" بن سلامؓ نے انہیں خواب میں دیکھا۔ ان سے پوچھا اے ابوعبد",""],["ٱللَّٰه","a"],["! آپ کا کیا حال ہے؟ حضرت سلمانؓ نے کہا خیریت ہے۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے پوچھا آپ نے کونسے عمل کو سب سے افضل پایا؟ حضرت سلمانؓ نے فرمایا میں نے توکل کو عجیب چیز پایا۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Sa'd (Vol.4 Pg.93). Abu Nu'aym has reported the second narration in his Hilya (Vol.1 Pg.205)."]]},{"b":[["n",[["حضرت عوف بن مالکؓ","b"],[" فرماتے ہیں میں نے خواب میں کھال کا خیمہ اور سبز چراگاہ دیکھی اور خیمے کے اردگرد بکریاں بیٹھی ہوئی تھیں جو جگالی کر رہی تھیں اور مینگنی کی جگہ عجوہ کھجوریں نکل رہی ہیں۔ میں نے پوچھا یہ خیمہ کس کا ہے؟ کسی نے بتایا حضرت عبدالرحمٰن بن عوفؓ کا ہے۔ چنانچہ ہم لوگوں نے کچھ دیر انتظار کیا، پھر حضرت عبدالرحمٰنؓ خیمہ سے باہر تشریف لائے اور فرمایا یہ سب کچھ ہم کو ",""],["ٱللَّٰه","a"],[" نے قرآن کی وجہ سے دیا ہے لیکن اگر تم اس گھاٹی سے پرلی طرف جھانکو تو تمہیں ایسی نعمتیں نظر آئیں گی جنہیں تمہاری آنکھ نے کبھی دیکھا نہیں اور تمہارے کان نے کبھی سنا نہیں اور جن کا خیال بھی تمہارے دل میں نہیں آیا ہوگا۔ یہ نعمتیں ",""],["ٱللَّٰه","a"],[" نے حضرت ابوالدرداءؓ کے لیے تیار کی ہیں کیونکہ وہ دونوں ہاتھوں اور سینے سے دنیا کو دھکے دیا کرتے تھے (بڑے زاہد تھے)۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilya (Vol.1 Pg.210)."]]},{"b":[["n",[["امام واقدی کے اساتذہ حضرات فرماتے ہیں ",""],["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمرو بن حرامؓ","b"],[" نے فرمایا میں نے جنگِ احد سے پہلے خواب میں حضرت مبشر بن عبدالمنذرؓ کو دیکھا، وہ مجھ سے کہہ رہے ہیں تم چند دنوں میں ہمارے پاس آنے والے ہو۔ میں نے پوچھا آپ کہاں ہیں؟ فرمایا ہم جنت میں ہیں اور جہاں چاہتے ہیں جا کر چر لیتے ہیں۔ میں نے کہا کیا آپ جنگِ بدر کے دن قتل نہیں ہوئے تھے؟ فرمایا ہاں، قتل تو ہوا تھا لیکن پھر زندہ ہو گیا۔ میں نے جا کر یہ خواب حضورؐ کی خدمت میں عرض کیا تو فرمایا اے ابوجابر! اس خواب کی تعبیر یہ ہے کہ تمہیں (جنگِ احد میں) شہادت کا درجہ ملے گا۔",""],[" (9)","s"]]]],"f":[["(9)","Haakim (Vol.3 Pg.204)."]]}]}}});
